window.STORY=[{"n":1,"title":"桜の枝","sub":"幼稚園編","era":"kinder","lead":"耀平は4歳で両親を亡くし、祖父と暮らしながら剣聖に憧れ、年長のスキル判定で「一花心舞」と笑われる。","scenes":[{"key":"1-1","title":"祖父の家","bg":"bg_grandpa_house","dark":false,"mood":"soft","bgm":"soft2","cast":["yohei"],"lines":[{"t":"n","s":"四歳の春、耀平は小さなリュックを背負って、祖父の家の玄関に立っていた。","f":"yohei"},{"t":"n","s":"両親が事故で亡くなったのは、つい先週のことだ。まだ四歳の耀平には、「いない」という言葉の重さが、うまく掴めていなかった。ただ、家に帰っても、誰も「おかえり」と言わない。それだけは分かっていた。","f":"yohei"},{"t":"d","s":"「……腹は減っとらんか」","f":"yohei"},{"t":"n","s":"祖父は、不器用な声で言った。皺だらけの手が、靴箱の上で行き場を失っている。","f":"yohei"},{"t":"d","s":"「ううん」","f":"yohei"},{"t":"d","s":"「そうか」","f":"yohei"},{"t":"n","s":"会話は、それで終わった。祖父は剣のことも、スキルのことも、何も知らない普通の老人だ。どう接していいか分からないまま、耀平の隣に黙って座り続けた。","f":"yohei"},{"t":"n","s":"その夜、耀平は祖父の布団の端で、小さく丸くなって眠った。祖父は一晩中、眠らずに、その背中を見ていた。","f":"yohei"}]},{"key":"1-2","title":"乃亜の家のごはん","bg":"bg_grandpa_house","dark":false,"mood":"soft","bgm":"soft3","cast":["noa","yohei"],"lines":[{"t":"n","s":"歩いて二分のところに、乃亜の家があった。","f":"noa"},{"t":"d","s":"「あら、耀平くん。ごはん、食べていきなさい」","f":"noa"},{"t":"n","s":"乃亜の母に手を引かれ、耀平は食卓についた。味噌汁の湯気。焼き魚。祖父の家では見ない、にぎやかな食卓だ。","f":"noa"},{"t":"n","s":"向かいの席で、同い年の乃亜が、じっと耀平を見ていた。口数の少ない子だ。大きな目だけが、よく動く。","f":"noa"},{"t":"d","s":"「……なに？」","f":"noa"},{"t":"d","s":"「べつに」","f":"noa"},{"t":"n","s":"乃亜は目を逸らし、魚をほぐし始めた。そして、小さな声で言った。","f":"noa"},{"t":"d","s":"「さかな、ほね、とってあげる」","f":"noa"},{"t":"d","s":"「いいの？」","f":"noa"},{"t":"d","s":"「……ちゃんと、たべなよ」","f":"noa"},{"t":"n","s":"耀平は、こくんとうなずいた。その日から、夕方になると、耀平の足は自然と乃亜の家に向かうようになった。","f":"yohei"}]},{"key":"1-3","title":"テレビの中の剣聖","bg":"bg_grandpa_house","dark":false,"mood":"daily","bgm":"daily4","cast":["yohei"],"lines":[{"t":"cg","v":"cg_tv_kensei"},{"t":"n","s":"五歳になる少し前。祖父の家の居間で、耀平はひとりでテレビを見ていた。","f":"yohei"},{"t":"n","s":"画面には、一人の男が映っていた。刀を腰に差し、静かに立っている。周りには荒れた街。そして、凶器を振り回す男が一人。","f":"yohei"},{"t":"d","s":"『剣聖だ！　剣聖が来たぞ！』","f":"yohei"},{"t":"n","s":"悲鳴のような歓声が上がる。","f":"yohei"},{"t":"n","s":"剣聖は、走らなかった。ただ、一歩、踏み出した。","f":"yohei"},{"t":"n","s":"次の瞬間、悪者の凶器が真っ二つに折れて、地面に落ちた。悪者は、何が起きたか分からない顔で、その場に崩れ落ちる。","f":"yohei"},{"t":"n","s":"耀平は、息をするのを忘れていた。","f":"yohei"},{"t":"d","s":"「……かっこいい」","f":"yohei"},{"t":"n","s":"その声は、自分でも驚くほど、はっきり出た。","f":"yohei"},{"t":"n","s":"気がつくと、耀平は庭に飛び出していた。落ちていた桜の枝を拾い、さっき見た剣聖と同じように構える。","f":"yohei"},{"t":"d","s":"「えいっ」","f":"yohei"},{"t":"n","s":"びゅん、と枝が空を切った。まだ、へなへなの音だった。","f":"yohei"},{"t":"d","s":"「えいっ。えいっ」","f":"yohei"},{"t":"n","s":"縁側で、祖父が黙って茶を啜っていた。何か言いたそうに口を開き、閉じ、また開いて、結局こう言った。","f":"yohei"},{"t":"d","s":"「……腹が減ったら、言いなさい」","f":"yohei"},{"t":"n","s":"祖父は、剣のことを何も知らない。教えてやれることは、何もない。だから、ただ見ていることにした。孫が、初めて自分から動き出したのだから。","f":"yohei"}]},{"key":"1-4","title":"竜馬","bg":"bg_kindergarten","dark":false,"mood":"daily","bgm":"daily5","cast":["yohei","ryoma","noa"],"lines":[{"t":"cg","v":"cg_sakura_branch"},{"t":"n","s":"公園の隅で、耀平が枝を振っていると、背後から声がした。","f":"yohei"},{"t":"d","s":"「おまえ、なにやってんだ」","f":"yohei"},{"t":"n","s":"振り向くと、同じ組の竜馬が立っていた。声が大きく、いつも誰かと喧嘩している男の子だ。","f":"ryoma"},{"t":"d","s":"「……けん」","f":"ryoma"},{"t":"d","s":"「けん？」","f":"ryoma"},{"t":"d","s":"「けんせい、みた。かっこよかった」","f":"ryoma"},{"t":"n","s":"竜馬は、枝と耀平の顔を、交互に見た。それから、耀平がもう一度振るのを、じっと見た。","f":"ryoma"},{"t":"n","s":"びゅん。さっきより、少しだけ鋭い音がした。","f":"ryoma"},{"t":"d","s":"「……いまの、すげえ」","f":"ryoma"},{"t":"d","s":"「ほんと？」","f":"ryoma"},{"t":"d","s":"「ほんと！　おれにもやらせろ！」","f":"ryoma"},{"t":"n","s":"竜馬は、足元の枝を拾って振り回し始めた。三回振って、自分の足を叩いて、「いてっ」と叫ぶ。耀平は、思わず笑った。","f":"ryoma","m":"happy"},{"t":"n","s":"そこへ、砂場の方から、乃亜が歩いてきた。","f":"noa"},{"t":"d","s":"「……なにしてるの」","f":"noa"},{"t":"d","s":"「けんせいごっこ！　耀平、めちゃくちゃつよいんだぞ！」","f":"noa"},{"t":"n","s":"竜馬が、なぜか自慢げに胸を張る。乃亜は耀平を見て、小さく言った。","f":"ryoma"},{"t":"d","s":"「……ふーん」","f":"ryoma"},{"t":"n","s":"その目は、少しだけ、笑っていた。","f":"ryoma"}]},{"key":"1-5","title":"スキル判定の日","bg":"bg_kindergarten","dark":false,"mood":"daily","bgm":"daily1","cast":["yohei","ryoma","noa"],"lines":[{"t":"n","s":"年長の秋。幼稚園の遊戯室に、組の全員が集められた。"},{"t":"d","s":"「みんな、今日は、スキルを調べる日です。ひとりずつ、前に出てきてね」"},{"t":"n","s":"先生が、透明な水晶玉を台の上に置く。手をかざすと、その子のスキルが形になって現れる。"},{"t":"n","s":"最初は竜馬だった。","f":"ryoma"},{"t":"d","s":"「いくぜ！」","f":"ryoma"},{"t":"n","s":"水晶玉に手をかざすと、赤い光が弾けた。手のひらの上に、ぼっ、と小さな炎が灯る。","f":"ryoma"},{"t":"d","s":"「紅蓮爆炎、ですね。すごい、強いスキルよ」","f":"ryoma"},{"t":"d","s":"「やった！　おれ、つえー！」","f":"ryoma"},{"t":"n","s":"歓声が上がる。竜馬は、鼻の下を擦って、耀平のほうを振り向いた。","f":"ryoma"},{"t":"d","s":"「耀平！　つぎ、おまえだぞ！　ぜったい、おれよりすげーやつだ！」","f":"ryoma"},{"t":"n","s":"次は乃亜だった。水晶玉に、青い光が滲む。空中に、小さな水の珠が、ふわりと浮かんだ。","f":"noa"},{"t":"d","s":"「碧水心希。きれいなスキルね」","f":"noa"},{"t":"n","s":"乃亜は何も言わず、ちょっとだけ頬を赤くして、耀平の隣に戻ってきた。","f":"noa"},{"t":"d","s":"「……つぎ、がんばって」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"n","s":"そして、耀平の番になった。","f":"yohei"},{"t":"n","s":"水晶玉に、手をかざす。","f":"yohei"},{"t":"n","s":"……何も、起きなかった。","f":"yohei"},{"t":"n","s":"一秒。二秒。","f":"yohei"},{"t":"n","s":"やがて、ふわり、と何かが宙を舞った。","f":"yohei"},{"t":"n","s":"桜の花びらが、たった一枚。","f":"yohei"},{"t":"n","s":"ひらひらと揺れながら、床に落ちた。それきり、何も起きない。","f":"yohei"},{"t":"d","s":"「えっと……一花心舞、ですね」","f":"yohei"},{"t":"n","s":"先生が、困ったように言った。","f":"yohei"},{"t":"n","s":"どっと、笑い声が起きた。","f":"yohei"},{"t":"d","s":"「それだけ？」","f":"yohei"},{"t":"d","s":"「はなびら、いちまいだけ！」","f":"yohei"},{"t":"d","s":"「しょぼーい！」","f":"yohei"},{"t":"n","s":"耀平は、床に落ちた花びらを、じっと見ていた。笑われていることは、分かった。でも、不思議と悲しくはなかった。花びらが落ちる直前、肩に触れたとき、体が、ほんの少し、軽く感じたからだ。","f":"yohei"},{"t":"d","s":"「……なんだよ、それ」","f":"yohei"},{"t":"n","s":"低い声がした。竜馬だった。さっきまで輝いていた目から、光が消えている。","f":"ryoma"},{"t":"d","s":"「ぜったいすげーって、いったのに」","f":"ryoma"},{"t":"d","s":"「りょうま……」","f":"ryoma"},{"t":"d","s":"「おれ、おまえのことかっこいいと思ってたのに……そんなの、なんにもつよくないじゃんか！」","f":"ryoma"},{"t":"n","s":"竜馬は、そう叫んで、遊戯室を飛び出した。","f":"ryoma"},{"t":"n","s":"遊戯室が、静まり返る。","f":"ryoma"},{"t":"n","s":"そのとき、隣で、小さな声がした。","f":"ryoma"},{"t":"d","s":"「……きれい」","f":"ryoma"},{"t":"n","s":"乃亜だった。まっすぐに、床の花びらを見ていた。","f":"noa"},{"t":"d","s":"「ひとひらだけ、きれい」","f":"noa"},{"t":"n","s":"笑い声が、少しだけ、小さくなった。耀平は、乃亜の顔を見た。乃亜は、ふいと目を逸らして、耳まで赤くしていた。","f":"yohei"},{"t":"d","s":"「……べつに、ほんとのこと、いっただけ」","f":"yohei"}]},{"key":"1-6","title":"卒園まで","bg":"bg_kindergarten","dark":false,"mood":"soft","bgm":"soft3","cast":["yohei","ryoma","noa"],"lines":[{"t":"n","s":"それから、竜馬は耀平に話しかけなくなった。","f":"ryoma"},{"t":"n","s":"公園に行っても、竜馬は他の子たちと走り回るだけで、耀平の方を見ない。耀平も、何も言わなかった。","f":"ryoma"},{"t":"n","s":"ただ、毎日、枝を振った。","f":"ryoma"},{"t":"n","s":"朝、庭で。夕方、公園の隅で。雨の日は、縁側で。","f":"ryoma"},{"t":"n","s":"祖父は、何も言わずに、温かい麦茶を置いていく。","f":"ryoma"},{"t":"d","s":"「……すこし、力が入りすぎとる」","f":"ryoma"},{"t":"n","s":"ある日、祖父がぽつりと言った。","f":"ryoma"},{"t":"d","s":"「おじいちゃん、けんのこと、わかるの？」","f":"ryoma"},{"t":"d","s":"「いや、ちっとも分からん。ただ、おまえの背中を見とると、そんな気がしただけじゃ」","f":"ryoma"},{"t":"n","s":"耀平は少し考えてから、肩の力を抜いて、もう一度振った。","f":"yohei"},{"t":"n","s":"びゅん。","f":"yohei"},{"t":"n","s":"いい音がした。縁側の祖父が、小さく目を細めた。","f":"yohei"},{"t":"n","s":"卒園式の日。園庭の桜が、満開だった。","f":"yohei"},{"t":"n","s":"乃亜が、耀平の隣に並んで、花びらを見上げた。","f":"noa"},{"t":"d","s":"「ようへい」","f":"noa"},{"t":"d","s":"「なに？」","f":"noa"},{"t":"d","s":"「……がんばってね」","f":"noa"},{"t":"d","s":"「なにを？」","f":"noa"},{"t":"d","s":"「それは、じぶんで、かんがえて」","f":"noa"},{"t":"n","s":"乃亜はそう言って、つんと顔を逸らした。耀平は首を傾げながらも、笑った。","f":"noa","m":"happy"},{"t":"n","s":"桜の枝が、風に揺れた。","f":"noa"},{"t":"n","s":"その枝の先から、花びらが一枚、ひらりと舞った。","f":"noa"}]}]},{"n":2,"title":"入学式と運動会","sub":"小学校・低学年","era":"elem","lead":"耀平は乃亜と同じ教室で眠そうに過ごし、竜馬は少しだけ遠くなる。","scenes":[{"key":"2-1","title":"入学式","bg":"bg_graduation","dark":false,"mood":"daily","bgm":"daily3","cast":["noa","yohei","ryoma"],"lines":[{"t":"n","s":"満開の桜の下を、三人は歩いていた。"},{"t":"n","s":"真新しいランドセルが、背中でかたかたと鳴る。六歳の春。耀平の隣には乃亜がいて、少し先を、竜馬が一人で歩いている。","f":"yohei"},{"t":"d","s":"「……りょうま、まってくれないね」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「いいの？」","f":"yohei"},{"t":"d","s":"「べつに。かってに、いくから」","f":"yohei"},{"t":"n","s":"耀平は眠そうに目をこすった。今朝も夜明け前から、庭で枝を振っていたせいだ。少し後ろを、祖父が黙ってついてくる。着慣れない背広の袖を、時々引っ張りながら。","f":"yohei"},{"t":"n","s":"校門の前で、別の幼稚園から来た男の子たちが、こちらを指さした。","f":"yohei"},{"t":"d","s":"「あいつだよ。スキル、はなびらいちまいのやつ」","f":"yohei"},{"t":"d","s":"「えー、しょぼ。ほんとに？」","f":"yohei"},{"t":"n","s":"くすくすと笑う声。耀平は、聞こえていないように、ぼんやりと空を見ていた。","f":"yohei","m":"happy"},{"t":"n","s":"乃亜が、ぴたりと足を止めた。くるりと振り向いて、男の子たちをじっと見る。大きな目で、まばたきもせずに。","f":"noa"},{"t":"d","s":"「……なに？」","f":"noa"},{"t":"d","s":"「な、なんだよ」","f":"noa"},{"t":"d","s":"「いま、なんていったの」","f":"noa"},{"t":"d","s":"「べ、べつに……」","f":"noa"},{"t":"d","s":"「もういっかい、いって」","f":"noa"},{"t":"n","s":"低い声だった。六歳とは思えない、静かな圧があった。男の子たちは顔を見合わせて、そそくさと逃げていった。","f":"noa"},{"t":"d","s":"「乃亜」","f":"noa"},{"t":"d","s":"「なに」","f":"noa"},{"t":"d","s":"「こわいよ」","f":"noa"},{"t":"d","s":"「……うるさい」","f":"noa"},{"t":"n","s":"乃亜は前を向いて、ずんずん歩き出した。耳が、少しだけ赤かった。","f":"noa"}]},{"key":"2-2","title":"ねむい日々","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily4","cast":["yohei","noa","ryoma"],"lines":[{"t":"n","s":"一年一組の教室。窓から入る日差しが、あたたかい。"},{"t":"d","s":"「では、この問題が分かる人」"},{"t":"n","s":"先生の声が、遠くで聞こえる。耀平の瞼が、ゆっくり落ちていく。","f":"yohei"},{"t":"d","s":"「……耀平くん？　耀平くん！」","f":"yohei"},{"t":"n","s":"ごつん、と、隣の席から肘が飛んできた。","f":"yohei"},{"t":"d","s":"「いたっ」","f":"yohei"},{"t":"d","s":"「あてられてる」","f":"yohei"},{"t":"d","s":"「え？」","f":"yohei"},{"t":"d","s":"「……さんたす、に」","f":"yohei"},{"t":"d","s":"「に？」","f":"yohei"},{"t":"d","s":"「ばか」","f":"yohei"},{"t":"n","s":"乃亜が小声で答えを教える。耀平は慌てて立ち上がり、「に、です」と答えた。教室がくすくす笑う。","f":"noa","m":"happy"},{"t":"n","s":"先生は苦笑して言った。","f":"noa","m":"sweat"},{"t":"d","s":"「耀平くん、昨日は夜更かししたのかな？」","f":"noa"},{"t":"d","s":"「いえ。あさ、はやかったです」","f":"noa"},{"t":"d","s":"「朝？」","f":"noa"},{"t":"d","s":"「けんを、ふってました」","f":"noa"},{"t":"n","s":"教室が、しんとなった。それから誰かが、小さく吹き出した。","f":"noa"},{"t":"d","s":"「はなびらのひとなのに、けん？」","f":"noa"},{"t":"n","s":"乃亜が、机の下で耀平の足を踏んだ。","f":"noa"},{"t":"d","s":"「いたい」","f":"noa"},{"t":"d","s":"「しゃべりすぎ」","f":"noa"},{"t":"n","s":"放課後の廊下で、耀平は竜馬とすれ違った。一瞬、目が合う。竜馬はむっとした顔で、ふいと視線を逸らして行ってしまった。","f":"yohei"},{"t":"d","s":"「……りょうま」","f":"yohei"},{"t":"d","s":"「ほうっておけば」","f":"yohei"},{"t":"n","s":"乃亜が言った。","f":"noa"},{"t":"d","s":"「でも」","f":"noa"},{"t":"d","s":"「あっちが、むかしのことで、すねてるだけ」","f":"noa"},{"t":"d","s":"「すねてるの？」","f":"noa"},{"t":"d","s":"「ぜったい、そう」","f":"noa"},{"t":"n","s":"乃亜は、少し間を置いて、付け加えた。","f":"noa"},{"t":"d","s":"「……りょうまは、ほんとは、さびしいだけだよ」","f":"noa"},{"t":"n","s":"耀平には、よく分からなかった。ただ、その言葉だけは、なぜか胸に残った。","f":"yohei"}]},{"key":"2-3","title":"運動会","bg":"bg_schoolyard_middle","dark":false,"mood":"daily","bgm":"daily5","cast":["ryoma","noa","yohei"],"lines":[{"t":"n","s":"秋。運動会の日は、からりと晴れた。"},{"t":"n","s":"校庭には、色とりどりの旗。保護者席の隅で、祖父が膝にお重を抱えて座っている。隣では乃亜の母が、手を振っていた。","f":"noa"},{"t":"d","s":"「耀平くーん！　がんばってー！」","f":"noa"},{"t":"d","s":"「おじいさん、お茶をどうぞ」","f":"noa"},{"t":"d","s":"「……すまん」","f":"noa"},{"t":"n","s":"祖父は、なぜか居心地悪そうに、湯呑みを受け取った。","f":"noa"},{"t":"n","s":"徒競走の順番が来た。スタートラインに並ぶ六人。その中に、竜馬と、耀平がいた。","f":"ryoma"},{"t":"d","s":"「いちについて」","f":"ryoma"},{"t":"n","s":"竜馬が、ちらりと耀平を見た。何か言いたそうな顔だ。けれど、結局、何も言わずに前を向いた。","f":"ryoma"},{"t":"d","s":"「よーい、どん！」","f":"ryoma"},{"t":"n","s":"竜馬は、弾丸のように飛び出した。小さな体で地面を蹴る音が、聞こえるほどの勢い。炎のような走りだった。","f":"ryoma"},{"t":"n","s":"耀平はといえば、眠そうに、とことこと走っていた。","f":"yohei"},{"t":"n","s":"結果は、竜馬が一位。耀平は四位。","f":"ryoma"},{"t":"d","s":"「やったー！　おれ、いちばんだ！」","f":"ryoma"},{"t":"n","s":"竜馬は、旗を高く掲げて叫んだ。歓声が上がる。ゴールを出た耀平のところに、乃亜が駆け寄ってきた。むすっとした顔で。","f":"ryoma"},{"t":"d","s":"「ようへい」","f":"ryoma"},{"t":"d","s":"「なに？」","f":"ryoma"},{"t":"d","s":"「ちゃんと、はしって」","f":"ryoma"},{"t":"d","s":"「ちゃんと、はしった」","f":"ryoma"},{"t":"d","s":"「うそ。ねむそうだった」","f":"ryoma"},{"t":"d","s":"「ねむかった」","f":"ryoma"},{"t":"d","s":"「ばか」","f":"ryoma"},{"t":"n","s":"乃亜は、ぷいと顔を背けた。けれど、そのあと小さく付け加える。","f":"noa"},{"t":"d","s":"「……けが、してない？」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「ならいい」","f":"noa"},{"t":"n","s":"そのとき、竜馬が、旗を持ったままこちらに歩いてきた。","f":"ryoma"},{"t":"d","s":"「おい、乃亜」","f":"ryoma"},{"t":"d","s":"「なに」","f":"ryoma"},{"t":"d","s":"「み、みてたか？　おれ、いちばんだったろ」","f":"ryoma"},{"t":"d","s":"「……うん。みてた。おめでとう」","f":"ryoma"},{"t":"n","s":"乃亜が、ほんの少しだけ、口の端を上げて言った。竜馬の顔が、ぱっと赤くなる。","f":"noa"},{"t":"d","s":"「べ、べつに、おまえのためにはしったんじゃねーし！　かんちがいすんなよ！」","f":"noa"},{"t":"d","s":"「してないよ」","f":"noa"},{"t":"d","s":"「してねーならいいけど！」","f":"noa"},{"t":"n","s":"竜馬は、旗をぶんぶん振りながら、逃げるように走っていった。耀平は、その背中を見ながら、首をかしげた。","f":"ryoma"},{"t":"d","s":"「りょうま、なんであかいの？」","f":"ryoma"},{"t":"d","s":"「しらない」","f":"ryoma"},{"t":"d","s":"「あついのかな」","f":"ryoma"},{"t":"n","s":"乃亜は、深いため息をついた。","f":"noa"},{"t":"d","s":"「……ようへいは、ほんとに、ばか」","f":"noa"},{"t":"n","s":"お昼になった。祖父のお重には、不揃いなおにぎりが、ぎっしり詰まっていた。","f":"noa"},{"t":"d","s":"「……すまん。うまく、にぎれんかった」","f":"noa"},{"t":"d","s":"「おじいちゃん、おいしいよ」","f":"noa"},{"t":"d","s":"「……そうか」","f":"noa"},{"t":"n","s":"祖父は、そっぽを向いて茶を啜った。耳の先が、少し赤かった。","f":"noa","m":"blush"},{"t":"n","s":"乃亜も、一つもらって、じっと眺めた。","f":"noa"},{"t":"d","s":"「……おおきい」","f":"noa"},{"t":"d","s":"「いや、か？」","f":"noa"},{"t":"d","s":"「ううん。おいしい」","f":"noa"},{"t":"n","s":"祖父が、湯呑みを持つ手を、小さく震わせた。","f":"noa"}]},{"key":"2-4","title":"帰り道","bg":"bg_riverside","dark":false,"mood":"daily","bgm":"daily1","cast":["yohei","noa"],"lines":[{"t":"cg","v":"cg_walk_home3"},{"t":"n","s":"夕焼けの道を、耀平と乃亜は並んで歩いていた。","f":"yohei"},{"t":"d","s":"「りょうま、はやかったね」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「かっこよかった」","f":"yohei"},{"t":"d","s":"「……ふーん」","f":"yohei"},{"t":"n","s":"乃亜は、石ころを蹴った。","f":"noa"},{"t":"d","s":"「ようへいだって、かっこいいよ」","f":"noa"},{"t":"d","s":"「え」","f":"noa"},{"t":"d","s":"「けんふってる、とき」","f":"noa"},{"t":"d","s":"「ほんと？」","f":"noa"},{"t":"d","s":"「……べつに。みたまま、いっただけ」","f":"noa"},{"t":"n","s":"耀平は、ぽかんとして、それから、ふわっと笑った。","f":"yohei","m":"happy"},{"t":"d","s":"「ありがとう」","f":"yohei"},{"t":"d","s":"「おれいは、いらない」","f":"yohei"},{"t":"n","s":"乃亜は、顔を前に向けたまま、歩く速度を少しだけ上げた。","f":"noa"},{"t":"n","s":"夕焼けの空に、桜はもう、咲いていなかった。それでも、耀平の肩のあたりを、一枚だけ、季節外れの花びらが、ふわりと舞って消えた。","f":"yohei"},{"t":"n","s":"誰も、それには気づかなかった。","f":"yohei"}]}]},{"n":3,"title":"夏祭りと遠足のお弁当","sub":"小学校・中学年","era":"elem","lead":"乃亜の照れと、竜馬の言えない気持ちが、少しずつ積もっていく。","scenes":[{"key":"3-1","title":"夏祭り","bg":"bg_riverside","dark":false,"mood":"soft","bgm":"soft4","cast":["noa","yohei","ryoma"],"lines":[{"t":"n","s":"三年生の夏。神社の境内は、提灯の灯りと人の声でいっぱいだった。"},{"t":"d","s":"「おじいちゃん、りんごあめ、ほしい」"},{"t":"d","s":"「ああ、買ってやろう。……いくらじゃ」"},{"t":"d","s":"「えっと、にひゃくえん」"},{"t":"n","s":"祖父は財布を開いて、小銭をじっと数えた。祭りに来るのは、十年ぶりだという。"},{"t":"n","s":"そこへ、からん、ころん、と下駄の音が近づいてきた。"},{"t":"d","s":"「……耀平」"},{"t":"cg","v":"cg_yukata"},{"t":"n","s":"振り向くと、乃亜が立っていた。紺地に金魚の柄の浴衣。髪には、小さな花の飾り。いつもと違う姿に、乃亜は居心地悪そうに袖をつまんでいる。","f":"noa"},{"t":"n","s":"耀平は、じっと乃亜を見て、言った。","f":"yohei"},{"t":"d","s":"「あつそう」","f":"yohei"},{"t":"d","s":"「……は？」","f":"yohei"},{"t":"d","s":"「それ、あつそう」","f":"yohei"},{"t":"n","s":"乃亜の眉が、ぴくりと動いた。","f":"noa"},{"t":"d","s":"「それだけ？」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「……ばか」","f":"noa"},{"t":"n","s":"乃亜は、ぷいと顔を背けて、すたすた歩き出した。耀平は、なぜ怒られたのか分からずに首をかしげる。その背中を見ながら、祖父が、ごほん、と咳をした。","f":"noa"},{"t":"d","s":"「耀平」","f":"noa"},{"t":"d","s":"「なに？」","f":"noa"},{"t":"d","s":"「ああいうときは、似合っとる、と言うもんじゃ」","f":"noa"},{"t":"d","s":"「にあってるって？」","f":"noa"},{"t":"d","s":"「そうじゃ」","f":"noa"},{"t":"d","s":"「……そうなの？」","f":"noa"},{"t":"n","s":"耀平は、少し考えてから、小走りで乃亜を追いかけた。","f":"yohei"},{"t":"d","s":"「乃亜」","f":"yohei"},{"t":"d","s":"「なに」","f":"yohei"},{"t":"d","s":"「にあってる」","f":"yohei"},{"t":"d","s":"「……いまさら、おそい」","f":"yohei"},{"t":"n","s":"そう言いながらも、乃亜は振り向かなかった。ただ、浴衣の袖から覗く耳が、提灯の光よりも赤かった。","f":"noa"},{"t":"n","s":"屋台を回った。金魚すくいで、乃亜は一匹も取れずに紙を破いた。射的で、耀平は一発も当たらなかった。りんごあめを二人で一つずつ舐めながら歩いていると、背後から声がした。","f":"noa"},{"t":"d","s":"「おまえら、きてたのか」","f":"noa"},{"t":"n","s":"竜馬が、友達三人と立っていた。その視線が、乃亜の浴衣にぶつかって、固まる。","f":"ryoma"},{"t":"d","s":"「……」","f":"ryoma"},{"t":"d","s":"「なに」","f":"ryoma"},{"t":"d","s":"「な、なんでもねえ」","f":"ryoma"},{"t":"d","s":"「竜馬くん、どうしたの？　顔、まっかだよ」","f":"ryoma"},{"t":"d","s":"「うるせえ！　あつかっただけだ！」","f":"ryoma"},{"t":"n","s":"友達に囲まれて、竜馬は走って人混みへ消えた。","f":"ryoma"},{"t":"d","s":"「竜馬、へんなの」","f":"ryoma"},{"t":"d","s":"「……ほんとに、ばか」","f":"ryoma"},{"t":"d","s":"「おれ？」","f":"ryoma"},{"t":"d","s":"「どっちも」","f":"ryoma"},{"t":"n","s":"夜空に、ひゅう、と細い音が昇った。ドン、と大きな花が咲く。","f":"ryoma"},{"t":"d","s":"「きれい」","f":"ryoma"},{"t":"n","s":"乃亜が、ぽつりと言った。耀平は、返事をしなかった。見ると、眠そうに、こくり、こくり、と頭を揺らしている。","f":"noa"},{"t":"d","s":"「……耀平。ねてる」","f":"noa"},{"t":"d","s":"「ねてない」","f":"noa"},{"t":"d","s":"「ねてる」","f":"noa"},{"t":"d","s":"「ねて……」","f":"noa"},{"t":"n","s":"こて、と、耀平の頭が、乃亜の肩に落ちた。","f":"yohei"},{"t":"n","s":"乃亜は、固まった。心臓の音が、花火よりうるさく聞こえる。","f":"noa"},{"t":"d","s":"「ち、ちょっと……」","f":"noa"},{"t":"d","s":"「……すう」","f":"noa"},{"t":"d","s":"「……ばか」","f":"noa"},{"t":"n","s":"けれど、乃亜は、そのまま動かなかった。花火が終わるまで、ずっと。","f":"noa"},{"t":"n","s":"少し離れた場所で、祖父が麦茶を飲みながら、その様子を静かに見ていた。","f":"noa"},{"t":"d","s":"「……ええ友達を持ったのう」","f":"noa"},{"t":"n","s":"誰にともなく、祖父はつぶやいた。","f":"noa"}]},{"key":"3-2","title":"遠足のお弁当","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily5","cast":["noa","yohei","ryoma"],"lines":[{"t":"n","s":"四年生の秋、遠足。バスの中で、竜馬は後ろの席から、前の席の乃亜をちらちらと気にしていた。","f":"ryoma"},{"t":"n","s":"昼になると、広い芝生に、みんながレジャーシートを広げた。耀平が寝転がろうとしたそのとき、乃亜が、ぶっきらぼうに弁当箱を差し出した。","f":"yohei"},{"t":"d","s":"「……ん」","f":"yohei"},{"t":"d","s":"「なに？」","f":"yohei"},{"t":"d","s":"「べんとう。あげる」","f":"yohei"},{"t":"d","s":"「乃亜のお母さんの？」","f":"yohei"},{"t":"d","s":"「ちがう。わたしの」","f":"yohei"},{"t":"n","s":"耀平は目をまたたいた。蓋を開けると、少し形の崩れたおにぎりと、焦げ目のついた玉子焼き、いびつなタコさんウインナー。","f":"yohei"},{"t":"d","s":"「……乃亜がつくったの？」","f":"yohei"},{"t":"d","s":"「よ、よけいなこと、きかなくていい」","f":"yohei"},{"t":"d","s":"「すごい」","f":"yohei"},{"t":"d","s":"「べつに。きのう、ひまだったから、つくっただけ」","f":"yohei"},{"t":"d","s":"「あまったの？」","f":"yohei"},{"t":"d","s":"「そう。あまった。たまたま」","f":"yohei"},{"t":"n","s":"本当は、前の晩、母に頼んで三時間つきっきりで教わった。玉子焼きは、五回失敗した。でも、そんなことは、絶対に言わない。","f":"yohei"},{"t":"n","s":"耀平は、玉子焼きを口に入れた。","f":"yohei"},{"t":"d","s":"「……おいしい」","f":"yohei"},{"t":"d","s":"「ほんと？」","f":"yohei"},{"t":"d","s":"「うん。しょっぱいけど、おいしい」","f":"yohei"},{"t":"d","s":"「しょっぱいは、よけい」","f":"yohei"},{"t":"n","s":"乃亜は、むっとした。けれど、口元が緩んでいる。","f":"noa"},{"t":"d","s":"「おれ、これ、すき」","f":"noa"},{"t":"d","s":"「……そう。ならいい」","f":"noa"},{"t":"n","s":"乃亜は、自分の弁当を開けた。母が作った、綺麗な弁当だ。そっちは、わざと見せなかった。","f":"noa"},{"t":"n","s":"少し離れた木の陰で、竜馬が、その様子を見ていた。母の作った弁当を、無言で口に運ぶ。味が、よく分からなかった。","f":"ryoma"},{"t":"d","s":"「……いいなあ」","f":"ryoma"},{"t":"n","s":"小さく漏れた声は、誰にも聞こえなかった。","f":"ryoma"}]},{"key":"3-3","title":"バレンタイン","bg":"bg_classroom_middle","dark":false,"mood":"soft","bgm":"soft2","cast":["noa","yohei","ryoma"],"lines":[{"t":"n","s":"四年生の冬。二月十四日。乃亜の机の上には、チョコの山ができていた。女子からの友チョコが半分。残りの半分は、顔を真っ赤にした男子たちが、そっと置いていったものだ。","f":"noa"},{"t":"d","s":"「のあちゃん、すごい……」","f":"noa"},{"t":"d","s":"「べつに」","f":"noa"},{"t":"n","s":"乃亜は、無表情で、紙袋にチョコを詰めていく。そして、その中から、小さな包みを一つだけ取り出して、耀平の席に歩いてきた。","f":"noa"},{"t":"d","s":"「耀平。ん」","f":"noa"},{"t":"n","s":"包みが、ぽいと机に放られた。","f":"noa"},{"t":"d","s":"「なに？」","f":"noa"},{"t":"d","s":"「ぎり」","f":"noa"},{"t":"d","s":"「ぎり？」","f":"noa"},{"t":"d","s":"「ぎりちょこ。みんなにあげてるの」","f":"noa"},{"t":"d","s":"「そうなんだ。ありがとう」","f":"noa"},{"t":"n","s":"耀平は素直に受け取って、包みを開けた。小さなハート型のチョコだった。形は不揃いで、ところどころ欠けている。","f":"yohei"},{"t":"d","s":"「……みんなにあげてるにしては、ていねいだね」","f":"yohei"},{"t":"d","s":"「う、うるさい！」","f":"yohei"},{"t":"n","s":"乃亜は、真っ赤になって走っていった。","f":"noa"},{"t":"n","s":"廊下の隅で、竜馬が、その一部始終を見ていた。ポケットの中には、昨日、小遣いで買ったチョコが入っている。何度も渡そうと思って、何度も手が止まった。","f":"ryoma"},{"t":"n","s":"そこへ、乃亜が通りかかった。","f":"noa"},{"t":"d","s":"「竜馬」","f":"noa"},{"t":"d","s":"「お、おう」","f":"noa"},{"t":"d","s":"「ん。ぎり」","f":"noa"},{"t":"n","s":"同じような小さな包みが、竜馬の手に押し付けられた。","f":"ryoma"},{"t":"d","s":"「……さ、さんきゅ」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"n","s":"乃亜は、それだけ言って、教室に戻っていった。竜馬は、しばらくその場に立ち尽くしていた。やがて、ポケットの中のチョコを、ぎゅっと握りしめる。","f":"noa"},{"t":"d","s":"「……へたくそ」","f":"noa"},{"t":"n","s":"自分に言い聞かせるように呟いて、包みを押し込んだ。渡せなかったチョコは、ポケットの中で、少しだけ溶けていた。","f":"noa"},{"t":"n","s":"その夜、耀平は、祖父の前でチョコを広げた。","f":"yohei"},{"t":"d","s":"「……誰からじゃ」","f":"yohei"},{"t":"d","s":"「乃亜。ぎりだって」","f":"yohei"},{"t":"d","s":"「ほう。ぎりにしては、ていねいじゃのう」","f":"yohei"},{"t":"d","s":"「ぼくもそう思った」","f":"yohei"},{"t":"n","s":"二人は、小さなハートを半分に割って、黙って口に入れた。苦くて、少し甘かった。","f":"yohei"}]}]},{"n":4,"title":"木刀選び、林間学校、クリスマス","sub":"小学校・高学年","era":"elem","lead":"五年生の耀平は、はじめて自分の刀を手にする。そして、竜馬の視線が少しずつ尖っていく。","scenes":[{"key":"4-1","title":"木刀選び","bg":"bg_grandpa_house","dark":false,"mood":"daily","bgm":"daily5","cast":["yohei"],"lines":[{"t":"n","s":"五年生の春。祖父は、耀平を連れて、町外れの古い道具屋を訪ねた。","f":"yohei"},{"t":"d","s":"「ここじゃ」","f":"yohei"},{"t":"d","s":"「ぶきやさん？」","f":"yohei"},{"t":"d","s":"「木刀を扱っておる。お前も、もう棒切れでは足りんじゃろう」","f":"yohei"},{"t":"n","s":"耀平の目が、ぱっと開いた。毎朝、庭の枝を拾っては振っていた。手のひらの皮は、とうに厚くなっている。","f":"yohei"},{"t":"n","s":"店の奥には、何十本もの木刀が立てかけられていた。白樫、赤樫、枇杷。長さも反りも、少しずつ違う。","f":"yohei"},{"t":"d","s":"「好きなのを持ってみい」","f":"yohei"},{"t":"n","s":"耀平は、一本ずつ手に取った。重い。軽い。長い。短い。何本目かで、ぴたりと止まった。","f":"yohei"},{"t":"d","s":"「……これ」","f":"yohei"},{"t":"d","s":"「ほう。それは枇杷じゃな。重いぞ」","f":"yohei"},{"t":"d","s":"「でも、しっくりくる」","f":"yohei"},{"t":"n","s":"耀平は、ゆっくりと構えた。振り下ろす。空気が、すっと割れる音がした。","f":"yohei"},{"t":"n","s":"店主の老人が、奥から顔を出した。","f":"yohei"},{"t":"d","s":"「ほう……坊や、誰に習った」","f":"yohei"},{"t":"d","s":"「だれにも。テレビで、見ただけ」","f":"yohei"},{"t":"d","s":"「テレビ、のう」","f":"yohei"},{"t":"d","s":"「けんせいさんの、まねです」","f":"yohei"},{"t":"n","s":"老人は目を細め、祖父の顔を見た。祖父は、黙って首を横に振る。教えていない、という意味だった。","f":"yohei"},{"t":"d","s":"「……そうか。ええ振りじゃ。持っていきなされ」","f":"yohei"},{"t":"d","s":"「いくらですか」","f":"yohei"},{"t":"d","s":"「いらん。その代わり、折るなよ」","f":"yohei"},{"t":"n","s":"外に出ると、耀平は木刀を抱きしめるように持って、何度も振り返った。","f":"yohei"},{"t":"d","s":"「おじいちゃん、ありがとう」","f":"yohei"},{"t":"d","s":"「礼なら、あの店主に言うんじゃな」","f":"yohei"},{"t":"d","s":"「おじいちゃんにも」","f":"yohei"},{"t":"d","s":"「……そうか」","f":"yohei"},{"t":"n","s":"祖父の背中は、少しだけ丸くなっていた。それでも、孫の後ろ姿を見るその目は、ひどくやわらかかった。","f":"yohei"},{"t":"n","s":"その日から、耀平の朝は、木刀と一緒に始まった。","f":"yohei"},{"t":"n","s":"夜明け前に起き、庭に立つ。構える。振る。ときどき、風に乗って、どこからか桜の花びらが一枚だけ、ひらりと舞い込んでくる。","f":"yohei"},{"t":"d","s":"「……また、きた」","f":"yohei"},{"t":"n","s":"耀平は、その花びらに刀の先を触れさせた。すると、体が、ほんの一瞬だけ、軽くなる。","f":"yohei"},{"t":"d","s":"「やっぱり、へんなスキル」","f":"yohei"},{"t":"n","s":"小さく笑って、耀平は木刀を振り下ろした。","f":"yohei"}]},{"key":"4-2","title":"木刀の噂","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily1","cast":["yohei","ryoma","noa"],"lines":[{"t":"n","s":"翌週、教室。耀平が布袋に入れた木刀を持ってくると、さっそく人だかりができた。","f":"yohei"},{"t":"d","s":"「うわ、本物の木刀だ！」","f":"yohei"},{"t":"d","s":"「かっこいい！　ちょっと持たせて」","f":"yohei"},{"t":"d","s":"「だめ。あぶないから」","f":"yohei"},{"t":"d","s":"「ケチ」","f":"yohei"},{"t":"n","s":"そこへ、割り込む影があった。","f":"yohei"},{"t":"d","s":"「おい」","f":"yohei"},{"t":"n","s":"竜馬だった。腕を組んで、耀平の机を見下ろしている。","f":"ryoma"},{"t":"d","s":"「なんだよ、それ」","f":"ryoma"},{"t":"d","s":"「木刀。おじいちゃんが、かってくれた」","f":"ryoma"},{"t":"d","s":"「スキルが“一花”のくせに、刀かよ」","f":"ryoma"},{"t":"n","s":"教室が、少し静かになった。","f":"ryoma"},{"t":"d","s":"「花びら出すだけのスキルで、刀なんか持って、なにするんだ」","f":"ryoma"},{"t":"d","s":"「……べつに。かっこいいから」","f":"ryoma"},{"t":"d","s":"「かっこいい？　おまえが？」","f":"ryoma"},{"t":"n","s":"竜馬は鼻で笑った。けれど、その目は笑っていない。幼稚園の頃、一緒に木の枝を振り回して遊んだ記憶が、竜馬の中にまだ残っている。自分は炎を出せるようになったのに、耀平は何も変わらない。変わらないはずなのに、毎日あんなに振っている。それが、なぜか、気に入らなかった。","f":"ryoma","m":"happy"},{"t":"d","s":"「竜馬」","f":"ryoma"},{"t":"n","s":"乃亜の声が、割って入った。","f":"noa"},{"t":"d","s":"「やめなよ」","f":"noa"},{"t":"d","s":"「なんだよ、乃亜。おれはほんとのこと言っただけだろ」","f":"noa"},{"t":"d","s":"「ほんとかどうかじゃなくて、いやな言い方だって言ってるの」","f":"noa"},{"t":"d","s":"「……ちっ」","f":"noa"},{"t":"n","s":"竜馬は舌打ちをして、席に戻っていった。乃亜は、深いため息をついた。","f":"ryoma"},{"t":"d","s":"「耀平。言い返さなくていいの」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「なんで」","f":"ryoma"},{"t":"d","s":"「だって、ほんとに、へんなスキルだから」","f":"ryoma"},{"t":"d","s":"「そういう問題じゃ……」","f":"ryoma"},{"t":"n","s":"乃亜は、言葉を飲み込んだ。耀平は本気で気にしていない。その顔を見ると、怒っている自分のほうが馬鹿みたいに思えてくる。","f":"noa"},{"t":"d","s":"「……もう、いい」","f":"noa"},{"t":"d","s":"「のあ、おこってる？」","f":"noa"},{"t":"d","s":"「おこってない。あきれてるだけ」","f":"noa"},{"t":"d","s":"「どっちでもおなじだよ」","f":"noa"},{"t":"d","s":"「ちがう」","f":"noa"},{"t":"n","s":"そんなやりとりを、竜馬は席から横目で見ていた。","f":"ryoma"}]},{"key":"4-3","title":"林間学校","bg":"bg_riverside","dark":true,"mood":"night","bgm":"night2","cast":["yohei","noa","ryoma"],"lines":[{"t":"n","s":"五年生の夏は、林間学校だった。山あいの宿泊施設で、二泊三日。班ごとに分かれて、飯ごう炊さんをし、山道を歩き、夜にはキャンプファイヤーを囲む。"},{"t":"n","s":"耀平の班は、乃亜と、あと三人の男女だった。竜馬は別の班だったが、ときどき遠くから、こちらを睨むように見ていた。","f":"yohei","m":"anger"},{"t":"d","s":"「ごはん、まだー？」","f":"yohei"},{"t":"d","s":"「耀平、つまみぐいしないで」","f":"yohei"},{"t":"d","s":"「してない」","f":"yohei"},{"t":"d","s":"「じゃあ、口のまわりについてるのは？」","f":"yohei"},{"t":"d","s":"「……ごはんつぶ」","f":"yohei"},{"t":"d","s":"「してるじゃない」","f":"yohei"},{"t":"n","s":"班のみんなが笑う。乃亜は、呆れた顔で耀平の頬を指でぬぐった。","f":"noa","m":"happy"},{"t":"d","s":"「ほんと、手がかかる」","f":"noa"},{"t":"d","s":"「ありがとう」","f":"noa"},{"t":"d","s":"「お礼いらないから、手伝って」","f":"noa"},{"t":"n","s":"炊きあがった飯ごうの米は、少し焦げていた。それでも、みんなで食べたカレーは、特別においしかった。","f":"noa"},{"t":"n","s":"夜。キャンプファイヤーの炎が、ぱちぱちと夜空に火の粉を飛ばす。生徒たちは輪になって、歌ったり、笑ったりしていた。","f":"noa","m":"happy"},{"t":"n","s":"耀平は、その輪から少し離れた丸太に座って、ぼんやりと炎を見ていた。","f":"yohei"},{"t":"d","s":"「ここ、いい？」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"n","s":"乃亜が、隣に腰を下ろした。しばらく二人とも、何も言わなかった。","f":"noa"},{"t":"d","s":"「……きれいだね」","f":"noa"},{"t":"d","s":"「うん。でも、竜馬の炎のほうが、もっときれいだよ」","f":"noa"},{"t":"d","s":"「竜馬の？」","f":"noa"},{"t":"d","s":"「うん。まっすぐで、強い。おれ、あれ、すき」","f":"noa"},{"t":"n","s":"乃亜は、驚いて耀平の横顔を見た。","f":"noa"},{"t":"d","s":"「あんなこと言われてるのに」","f":"noa"},{"t":"d","s":"「だって、ほんとのことだし。竜馬は、ずっとがんばってるから」","f":"noa"},{"t":"d","s":"「……そういうとこだよ」","f":"noa"},{"t":"d","s":"「なにが？」","f":"noa"},{"t":"d","s":"「なんでもない」","f":"noa"},{"t":"n","s":"乃亜は、膝を抱えて、小さく笑った。","f":"noa","m":"happy"},{"t":"d","s":"「耀平はさ、いつか、竜馬よりも強くなるよ」","f":"noa"},{"t":"d","s":"「ほんと？」","f":"noa"},{"t":"d","s":"「わたしが、そう決めた」","f":"noa"},{"t":"d","s":"「のあが決めたなら、なるのかな」","f":"noa"},{"t":"d","s":"「なるの」","f":"noa"},{"t":"n","s":"焚き火の向こうで、竜馬が友達と肩を組んで笑っていた。けれど、その視線がふっとこちらに向いて、すぐに逸らされる。乃亜と耀平が並んで座っている、その姿を、見たくなかったのかもしれない。","f":"ryoma"},{"t":"n","s":"翌朝。山道を歩く途中、耀平は、足を滑らせた同じ班の女の子の手を、とっさに掴んだ。","f":"yohei"},{"t":"d","s":"「あぶない！」","f":"yohei"},{"t":"d","s":"「きゃっ……」","f":"yohei"},{"t":"n","s":"崖というほどではない。けれど、斜面を転がれば怪我をする高さだった。耀平は、女の子を引き上げると、すぐに自分も体勢を戻した。","f":"yohei"},{"t":"d","s":"「だいじょうぶ？」","f":"yohei"},{"t":"d","s":"「う、うん……ありがとう。耀平くん、すごい」","f":"yohei"},{"t":"d","s":"「たまたま。毎朝、木刀を振ってるから、足腰はつよいかも」","f":"yohei"},{"t":"n","s":"遅れて駆けつけた先生が、目を丸くした。","f":"yohei","m":"surprise"},{"t":"d","s":"「今の反応は……君、何かやっているのか」","f":"yohei"},{"t":"d","s":"「いえ。ふつうです」","f":"yohei"},{"t":"n","s":"耀平はそう答えて、また眠そうな顔に戻った。桜の花びらが、ほんの一枚、風に乗って彼の肩に落ちていたことには、誰も気づかなかった。","f":"yohei"}]},{"key":"4-4","title":"クリスマス","bg":"bg_noa_house","dark":false,"mood":"soft","bgm":"soft4","cast":["yohei","noa"],"lines":[{"t":"n","s":"十二月。町じゅうが、赤と緑に染まった。"},{"t":"n","s":"クリスマスイブの夜、耀平は乃亜の家に招かれた。ダイニングテーブルには、ローストチキンと、サラダ、ポタージュ、そして大きなケーキ。乃亜の母が、にこにこと皿を並べていく。","f":"yohei"},{"t":"d","s":"「耀平くん、遠慮しないでね」","f":"yohei"},{"t":"d","s":"「ありがとうございます」","f":"yohei"},{"t":"d","s":"「お父さんが残業でね、今夜はちょうど席が空いてるのよ。いっぱい食べて」","f":"yohei"},{"t":"n","s":"乃亜の父の席に、耀平は座った。広くて、あたたかい食卓だった。家族の笑い声。皿の音。湯気。耀平は、ふっと、胸の奥が静かに痛んだ。","f":"noa"},{"t":"d","s":"「……どうしたの？」","f":"noa"},{"t":"d","s":"「ううん。おいしい」","f":"noa"},{"t":"d","s":"「でも、箸がとまってる」","f":"noa"},{"t":"d","s":"「だいじょうぶ」","f":"noa"},{"t":"n","s":"乃亜は、じっと耀平を見た。けれど、何も聞かなかった。","f":"noa"},{"t":"n","s":"食後、二人はベランダに出た。冬の空気は澄んでいて、星が高く瞬いていた。","f":"noa"},{"t":"d","s":"「ねえ、耀平」","f":"noa"},{"t":"d","s":"「なに」","f":"noa"},{"t":"d","s":"「これ」","f":"noa"},{"t":"n","s":"乃亜が差し出したのは、小さな包みだった。開けると、手編みのマフラーが入っていた。少し編み目が不揃いで、端がほつれている。","f":"noa"},{"t":"d","s":"「……これ」","f":"noa"},{"t":"d","s":"「ま、まえのチョコよりは、うまくできたと思う」","f":"noa"},{"t":"d","s":"「すごい」","f":"noa"},{"t":"d","s":"「そ、そんなに見ないで。はずかしいから」","f":"noa"},{"t":"n","s":"耀平は、マフラーを首に巻いた。毛糸の匂いがした。あたたかかった。","f":"yohei"},{"t":"d","s":"「ありがとう」","f":"yohei"},{"t":"d","s":"「……うん」","f":"yohei"},{"t":"d","s":"「おれも、これ」","f":"yohei"},{"t":"n","s":"耀平がポケットから取り出したのは、小さな木の札だった。不器用な字で、「の」と「あ」の文字が彫られている。","f":"yohei"},{"t":"d","s":"「おじいちゃんに、教わって、つくった。お守り」","f":"yohei"},{"t":"d","s":"「……」","f":"yohei"},{"t":"d","s":"「へたでごめん」","f":"yohei"},{"t":"d","s":"「へたじゃ、ない」","f":"yohei"},{"t":"n","s":"乃亜は、その木札を両手で包むように持った。声が、少しだけ震えている。","f":"noa"},{"t":"d","s":"「大事にする」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「ずっと、大事にする」","f":"noa"},{"t":"n","s":"夜空に、小さな雪が舞い始めた。二人は、並んで空を見上げていた。耀平の首のマフラーが、ふわりと風に揺れる。","f":"yohei"},{"t":"n","s":"家に帰ると、祖父は炬燵で、一人で茶をすすっていた。","f":"yohei"},{"t":"d","s":"「ただいま」","f":"yohei"},{"t":"d","s":"「おかえり。……ええ顔をしとるのう」","f":"yohei"},{"t":"d","s":"「そうかな」","f":"yohei"},{"t":"d","s":"「その首のは、乃亜ちゃんか」","f":"yohei"},{"t":"d","s":"「うん。あったかい」","f":"yohei"},{"t":"d","s":"「そうか」","f":"yohei"},{"t":"n","s":"祖父は、ゆっくりと湯呑みを置いた。","f":"yohei"},{"t":"d","s":"「耀平。覚えておけ」","f":"yohei"},{"t":"d","s":"「なに？」","f":"yohei"},{"t":"d","s":"「人から貰った温もりは、ちゃんと返せる人間になれ」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「それが、強さの、いちばん根っこじゃ」","f":"yohei"},{"t":"n","s":"耀平は、その言葉の意味を、まだ全部は分からなかった。けれど、首元のマフラーを、そっと握りしめた。","f":"yohei"},{"t":"n","s":"外では、雪が静かに降り続けていた。","f":"yohei"}]}]},{"n":5,"title":"竜馬との喧嘩","sub":"小学校・六年生","era":"elem","lead":"言い返さない耀平に、竜馬は苛立ちを募らせる。そして放課後、二人の距離は、一度だけ最悪の形で縮まる。","scenes":[{"key":"5-1","title":"見えないところで","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily1","cast":["yohei","noa","ryoma"],"lines":[{"t":"n","s":"六年生の春。耀平の背は伸び、手のひらの肉刺はさらに厚くなった。相変わらず、授業中はほとんど眠そうな顔をしている。","f":"yohei"},{"t":"d","s":"「耀平、起きて。先生こっち見てる」","f":"yohei"},{"t":"d","s":"「……起きてる」","f":"yohei"},{"t":"d","s":"「目、閉じてる」","f":"yohei"},{"t":"d","s":"「考えてる」","f":"yohei"},{"t":"d","s":"「考えてる顔じゃないよ」","f":"yohei"},{"t":"n","s":"隣の席から、乃亜が小声で肘をつつく。耀平は、むにゃ、と返事にならない返事をして、また瞼を落とした。","f":"noa"},{"t":"n","s":"乃亜は、ため息をつきながらも、ノートの端に今日の宿題の範囲を書いて、そっと耀平の机にずらした。毎日のことだった。","f":"noa"},{"t":"n","s":"休み時間。廊下を歩いていた耀平の耳に、数人の笑い声が届いた。","f":"yohei"},{"t":"d","s":"「あいつだろ、“一花”の」","f":"yohei"},{"t":"d","s":"「まだ木刀もってんの？　ださ」","f":"yohei"},{"t":"d","s":"「花びら出して、チャンバラごっこかよ」","f":"yohei"},{"t":"n","s":"耀平は、聞こえなかったふりをして通り過ぎた。いつものことだった。慣れていた。いや、慣れたというより、気にならなかった。祖父の言葉があったからだ。弱い人間ほど、よく吠える。そう言って笑う祖父の顔が、耀平の頭のどこかに、いつも居座っていた。","f":"yohei","m":"happy"},{"t":"n","s":"翌日の昼休み。昨日の三人組のうちの一人が、頬を腫らして登校してきた。","f":"yohei"},{"t":"d","s":"「どうしたの、それ」","f":"yohei"},{"t":"d","s":"「……転んだ」","f":"yohei"},{"t":"d","s":"「転んだにしては、変なとこ腫れてるぞ」","f":"yohei"},{"t":"d","s":"「うるさい！」","f":"yohei"},{"t":"n","s":"別の一人は、昨日まで偉そうに笑っていたくせに、廊下で耀平を見るなり、目を逸らして遠回りしていった。","f":"yohei"},{"t":"n","s":"耀平は、不思議そうに首をかしげた。","f":"yohei"},{"t":"d","s":"「ねえ、乃亜。あの人たち、最近おとなしいね」","f":"yohei"},{"t":"d","s":"「……そうだね」","f":"yohei"},{"t":"d","s":"「なんでだろう」","f":"yohei"},{"t":"d","s":"「さあ」","f":"yohei"},{"t":"n","s":"乃亜は、窓の外を見たまま答えた。校庭の隅の、焼却炉の裏。そこから、竜馬が一人で歩いてくるのが見えた。右手の拳に、小さな擦り傷がある。","f":"noa"},{"t":"n","s":"乃亜は、ほんの少しだけ眉を寄せて、それから、何も見なかったふりをした。","f":"noa"}]},{"key":"5-2","title":"放課後の呼び出し","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily2","cast":["ryoma","yohei","noa"],"lines":[{"t":"n","s":"それは、六月の終わりだった。梅雨の合間の、蒸し暑い日。"},{"t":"n","s":"帰りの会が終わると、竜馬が、耀平の机の前に立った。","f":"ryoma"},{"t":"d","s":"「おい、耀平」","f":"ryoma"},{"t":"d","s":"「なに？」","f":"ryoma"},{"t":"d","s":"「ちょっと来い」","f":"ryoma"},{"t":"d","s":"「どこに」","f":"ryoma"},{"t":"d","s":"「裏。誰もいないとこだ」","f":"ryoma"},{"t":"n","s":"教室が、ざわついた。乃亜が、がたん、と椅子を引いて立ち上がる。","f":"noa"},{"t":"d","s":"「竜馬、なにするつもり」","f":"noa"},{"t":"d","s":"「乃亜には関係ねえ」","f":"noa"},{"t":"d","s":"「関係ある。耀平は」","f":"noa"},{"t":"d","s":"「いいよ、乃亜」","f":"noa"},{"t":"n","s":"耀平は、のそりと立ち上がって、いつもの眠そうな顔のまま、小さく笑った。","f":"yohei","m":"happy"},{"t":"d","s":"「すぐもどる」","f":"yohei"},{"t":"d","s":"「……ほんとに？」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"n","s":"乃亜は、唇を噛んだ。けれど、それ以上は止められなかった。止められないのだと、分かってしまったからだ。竜馬の目に、冗談の色は、ひとつもなかった。","f":"noa"},{"t":"n","s":"校舎の裏手。古い体育倉庫の脇の、人気のない空き地。雑草が、膝ほどまで伸びている。","f":"noa"},{"t":"n","s":"竜馬は、足を止めて、振り返った。","f":"ryoma"},{"t":"d","s":"「なあ、耀平」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「おまえ、なんで言い返さねえんだよ」","f":"ryoma"},{"t":"d","s":"「……なんでって」","f":"ryoma"},{"t":"d","s":"「バカにされてんだぞ。スキルのことも、木刀のことも。なのに、へらへらして。毎日、毎日、眠そうな顔して」","f":"ryoma"},{"t":"n","s":"竜馬の拳が、ぎゅっと握られる。","f":"ryoma"},{"t":"d","s":"「おれは、がんばってんだよ。毎日、毎日、火の出し方を練習して、親父にも殴られて。なのに、おまえは、何にもしてねえ顔して、おれより……」","f":"ryoma"},{"t":"n","s":"言葉が、途切れた。竜馬は、自分が何を言おうとしていたのか、分からなくなったようだった。","f":"ryoma"},{"t":"d","s":"「おれより、何？」","f":"ryoma"},{"t":"d","s":"「うるせえ！」","f":"ryoma"},{"t":"n","s":"竜馬が、地面を蹴った。","f":"ryoma"},{"t":"n","s":"拳が飛んでくる。耀平は、半歩だけ下がって、それをかわした。二発目。三発目。どれも、重い。竜馬は、体も大きく、力も強かった。けれど、動きが、あまりに真っ直ぐだった。","f":"yohei"},{"t":"d","s":"「くそっ、避けんな！」","f":"yohei"},{"t":"d","s":"「あたったら、いたいから」","f":"yohei"},{"t":"d","s":"「あたり前だろ！」","f":"yohei"},{"t":"n","s":"耀平は、息を吸った。毎朝、庭で木刀を振り続けてきた足腰が、自然と、体を支える。竜馬の拳が空を切った一瞬、懐に滑り込んで、掌底を腹に叩き込んだ。","f":"yohei"},{"t":"d","s":"「ぐっ……」","f":"yohei"},{"t":"n","s":"竜馬が、膝をつく。耀平は、そこで止まった。追撃はしなかった。","f":"ryoma"},{"t":"d","s":"「もう、やめよう」","f":"ryoma"},{"t":"d","s":"「……ふざけんな」","f":"ryoma"},{"t":"d","s":"「竜馬、けがするよ」","f":"ryoma"},{"t":"d","s":"「ふざけんなあああっ！」","f":"ryoma"},{"t":"n","s":"竜馬が、叫んだ。","f":"ryoma"}]},{"key":"5-3","title":"紅蓮","bg":"bg_classroom_middle","dark":true,"mood":"battle","bgm":"battle1","cast":["ryoma","yohei","noa"],"lines":[{"t":"n","s":"空気が、変わった。"},{"t":"n","s":"竜馬の全身から、赤い熱が噴き上がる。足元の雑草が、じりじりと縮れて、灰に変わっていく。彼の掌の中で、小さな火の玉が、ぐるぐると膨らんでいった。","f":"ryoma"},{"t":"d","s":"「竜馬……？」","f":"ryoma"},{"t":"d","s":"「負けねえ……！　おまえにだけは、負けねえ……！」","f":"ryoma"},{"t":"n","s":"小学生が出す火力ではなかった。いや、出していいものではなかった。竜馬自身の顔が、青ざめている。止めたいのに、止まらない。感情が昂ぶりすぎて、スキルが、手綱を離れて暴れていた。","f":"ryoma"},{"t":"d","s":"「竜馬、それ、やばい。やめて」","f":"ryoma"},{"t":"d","s":"「うるせえ！　もう、とまんねえんだよ！」","f":"ryoma"},{"t":"n","s":"火の玉が、爆ぜた。","f":"ryoma"},{"t":"d","s":"「紅蓮――爆炎ッ！」","f":"ryoma"},{"t":"n","s":"赤い奔流が、耀平を飲み込んだ。","f":"yohei"},{"t":"n","s":"轟音と熱風が、空き地を薙ぎ払う。体育倉庫の壁が焦げて、窓ガラスが割れた。教室の窓から、悲鳴が上がる。","f":"yohei","fx":"shake"},{"t":"n","s":"煙が、ゆっくり晴れていく。","f":"yohei"},{"t":"n","s":"竜馬は、肩で息をしながら、その中心を見つめていた。そして、凍りついた。","f":"ryoma"},{"t":"n","s":"耀平は、立っていた。","f":"yohei"},{"t":"n","s":"制服の袖は焼け焦げ、頬と腕には、赤い火傷の跡がある。膝は、少し笑っている。それでも、倒れていなかった。木刀を握った右手を、前に突き出すようにして、全身で、炎を受け止めていた。","f":"yohei"},{"t":"d","s":"「……いたい」","f":"yohei"},{"t":"d","s":"「な……」","f":"yohei"},{"t":"d","s":"「でも、だいじょうぶ」","f":"yohei"},{"t":"n","s":"耀平の足元には、焦げた草の中に、小さな桜の花びらが、ひらり、ひらりと舞い落ちていた。竜馬は、それを見たはずだった。けれど、頭が追いつかなかった。","f":"yohei"},{"t":"d","s":"「なんで……」","f":"yohei"},{"t":"d","s":"「毎日、振ってるから」","f":"yohei"},{"t":"d","s":"「は……？」","f":"yohei"},{"t":"d","s":"「おじいちゃんが、毎日やってれば、体は覚えるって」","f":"yohei"},{"t":"n","s":"耀平は、ゆっくりと、一歩、前に出た。","f":"yohei"},{"t":"d","s":"「竜馬。もう、いい？」","f":"yohei"},{"t":"d","s":"「……っ」","f":"yohei"},{"t":"d","s":"「竜馬は、がんばってる。それは、おれ、知ってる」","f":"yohei"},{"t":"n","s":"竜馬の手から、火が消えた。膝が、がくりと折れる。","f":"ryoma"},{"t":"d","s":"「おれ……おれは……」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「殺す、つもりじゃ……」","f":"ryoma"},{"t":"d","s":"「うん。分かってる」","f":"ryoma"},{"t":"n","s":"竜馬の目から、ぽろぽろと、涙がこぼれ落ちた。悔しさと、恐怖と、自分への情けなさが、いっぺんに溢れ出していた。","f":"ryoma","m":"sad"},{"t":"d","s":"「ごめん……ごめん……」","f":"ryoma"},{"t":"d","s":"「いいよ」","f":"ryoma"},{"t":"d","s":"「よくねえだろ……」","f":"ryoma"},{"t":"d","s":"「いいよ。おれ、生きてるから」","f":"ryoma"},{"t":"n","s":"耀平は、へらりと笑った。竜馬は、顔を覆って泣いた。","f":"yohei","m":"sad"},{"t":"n","s":"駆けつけてきた先生と、乃亜が、同時に空き地に飛び込んできた。","f":"noa"},{"t":"d","s":"「耀平！」","f":"noa"},{"t":"n","s":"乃亜は、耀平の姿を見るなり、顔から血の気が引いた。","f":"noa"},{"t":"d","s":"「どうしたの、これ！　火傷……！」","f":"noa"},{"t":"d","s":"「だいじょうぶ。見た目ほどじゃないよ」","f":"noa"},{"t":"d","s":"「だいじょうぶじゃない！　はやく保健室！」","f":"noa"},{"t":"n","s":"先生は、焦げた地面と、倒れた竜馬と、耀平の火傷を順に見て、絶句していた。","f":"ryoma"},{"t":"d","s":"「何があった」","f":"ryoma"},{"t":"d","s":"「……おれが、やりました」","f":"ryoma"},{"t":"n","s":"竜馬が、顔を上げずに言った。","f":"ryoma"},{"t":"d","s":"「おれが、耀平に、殺す気で……」","f":"ryoma"},{"t":"d","s":"「竜馬」","f":"ryoma"},{"t":"n","s":"耀平は、先生を見た。","f":"yohei"},{"t":"d","s":"「ちがいます。ぼくたち、ふざけてて、ちょっとやりすぎちゃっただけです」","f":"yohei"},{"t":"d","s":"「ふざけて、って……」","f":"yohei"},{"t":"d","s":"「ほんとうに。ぼくが悪いんです」","f":"yohei"},{"t":"n","s":"先生は、何かを言いかけて、やめた。耀平の目が、あまりにも真っ直ぐだったからだ。","f":"yohei"}]},{"key":"5-4","title":"保健室","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily4","cast":["noa","ryoma","yohei"],"lines":[{"t":"n","s":"保健室のベッドで、耀平は、包帯を巻かれていた。","f":"yohei"},{"t":"n","s":"診察をした養護の先生が、首をひねっている。","f":"yohei"},{"t":"d","s":"「おかしいわね。あれだけの火力を受けて、ほとんど軽症だなんて」","f":"yohei"},{"t":"d","s":"「体、じょうぶなので」","f":"yohei"},{"t":"d","s":"「それだけで説明がつく範囲じゃないんだけど……」","f":"yohei"},{"t":"d","s":"「毎日、剣を振ってるので」","f":"yohei"},{"t":"n","s":"先生は、それ以上は聞かなかった。後遺症も、残りそうになかった。ただ、一週間は安静にするようにと言って、部屋を出ていった。","f":"yohei"},{"t":"n","s":"カーテンの向こうで、静かな足音が止まる。","f":"yohei"},{"t":"d","s":"「……入っていい？」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"n","s":"乃亜が、そっとカーテンをくぐった。目が、真っ赤に腫れている。","f":"noa"},{"t":"d","s":"「泣いたの？」","f":"noa"},{"t":"d","s":"「泣いてない」","f":"noa"},{"t":"d","s":"「目、まっか」","f":"noa"},{"t":"d","s":"「……ばか」","f":"noa"},{"t":"n","s":"乃亜は、ベッドの端に腰かけて、ぎゅっと自分のスカートを握りしめた。","f":"noa"},{"t":"d","s":"「なんで、やられっぱなしだったの」","f":"noa"},{"t":"d","s":"「やられっぱなしじゃないよ。一回、お腹、殴った」","f":"noa"},{"t":"d","s":"「そういうことじゃなくて」","f":"noa"},{"t":"d","s":"「……うん」","f":"noa"},{"t":"d","s":"「なんで、先生に、本当のこと言わなかったの」","f":"noa"},{"t":"n","s":"耀平は、天井を見つめた。","f":"yohei"},{"t":"d","s":"「竜馬は、ほんとは、悪い子じゃないから」","f":"yohei"},{"t":"d","s":"「悪い子じゃなくても、やっちゃいけないことだよ」","f":"yohei"},{"t":"d","s":"「うん。でも、竜馬、自分が一番、分かってると思う」","f":"yohei"},{"t":"d","s":"「……」","f":"yohei"},{"t":"d","s":"「あの顔、見たでしょ」","f":"yohei"},{"t":"n","s":"乃亜は、黙った。確かに、見た。座り込んで、ぐしゃぐしゃに泣いていた、あの横顔を。","f":"noa","m":"sad"},{"t":"d","s":"「それにね」","f":"noa"},{"t":"d","s":"「それに？」","f":"noa"},{"t":"d","s":"「竜馬、おれがバカにされたとき、たぶん、陰で殴ってくれてたよね」","f":"noa"},{"t":"n","s":"乃亜が、はっと顔を上げた。","f":"noa"},{"t":"d","s":"「……知ってたの」","f":"noa"},{"t":"d","s":"「なんとなく。最近、みんな、おとなしくなったから」","f":"noa"},{"t":"d","s":"「竜馬、本人には、絶対言わないよ」","f":"noa"},{"t":"d","s":"「うん。だから、おれも、言わない」","f":"noa"},{"t":"n","s":"耀平は、小さく笑った。","f":"yohei","m":"happy"},{"t":"d","s":"「竜馬はさ、素直じゃないだけなんだよ」","f":"yohei"},{"t":"d","s":"「……なんで、あんたが、そんなに分かってるの」","f":"yohei"},{"t":"d","s":"「だって、幼稚園のとき、いっしょに遊んだから」","f":"yohei"},{"t":"n","s":"乃亜は、何も言えなかった。胸の奥が、ぎゅっと痛んだ。耀平は、誰よりも傷ついているはずなのに、誰よりも、人を見ている。","f":"noa"},{"t":"d","s":"「ねえ、乃亜」","f":"noa"},{"t":"d","s":"「なに」","f":"noa"},{"t":"d","s":"「おれ、強くなるよ」","f":"noa"},{"t":"n","s":"耀平の声は、静かだった。いつもの眠そうな調子とは、少し違っていた。","f":"yohei"},{"t":"d","s":"「今日、思った。おれ、まだ、全然、足りないって。竜馬が本気出したのに、おれ、立ってるだけで精一杯だった」","f":"yohei"},{"t":"d","s":"「……うん」","f":"yohei"},{"t":"d","s":"「もっと、強くなる。誰にも、あんな顔、させないくらいに」","f":"yohei"},{"t":"d","s":"「誰にも？」","f":"yohei"},{"t":"d","s":"「竜馬にも。乃亜にも」","f":"yohei"},{"t":"n","s":"乃亜は、息を詰めた。","f":"noa"},{"t":"d","s":"「だからさ、見ててよ」","f":"noa"},{"t":"n","s":"耀平は、顔を横に向けて、乃亜を見た。","f":"yohei"},{"t":"d","s":"「おれが、どこまで行くか」","f":"yohei"},{"t":"n","s":"乃亜の瞳が、潤んだ。けれど、今度は、泣かなかった。","f":"noa"},{"t":"d","s":"「……うん」","f":"noa"},{"t":"d","s":"「ありがとう」","f":"noa"},{"t":"d","s":"「見てる。ずっと、見てるから」","f":"noa"},{"t":"n","s":"カーテンの外では、夕暮れの光が、窓に長い影を落としていた。","f":"noa"},{"t":"n","s":"廊下の隅の壁に、竜馬が背を預けて、座り込んでいた。保健室から漏れてくる二人の声を、じっと、聞いていた。","f":"ryoma"},{"t":"n","s":"拳を、強く握る。爪が、掌に食い込むほどに。","f":"ryoma"},{"t":"d","s":"「……見てろ、か」","f":"ryoma"},{"t":"n","s":"誰にも聞こえない声で、竜馬は呟いた。","f":"ryoma"},{"t":"d","s":"「おれだって、見てるさ」","f":"ryoma"},{"t":"n","s":"それから、竜馬は、立ち上がった。涙の跡を、袖で乱暴に拭って、振り返らずに、廊下を歩き去っていった。","f":"ryoma","m":"sad"}]}]},{"n":6,"title":"乃亜との約束と卒業式","sub":"小学校・卒業","era":"elem","lead":"言えなかった「ごめん」と、交わした約束。三人は、それぞれの気持ちを抱えたまま小学校を終える。","scenes":[{"key":"6-1","title":"一週間","bg":"bg_classroom_middle","dark":false,"mood":"soft","bgm":"soft3","cast":["yohei","ryoma","noa"],"lines":[{"t":"n","s":"火傷は、一週間もすると、跡も残さず消えてしまった。"},{"t":"n","s":"保健室の先生は何度も首をかしげていたが、耀平本人は、あっけらかんとしていた。","f":"yohei"},{"t":"d","s":"「ほら、もうなおった」","f":"yohei"},{"t":"d","s":"「なおった、じゃないわよ」","f":"yohei"},{"t":"d","s":"「ほんとだって」","f":"yohei"},{"t":"d","s":"「……ちゃんと、お医者さんにも見てもらったほうがいいと思う」","f":"yohei"},{"t":"d","s":"「だいじょうぶ。おじいちゃんも、へいきって言ってた」","f":"yohei"},{"t":"n","s":"乃亜は、疑わしそうに耀平の腕を覗き込んだ。白い肌には、赤みひとつ残っていない。","f":"noa"},{"t":"d","s":"「……変な体」","f":"noa"},{"t":"d","s":"「ほめてる？」","f":"noa"},{"t":"d","s":"「ほめてない」","f":"noa"},{"t":"n","s":"教室の席に戻ると、竜馬の姿はなかった。喧嘩の翌日から、竜馬は三日間、学校を休んでいた。四日目に登校してきたときも、誰とも目を合わせようとせず、昼休みには、いつの間にか教室から消えていた。","f":"ryoma"},{"t":"d","s":"「竜馬、まだ来づらいのかな」","f":"ryoma"},{"t":"d","s":"「あんたのせいじゃないでしょ」","f":"ryoma"},{"t":"d","s":"「でも、おれのせいでもあるし」","f":"ryoma"},{"t":"d","s":"「違う」","f":"ryoma"},{"t":"n","s":"乃亜は、短く言い切った。","f":"noa"},{"t":"d","s":"「竜馬が、自分で選んだことでしょ」","f":"noa"},{"t":"n","s":"耀平は、少し考えて、それから、小さく頷いた。","f":"yohei"},{"t":"d","s":"「……そうだね」","f":"yohei"},{"t":"n","s":"先生たちは、結局、喧嘩の件を大きくはしなかった。竜馬の親が学校に呼ばれて、深く頭を下げた。耀平の祖父も呼ばれたが、祖父は、焦げた地面を眺めて、ひとことだけ言ったという。","f":"ryoma"},{"t":"d","s":"「子どもの喧嘩です。わしの孫も、悪かった」","f":"ryoma"},{"t":"n","s":"それきりだった。","f":"ryoma"}]},{"key":"6-2","title":"竜馬の背中","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily3","cast":["ryoma","yohei"],"lines":[{"t":"n","s":"夏休み前の最後の日。教室の掃除が終わって、みんなが帰っていく中、耀平は一人で、校舎の裏の花壇に水をやっていた。","f":"yohei"},{"t":"n","s":"背後で、砂利を踏む足音がした。","f":"yohei"},{"t":"d","s":"「……おい」","f":"yohei"},{"t":"n","s":"振り向くと、竜馬が立っていた。ポケットに手を突っ込んで、そっぽを向いている。","f":"ryoma"},{"t":"d","s":"「竜馬」","f":"ryoma"},{"t":"d","s":"「……水やり、当番だったか」","f":"ryoma"},{"t":"d","s":"「ううん。ひま、だったから」","f":"ryoma"},{"t":"d","s":"「ふーん」","f":"ryoma"},{"t":"n","s":"沈黙。蝉の声だけが、やけにうるさく降ってくる。","f":"ryoma"},{"t":"d","s":"「……あのさ」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「あの、時」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「……」","f":"ryoma"},{"t":"n","s":"竜馬の口が、何度か開いて、何度か閉じた。ようやく出てきたのは、ひどく不器用な言葉だった。","f":"ryoma"},{"t":"d","s":"「……火傷、なおったのか」","f":"ryoma"},{"t":"d","s":"「うん。もう、きれいになった」","f":"ryoma"},{"t":"d","s":"「そっか」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「……そっか」","f":"ryoma"},{"t":"n","s":"竜馬は、足元の小石を蹴った。それは、かつん、と乾いた音を立てて、花壇の縁に当たった。","f":"ryoma"},{"t":"d","s":"「おれ、おまえに、あやまる気は、ねえ」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「あやまったって、あの火は、消えねえし」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「でも」","f":"ryoma"},{"t":"n","s":"竜馬の声が、少しだけ、震えた。","f":"ryoma"},{"t":"d","s":"「次は、ぜってえ、止めてみせる」","f":"ryoma"},{"t":"n","s":"耀平は、じょうろを下ろして、竜馬を見た。","f":"yohei"},{"t":"d","s":"「止める？」","f":"yohei"},{"t":"d","s":"「あの火を。自分で。おれの、スキルを」","f":"yohei"},{"t":"d","s":"「……うん」","f":"yohei"},{"t":"d","s":"「だから、おまえ、中学でも、逃げんなよ」","f":"yohei"},{"t":"d","s":"「にげないよ」","f":"yohei"},{"t":"d","s":"「おれは、強くなる。おまえよりも、ぜってえ強くなる」","f":"yohei"},{"t":"d","s":"「いいね」","f":"yohei"},{"t":"d","s":"「だから……」","f":"yohei"},{"t":"n","s":"竜馬は、そこで言葉を切った。そして、小さな声で、ほとんど独り言のように言った。","f":"ryoma"},{"t":"d","s":"「……もう、あんな顔、させねえ」","f":"ryoma"},{"t":"n","s":"耀平には、それが何を指しているのか、よく分からなかった。でも、聞き返しはしなかった。","f":"yohei"},{"t":"d","s":"「じゃあ、おれも、もっと強くなる」","f":"yohei"},{"t":"d","s":"「は？」","f":"yohei"},{"t":"d","s":"「竜馬が強くなるなら、おれも、置いてかれたくないから」","f":"yohei"},{"t":"d","s":"「……ちっ」","f":"yohei"},{"t":"n","s":"竜馬は、舌打ちをして、背を向けた。けれど、その背中は、前よりも少しだけ、まっすぐに見えた。","f":"ryoma"},{"t":"d","s":"「じゃあな」","f":"ryoma"},{"t":"d","s":"「うん。またね」","f":"ryoma"},{"t":"d","s":"「……おう」","f":"ryoma"},{"t":"n","s":"去っていく竜馬の背中を見送りながら、耀平は、じょうろの水を、花壇にゆっくりと注いだ。","f":"ryoma"}]},{"key":"6-3","title":"秋の約束","bg":"bg_riverside","dark":false,"mood":"soft","bgm":"soft1","cast":["noa","yohei"],"lines":[{"t":"n","s":"秋になった。中学受験をする子たちが、少しずつ、教室から机を空けていく。"},{"t":"n","s":"耀平の進学先は、もう決まっていた。祖父が、役所で取り寄せてくれた案内書の、一番上の学校。全寮制の、スキル持ちの子どもたちを集めた中学校だった。","f":"yohei"},{"t":"d","s":"「……やっぱり、行くんだね」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「寮、なんだよね」","f":"yohei"},{"t":"d","s":"「うん。おじいちゃん、ひとりになるけど、行けって」","f":"yohei"},{"t":"d","s":"「……そう」","f":"yohei"},{"t":"n","s":"乃亜は、ブランコの鎖を握ったまま、俯いた。","f":"noa"},{"t":"n","s":"夕暮れの公園。ブランコがきい、きい、と小さく軋む。","f":"noa"},{"t":"d","s":"「乃亜は、受かったんでしょ」","f":"noa"},{"t":"d","s":"「うん。同じとこ」","f":"noa"},{"t":"d","s":"「やった」","f":"noa"},{"t":"d","s":"「やった、じゃないでしょ。わたしが、勉強、どれだけ」","f":"noa"},{"t":"d","s":"「ごめん。ありがとう」","f":"noa"},{"t":"d","s":"「……ふん」","f":"noa"},{"t":"n","s":"乃亜は、ふいっと顔を逸らした。耳が、夕日の色に染まっている。","f":"noa"},{"t":"d","s":"「でもね、耀平」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「中学に行ったら、きっと、いろんなことが変わる」","f":"noa"},{"t":"d","s":"「そうかな」","f":"noa"},{"t":"d","s":"「規格外とか、強い人とか、いっぱい出てくる。わたしは、たぶん、ついていけなくなる」","f":"noa"},{"t":"d","s":"「そんなことないよ」","f":"noa"},{"t":"d","s":"「あるよ」","f":"noa"},{"t":"n","s":"乃亜は、静かに言った。","f":"noa"},{"t":"d","s":"「わたしのスキルは、水を、少しだけ操れるだけ。耀平みたいに、強くなれるわけじゃない」","f":"noa"},{"t":"d","s":"「乃亜」","f":"noa"},{"t":"d","s":"「だから、ね」","f":"noa"},{"t":"n","s":"乃亜が、ブランコから降りた。そして、耀平の前に立って、小さな手を差し出した。","f":"noa"},{"t":"d","s":"「約束して」","f":"noa"},{"t":"d","s":"「なにを」","f":"noa"},{"t":"d","s":"「どこまで強くなっても、どこに行っても、最後は、ちゃんと、わたしのところに帰ってくるって」","f":"noa"},{"t":"n","s":"耀平は、きょとんとして、乃亜の手を見た。","f":"yohei"},{"t":"d","s":"「……帰る？」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「おれの家、おじいちゃんの家だけど」","f":"yohei"},{"t":"d","s":"「そういうことじゃない」","f":"yohei"},{"t":"d","s":"「どういうこと？」","f":"yohei"},{"t":"d","s":"「……ばか」","f":"yohei"},{"t":"n","s":"乃亜は、真っ赤になって俯いた。それでも、手は引っ込めなかった。","f":"noa"},{"t":"n","s":"耀平は、しばらく考えていた。それから、ゆっくりと、乃亜の手を握った。","f":"yohei"},{"t":"d","s":"「うん。分かった」","f":"yohei"},{"t":"d","s":"「ほんとに、分かってる？」","f":"yohei"},{"t":"d","s":"「分かってない」","f":"yohei"},{"t":"d","s":"「……ほら」","f":"yohei"},{"t":"d","s":"「でも、帰ってくる。それは、約束する」","f":"yohei"},{"t":"cg","v":"cg_promise"},{"t":"n","s":"乃亜は、顔を上げた。夕日が、彼女の瞳に映っている。","f":"noa"},{"t":"d","s":"「どこに行っても？」","f":"noa"},{"t":"d","s":"「どこに行っても」","f":"noa"},{"t":"d","s":"「ずっと？」","f":"noa"},{"t":"d","s":"「ずっと」","f":"noa"},{"t":"n","s":"乃亜の目から、ぽろ、と一粒、涙がこぼれた。慌てて拭って、無理やり笑う。","f":"noa","m":"sad"},{"t":"d","s":"「……約束、したからね」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「破ったら、水ぶっかけるから」","f":"noa"},{"t":"d","s":"「それは、いやだ」","f":"noa"},{"t":"d","s":"「じゃあ、破らないで」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"n","s":"握り合った手の上に、枯れかけた桜の葉が、ひらりと一枚、落ちてきた。","f":"noa"}]},{"key":"6-4","title":"卒業式","bg":"bg_graduation","dark":false,"mood":"climax","bgm":"climax1","cast":["yohei","ryoma","noa"],"lines":[{"t":"n","s":"三月。校庭の桜は、まだ蕾だった。"},{"t":"n","s":"卒業式の朝、耀平は、慣れない制服の襟を引っ張りながら、体育館の隅に立っていた。保護者席には、背広を着た祖父が、静かに座っている。少し、痩せたように見えた。","f":"yohei"},{"t":"d","s":"「……おじいちゃん、きたね」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「痩せた？」","f":"yohei"},{"t":"d","s":"「そう、かな」","f":"yohei"},{"t":"d","s":"「ちゃんと、食べてる？」","f":"yohei"},{"t":"d","s":"「たぶん」","f":"yohei"},{"t":"n","s":"隣の列から、乃亜が不安そうに覗き込む。耀平は、「だいじょうぶ」と笑ってみせたが、その視線は、祖父の背中から離れなかった。","f":"noa"},{"t":"n","s":"式は、粛々と進んだ。卒業証書を受け取って、校歌を歌って、拍手の中を退場する。","f":"noa"},{"t":"n","s":"校庭に出ると、桜の枝が風に揺れていた。蕾の先が、ほんの少しだけ、ほころびかけている。","f":"noa"},{"t":"d","s":"「おい」","f":"noa"},{"t":"n","s":"聞き慣れた声に振り向くと、竜馬が立っていた。","f":"ryoma"},{"t":"d","s":"「竜馬」","f":"ryoma"},{"t":"d","s":"「同じ中学、なんだろ」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「ま、そうだと思ってた」","f":"ryoma"},{"t":"d","s":"「竜馬も、同じ？」","f":"ryoma"},{"t":"d","s":"「あたり前だろ。親父が、どうしても行けって」","f":"ryoma"},{"t":"d","s":"「そっか」","f":"ryoma"},{"t":"d","s":"「……なあ」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「中学で、決着、つけっからな」","f":"ryoma"},{"t":"d","s":"「いいよ」","f":"ryoma"},{"t":"d","s":"「おまえ、軽いな」","f":"ryoma"},{"t":"d","s":"「だって、約束したから。強くなるって」","f":"ryoma"},{"t":"d","s":"「だれと」","f":"ryoma"},{"t":"d","s":"「乃亜と、竜馬と」","f":"ryoma"},{"t":"n","s":"竜馬は、一瞬、固まった。それから、鼻をこすって、そっぽを向いた。","f":"ryoma"},{"t":"d","s":"「……へっ。じゃあ、約束、守れよ」","f":"ryoma"},{"t":"d","s":"「うん。竜馬も」","f":"ryoma"},{"t":"d","s":"「当然だ」","f":"ryoma"},{"t":"n","s":"二人は、拳を軽く、ごつ、とぶつけ合った。幼稚園の頃、木の枝を振り回して遊んだ、あの日と同じように。","f":"ryoma"},{"t":"n","s":"少し離れた木の下で、乃亜が、その様子を見ていた。胸の奥に、あたたかいものと、ちくりとした痛みが、同時に広がる。","f":"noa"},{"t":"d","s":"「……ほんと、ばか」","f":"noa"},{"t":"n","s":"呟いた声は、風に溶けた。","f":"noa"},{"t":"n","s":"式の後、耀平は、祖父と並んで校門を出た。","f":"yohei"},{"t":"d","s":"「おじいちゃん」","f":"yohei"},{"t":"d","s":"「なんじゃ」","f":"yohei"},{"t":"d","s":"「ありがとう。卒業、見に来てくれて」","f":"yohei"},{"t":"d","s":"「当たり前じゃ。孫の晴れ舞台じゃ」","f":"yohei"},{"t":"d","s":"「……ねえ」","f":"yohei"},{"t":"d","s":"「ん？」","f":"yohei"},{"t":"d","s":"「寮に入ったら、おじいちゃん、ひとりになるよ」","f":"yohei"},{"t":"d","s":"「構わん」","f":"yohei"},{"t":"d","s":"「ほんとに？」","f":"yohei"},{"t":"d","s":"「わしは、ひとりでも、やっていける」","f":"yohei"},{"t":"n","s":"祖父は、そう言って、小さく咳き込んだ。耀平は、思わずその背中を支える。","f":"yohei"},{"t":"d","s":"「だいじょうぶ？」","f":"yohei"},{"t":"d","s":"「ああ。少し、風邪気味でな」","f":"yohei"},{"t":"d","s":"「ほんとに？」","f":"yohei"},{"t":"d","s":"「ほんとじゃ」","f":"yohei"},{"t":"n","s":"耀平は、祖父の顔を、じっと見つめた。その目は、穏やかで、少しだけ、遠くを見ているようだった。","f":"yohei"},{"t":"d","s":"「耀平」","f":"yohei"},{"t":"d","s":"「なに」","f":"yohei"},{"t":"d","s":"「おまえは、強くなる。わしには、分かる」","f":"yohei"},{"t":"d","s":"「……うん」","f":"yohei"},{"t":"d","s":"「だから、迷うな。前だけ見ていろ」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「それで、ええんじゃ」","f":"yohei"},{"t":"n","s":"祖父は、孫の頭を、ぽん、と撫でた。大きくて、ごつごつした手だった。いつもと同じ手のはずなのに、なぜか、いつもより、少しだけ軽く感じた。","f":"yohei"},{"t":"n","s":"校門の脇で、桜の蕾が、風に揺れていた。もうすぐ、春が来る。","f":"yohei"},{"t":"n","s":"耀平の、新しい春が。","f":"yohei"}]}]},{"n":7,"title":"祖父の死と学生寮","sub":"中学・1年","era":"middle","lead":"新しい春、新しい部屋。そして、いちばん静かな別れ。","scenes":[{"key":"7-1","title":"入学式","bg":"bg_graduation","dark":false,"mood":"daily","bgm":"daily3","cast":["yohei","ren","noa"],"lines":[{"t":"n","s":"中学校の入学式は、体育館ではなく、広い講堂で行われた。"},{"t":"n","s":"高い天井。磨かれた床。壇上に並ぶ教師たちの背筋は、どれも不思議なほど真っ直ぐだった。新入生は百二十人ほど。全員が、何かしらのスキルを持つ子どもたちだ。"},{"t":"d","s":"「……ひろいな」"},{"t":"d","s":"「当たり前でしょ。全国から集まってるんだから」"},{"t":"d","s":"「そうなんだ」"},{"t":"d","s":"「知らなかったの？」"},{"t":"d","s":"「寝てた」"},{"t":"n","s":"隣の席の乃亜は、頭を押さえた。","f":"noa"},{"t":"n","s":"壇上に、一人の生徒が上がった。","f":"noa"},{"t":"n","s":"制服の着こなしは完璧で、背筋が一本の線のようだった。三年生。生徒会長。胸のバッジが、静かに光っている。","f":"ren"},{"t":"d","s":"「新入生の皆さん。入学おめでとう」","f":"ren"},{"t":"n","s":"よく通る声だった。大きくはないのに、講堂の隅々まで届く。","f":"ren"},{"t":"d","s":"「生徒会長の九条蓮です。この学校には、多くの先輩がいて、多くの仲間がいます。困ったときは、遠慮なく頼ってください」","f":"ren"},{"t":"n","s":"そこまで言って、蓮は、ふと、会場全体を見渡した。","f":"ren"},{"t":"n","s":"ほんの一瞬だけ、耀平と、視線が合った気がした。","f":"yohei"},{"t":"d","s":"「……あの人、強い」","f":"yohei"},{"t":"d","s":"「え？」","f":"yohei"},{"t":"d","s":"「なんとなく。立ってるだけで、すごい」","f":"yohei"},{"t":"d","s":"「耀平、あんたが言うと説得力あるよね」","f":"yohei"},{"t":"d","s":"「え、そう？」","f":"yohei"},{"t":"d","s":"「いい意味じゃないけど」","f":"yohei"},{"t":"n","s":"蓮は、何事もなかったように壇を降りていった。","f":"ren"},{"t":"n","s":"その夜、耀平は荷物を抱えて、学生寮の扉の前に立っていた。","f":"yohei"},{"t":"n","s":"白い壁。木の廊下。二人部屋。同室の少年は、人懐っこく手を振ってきた。","f":"yohei"},{"t":"d","s":"「よろしく！　おれ、佐野。スキルは『加速』。足、ちょっと速くなるだけだけどな！」","f":"yohei"},{"t":"d","s":"「耀平です。スキルは、『一花心舞』」","f":"yohei"},{"t":"d","s":"「いっか、しんぶ？　なんだそれ、かっこいいな！」","f":"yohei"},{"t":"d","s":"「え」","f":"yohei"},{"t":"d","s":"「え？」","f":"yohei"},{"t":"d","s":"「……ううん、なんでも」","f":"yohei"},{"t":"n","s":"耀平は、少し驚いた。馬鹿にされなかったのは、いつ以来だろう。","f":"yohei"},{"t":"n","s":"窓の外では、夜桜が一本、街灯の下で静かに咲いていた。","f":"yohei"}]},{"key":"7-2","title":"ひとりの部屋","bg":"bg_dorm","dark":true,"mood":"night","bgm":"night2","cast":["ren","yohei","ryoma"],"lines":[{"t":"n","s":"寮の朝は早い。耀平は、日の出前に起きて、裏庭に出た。","f":"yohei"},{"t":"n","s":"木刀を握る。構える。振る。","f":"yohei"},{"t":"n","s":"家の庭とは違う、広い芝生。冷たい空気。遠くで、鳥が鳴いている。","f":"yohei"},{"t":"d","s":"「……おじいちゃんの庭と、ちがうな」","f":"yohei"},{"t":"n","s":"ひとりごとのように呟いて、また振る。何度も、何度も。風に乗って、桜の花びらが一枚、また一枚と舞い降りてくる。","f":"yohei"},{"t":"d","s":"「こんな朝から、精が出るな」","f":"yohei"},{"t":"n","s":"不意に、背後から声がした。振り向くと、蓮が立っていた。制服の上着を肩にかけ、静かにこちらを見ている。","f":"ren"},{"t":"d","s":"「会長」","f":"ren"},{"t":"d","s":"「九条でいい。……今の太刀筋、独学か」","f":"ren"},{"t":"d","s":"「はい」","f":"ren"},{"t":"d","s":"「そうか」","f":"ren"},{"t":"n","s":"蓮は、短く頷いただけで、それ以上は何も言わなかった。ただ、足元に落ちた桜の花びらを、ほんの少しだけ長く見つめていた。","f":"ren"},{"t":"d","s":"「あまり無理をしすぎるな。寮は、朝食に遅れると冷める」","f":"ren"},{"t":"d","s":"「はい」","f":"ren"},{"t":"d","s":"「それだけだ」","f":"ren"},{"t":"n","s":"蓮は、そのまま去っていった。耀平は、首をかしげる。","f":"ren"},{"t":"d","s":"「……いい人、なのかな」","f":"ren"},{"t":"n","s":"授業は、ほとんど寝ていた。教師が板書をしているあいだに、まぶたが重くなる。気づけば、乃亜がノートの端に宿題の範囲を書いて、机の隅にそっと置いてくれている。","f":"noa"},{"t":"d","s":"「また寝てた」","f":"noa"},{"t":"d","s":"「ごめん」","f":"noa"},{"t":"d","s":"「謝るなら起きて」","f":"noa"},{"t":"d","s":"「がんばる」","f":"noa"},{"t":"d","s":"「がんばれてない」","f":"noa"},{"t":"n","s":"竜馬も、同じクラスだった。","f":"ryoma"},{"t":"d","s":"「おい、耀平」","f":"ryoma"},{"t":"d","s":"「ん？」","f":"ryoma"},{"t":"d","s":"「放課後、訓練場いくぞ。ひとりだと、つまんねえ」","f":"ryoma"},{"t":"d","s":"「いいの？」","f":"ryoma"},{"t":"d","s":"「別に。おれが勝手に付き合わせるだけだ」","f":"ryoma"},{"t":"n","s":"竜馬の言い方は相変わらず乱暴だったが、小学校の頃のような棘は、もうなかった。","f":"ryoma"}]},{"key":"7-3","title":"電話","bg":"bg_dorm","dark":true,"mood":"night","bgm":"night2","cast":["yohei","noa"],"lines":[{"t":"n","s":"五月の連休が明けた頃だった。"},{"t":"n","s":"寮の電話が鳴ったのは、夜の九時を過ぎてからだった。"},{"t":"d","s":"「耀平くん、電話よ。……おうちから」"},{"t":"n","s":"寮母さんの声が、いつもより少し硬かった。受話器を受け取ると、聞き慣れない女性の声がした。"},{"t":"d","s":"「もしもし。耀平くん？　隣の、山口です」"},{"t":"d","s":"「山口さん。どうしたんですか」"},{"t":"d","s":"「あのね、落ち着いて聞いてね。おじいちゃんが、今朝から、体調をくずして……入院したの」"},{"t":"n","s":"耀平の指先が、冷たくなった。","f":"yohei"},{"t":"d","s":"「……どこの、病院ですか」","f":"yohei"},{"t":"d","s":"「市立の。でもね、お医者さんが、できれば耀平くんを、すぐ呼んだほうがいいって」","f":"yohei"},{"t":"n","s":"受話器を置いた耀平は、しばらく、動けなかった。","f":"yohei"},{"t":"d","s":"「耀平」","f":"yohei"},{"t":"n","s":"振り向くと、乃亜が立っていた。寮母さんから、聞いたのだろう。顔が青い。","f":"noa"},{"t":"d","s":"「……行こう」","f":"noa"},{"t":"d","s":"「乃亜」","f":"noa"},{"t":"d","s":"「一緒に行く。タクシー、呼んでもらった」","f":"noa"},{"t":"d","s":"「いいの？」","f":"noa"},{"t":"d","s":"「あんたを、ひとりで行かせるわけないでしょ」","f":"noa"},{"t":"n","s":"乃亜は、耀平の手を、ぎゅっと握った。冷たい指先だった。けれど、その握力は、驚くほど強かった。","f":"noa"}]},{"key":"7-4","title":"祖父の最期","bg":"bg_classroom_middle","dark":false,"mood":"sad","bgm":"sad1","cast":["yohei","noa"],"lines":[{"t":"n","s":"病院の廊下は、静かで、薬品の匂いがした。"},{"t":"n","s":"白い病室。小さなベッド。その上で、祖父は、細い呼吸をしていた。"},{"t":"d","s":"「……おじいちゃん」"},{"t":"n","s":"祖父は、ゆっくりと目を開けた。そして、孫の姿を見て、ほんの少しだけ、笑った。","m":"happy"},{"t":"d","s":"「……来たか」"},{"t":"d","s":"「うん」"},{"t":"d","s":"「学校は、どうじゃ」"},{"t":"d","s":"「だいじょうぶ。たのしいよ」"},{"t":"d","s":"「そうか。それは、よかった」"},{"t":"n","s":"声は、かすれていた。耀平は、祖父の手を握った。以前より、ずっと細くなっている。","f":"yohei"},{"t":"d","s":"「おじいちゃん、病気だったの？」","f":"yohei"},{"t":"d","s":"「いや。歳じゃ。ただの、歳」","f":"yohei"},{"t":"d","s":"「でも」","f":"yohei"},{"t":"d","s":"「老いて死ぬのは、ええもんじゃ。……ようやく、そこへ行ける」","f":"yohei"},{"t":"d","s":"「そこ、って」","f":"yohei"},{"t":"d","s":"「おまえのお父さんと、お母さんのところじゃ」","f":"yohei"},{"t":"n","s":"耀平の喉が、ひくりと鳴った。四歳のとき、いなくなった人たち。顔も、声も、もう輪郭しか覚えていない。","f":"yohei"},{"t":"d","s":"「……おじいちゃん」","f":"yohei"},{"t":"d","s":"「泣くな。泣くのは、後でええ」","f":"yohei"},{"t":"d","s":"「でも」","f":"yohei"},{"t":"d","s":"「わしの話を、聞け」","f":"yohei"},{"t":"n","s":"祖父は、ゆっくりと息を吸った。","f":"yohei"},{"t":"d","s":"「耀平。おまえの、一花心舞はな」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「バカにされとるじゃろう」","f":"yohei"},{"t":"d","s":"「……うん」","f":"yohei"},{"t":"d","s":"「それでええ。むしろ、ええんじゃ」","f":"yohei"},{"t":"d","s":"「なんで？」","f":"yohei"},{"t":"d","s":"「バカにされとるあいだは、誰も、おまえを警戒せん。……その間に、力を蓄えられる」","f":"yohei"},{"t":"n","s":"祖父の目が、静かに光った。","f":"yohei","fx":"flash"},{"t":"d","s":"「いつか、おまえのスキルが、本物の形を見せる日が来る。そのとき、桜は、ただの桜ではなくなる」","f":"yohei"},{"t":"d","s":"「おじいちゃん、知ってたの？」","f":"yohei"},{"t":"d","s":"「いや。何も知らん。わしは、ただのじいさんじゃ。……ただ、おまえを見ておれば、分かる」","f":"yohei"},{"t":"n","s":"祖父は、ふ、と笑った。","f":"yohei","m":"happy"},{"t":"d","s":"「前だけ見ろ。迷うな。人から貰った温もりは、ちゃんと返せ。……それだけ守れば、おまえは、どこまでも行ける」","f":"yohei"},{"t":"d","s":"「うん。うん」","f":"yohei"},{"t":"d","s":"「乃亜ちゃん」","f":"yohei"},{"t":"n","s":"祖父の視線が、扉の脇で立ち尽くしていた乃亜に向いた。","f":"noa"},{"t":"d","s":"「はい」","f":"noa"},{"t":"d","s":"「この子を、頼む。……だらしのない孫じゃが」","f":"noa"},{"t":"d","s":"「……はい」","f":"noa"},{"t":"d","s":"「頼まれてくれるか」","f":"noa"},{"t":"d","s":"「はい。ずっと」","f":"noa"},{"t":"n","s":"乃亜は、唇を噛んで、深く頭を下げた。","f":"noa"},{"t":"n","s":"祖父は、満足そうに目を閉じた。そして、孫の手を、もう一度だけ、握り返した。","f":"noa"},{"t":"d","s":"「ええ孫を、持ったのう」","f":"noa"},{"t":"n","s":"それが、最後の言葉だった。","f":"noa"},{"t":"n","s":"窓の外では、夜明け前の空が、少しずつ白んできていた。耀平の手の中で、祖父の手の温度が、ゆっくりと、遠くなっていく。","f":"yohei"},{"t":"d","s":"「おじいちゃん……」","f":"yohei"},{"t":"n","s":"返事は、なかった。","f":"yohei"},{"t":"n","s":"病室の窓の隙間から、どこからか風が入り込んで、桜の花びらが一枚、ベッドの上にひらりと落ちた。この季節に、桜が咲いているはずもないのに。","f":"yohei"},{"t":"n","s":"耀平は、声を出さずに、泣いた。","f":"yohei","m":"sad"}]},{"key":"7-5","title":"葬儀と、寮","bg":"bg_dorm","dark":false,"mood":"sad","bgm":"sad1","cast":["yohei","noa","ryoma"],"lines":[{"t":"n","s":"葬儀は、小さく、静かに行われた。"},{"t":"cg","v":"cg_grandpa_funeral"},{"t":"n","s":"参列者は、近所の人たちと、祖父の古い知り合いが数人。耀平は、喪服代わりの制服を着て、黙って最前列に座っていた。","f":"yohei"},{"t":"n","s":"焼香の列の中に、見慣れた背中があった。","f":"yohei"},{"t":"n","s":"竜馬だった。","f":"ryoma"},{"t":"n","s":"黒い礼服。ぎこちなく手を合わせて、深く頭を下げる。それから、耀平の前に来て、何か言いかけて、やめた。","f":"yohei"},{"t":"d","s":"「……」","f":"yohei"},{"t":"d","s":"「ありがとう、来てくれて」","f":"yohei"},{"t":"d","s":"「……おう」","f":"yohei"},{"t":"d","s":"「竜馬」","f":"yohei"},{"t":"d","s":"「……なんだよ」","f":"yohei"},{"t":"d","s":"「ありがとう」","f":"yohei"},{"t":"d","s":"「だから、言うなって」","f":"yohei"},{"t":"n","s":"竜馬は、乱暴に袖で目元を拭った。そして、乱暴な足取りで去っていった。","f":"ryoma"},{"t":"n","s":"葬儀のあと、耀平は、祖父の家に一人で戻った。","f":"yohei"},{"t":"n","s":"縁側。炬燵。古い茶箪笥。庭の隅には、耀平が毎朝木刀を振った跡が、地面にうっすらと残っている。","f":"yohei"},{"t":"n","s":"箪笥の引き出しから、一通の封筒が出てきた。宛名は、不器用な字で、「耀平へ」。","f":"yohei"},{"t":"n","s":"封を切ると、短い手紙が入っていた。","f":"yohei"},{"t":"d","s":"『耀平へ。 この手紙を読んでいるということは、わしは、もうおらんのじゃろう。 おまえは、わしの自慢の孫じゃ。 強くなれ。優しくなれ。そして、ちゃんと、笑え。 乃亜ちゃんを、大事にな。 　　　　　　　　　　　　　　　　　　祖父』","f":"yohei"},{"t":"n","s":"耀平は、その手紙を、胸に抱いた。声を殺して、泣いた。誰もいない縁側で、桜の花びらが、さらさらと舞っていた。","f":"yohei","m":"sad"},{"t":"d","s":"「おじいちゃん……おれ、強くなるよ」","f":"yohei"},{"t":"n","s":"呟いた声は、庭に吸い込まれて消えた。","f":"yohei"},{"t":"cg","v":"cg_dorm_visit"},{"t":"n","s":"その夜、寮に戻ると、乃亜が、玄関で待っていた。","f":"noa"},{"t":"d","s":"「おかえり」","f":"noa"},{"t":"d","s":"「……ただいま」","f":"noa"},{"t":"d","s":"「ごはん、食べた？」","f":"noa"},{"t":"d","s":"「食べてない」","f":"noa"},{"t":"d","s":"「食堂、まだ開いてる。一緒に行こう」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"cg","v":"cg_noa_dinner"},{"t":"n","s":"乃亜は、何も聞かなかった。ただ、並んで歩いた。食堂のテーブルで、向かい合って座った。耀平の前に、湯気の立つ味噌汁が置かれる。","f":"noa"},{"t":"d","s":"「……あったかい」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「おじいちゃんの味噌汁、思い出した」","f":"noa"},{"t":"d","s":"「そう」","f":"noa"},{"t":"d","s":"「また、泣きそう」","f":"noa"},{"t":"d","s":"「泣いていいよ」","f":"noa"},{"t":"d","s":"「でも、ここ食堂だし」","f":"noa"},{"t":"d","s":"「いいよ。見ないでおく」","f":"noa"},{"t":"n","s":"乃亜は、横を向いて、窓の外を見た。耀平は、俯いたまま、味噌汁の湯気に、ぽたりと一粒、涙を落とした。","f":"noa","m":"sad"},{"t":"n","s":"約束は、まだ、守られていた。","f":"noa"}]}]},{"n":8,"title":"修学旅行と肝試し","sub":"中学・1年","era":"middle","lead":"山あいの旅館に、一年生から三年生までが集まった。何も知らない子どもたちの夜は、静かに、それでも確実に近づいてくる。","scenes":[{"key":"8-1","title":"バスの窓","bg":"bg_riverside","dark":false,"mood":"daily","bgm":"daily4","cast":["yohei","ryoma","noa"],"lines":[{"t":"n","s":"十月。中学の合同修学旅行は、県境の山あいにある旅館での二泊三日だった。"},{"t":"n","s":"一年生から三年生までの全員が、大型バスに分かれて乗り込む。窓の外には、色づき始めた山の稜線が流れていく。"},{"t":"d","s":"「耀平、起きてる？」"},{"t":"d","s":"「起きてる」"},{"t":"d","s":"「目、閉じてるけど」"},{"t":"d","s":"「景色を、楽しんでる」"},{"t":"d","s":"「嘘つき」"},{"t":"n","s":"通路を挟んだ席から、乃亜が呆れた顔でこちらを見ていた。","f":"noa"},{"t":"n","s":"耀平はあくびを噛み殺して、窓の外に目を向けた。寮に入って半年。祖父のいない最初の秋だった。","f":"yohei"},{"t":"d","s":"「……山、きれいだね」","f":"yohei"},{"t":"d","s":"「うん。おじいちゃんの庭の、桜の葉っぱに似てる」","f":"yohei"},{"t":"d","s":"「葉っぱ、って」","f":"yohei"},{"t":"d","s":"「赤いところが」","f":"yohei"},{"t":"d","s":"「あんた、ほんとに桜が好きね」","f":"yohei"},{"t":"d","s":"「好きっていうか、気づくと、そこにあるから」","f":"yohei"},{"t":"n","s":"耀平は小さく笑った。","f":"yohei","m":"happy"},{"t":"n","s":"後ろの席で、竜馬が窓にもたれて腕を組んでいた。目を閉じているが、眠ってはいない。耳だけが、前の席の会話を拾っている。","f":"ryoma"},{"t":"d","s":"「……好きなもん、あるだけ、ましだろ」","f":"ryoma"},{"t":"n","s":"誰にも聞こえない声で、竜馬は呟いた。","f":"ryoma"}]},{"key":"8-2","title":"黒い影","bg":"bg_classroom_middle","dark":true,"mood":"tense","bgm":"tense2","cast":["ren","yohei","noa"],"lines":[{"t":"n","s":"二日目の午後は、旅館の裏山のハイキングだった。"},{"t":"n","s":"学年ごとに列を作り、先生の先導で木漏れ日の道を登る。耀平は列の真ん中あたりを、のんびりと歩いていた。","f":"yohei"},{"t":"d","s":"「ねえ、耀平。さっきから、なんか静かじゃない？」","f":"yohei"},{"t":"d","s":"「そう？」","f":"yohei"},{"t":"d","s":"「鳥の声。さっきまで、すごかったのに」","f":"yohei"},{"t":"n","s":"耀平は足を止めて、耳を澄ませた。確かに、鳥の声がない。風も止んでいる。","f":"yohei"},{"t":"d","s":"「……ほんとだ」","f":"yohei"},{"t":"d","s":"「でしょ？」","f":"yohei"},{"t":"d","s":"「なんか、いやな感じ」","f":"yohei"},{"t":"n","s":"その瞬間だった。","f":"yohei"},{"t":"n","s":"列の最後尾の、さらに後ろ。木々の奥で、枝がばきりと折れる音がした。","f":"yohei"},{"t":"d","s":"「誰だ」","f":"yohei"},{"t":"n","s":"低い声が、静寂を切り裂いた。","f":"yohei"},{"t":"n","s":"振り向くと、生徒会長の九条蓮が、列から外れた斜面に立っていた。その視線の先に、黒い外套の男が一人、木の陰からこちらを覗き込んでいる。","f":"ren"},{"t":"d","s":"「……チッ。気づかれたか」","f":"ren"},{"t":"d","s":"「ここは学校行事の最中だ。部外者は立ち入り禁止だぞ」","f":"ren"},{"t":"d","s":"「ガキの遠足に、目を光らせてんじゃねえよ」","f":"ren"},{"t":"n","s":"男が、口の端を持ち上げた。次の瞬間、男の足元の落ち葉が、ぶわりと舞い上がった。","f":"ren"},{"t":"d","s":"「下がっていろ」","f":"ren"},{"t":"n","s":"蓮は短く言った。生徒たちが、ざわつく。先生たちが慌てて前に出ようとして、蓮に手で制された。","f":"ren"},{"t":"d","s":"「大丈夫です。私が対応します」","f":"ren"},{"t":"d","s":"「会長、しかし――」","f":"ren"},{"t":"d","s":"「列を、そのまま進めてください。いつもの行程を崩さないように」","f":"ren"},{"t":"n","s":"蓮の声は静かだった。けれど、有無を言わせない響きがあった。","f":"ren"},{"t":"n","s":"男が、地面を蹴る。拳が、風を割いて蓮の顔面へ迫る。蓮は半歩だけ身を引いて、それをかわし、掌底を男の脇腹に叩き込んだ。","f":"ren"},{"t":"d","s":"「ぐっ……！」","f":"ren"},{"t":"n","s":"鈍い音。男の体が、くの字に折れて吹き飛ぶ。木の幹に叩きつけられて、落ち葉の上に転がった。","f":"ren","fx":"shake"},{"t":"d","s":"「……なんだ、てめえ……ただの中坊じゃ、ねえな」","f":"ren"},{"t":"d","s":"「去れ。今回は見逃す」","f":"ren"},{"t":"n","s":"男は、よろよろと立ち上がって、蓮を睨んだ。それから、舌打ちを一つして、森の奥へ消えていった。","f":"ren","m":"anger"},{"t":"d","s":"「……今の、なに？」","f":"ren"},{"t":"d","s":"「会長、すごい……」","f":"ren"},{"t":"d","s":"「見えた？　今の動き、全然見えなかった」","f":"ren"},{"t":"n","s":"列がざわめく中、耀平は、じっと蓮の背中を見つめていた。","f":"yohei"},{"t":"d","s":"「……あの人、わざと、全力を出してなかった」","f":"yohei"},{"t":"d","s":"「え？」","f":"yohei"},{"t":"d","s":"「全力を出したら、みんなが気づくから。だから、あんなふうに」","f":"yohei"},{"t":"n","s":"乃亜が、驚いた顔で耀平の横顔を見た。","f":"noa"},{"t":"d","s":"「耀平……見えてたの？」","f":"noa"},{"t":"d","s":"「なんとなく。立ち方で、分かる」","f":"noa"},{"t":"n","s":"蓮が、ふと、こちらを振り向いた。ほんの一瞬、視線が合う。蓮は何も言わず、わずかに目を細めただけだった。","f":"ren"}]},{"key":"8-3","title":"会議","bg":"bg_classroom_middle","dark":true,"mood":"tense","bgm":"tense2","cast":["ren","yohei"],"lines":[{"t":"n","s":"その夜。旅館の一番奥の小さな和室に、三人の教師と、蓮が集まっていた。","f":"ren"},{"t":"n","s":"障子は閉められ、廊下には教師が一人、見張りに立っている。","f":"ren"},{"t":"d","s":"「先ほどの男は、おそらく斥候だ」","f":"ren"},{"t":"n","s":"蓮が、静かに切り出した。","f":"ren"},{"t":"d","s":"「斥候……？　どこの、ですか」","f":"ren"},{"t":"d","s":"「分からない。ただ、あの動き、あの口ぶり。ただの不審者ではないでしょう」","f":"ren"},{"t":"d","s":"「しかし会長、生徒たちは何も気づいていません。このまま日程を進めれば、問題は――」","f":"ren"},{"t":"d","s":"「問題は、明日の夜です」","f":"ren"},{"t":"n","s":"蓮は、机の上の行程表を指でなぞった。","f":"ren"},{"t":"d","s":"「一年生の、肝試し」","f":"ren"},{"t":"n","s":"担任の木村が、はっとして顔を上げた。","f":"ren"},{"t":"d","s":"「あの森の、山道を、一年生が班ごとに歩くのですね」","f":"ren"},{"t":"d","s":"「そうです。生徒が分散して、しかも夜に、人気のない森の中へ入る。……もし私が襲撃する側なら、この機会を逃しません」","f":"ren"},{"t":"d","s":"「では、中止にしましょう」","f":"ren"},{"t":"d","s":"「中止にすれば、相手は別の機会を探すだけです。それに、生徒たちに不安を与える」","f":"ren"},{"t":"n","s":"蓮は、一呼吸おいて、続けた。","f":"ren"},{"t":"d","s":"「ですから、予定どおり実施します。ただし、先生方と私が、森の周囲に潜みます。襲撃があれば、すぐに動けるように」","f":"ren"},{"t":"d","s":"「それは……」","f":"ren"},{"t":"d","s":"「生徒たちは、何も知らなくていい。今夜、見聞きしたことは、口外しないでください」","f":"ren"},{"t":"n","s":"教師たちは、しばらく黙っていた。やがて、木村が重い息を吐いた。","f":"ren"},{"t":"d","s":"「……分かりました。会長の判断に、従います」","f":"ren"},{"t":"d","s":"「ありがとうございます」","f":"ren"},{"t":"n","s":"蓮は、窓の外の暗い山を見つめた。","f":"ren"},{"t":"d","s":"「それと、もう一つ」","f":"ren"},{"t":"d","s":"「はい」","f":"ren"},{"t":"d","s":"「一年生に、気になる生徒が一人います」","f":"ren"},{"t":"d","s":"「気になる、というと」","f":"ren"},{"t":"d","s":"「いえ。今は、まだ」","f":"ren"},{"t":"n","s":"蓮は、それ以上は言わなかった。耀平の名前も、あの視線のことも、口にしなかった。","f":"ren"}]},{"key":"8-4","title":"班決め","bg":"bg_classroom_middle","dark":true,"mood":"night","bgm":"night3","cast":["noa","yohei","ryoma"],"lines":[{"t":"n","s":"翌日の午後。旅館の大広間に、一年生が集められた。"},{"t":"d","s":"「それでは、今夜の肝試しの班を発表します。六人一組で、森の山道を一周してきてください」"},{"t":"n","s":"木村が、名簿を読み上げる。"},{"t":"d","s":"「第三班。山下、田中、小川……」"},{"t":"d","s":"「第五班。佐野、耀平、乃亜、中野、小川……」"},{"t":"n","s":"耀平は、乃亜と目を合わせた。","f":"yohei"},{"t":"d","s":"「同じ班だね」","f":"yohei"},{"t":"d","s":"「みたいね」","f":"yohei"},{"t":"d","s":"「よかった」","f":"yohei"},{"t":"d","s":"「なにが」","f":"yohei"},{"t":"d","s":"「知ってる人がいるから」","f":"yohei"},{"t":"d","s":"「……ふん」","f":"yohei"},{"t":"n","s":"乃亜は、そっぽを向いた。耳が少し赤い。","f":"noa","m":"blush"},{"t":"d","s":"「おーい、耀平！　同じ班だな！」","f":"noa"},{"t":"n","s":"寮の同室の佐野が、駆け寄ってきた。","f":"noa"},{"t":"d","s":"「うん、よろしく」","f":"noa"},{"t":"d","s":"「肝試し、楽しみだなあ。お化け役、先輩がやるんだろ？」","f":"noa"},{"t":"d","s":"「そうみたい」","f":"noa"},{"t":"d","s":"「怖がらせてくれるかなあ」","f":"noa"},{"t":"d","s":"「佐野は、怖がり？」","f":"noa"},{"t":"d","s":"「いや、全然！　足が速いから、逃げ切れる！」","f":"noa"},{"t":"d","s":"「それ、怖がりの人が言うやつ」","f":"noa"},{"t":"n","s":"班の残り二人、中野と小川は、少し離れたところで緊張した顔をしていた。","f":"noa"},{"t":"d","s":"「竜馬は、別の班か」","f":"noa"},{"t":"d","s":"「そうみたい」","f":"noa"},{"t":"d","s":"「ふーん」","f":"noa"},{"t":"n","s":"耀平は何気なく呟いて、広間の反対側を見た。竜馬は、別の班の輪の端で、腕を組んでこちらを睨んでいた。目が合うと、ふいと顔を背ける。","f":"yohei","m":"anger"},{"t":"d","s":"「あいつ、まだ睨んでる」","f":"yohei"},{"t":"d","s":"「そう？」","f":"yohei"},{"t":"d","s":"「あんたのこと気にしてるのよ、たぶん」","f":"yohei"},{"t":"d","s":"「なんで？」","f":"yohei"},{"t":"d","s":"「……さあね」","f":"yohei"},{"t":"n","s":"乃亜は、軽く肩をすくめた。","f":"noa"}]},{"key":"8-5","title":"肝試し","bg":"bg_grave","dark":true,"mood":"tense","bgm":"tense2","cast":["yohei","ren","ryoma"],"lines":[{"t":"cg","v":"cg_kimodameshi"},{"t":"n","s":"夜。山道の入口には、小さな提灯が一つだけ吊るされていた。"},{"t":"n","s":"森の中は、真っ暗だった。木々の枝が空を覆い、月明かりもほとんど届かない。風が吹くたびに、葉がざわざわと鳴る。"},{"t":"d","s":"「じゃあ、第五班、出発！」"},{"t":"n","s":"木村の声に送り出されて、六人は山道に足を踏み入れた。"},{"t":"d","s":"「うわ、思ったより暗いな……」"},{"t":"d","s":"「足元、気をつけて」"},{"t":"d","s":"「お、おい、押すなよ」"},{"t":"d","s":"「押してない」"},{"t":"n","s":"先頭を行くのは佐野。その後ろに中野、小川。最後尾に、耀平と乃亜。","f":"yohei"},{"t":"d","s":"「……ねえ、耀平」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「さっきから、変じゃない？」","f":"yohei"},{"t":"d","s":"「うん。気づいてた」","f":"yohei"},{"t":"d","s":"「やっぱり」","f":"yohei"},{"t":"n","s":"風が止んでいる。昨日のハイキングのときと同じだった。","f":"yohei"},{"t":"n","s":"鳥の声も、虫の音もしない。","f":"yohei"},{"t":"d","s":"「お化け役の先輩、まだ出てこないね」","f":"yohei"},{"t":"d","s":"「出てこないんじゃなくて、出られないんだと思う」","f":"yohei"},{"t":"d","s":"「え？」","f":"yohei"},{"t":"d","s":"「先輩たち、たぶん、持ち場に誰もいない」","f":"yohei"},{"t":"n","s":"耀平は、木刀を握る手に力を込めた。布袋から取り出したのは、旅館を出る直前だった。","f":"yohei"},{"t":"d","s":"「佐野」","f":"yohei"},{"t":"d","s":"「ん？」","f":"yohei"},{"t":"d","s":"「止まって」","f":"yohei"},{"t":"d","s":"「どうした？」","f":"yohei"},{"t":"d","s":"「……来る」","f":"yohei"},{"t":"n","s":"耀平の声が、いつもの眠そうな調子ではなかった。","f":"yohei"},{"t":"n","s":"その一瞬後、茂みの奥から、黒い影が飛び出した。","f":"yohei"},{"t":"n","s":"一方、遠く離れた森の外れ。","f":"yohei"},{"t":"n","s":"九条蓮は、旅館の屋根の上から山道を見下ろしていた。傍らには、木村ら三人の教師。","f":"ren"},{"t":"d","s":"「会長、そろそろ配置につきましょう」","f":"ren"},{"t":"d","s":"「ええ。……ですが」","f":"ren"},{"t":"n","s":"蓮は、眉をひそめた。","f":"ren"},{"t":"d","s":"「妙ですね。見回りに出ているはずの先生の姿が、いない」","f":"ren"},{"t":"d","s":"「え？」","f":"ren"},{"t":"d","s":"「第三班が出発したときから、持ち場の先輩の気配が、一つ消えている」","f":"ren"},{"t":"n","s":"蓮の顔色が、変わった。","f":"ren"},{"t":"d","s":"「しまった――誘い込まれた。急ぎます、全員、森へ！」","f":"ren"},{"t":"n","s":"蓮が屋根を蹴る。教師たちが、慌ててその後を追う。","f":"ren"},{"t":"n","s":"森の奥では、すでに、悲鳴が上がっていた。","f":"ren"},{"t":"n","s":"そして、その悲鳴を、少し離れた木の陰で聞いていた少年がいた。","f":"ren"},{"t":"n","s":"竜馬だった。別の班の列から、いつの間にか抜け出して、耀平たちの後を追っていたのだ。","f":"ryoma"},{"t":"d","s":"「……あいつら、なんで……」","f":"ryoma"},{"t":"n","s":"竜馬は、息を呑んで、木の幹にしがみついた。足が、動かなかった。","f":"ryoma","m":"surprise"},{"t":"n","s":"闇の向こうで、黒い外套の男が、ゆっくりと笑っていた。","f":"ryoma"}]}]},{"n":9,"title":"覚醒（百花繚乱）","sub":"中学・1年","era":"middle","lead":"「一花心舞」は、ただの捨てスキルではなかった。そして、その夜、耀平の目に桜が咲いた。","scenes":[{"key":"9-1","title":"襲撃","bg":"bg_grave","dark":true,"mood":"battle","bgm":"battle1","cast":["noa","yohei"],"lines":[{"t":"n","s":"茂みが、割れた。"},{"t":"n","s":"黒い影が三つ、子どもたちの前に躍り出た。うち二つは、黒い衣を着た屈強な男。最後の一人は、昨日、蓮に吹き飛ばされた、あの黒い外套の男だった。","fx":"shake"},{"t":"d","s":"「ようやく、あつまってくれたようだな」"},{"t":"n","s":"男は、腹を押さえながら、へらへらと笑った。","m":"happy"},{"t":"d","s":"「明日は帰るって言うから、待ったんだ。ガキどもの救助は、ここには来ねえ」"},{"t":"d","s":"「……あ、あの。お化け役の、先輩ですか？」"},{"t":"d","s":"「とんでもねえ。お前らを、買い取ってくれるお客さんがいるんだよ」"},{"t":"n","s":"佐野のいつもの笑顔が、凍りついた。"},{"t":"d","s":"「……は？」"},{"t":"d","s":"「スキル持ちの子どもは、高く売れる。特に、この学校のやつはな」"},{"t":"n","s":"男が手を振ると、後ろの二人が動いた。"},{"t":"d","s":"「うわっ――」"},{"t":"d","s":"「きゃあっ！」"},{"t":"n","s":"中野と小川が、一瞬で地面に押さえ込まれた。首筋に手刀が入る。二人の目が、ぐるりと白目をむいて、そのまま動かなくなった。"},{"t":"d","s":"「中野！　小川！」"},{"t":"d","s":"「大丈夫だ。気絶させただけだ。傷をつけたら、値が下がるからな」"},{"t":"n","s":"佐野が叫んで駆け出した。けれど、黒い外套の男の手が、すっと延びる。影が、地面からするりと立ち上がって、佐野の足を絡め取った。"},{"t":"d","s":"「うっ……あ、足が――」"},{"t":"d","s":"「足が速いって、実は、俺の影には勝てねえんだよ」"},{"t":"n","s":"佐野の体が、影に引きずり込まれ、ぶらりと逆さに吊り上げられた。"},{"t":"d","s":"「佐野っ！」"},{"t":"n","s":"耀平が叫んだ。木刀を押し出すように構えて、一歩、前へ出る。","f":"yohei"},{"t":"d","s":"「やめろ。その子を、離せ」","f":"yohei"},{"t":"d","s":"「ほう。ガキが、いっぱしに木刀か」","f":"yohei"},{"t":"n","s":"男は、面白そうに目を細めた。","f":"yohei"},{"t":"d","s":"「耀平」","f":"yohei"},{"t":"n","s":"乃亜が、耀平の前に立った。袖を、きゅっと握りしめて。","f":"noa"},{"t":"d","s":"「下がってて」","f":"noa"},{"t":"d","s":"「乃亜、でも」","f":"noa"},{"t":"d","s":"「下がってて。……お願い」","f":"noa"},{"t":"n","s":"乃亜の声は、震えていた。けれど、その手は、水のように静かに構えを取った。","f":"noa"},{"t":"d","s":"「碧水――心希」","f":"noa"},{"t":"n","s":"乃亜の周囲の空気が、ゆらりと揺れた。地面から、透明な水が湧き出して、乃亜の手の平の上で、細い紐のようによじれた。","f":"noa"}]},{"key":"9-2","title":"乃亜","bg":"bg_grave","dark":true,"mood":"battle","bgm":"battle1","cast":["yohei","noa"],"lines":[{"t":"d","s":"「……ガキの水使いというわけか」"},{"t":"n","s":"男は、鼻で笑った。","m":"happy"},{"t":"d","s":"「やってみろ。できるならな」"},{"t":"n","s":"乃亜が、腕を振る。水の紐が、錐のようにピンと張って男の顔面に飛んだ。","f":"noa"},{"t":"n","s":"こともなげに、男は首を傾ける。水の錐は、頬をかすめて、背後の木に穴を穿った。","f":"noa"},{"t":"d","s":"「ある程度は、できるようだな」","f":"noa"},{"t":"n","s":"男の影が、るる、と走る。乃亜の足元に黒い手が、三本、四本と延びてくる。","f":"noa"},{"t":"d","s":"「……っ」","f":"noa"},{"t":"n","s":"乃亜は、跳んでかわす。水の壁を作る。だが、影は、水を飲み込みながら進む。","f":"noa"},{"t":"d","s":"「乃亜！」","f":"noa"},{"t":"n","s":"耀平が、木刀を振り下ろした。影の手を、一本、断ち切る。","f":"yohei"},{"t":"d","s":"「ほう。このガキも、多少はやるか」","f":"yohei"},{"t":"n","s":"男の顔に、初めて余裕の消える色が浮かんだ。","f":"yohei"},{"t":"d","s":"「だが、ガキはガキだ」","f":"yohei"},{"t":"n","s":"男が、一歩、踏み込んだ。それだけで、距離が消えた。","f":"yohei"},{"t":"n","s":"蹴りが、耀平の脇腹にめり込んだ。","f":"yohei"},{"t":"d","s":"「がはっ……！」","f":"yohei"},{"t":"n","s":"耀平の体が、宙を舞った。木の幹に叩きつけられて、肺から空気が押し出される。視界が、赤く点滅した。","f":"yohei","fx":"shake"},{"t":"d","s":"「耀平っ！」","f":"yohei"},{"t":"n","s":"乃亜の悲鳴が、耳にこだまする。","f":"noa"},{"t":"d","s":"「……だいじょうぶ。まだ、立てる」","f":"noa"},{"t":"n","s":"耀平は、木刀を杖にして立ち上がった。口の端から、血が一筋、垂れている。","f":"yohei"},{"t":"d","s":"「ほう、まだ立つか。こいつ、頭のネジが飛んでるな」","f":"yohei"},{"t":"d","s":"「……二人とも、逃げて。おれが、時間を稼ぐ」","f":"yohei"},{"t":"d","s":"「耀平、無理よ！　相手は大人で――」","f":"yohei"},{"t":"d","s":"「分かってる」","f":"yohei"},{"t":"n","s":"耀平は、笑って見せた。","f":"yohei"},{"t":"d","s":"「でも、逃げるって、約束してないから」","f":"yohei"},{"t":"n","s":"男が、つまらなそうに首を鳴らした。","f":"yohei"},{"t":"d","s":"「バカが。じゃあ、もう少しだけ、やってやる」","f":"yohei"},{"t":"n","s":"黒い影が、耀平を飲み込もうとする。耀平は木刀を振った。踊った。踏み込んだ。けれど、どれも、届かない。逆に、一発、二発、三発と、体に重いものが入る。","f":"yohei"},{"t":"n","s":"やがて、耀平は膝をついた。","f":"yohei"},{"t":"d","s":"「……くっ」","f":"yohei"},{"t":"d","s":"「終わりだ」","f":"yohei"},{"t":"n","s":"男の拳が、耀平の頭を狙った。","f":"yohei"},{"t":"n","s":"その瞬間、乃亜が、体ごとぶつかった。","f":"noa"},{"t":"d","s":"「やめて！」","f":"noa"},{"t":"n","s":"拳が乃亜の肩をかすめ、乃亜の体が地面に強く叩きつけられた。","f":"noa","fx":"shake"},{"t":"d","s":"「乃亜っ！」","f":"noa"}]},{"key":"9-3","title":"桃色","bg":"bg_grave","dark":true,"mood":"battle","bgm":"battle1","cast":["yohei","noa"],"lines":[{"t":"d","s":"「あんまり顔を傷つけると、値が下がる。だから、こっちにしようかな」"},{"t":"n","s":"男は、乃亜の腕を、引きずり起こした。小さな手首を、片手でつかむ。","f":"noa"},{"t":"d","s":"「……離して。いやっ」","f":"noa"},{"t":"d","s":"「スキル持ちの子どもの体というのは、部位でも売れるんだよ。化け物のお客さんとかな」","f":"noa"},{"t":"n","s":"男は、へらへらと笑った。","f":"noa","m":"happy"},{"t":"d","s":"「腕の一本や二本、あってもいいだろ。むしろ、水を操れるやつなんざ、買い手はいくらでもつく――」","f":"noa"},{"t":"n","s":"男の影が、刀の形に延びた。黒い刃が、乃亜の肩にあてがわれる。","f":"noa"},{"t":"d","s":"「……やめろ」","f":"noa"},{"t":"n","s":"声がした。耐えるように、でも、あまりに小さな声で。","f":"noa"},{"t":"d","s":"「あん？」","f":"noa"},{"t":"d","s":"「……やめろ。乃亜に、触るな」","f":"noa"},{"t":"n","s":"男が振り返る。","f":"noa"},{"t":"n","s":"耀平が、立っていた。","f":"yohei"},{"t":"n","s":"血だらけの顔で、木刀を握りしめて、ゆらりと。","f":"yohei"},{"t":"d","s":"「やめろって、言ってるだろ」","f":"yohei"},{"t":"n","s":"ことばの、重さが、変わった。","f":"yohei"},{"t":"n","s":"耀平の胸の奥で、何かが、ぷつりと、切れた。","f":"yohei"},{"t":"n","s":"空っぽになるほどの怒り。強く、強く、心臓を揺さぶられる。視界が滲む。乃亜が傷つく。祖父の手の温度が、遠くなったあの日が、頭の中で重なる。","f":"noa"},{"t":"d","s":"「もう、誰も――」","f":"noa"},{"t":"n","s":"耀平の口から、ひどく小さな声がこぼれた。","f":"yohei"},{"t":"d","s":"「……誰も、奪うなよ」","f":"yohei"},{"t":"n","s":"ふわりと、風が吹いた。","f":"yohei"},{"t":"n","s":"さっきまで止まっていた風が、耀平を中心に、渦を巻く。","f":"yohei"},{"t":"n","s":"小さな桜の花びらが、一枚。二枚。三枚。いや、次々と、数え切れないほどの花びらが、耀平の周囲の空中に現れていく。","f":"yohei"},{"t":"d","s":"「……なんだ、こりゃ」","f":"yohei"},{"t":"n","s":"男が、無意識に一歩、下がった。","f":"yohei"},{"t":"n","s":"耀平が、ゆっくりと顔を上げる。","f":"yohei"},{"t":"n","s":"その目に、桜が咲いていた。","f":"yohei"},{"t":"n","s":"瞳の奥で、淡い桃色の光が、小さく、しかし確かに、灯っている。","f":"yohei"},{"t":"d","s":"「一花――」","f":"yohei"},{"t":"n","s":"耀平の口が、勝手に動いた。","f":"yohei"},{"t":"d","s":"「――百花繚乱」","f":"yohei","fx":"bloom"},{"t":"n","s":"桜の嵐が、弾けた。","f":"yohei"}]},{"key":"9-4","title":"百花繚乱","bg":"bg_grave","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["yohei"],"lines":[{"t":"cg","v":"cg_hyakka"},{"t":"n","s":"最初に感じたのは、あまりにも静かな感覚だった。"},{"t":"n","s":"さっきまでの痛みが、遠のいていく。袖をかすめる桜の花びらが、スローモーションのように見える。男の影の一本一本が、どこを通ってくるのか、分かった。"},{"t":"d","s":"「……見える」"},{"t":"n","s":"耀平は、木刀を、すっと構え直した。桜の花びらが、木刀の刀身に絡んで、淡い桃色の光を帯びる。","f":"yohei"},{"t":"d","s":"「てめえ……どこから、そんな――」","f":"yohei"},{"t":"n","s":"男の影が、怒涛のように迫る。耀平は、ひらりと身を翻した。影の手が、花びらに触れるたび、軽くいなされて、空を切る。","f":"yohei"},{"t":"d","s":"「なんだ、この動きは！」","f":"yohei"},{"t":"n","s":"桜を踏むたび、体が先に反応する。視線より、恐怖より、思考よりも、速く。","f":"yohei"},{"t":"n","s":"耀平は、木刀を、振った。","f":"yohei"},{"t":"n","s":"黒い影が、横一閃に、割れる。","f":"yohei","fx":"flash"},{"t":"d","s":"「ぐうっ……！」","f":"yohei"},{"t":"n","s":"男が、後ろによろめく。しかし、完全には崩れない。影を、盾のように張り直して、体勢を立て直す。","f":"yohei"},{"t":"d","s":"「調子に乗るなよガキ――！」","f":"yohei"},{"t":"n","s":"男の影が、拳の形に膨らんだ。巨大な黒い拳が、耀平に落とされる。","f":"yohei"},{"t":"n","s":"耀平は、その真下で、足を踏んだ。桜を踏む。踏む。踏む。踊るように拳の内側に滑り込み、横一閃。","f":"yohei","fx":"flash"},{"t":"n","s":"影が、散る。","f":"yohei"},{"t":"d","s":"「――っ、があああっ！」","f":"yohei"},{"t":"n","s":"男の口から、悲鳴と血が吹き出た。黒い外套が、胸から縦に裂けている。","f":"yohei"},{"t":"d","s":"「てめえ……ガキのくせに……」","f":"yohei"},{"t":"n","s":"男は、膝をついた。けれど、その目はまだ死んではいなかった。黒い影が、足元の地面を、ずる、と進む。","f":"yohei"},{"t":"d","s":"「これで、終わりにしてやる」","f":"yohei"},{"t":"n","s":"影が、耀平の足を絡め取る。耀平は、構わなかった。影の拘束を、木刀で断ち切る。あと一歩。あと一閃。","f":"yohei","fx":"flash"},{"t":"n","s":"だが、耀平の膝は、限界だった。","f":"yohei"},{"t":"d","s":"「……っ」","f":"yohei"},{"t":"n","s":"視界が、白くなる。桜の花びらが、ひらひらと、散っていく。","f":"yohei"},{"t":"d","s":"「今度こそ、終わりだ」","f":"yohei"},{"t":"n","s":"男が、拳を引いた。耀平は、それを、見ていた。ゆっくりと。分かっていたのに、体が動かない。","f":"yohei"},{"t":"n","s":"――そのとき。","f":"yohei"},{"t":"d","s":"「……痛いのは、いやですよね」","f":"yohei"},{"t":"n","s":"やさしい声がした。","f":"yohei"}]},{"key":"9-5","title":"白い少女","bg":"bg_grave","dark":true,"mood":"tense","bgm":"tense1","cast":["yohei","noa"],"lines":[{"t":"n","s":"その声は、風のように、すっと耀平の背中に入ってきた。","f":"yohei"},{"t":"n","s":"振り返る余裕もなかった。けれど、耳元に、人の気配が、ふっと降りてくる。","f":"yohei"},{"t":"d","s":"「淡雪」","f":"yohei"},{"t":"n","s":"ふわりと、白い光が、耀平を包んだ。","f":"yohei"},{"t":"n","s":"痛みが、消えた。血の味が、薄れていく。さっきまでの疲弊が、体の外に押し出されていくようだった。","f":"yohei"},{"t":"d","s":"「……誰だ、てめえ」","f":"yohei"},{"t":"n","s":"男が、警戒して一歩、下がる。","f":"yohei"},{"t":"n","s":"耀平の背中の暗闇から、一人の少女が、ゆっくりと歩いてきた。","f":"yohei"},{"t":"n","s":"長い水色の髪。白い美しい肌。淡い水色のコートの裾が、夜風に揺れている。まるで、物語の中から、押し出されてきたような姿だった。","f":"yohei"},{"t":"d","s":"「ここは、あなたの来るところではありませんよ」","f":"yohei"},{"t":"d","s":"「……なんだと？」","f":"yohei"},{"t":"d","s":"「ここは、人が傷つく場所ではありません。……だから、拒絶します」","f":"yohei"},{"t":"n","s":"少女は、指をそっと、空にかざした。","f":"yohei"},{"t":"d","s":"「――風花」","f":"yohei"},{"t":"n","s":"男の拳が、止まった。","f":"yohei"},{"t":"n","s":"いや、拒絶された。見えない壁に弾かれるように、男の体が、彼女の目の前で、大きく後ろへ弾き飛ばされた。","f":"yohei"},{"t":"d","s":"「がはっ……！　規格外……！？」","f":"yohei"},{"t":"n","s":"男の目が、初めて、恐怖に染まった。","f":"yohei"},{"t":"d","s":"「聞いてねーぞ……こんなところに、二人も……！」","f":"yohei"},{"t":"n","s":"男は、よろけながら立ち上がって、後ずさる。場の空気が、はっきりと変わった。","f":"yohei"},{"t":"d","s":"「こりゃヤバい」","f":"yohei"},{"t":"n","s":"男は影を蹴って、森の奥へ消えようとした。けれど、耀平がそれを許さなかった。","f":"yohei"},{"t":"d","s":"「……逃がさない」","f":"yohei"},{"t":"n","s":"桜を踏む。影を穿つ。最後の一閃。","f":"yohei","fx":"flash"},{"t":"d","s":"「百花繚乱――」","f":"yohei","fx":"bloom"},{"t":"n","s":"桜吹雪が、横一文字に走った。","f":"yohei"},{"t":"n","s":"男は、一言も発せず、崩れ落ちた。","f":"yohei"},{"t":"n","s":"静寂。","f":"yohei"},{"t":"n","s":"耀平は、木刀を落とした。と同時に、膝が崩れ、地面に倒れ込んだ。","f":"yohei"},{"t":"d","s":"「……のあ。ぶじ、か……」","f":"yohei"},{"t":"n","s":"とっさに起き上がろうとした乃亜は、起き上がれなかった。耀平の袖を握ったまま、目の前に起こった光景を、じっと見つめていた。","f":"noa"},{"t":"n","s":"はらはらと、桃色の花びらが、天から降り続ける。その真ん中で、少年が、安らかに目を閉じている。","f":"noa"},{"t":"d","s":"「……耀平」","f":"noa"},{"t":"n","s":"乃亜の視界が、ゆっくりと、暗くなっていく。意識が遠のく直前、白い少女が、耀平のもとにしゃがみ込んでいるのが、見えた。","f":"noa"},{"t":"n","s":"少女は、少年の頬の血を、指先でそっと拭った。","f":"noa"},{"t":"d","s":"「……耀平くんって、いうんですね」","f":"noa"},{"t":"n","s":"乃亜がさっき、何度も呼んでいたからだろう。少女は、小さく、優しく、微笑んだ。","f":"noa","m":"happy"},{"t":"d","s":"「あなたの桜、きれいでした」","f":"noa"},{"t":"n","s":"静かな声だった。いつまでも、ここで聞いていたいと思う、やさしい声。","f":"noa"},{"t":"d","s":"「また、会えますかね、耀平くん」","f":"noa"},{"t":"n","s":"少女は、立ち上がった。淡い水色のコートが、ふわりと夜風に揺れる。その姿は、白い光に溶けるように、すうっと遠のいていく。","f":"noa"},{"t":"n","s":"乃亜は、そこで、意識を手放した。","f":"noa"}]},{"key":"9-6","title":"あとに残ったもの","bg":"bg_classroom_middle","dark":true,"mood":"night","bgm":"night1","cast":["ren","yohei","noa"],"lines":[{"t":"d","s":"「――何だ、これは」"},{"t":"n","s":"九条蓮が、森の奥をのぞき込んだとき、そこには、戦いの跡だけが残っていた。","f":"ren"},{"t":"n","s":"倒れた黒い外套の男。気絶した二人の黒衣の男。そして、地面に倒れ込んでいる、五人の生徒たち。","f":"ren"},{"t":"n","s":"その足元に、桃色の花びらが、ひらり、ひらりと、降り積もっている。","f":"ren"},{"t":"d","s":"「会長、これは……」","f":"ren"},{"t":"d","s":"「……そうですね。何があったのか、分かりません」","f":"ren"},{"t":"n","s":"蓮は、足元の花びらを一枚、拾い上げた。指先で潰せば散って消えるそれは、確かに、誇り高い桜の御魂のように、暖かかった。","f":"ren"},{"t":"d","s":"「これは……」","f":"ren"},{"t":"n","s":"蓮は、倒れている生徒の中の、一人の顔を見た。","f":"ren"},{"t":"n","s":"血だらけの顔で、安らかに目を閉じている。手には、まだ木刀が握られている。","f":"ren"},{"t":"d","s":"「……耀平、か」","f":"ren"},{"t":"n","s":"蓮は、何も言わなかった。","f":"ren"},{"t":"d","s":"「とりあえず、全員を回収しましょう。この男たちも拘束を」","f":"ren"},{"t":"d","s":"「はい。……会長、この件は」","f":"ren"},{"t":"d","s":"「……あとで考えます」","f":"ren"},{"t":"n","s":"蓮は、そっと耀平を抱き上げた。軽い。この体のどこに、あんな力があったというのか。","f":"ren"},{"t":"n","s":"少し離れた木の陰で、竜馬が、息を殺していた。","f":"ryoma"},{"t":"n","s":"手足が、小刻みに震えている。視線の先で、桃色の花びらが、静かに消えていく。","f":"ryoma"},{"t":"d","s":"「……おれは、あのとき……」","f":"ryoma"},{"t":"n","s":"竜馬は、拳を、強く握りしめた。悔しさと、恐怖と、憧れと。それらが、胸の中でぐちゃぐちゃに混ざっていた。","f":"ryoma"},{"t":"d","s":"「何も、できなかった」","f":"ryoma"},{"t":"n","s":"こぼれた声は、誰にも届かなかった。","f":"ryoma"},{"t":"n","s":"翌朝。旅館の医務室で、乃亜は目を覚ました。","f":"noa"},{"t":"d","s":"「……耀平は？」","f":"noa"},{"t":"d","s":"「ここにいる。まだ寝てる」","f":"noa"},{"t":"n","s":"隣のベッドに、耀平がいた。顔の傷は、すでに消えている。","f":"yohei"},{"t":"d","s":"「……無事で、よかった」","f":"yohei"},{"t":"d","s":"「あなたも、無事ですよ」","f":"yohei"},{"t":"n","s":"医務室の先生が、優しく笑った。","f":"yohei","m":"happy"},{"t":"d","s":"「明日には、起きられるでしょう」","f":"yohei"},{"t":"n","s":"乃亜は、耀平の寝顔を、じっと見つめた。昨夜、見たものが、脳裏で、くりかえされる。","f":"noa"},{"t":"n","s":"あれは、規格外だ。","f":"noa"},{"t":"n","s":"あの白い少女と、同じ。世界に数十人しかいないとされる、成長限界のない、特別な存在。","f":"noa"},{"t":"d","s":"「……言わない」","f":"noa"},{"t":"n","s":"乃亜は、小さく、呟いた。","f":"noa"},{"t":"d","s":"「会長にも、先生にも。耀平が、遠くに行ってしまうかもしれないから」","f":"noa"},{"t":"n","s":"胸の奥が、きゅっと痛んだ。おなじくらい、誇らしい気持ちもあった。この人は、やっぱり、すごい人だった。","f":"noa"},{"t":"d","s":"「だけど、約束したからね。どこに行っても、帰ってくるって」","f":"noa"},{"t":"n","s":"隣のベッドで、耀平が、寝返りを打った。","f":"yohei"},{"t":"d","s":"「……ん、のあ……」","f":"yohei"},{"t":"n","s":"寝言だった。乃亜は、思わず、小さく笑った。","f":"noa","m":"happy"},{"t":"d","s":"「……ばか」","f":"noa"},{"t":"n","s":"窓の外では、朝日が、山の稜線をゆっくりと照らしていた。","f":"noa"}]}]},{"n":10,"title":"竜馬との喧嘩と改心","sub":"中学・1年","era":"middle","lead":"何も知らないふりをする耀平と、すべてを見ていた竜馬。ぶつかった末に、竜馬は一人で答えを出す。","scenes":[{"key":"10-1","title":"帰りのバス","bg":"bg_classroom_middle","dark":true,"mood":"night","bgm":"night2","cast":["yohei","noa","ren"],"lines":[{"t":"n","s":"修学旅行の最終日。帰りのバスの中は、行きよりもずっと静かだった。"},{"t":"d","s":"「昨夜、不審者が侵入したが、生徒会長の九条くんと先生方がすぐに対応した。怪我をした生徒はいない」"},{"t":"n","s":"担任の木村が、前の席で淡々と説明した。"},{"t":"d","s":"「なお、詳しいことは警察に任せている。皆さんは、気にしなくていい」"},{"t":"n","s":"生徒たちは、ほっとした顔と、少し不満げな顔に分かれた。何も知らないまま、あっさりと日常に戻される。それが、大人たちの選んだやり方だった。"},{"t":"d","s":"「……会長が、一人でやっつけたんだって」"},{"t":"d","s":"「やっぱ、すげえな」"},{"t":"d","s":"「お化け役の先輩たち、全員無事だったらしいよ」"},{"t":"n","s":"耀平は、窓にもたれて、目を閉じていた。眠っているのではない。あの夜のことを、頭の中で何度も繰り返していた。","f":"yohei"},{"t":"d","s":"「……耀平」","f":"yohei"},{"t":"d","s":"「ん」","f":"yohei"},{"t":"d","s":"「体、もう大丈夫なの」","f":"yohei"},{"t":"d","s":"「うん。ふしぎなくらい」","f":"yohei"},{"t":"d","s":"「そう」","f":"yohei"},{"t":"n","s":"隣の席の乃亜は、前を向いたまま、短く答えた。それ以上は、何も聞かなかった。","f":"noa"},{"t":"n","s":"聞かない代わりに、乃亜の指が、耀平の袖をそっとつまんでいた。","f":"noa"},{"t":"n","s":"バスが山を下りていく。窓の外を、秋の景色が流れていく。","f":"noa"},{"t":"n","s":"後ろの席から、じっと耀平の後頭部を見つめる視線があることに、耀平だけが気づいていなかった。","f":"yohei"}]},{"key":"10-2","title":"生徒会長","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily2","cast":["ren","yohei"],"lines":[{"t":"n","s":"学校に戻って三日後。昼休みの廊下で、耀平は呼び止められた。","f":"yohei"},{"t":"d","s":"「耀平」","f":"yohei"},{"t":"n","s":"振り向くと、九条蓮が立っていた。制服の襟まで整った、いつもの姿だった。","f":"ren"},{"t":"d","s":"「会長」","f":"ren"},{"t":"d","s":"「九条でいいと言っただろう」","f":"ren"},{"t":"d","s":"「はい、九条先輩」","f":"ren"},{"t":"d","s":"「……先日は、大変だったな」","f":"ren"},{"t":"n","s":"蓮の声は静かだった。けれど、その視線は、耀平の顔から指先まで、ゆっくりと確かめるように動いていた。","f":"ren"},{"t":"d","s":"「いえ。ぼくは、寝てただけなので」","f":"ren"},{"t":"d","s":"「寝ていた、か」","f":"ren"},{"t":"d","s":"「はい。気づいたら、朝でした」","f":"ren"},{"t":"n","s":"耀平は、あっさりと答えた。嘘ではなかった。少なくとも、最後の部分は。","f":"yohei"},{"t":"n","s":"蓮は、ポケットから何かを取り出した。薄桃色の、小さな花びらだった。","f":"ren"},{"t":"d","s":"「あの現場に、これが落ちていてな」","f":"ren"},{"t":"d","s":"「桜、ですね」","f":"ren"},{"t":"d","s":"「ああ。季節外れの、桜だ」","f":"ren"},{"t":"d","s":"「ふしぎですね」","f":"ren"},{"t":"d","s":"「……そうだな」","f":"ren"},{"t":"n","s":"蓮は、花びらを指先で潰した。ふ、と消える。","f":"ren"},{"t":"d","s":"「君は、桜が好きなのか」","f":"ren"},{"t":"d","s":"「好きというか、気づくと、そこにあるんです」","f":"ren"},{"t":"d","s":"「そうか」","f":"ren"},{"t":"n","s":"蓮は、それだけ言うと、小さく笑った。","f":"ren","m":"happy"},{"t":"d","s":"「いや、すまない。気にしないでくれ。……まさかな、と思っただけだ」","f":"ren"},{"t":"d","s":"「まさか、ですか？」","f":"ren"},{"t":"d","s":"「忘れてくれ。それより、朝の素振りは続けているのか」","f":"ren"},{"t":"d","s":"「はい」","f":"ren"},{"t":"d","s":"「そうか。無理はするなよ」","f":"ren"},{"t":"n","s":"蓮は、片手を軽く上げて、廊下の向こうへ歩いていった。","f":"ren"},{"t":"n","s":"耀平は、その背中を見送りながら、ほんの少しだけ、胸の奥で息をついた。","f":"yohei"},{"t":"i","s":"（……あの人、たぶん、少し疑ってる）","f":"yohei"},{"t":"n","s":"けれど、疑いは確信に変わらない。耀平の力は、まだ、証拠として残るほどのものではない。","f":"yohei"},{"t":"n","s":"それに、蓮自身が、自分の疑いを「まさか」で済ませようとしていた。生徒会長として、守るべき範囲を、あえて広げすぎないように。","f":"ren"}]},{"key":"10-3","title":"見てたぜ","bg":"bg_schoolyard_middle","dark":false,"mood":"daily","bgm":"daily3","cast":["ryoma","yohei"],"lines":[{"t":"n","s":"その日の放課後、訓練場。"},{"t":"n","s":"耀平がいつものように木刀を振っていると、背後から、足音が近づいてきた。","f":"yohei"},{"t":"d","s":"「おい」","f":"yohei"},{"t":"n","s":"振り返ると、竜馬が立っていた。腕を組み、いつもより低い声で。","f":"ryoma"},{"t":"d","s":"「竜馬。どうしたの」","f":"ryoma"},{"t":"d","s":"「見てたぜ」","f":"ryoma"},{"t":"d","s":"「なにを」","f":"ryoma"},{"t":"d","s":"「修学旅行の夜だ」","f":"ryoma"},{"t":"n","s":"耀平の手が、一瞬だけ止まった。","f":"yohei"},{"t":"d","s":"「……なんのこと」","f":"yohei"},{"t":"d","s":"「とぼけんな。おまえ、あの男を倒しただろ」","f":"yohei"},{"t":"d","s":"「倒してないよ。ぼくは、気絶してた」","f":"yohei"},{"t":"d","s":"「嘘つけ。桜が、見えた」","f":"yohei"},{"t":"n","s":"竜馬の声が、わずかに震えていた。怒りではない。もっと別の、うまく名前のつかないものだった。","f":"ryoma"},{"t":"d","s":"「おれは、あのとき、動けなかった。手も足も、ぜんぜん」","f":"ryoma"},{"t":"d","s":"「……」","f":"ryoma"},{"t":"d","s":"「怖かった。あの男も、おまえも」","f":"ryoma"},{"t":"d","s":"「竜馬」","f":"ryoma"},{"t":"d","s":"「でもな」","f":"ryoma"},{"t":"n","s":"竜馬は、拳を握りしめた。","f":"ryoma"},{"t":"d","s":"「おまえが、何か隠してんのは分かる。それが、むかつくんだよ」","f":"ryoma"},{"t":"d","s":"「隠してないよ」","f":"ryoma"},{"t":"d","s":"「じゃあ、証明しろ」","f":"ryoma"},{"t":"n","s":"竜馬の全身から、赤い熱が立ち上がった。","f":"ryoma"},{"t":"d","s":"「やるぞ、耀平。小学校のときの、続きだ」","f":"ryoma"},{"t":"d","s":"「やめようよ」","f":"ryoma"},{"t":"d","s":"「やめねえ。ここで逃げたら、おれはずっと、あの夜に置いてかれたままだ」","f":"ryoma"},{"t":"n","s":"耀平は、ゆっくりと息を吐いた。","f":"yohei"},{"t":"i","s":"（……逃げてるのは、おれのほうかもしれない）","f":"yohei"},{"t":"n","s":"そう思いながらも、桜の力を使うつもりはなかった。あれは、人に向けていいものではない。少なくとも、友達に向けるものでは。","f":"yohei"},{"t":"d","s":"「いいよ。でも、おれは、普通にやる」","f":"yohei"},{"t":"d","s":"「は？」","f":"yohei"},{"t":"d","s":"「木刀だけで。それ以外は、使わない」","f":"yohei"},{"t":"d","s":"「ふざけんなあっ！」","f":"yohei"},{"t":"n","s":"竜馬が、地面を蹴った。","f":"ryoma"}]},{"key":"10-4","title":"ぐだぐだの喧嘩","bg":"bg_schoolyard_middle","dark":false,"mood":"daily","bgm":"daily4","cast":["ryoma","yohei"],"lines":[{"t":"n","s":"炎が、訓練場の空気を焼いた。"},{"t":"n","s":"小学生の頃とは違う。中学生になった竜馬の炎は、より太く、より速くなっていた。拳に火を纏わせ、連続で叩き込んでくる。","f":"ryoma"},{"t":"n","s":"耀平は、木刀で受け流した。避けた。いなした。けれど、桜の力は使わない。","f":"yohei"},{"t":"d","s":"「くそっ、本気出せ！」","f":"yohei"},{"t":"d","s":"「出してるよ」","f":"yohei"},{"t":"d","s":"「嘘つけ！」","f":"yohei"},{"t":"d","s":"「ほんとだよ。だって、ぼくは、竜馬より弱いもん」","f":"yohei"},{"t":"d","s":"「ふざけんな！」","f":"yohei"},{"t":"n","s":"拳が、耀平の頬をかすめた。熱が肌を焼く。耀平は、一歩下がって、体勢を立て直した。","f":"yohei"},{"t":"n","s":"毎朝の素振りで鍛えた体は、確かに強くなっていた。けれど、純粋な技術と力だけでは、竜馬の炎には押される。","f":"ryoma"},{"t":"d","s":"「ほら見ろ！　やっぱり、大したことねえじゃねえか！」","f":"ryoma"},{"t":"d","s":"「そうだよ」","f":"ryoma"},{"t":"d","s":"「なんで言い返さねえんだよ！」","f":"ryoma"},{"t":"d","s":"「だって、本当のことだから」","f":"ryoma"},{"t":"n","s":"竜馬の顔が、ゆがんだ。","f":"ryoma"},{"t":"d","s":"「……だから、そういうところが、むかつくんだよ」","f":"ryoma"},{"t":"n","s":"竜馬は、一歩、下がった。両手を前に突き出す。空気が、ごうごうと渦を巻き始める。","f":"ryoma"},{"t":"d","s":"「竜馬、それ、やめて」","f":"ryoma"},{"t":"d","s":"「うるせえ。おまえが本気を出さねえなら、出させてやる」","f":"ryoma"},{"t":"d","s":"「あの火は、人に向けちゃだめだ」","f":"ryoma"},{"t":"d","s":"「うるせえっ！」","f":"ryoma"},{"t":"n","s":"小学校のときの、あの記憶が、二人の頭に同時によみがえった。","f":"ryoma"},{"t":"n","s":"竜馬の掌に、巨大な火球が膨らんでいく。焦げた地面。泣いていた自分。立っていた友達。","f":"ryoma","m":"sad"},{"t":"d","s":"「紅蓮――爆炎！」","f":"ryoma"},{"t":"n","s":"赤い奔流が、耀平に向かって放たれた。","f":"yohei"},{"t":"n","s":"耀平は、木刀を握りしめた。避けようとした。けれど、背後には、訓練場の壁がある。その向こうには、生徒たちの教室がある。","f":"yohei"},{"t":"i","s":"（……ここで避けたら、誰かが傷つく）","f":"yohei"},{"t":"n","s":"耀平の足が、止まった。","f":"yohei"},{"t":"n","s":"同時に、風が吹いた。","f":"yohei"},{"t":"n","s":"桜の花びらが、一枚、耀平の肩に舞い降りた。","f":"yohei"},{"t":"d","s":"「あ……」","f":"yohei"},{"t":"n","s":"その瞬間、耀平の体が、勝手に動いた。","f":"yohei"},{"t":"n","s":"桜を踏む。炎の流れが、見える。木刀に花びらが絡みつく。淡い桃色の光が、刀身を満たしていく。","f":"yohei"},{"t":"d","s":"「――百花繚乱」","f":"yohei","fx":"bloom"},{"t":"n","s":"耀平の口が、呟いた。","f":"yohei"},{"t":"n","s":"桜の嵐が、炎を飲み込んだ。","f":"yohei"},{"t":"n","s":"赤と桃色が、ぶつかり合い、やがて、桜が炎を包み込んで、ふっと消し去った。","f":"yohei"},{"t":"d","s":"「な……」","f":"yohei"},{"t":"n","s":"竜馬の目が、見開かれる。","f":"ryoma"},{"t":"n","s":"気づいたときには、耀平が、竜馬の目の前にいた。木刀の切っ先が、喉元に突きつけられている。","f":"yohei"},{"t":"n","s":"峰打ち。刃のない木刀だからこそ、できる止め方だった。","f":"yohei"},{"t":"d","s":"「……もう、いい？」","f":"yohei"},{"t":"n","s":"耀平の声は、静かだった。","f":"yohei"},{"t":"n","s":"竜馬の足から、力が抜けた。膝が、がくりと折れる。","f":"ryoma"},{"t":"d","s":"「おれは……」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「おれは、おまえに……」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"n","s":"竜馬の口が、何度か開いて、何度か閉じた。やがて、小さな声が漏れた。","f":"ryoma"},{"t":"d","s":"「……見てたんだ。ずっと」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「おまえが、毎朝、剣を振ってるのを」","f":"ryoma"},{"t":"d","s":"「え？」","f":"ryoma"},{"t":"d","s":"「寮の窓から、見えるんだよ。毎日、毎日」","f":"ryoma"},{"t":"n","s":"耀平は、目を丸くした。","f":"yohei","m":"surprise"},{"t":"d","s":"「それ、知らなかった」","f":"yohei"},{"t":"d","s":"「言うかよ、そんなこと」","f":"yohei"},{"t":"n","s":"竜馬は、地面に座り込んだまま、顔を伏せた。","f":"ryoma"}]},{"key":"10-5","title":"竜馬のひとり","bg":"bg_schoolyard_middle","dark":false,"mood":"daily","bgm":"daily5","cast":["ryoma","yohei"],"lines":[{"t":"n","s":"耀平は、竜馬を残して、訓練場を後にした。","f":"yohei"},{"t":"n","s":"何も言わなかった。言えなかった、という方が近い。ここで声をかけたら、竜馬のプライドが、粉々になってしまう気がした。","f":"ryoma"},{"t":"n","s":"一人きりになった訓練場で、竜馬は、しばらく動けなかった。","f":"ryoma"},{"t":"n","s":"夕暮れの光が、焦げた地面を照らしている。焼けた土の匂い。遠くで、運動部の掛け声が聞こえる。","f":"ryoma"},{"t":"d","s":"「……くそっ」","f":"ryoma"},{"t":"n","s":"竜馬は、地面に拳を叩きつけた。","f":"ryoma","fx":"shake"},{"t":"n","s":"悔しかった。","f":"ryoma"},{"t":"n","s":"負けたことが、ではない。","f":"ryoma"},{"t":"i","s":"（あいつは、あの炎を、止めやがった）","f":"ryoma"},{"t":"n","s":"人を傷つけないように。自分の後ろにあるものを、守るように。","f":"ryoma"},{"t":"n","s":"小学校のときも、そうだった。あのとき、竜馬は、本気で耀平を殺すつもりで火を出した。耀平は、それを受け止めて、笑って、「いいよ」と言った。","f":"ryoma"},{"t":"i","s":"（……何なんだよ、おまえは）","f":"ryoma"},{"t":"n","s":"頭の奥で、ずっと前の記憶が、浮かんできた。","f":"ryoma"},{"t":"n","s":"幼稚園の園庭。木の枝を持った、小さな男の子が二人。","f":"ryoma"},{"t":"d","s":"「ぼく、けんせいになる！」","f":"ryoma"},{"t":"d","s":"「おれもなる！」","f":"ryoma"},{"t":"d","s":"「じゃあ、おれが、ぜったいつよくなる！」","f":"ryoma"},{"t":"d","s":"「ぼくも！」","f":"ryoma"},{"t":"d","s":"「どっちがつよくなるか、しょうぶだ！」","f":"ryoma"},{"t":"d","s":"「うん！」","f":"ryoma"},{"t":"n","s":"笑っていた。あの頃は、ただ、楽しかった。","f":"ryoma"},{"t":"n","s":"竜馬は、気づいた。いつから、自分は、耀平を睨むようになったのだろう。いつから、あいつの努力を、馬鹿にするようになったのだろう。","f":"ryoma","m":"anger"},{"t":"n","s":"スキルが、先に目覚めた。炎を出せるようになった。周りが褒めてくれた。耀平は、花びらを出すだけだった。周りが笑った。","f":"yohei","m":"happy"},{"t":"n","s":"だから、自分のほうが上だと思った。","f":"yohei"},{"t":"n","s":"でも、違った。","f":"yohei"},{"t":"i","s":"（おれは、あいつに、憧れてたんだ）","f":"yohei"},{"t":"n","s":"毎朝、飽きもせず剣を振る背中に。バカにされても、笑っている顔に。何も隠さず、まっすぐ生きているあの目に。","f":"yohei"},{"t":"d","s":"「……ちくしょう」","f":"yohei"},{"t":"n","s":"竜馬の目から、涙がこぼれた。止まらなかった。悔しくて、情けなくて、そして、少しだけ、うれしくて。","f":"ryoma","m":"sad"},{"t":"d","s":"「おれは、あいつに、勝ちたい」","f":"ryoma"},{"t":"n","s":"絞り出すような声だった。","f":"ryoma"},{"t":"d","s":"「バカにするんじゃなくて、ちゃんと、勝ちたい」","f":"ryoma"},{"t":"n","s":"竜馬は、袖で乱暴に目をこすった。それから、ゆっくりと立ち上がった。","f":"ryoma"},{"t":"n","s":"夕日が、彼の背中を赤く染めていた。","f":"ryoma"},{"t":"n","s":"その夜から、竜馬は変わった。","f":"ryoma"},{"t":"n","s":"耀平をバカにする生徒に、拳を向けることはなくなった。代わりに、毎朝、誰よりも早く訓練場に現れるようになった。","f":"yohei"},{"t":"n","s":"耀平には、何も言わなかった。耀平も、何も聞かなかった。","f":"yohei"},{"t":"n","s":"二人の間には、気まずい空気だけが残った。それは、距離というより、お互いに、何かを待っているような沈黙だった。","f":"yohei"}]},{"key":"10-6","title":"ふたり分の距離","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily1","cast":["noa","ryoma","yohei"],"lines":[{"t":"n","s":"数日後。放課後の教室。"},{"t":"n","s":"乃亜が、荷物をまとめながら、ぽつりと聞いた。","f":"noa"},{"t":"d","s":"「竜馬と、何かあったの」","f":"noa"},{"t":"d","s":"「うん。ちょっとだけ」","f":"noa"},{"t":"d","s":"「ちょっと、ね」","f":"noa"},{"t":"d","s":"「ちゃんと話そうとは思ってる。でも、今は、話しかけないほうがいい気がする」","f":"noa"},{"t":"d","s":"「……そう」","f":"noa"},{"t":"n","s":"乃亜は、荷物を鞄に入れる手を止めた。","f":"noa"},{"t":"d","s":"「あいつ、最近、変わったよね」","f":"noa"},{"t":"d","s":"「そう？」","f":"noa"},{"t":"d","s":"「悪口、言わなくなった」","f":"noa"},{"t":"d","s":"「竜馬は、もともと、悪いやつじゃないから」","f":"noa"},{"t":"d","s":"「あんたって、ほんと、お人好し」","f":"noa"},{"t":"d","s":"「そうかな」","f":"noa"},{"t":"d","s":"「そうよ」","f":"noa"},{"t":"n","s":"乃亜は、小さく笑った。それから、窓の外を見た。校庭の隅で、竜馬が一人、黙々と素振りをしている。","f":"noa","m":"happy"},{"t":"d","s":"「……あいつも、がんばってるんだね」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「あんたも」","f":"noa"},{"t":"d","s":"「おれは、ふつうだよ」","f":"noa"},{"t":"d","s":"「ふつうじゃない」","f":"noa"},{"t":"n","s":"乃亜は、静かに言った。","f":"noa"},{"t":"d","s":"「ふつうじゃないから、怖いの。いつか、遠くに行っちゃいそうで」","f":"noa"},{"t":"n","s":"耀平は、少し考えて、乃亜の顔を見た。","f":"yohei"},{"t":"d","s":"「乃亜」","f":"yohei"},{"t":"d","s":"「なに」","f":"yohei"},{"t":"d","s":"「約束、覚えてる」","f":"yohei"},{"t":"d","s":"「……覚えてる」","f":"yohei"},{"t":"d","s":"「なら、だいじょうぶ」","f":"yohei"},{"t":"n","s":"乃亜の目が、わずかに潤んだ。けれど、すぐに顔を背けて、鞄を持ち上げた。","f":"noa"},{"t":"d","s":"「帰るよ」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「晩ごはん、食堂でいい？」","f":"noa"},{"t":"d","s":"「いい」","f":"noa"},{"t":"d","s":"「また、玉子焼き残さないでね」","f":"noa"},{"t":"d","s":"「がんばる」","f":"noa"},{"t":"d","s":"「がんばれてない」","f":"noa"},{"t":"n","s":"二人は、並んで教室を出た。","f":"noa"},{"t":"n","s":"校庭の隅で、竜馬の素振りの音が、夕空に響いていた。","f":"ryoma"}]}]},{"n":11,"title":"冬の行事と、はじめての刀","sub":"中学・1年冬〜2年春","era":"middle","lead":"クリスマス、初詣、バレンタイン。静かな日常の中で、耀平は自分の刀を探しはじめる。","scenes":[{"key":"11-1","title":"寮のクリスマス","bg":"bg_dorm","dark":true,"mood":"night","bgm":"night3","cast":["noa","yohei","ryoma"],"lines":[{"t":"n","s":"十二月。寮の食堂には、誰かが飾りつけた小さなツリーが置かれていた。"},{"t":"d","s":"「本日は、クリスマス会です。ケーキは一人一切れまでですよ」"},{"t":"n","s":"寮母の山口さんが、にこにこと宣言する。食堂のあちこちから歓声が上がった。"},{"t":"d","s":"「やった！　耀平、おれの分もあげるからさ、おまえの分のチキンくれよ！」"},{"t":"d","s":"「佐野。ケーキを一切れ渡して、チキンを一本もらうの、交換レートおかしくない？」"},{"t":"d","s":"「おかしくない！　おれの足の速さは、チキンの価値を上回る！」"},{"t":"d","s":"「関係ないよ、それ」"},{"t":"n","s":"同室の佐野との掛け合いにも、すっかり慣れた。耀平は、笑って紙皿を差し出す。","f":"yohei"},{"t":"n","s":"窓際の席には、乃亜が座っていた。ツリーの電飾が、横顔に淡く映っている。","f":"noa"},{"t":"d","s":"「耀平」","f":"noa"},{"t":"d","s":"「ん」","f":"noa"},{"t":"d","s":"「これ」","f":"noa"},{"t":"n","s":"乃亜が、小さな紙袋を差し出した。","f":"noa"},{"t":"d","s":"「プレゼント。去年のマフラーは、ちゃんと使ってるでしょ」","f":"noa"},{"t":"d","s":"「使ってるよ。今年も、毎朝巻いてる」","f":"noa"},{"t":"d","s":"「だから、手袋」","f":"noa"},{"t":"n","s":"紙袋の中には、濃い紺色の手袋が入っていた。指先に、薄く滑り止めがついている。","f":"noa"},{"t":"d","s":"「素振りのとき、手が冷たいでしょ。それなら、握りやすいほうがいいと思って」","f":"noa"},{"t":"d","s":"「……これ、乃亜が選んだの」","f":"noa"},{"t":"d","s":"「ま、まあ。店員さんに聞きながら」","f":"noa"},{"t":"d","s":"「ありがとう」","f":"noa"},{"t":"d","s":"「べつに。お礼を言われるほどじゃ」","f":"noa"},{"t":"d","s":"「あったかい」","f":"noa"},{"t":"n","s":"耀平は手袋をはめて、拳を握った。ぴたり、と手に馴染む。","f":"yohei"},{"t":"d","s":"「ぴったり」","f":"yohei"},{"t":"d","s":"「サイズ、前に測ったから」","f":"yohei"},{"t":"d","s":"「いつ」","f":"yohei"},{"t":"d","s":"「……あんたが寝てるとき」","f":"yohei"},{"t":"d","s":"「え」","f":"yohei"},{"t":"d","s":"「な、なんでもない！」","f":"yohei"},{"t":"n","s":"乃亜は、真っ赤になってそっぽを向いた。","f":"noa"},{"t":"n","s":"耀平は少し考えて、ポケットから小さな包みを取り出した。","f":"yohei"},{"t":"d","s":"「おれも、これ」","f":"yohei"},{"t":"d","s":"「え」","f":"yohei"},{"t":"d","s":"「去年は木札だったから。今年は、ちゃんと買ってみた」","f":"yohei"},{"t":"n","s":"包みの中には、小さな髪留めが入っていた。淡い水色の石が、一粒だけ光っている。","f":"yohei"},{"t":"d","s":"「……耀平が、買ったの」","f":"yohei"},{"t":"d","s":"「佐野に相談した。女の子には、これがいいって」","f":"yohei"},{"t":"d","s":"「……佐野くんに」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「あんたって、ほんとに」","f":"yohei"},{"t":"d","s":"「だめだった？」","f":"yohei"},{"t":"d","s":"「だめじゃない」","f":"yohei"},{"t":"cg","v":"cg_hairclip"},{"t":"n","s":"乃亜は、髪留めを両手で包んだ。声が、少しだけ震えている。","f":"noa"},{"t":"d","s":"「……つけて、みる」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"n","s":"乃亜は、前髪を軽く留めた。水色の石が、電飾の光を受けてきらりと光る。","f":"noa"},{"t":"d","s":"「どう」","f":"noa"},{"t":"d","s":"「似合ってる」","f":"noa"},{"t":"d","s":"「……ちゃんと言えるようになったじゃない」","f":"noa"},{"t":"d","s":"「おじいちゃんに教わったから」","f":"noa"},{"t":"n","s":"乃亜は、ふ、と小さく笑った。その笑顔を、少し離れた席から竜馬が見ていた。何かを言いかけて、やめる。ケーキを黙って口に運ぶ。","f":"noa","m":"happy"},{"t":"d","s":"「竜馬、ケーキ食べないの」","f":"noa"},{"t":"d","s":"「うるせえ。食ってる」","f":"noa"},{"t":"d","s":"「もう一個あげようか」","f":"noa"},{"t":"d","s":"「いらねえよ！」","f":"noa"},{"t":"n","s":"佐野の軽口に、竜馬が怒鳴り返す。けれど、その声には、以前のような棘がなかった。","f":"ryoma","m":"anger"}]},{"key":"11-2","title":"初詣","bg":"bg_riverside","dark":false,"mood":"soft","bgm":"soft1","cast":["noa","yohei","ryoma"],"lines":[{"t":"n","s":"年が明けて、一月。初詣は、地元の神社に行くことにした。"},{"t":"d","s":"「明けましておめでとう」"},{"t":"cg","v":"cg_hatsumode"},{"t":"d","s":"「おめでとう。……着物、着てきたんだ」"},{"t":"d","s":"「お母さんが、どうしてもって」"},{"t":"d","s":"「似合ってる」"},{"t":"d","s":"「それ、毎回言わなくていいから」"},{"t":"d","s":"「じゃあ、言わない」"},{"t":"d","s":"「それはそれで、いやなの」"},{"t":"n","s":"乃亜は、赤い振り袖の袖をつまんで、ぷいと前を歩き出した。耀平は、その背中を追いかける。","f":"noa"},{"t":"n","s":"神社の境内は、人でごった返していた。屋台の匂い。鈴の音。白い息があちこちで揺れている。","f":"noa"},{"t":"n","s":"二人は、列に並んで、賽銭を投げ、手を合わせた。","f":"noa"},{"t":"i","s":"（……おじいちゃん。ぼく、少し強くなれたよ）","f":"noa"},{"t":"n","s":"耀平は、目を閉じて、心の中でそう呟いた。祖父はいない。けれど、祖父に向けた言葉だけは、変わらず胸の中にあった。","f":"yohei"},{"t":"i","s":"（これからも、見ててください）","f":"yohei"},{"t":"n","s":"目を開けると、隣の乃亜も、まだ手を合わせていた。長いまつげが、白い息の向こうで揺れている。","f":"noa"},{"t":"d","s":"「長いね」","f":"noa"},{"t":"d","s":"「……聞かないで」","f":"noa"},{"t":"d","s":"「何をお願いしたの」","f":"noa"},{"t":"d","s":"「言ったら、叶わなくなるでしょ」","f":"noa"},{"t":"d","s":"「そうなの」","f":"noa"},{"t":"d","s":"「そうなの」","f":"noa"},{"t":"n","s":"乃亜は、ちらりと耀平を見て、すぐに目を逸らした。","f":"noa"},{"t":"i","s":"（……耀平が、遠くに行きませんように。行っても、ちゃんと帰ってきますように）","f":"noa"},{"t":"n","s":"そんな祈りを、乃亜は胸の中にしまった。言えるはずがなかった。","f":"noa"},{"t":"n","s":"おみくじを引いた。耀平は小吉。乃亜は、中吉。","f":"yohei"},{"t":"d","s":"「小吉って、何がいいの」","f":"yohei"},{"t":"d","s":"「『焦るな、基本を大切に』だって」","f":"yohei"},{"t":"d","s":"「耀平らしいね」","f":"yohei"},{"t":"d","s":"「乃亜は？」","f":"yohei"},{"t":"d","s":"「『待ち人、来る。ただし素直になるべし』」","f":"yohei"},{"t":"d","s":"「待ち人って、誰」","f":"yohei"},{"t":"d","s":"「……知らない」","f":"yohei"},{"t":"n","s":"乃亜は、おみくじをくしゃっと握って、結び場に走っていった。耀平は首をかしげる。","f":"noa"},{"t":"n","s":"境内の端で、竜馬が一人、おみくじを引いていた。結果を見て、無言でポケットに突っ込む。それから、ふと顔を上げて、こちらと目が合った。","f":"ryoma"},{"t":"d","s":"「……よお」","f":"ryoma"},{"t":"d","s":"「あけましておめでとう、竜馬」","f":"ryoma"},{"t":"d","s":"「……おう」","f":"ryoma"},{"t":"n","s":"それだけだった。竜馬は、すぐに背を向けて去っていった。でも、その短い会話は、これまでの沈黙とは、少しだけ違っていた。","f":"ryoma"}]},{"key":"11-3","title":"バレンタイン","bg":"bg_classroom_middle","dark":false,"mood":"soft","bgm":"soft2","cast":["noa","yohei","ryoma"],"lines":[{"t":"n","s":"二月十四日。"},{"t":"n","s":"乃亜の机の上は、また、チョコレートの山になっていた。","f":"noa"},{"t":"d","s":"「乃亜さん、これ」","f":"noa"},{"t":"d","s":"「ありがとう。でも、わたし、お返しできないよ」","f":"noa"},{"t":"d","s":"「いいの！　渡したいだけだから！」","f":"noa"},{"t":"n","s":"女子たちが、顔を赤くして去っていく。乃亜は、淡々と紙袋にチョコを詰めていく。中学に入って、乃亜のモテ具合はさらに上がった。男子からも、女子からも。","f":"noa","m":"blush"},{"t":"n","s":"一方、耀平の机には、一つだけ。","f":"yohei"},{"t":"d","s":"「あの……耀平くん」","f":"yohei"},{"t":"d","s":"「ん」","f":"yohei"},{"t":"d","s":"「これ、よかったら」","f":"yohei"},{"t":"n","s":"見たことのない女子生徒が、小さな箱を差し出していた。耳まで赤い。","f":"yohei"},{"t":"d","s":"「ありがとう。でも、どうして」","f":"yohei"},{"t":"d","s":"「その……修学旅行のとき、みんなが怖がってる中で、耀平くんだけ、ちゃんと前に立ってたから」","f":"yohei"},{"t":"d","s":"「あ、あれは、たまたま」","f":"yohei"},{"t":"d","s":"「かっこよかった、です」","f":"yohei"},{"t":"n","s":"女子は、それだけ言って走り去った。耀平は、箱を持ったまま、きょとんとしている。","f":"yohei"},{"t":"d","s":"「……へえ」","f":"yohei"},{"t":"n","s":"背後から、冷たい声が降ってきた。","f":"yohei"},{"t":"d","s":"「乃亜」","f":"yohei"},{"t":"d","s":"「モテるんだ」","f":"yohei"},{"t":"d","s":"「え、これは、たまたま」","f":"yohei"},{"t":"d","s":"「たまたま、ね」","f":"yohei"},{"t":"n","s":"乃亜は、つかつかと耀平の机に近づいた。紙袋から、小さな包みを一つ取り出して、わざとらしく、耀平の目の前に置く。","f":"noa"},{"t":"d","s":"「これ。ぎり」","f":"noa"},{"t":"d","s":"「ありがとう」","f":"noa"},{"t":"d","s":"「ぎりだから。他の人のと、同じ」","f":"noa"},{"t":"d","s":"「同じにしては、包みが大きいね」","f":"noa"},{"t":"d","s":"「うるさい！」","f":"noa"},{"t":"n","s":"乃亜は、真っ赤になって声を張り上げた。教室中が、ざわつく。","f":"noa"},{"t":"d","s":"「乃亜さん、耀平くんと仲いいよね」","f":"noa"},{"t":"d","s":"「幼なじみ、なんだって」","f":"noa"},{"t":"d","s":"「いいなあ」","f":"noa"},{"t":"n","s":"ひそひそ声が、あちこちから聞こえてくる。乃亜は、耳まで赤くしたまま、すとんと自分の席に座った。","f":"noa"},{"t":"i","s":"（……わたし、何やってるんだろう）","f":"noa"},{"t":"n","s":"頭を抱える乃亜を、少し離れた席から竜馬がちらりと見ていた。机の中には、昨日買ったチョコが入っている。渡すつもりだった。でも、今日も、渡せなかった。","f":"noa"},{"t":"i","s":"（……まだ、早えか）","f":"noa"},{"t":"n","s":"竜馬は、小さく息を吐いて、チョコを鞄の奥にしまい込んだ。","f":"ryoma"},{"t":"n","s":"その日の夕方、校庭の隅で、竜馬が一人、素振りをしていた。耀平は、窓越しにそれを見ながら、乃亜がくれた包みを開けた。小さなトリュフが三つ、並んでいる。","f":"ryoma"},{"t":"d","s":"「……ほんとに、同じなのかな」","f":"ryoma"},{"t":"n","s":"一つ口に入れる。ほろ苦くて、少し甘かった。","f":"ryoma"}]},{"key":"11-4","title":"刀を探しに","bg":"bg_principal","dark":false,"mood":"daily","bgm":"daily5","cast":["yohei","noa","ryoma"],"lines":[{"t":"n","s":"春。二年生に進級する直前の三月の終わり。"},{"t":"d","s":"「耀平。ちょっと来てくれ」"},{"t":"n","s":"放課後の廊下で、木村先生に呼び止められた。"},{"t":"d","s":"「はい」"},{"t":"d","s":"「君は、毎朝、素振りをしているそうだな」"},{"t":"d","s":"「はい」"},{"t":"d","s":"「うちの学校は、二年生から、実技で刃引きの刀を使う授業がある。君も、そろそろ、木刀から卒業してはどうだ」"},{"t":"d","s":"「刀、ですか」"},{"t":"d","s":"「ああ。自分で選んで、学校に申請を出すんだ。街の刀鍛冶を、紹介してやる」"},{"t":"n","s":"耀平は、少しだけ目を丸くして、それから、ゆっくりと頷いた。","f":"yohei","m":"surprise"},{"t":"d","s":"「ありがとうございます」","f":"yohei"},{"t":"n","s":"週末。二人で、街外れの古い刀鍛冶の工房を訪ねた。","f":"yohei"},{"t":"d","s":"「こんなところ、初めて入る」","f":"yohei"},{"t":"d","s":"「おれも」","f":"yohei"},{"t":"d","s":"「それなのに、緊張してないんだね」","f":"yohei"},{"t":"d","s":"「緊張してるよ」","f":"yohei"},{"t":"d","s":"「全然、見えない」","f":"yohei"},{"t":"d","s":"「顔に出ないだけ」","f":"yohei"},{"t":"n","s":"暖簾をくぐると、薄暗い工房の壁に、ずらりと刀が並んでいた。刃引きの練習刀もあれば、本物の刃のついた古刀もある。","f":"yohei"},{"t":"d","s":"「いらっしゃい」","f":"yohei"},{"t":"n","s":"奥の炉の前から、無口そうな刀鍛冶の老人が顔を出した。","f":"yohei"},{"t":"d","s":"「学校の申請か」","f":"yohei"},{"t":"d","s":"「はい。刃引きのものを」","f":"yohei"},{"t":"d","s":"「好きに握ってみなさい」","f":"yohei"},{"t":"n","s":"耀平は、壁にかけられた刀を、一本ずつ、慎重に握った。重い。軽い。長い。短い。どれも、少しずつ違う。","f":"yohei"},{"t":"d","s":"「ねえ、耀平。これ、かっこよくない？」","f":"yohei"},{"t":"d","s":"「それは、飾り用じゃないかな」","f":"yohei"},{"t":"d","s":"「あ、本当だ。値札が、ゼロ多い」","f":"yohei"},{"t":"d","s":"「乃亜、触らないほうがいいよ」","f":"yohei"},{"t":"n","s":"乃亜が、慌てて手を引っ込める。","f":"noa"},{"t":"n","s":"何本目だっただろう。ふと、耀平の手が止まった。","f":"yohei"},{"t":"n","s":"黒い鞘に収まった、地味な一振りだった。装飾はない。刃引きの練習刀として、工房の端に立てかけられている。","f":"yohei"},{"t":"n","s":"握った瞬間、指先に、じんわりと温かさが伝わってきた。","f":"yohei"},{"t":"d","s":"「……これ」","f":"yohei"},{"t":"d","s":"「それかい」","f":"yohei"},{"t":"n","s":"老人が、目を細めた。","f":"yohei"},{"t":"d","s":"「無銘の練習刀だ。特に変わったところはない。ただ、持ち主を選ぶ癖があってな。誰が握っても、冷たいままだった」","f":"yohei"},{"t":"d","s":"「冷たい、ままだった」","f":"yohei"},{"t":"d","s":"「そう。だが、君が握ると、温かい」","f":"yohei"},{"t":"n","s":"耀平は、鞘から少しだけ刀身を引き抜いた。白い刃が、静かに光る。","f":"yohei"},{"t":"n","s":"そのとき、どこからともなく、窓の隙間を抜けて、桜の花びらが一枚、舞い込んだ。","f":"yohei"},{"t":"n","s":"刀の上に、ふわりと落ちる。花びらは、消えなかった。刀身の上に静かにとどまって、ほんの一瞬だけ、淡く光った。","f":"yohei","fx":"flash"},{"t":"d","s":"「……」","f":"yohei"},{"t":"d","s":"「……」","f":"yohei"},{"t":"n","s":"老人が、何も言わずに耀平を見ていた。乃亜も、息を詰めて、その光景を見つめている。","f":"yohei"},{"t":"d","s":"「……不思議なことも、あるもんだ」","f":"yohei"},{"t":"d","s":"「あ、あの、季節外れの桜が、時々……」","f":"yohei"},{"t":"d","s":"「そうかい。……それなら、その刀は、君が持っていきなさい」","f":"yohei"},{"t":"d","s":"「いくらですか」","f":"yohei"},{"t":"d","s":"「学校の申請額でいい。ただし、一週間預けなさい。花びらを乗せても折れんように、打ち直しておく。……大切に使うことだ」","f":"yohei"},{"t":"n","s":"耀平は、深く頭を下げた。","f":"yohei"},{"t":"n","s":"工房を出ると、通りの向こうから、見覚えのある背中が歩いてきた。","f":"yohei"},{"t":"d","s":"「……竜馬」","f":"yohei"},{"t":"d","s":"「……よお」","f":"yohei"},{"t":"n","s":"竜馬は、腰に新しい刃引きの刀を提げていた。赤い鞘に、炎のような模様が彫られている。","f":"ryoma"},{"t":"d","s":"「おまえも、刀か」","f":"ryoma"},{"t":"d","s":"「うん。さっき、決めた」","f":"ryoma"},{"t":"d","s":"「そうか。おれも、決めたとこだ」","f":"ryoma"},{"t":"n","s":"気まずい沈黙が流れた。乃亜が、二人を交互に見ている。","f":"noa"},{"t":"d","s":"「……そ、そっか」","f":"noa"},{"t":"d","s":"「おう」","f":"noa"},{"t":"d","s":"「いい刀だね」","f":"noa"},{"t":"d","s":"「おまえのも、な」","f":"noa"},{"t":"n","s":"短い会話だった。それだけだった。竜馬は、それ以上何も言わず、少しだけ頷いて、歩き去っていった。","f":"ryoma"},{"t":"d","s":"「……あいつ、ちゃんと話したそうだったね」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「いつか、ちゃんと話せるといいね」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"n","s":"一週間後。耀平は、打ち直されて戻ってきた刀を腰に提げ、そっと手を置いた。","f":"yohei"},{"t":"n","s":"夕暮れの空に、春の風が吹いていた。鞘の中で、刃が小さく、ことりと鳴った。","f":"yohei"}]}]},{"n":12,"title":"体育祭、文化祭、受験、卒業","sub":"中学・2年〜3年","era":"middle","lead":"行事の日々が過ぎていく。竜馬との距離は、少しずつ、少しずつ変わっていく。","scenes":[{"key":"12-1","title":"体育祭","bg":"bg_schoolyard_middle","dark":false,"mood":"daily","bgm":"daily3","cast":["ryoma","yohei","noa"],"lines":[{"t":"n","s":"二年生の秋。体育祭は、よく晴れた日に行われた。"},{"t":"n","s":"校庭には色とりどりの旗が並び、スピーカーからは行進曲が流れている。生徒たちは、赤、青、白、緑の四つの組に分かれて、朝からずっと落ち着かない様子だった。"},{"t":"d","s":"「耀平、起きて。開会式」"},{"t":"d","s":"「起きてる」"},{"t":"d","s":"「立ったまま寝ないで」"},{"t":"d","s":"「寝てない。目を閉じて、風を感じてる」"},{"t":"d","s":"「それを寝てるって言うの」"},{"t":"n","s":"乃亜に背中をつつかれて、耀平はあくびを噛み殺す。同じ赤組の佐野が、隣で屈伸をしていた。","f":"noa"},{"t":"d","s":"「いやあ、今日こそ俺の出番だな！　最終種目、組対抗リレー！　アンカーは俺！」","f":"noa"},{"t":"d","s":"「佐野、足、速いもんね」","f":"noa"},{"t":"d","s":"「だろ！　スキルも『加速』だし！」","f":"noa"},{"t":"d","s":"「スキルは使用禁止だよ」","f":"noa"},{"t":"d","s":"「……あ」","f":"noa"},{"t":"n","s":"佐野の顔が、みるみる青くなった。","f":"noa"},{"t":"n","s":"種目は順調に進んだ。耀平は、障害物競走で三位。借り物競走では「眠そうな人」の札を引いて、自分自身を連れてゴールした。","f":"yohei"},{"t":"d","s":"「それ、ありなの？」","f":"yohei"},{"t":"d","s":"「審判の先生がいいって言った」","f":"yohei"},{"t":"d","s":"「あんたの運、変なところで強いよね」","f":"yohei"},{"t":"n","s":"乃亜は笑いながら、水筒を差し出す。冷たい麦茶が、喉に染みた。","f":"noa"},{"t":"n","s":"そして、最終種目。組対抗リレー。","f":"noa"},{"t":"n","s":"赤組のアンカーは、竜馬だった。佐野は第三走者。青組のアンカーは、別のクラスの運動部のエースだった。","f":"ryoma"},{"t":"d","s":"「竜馬、頼んだぞ！」","f":"ryoma"},{"t":"d","s":"「うるせえ。任せとけ」","f":"ryoma"},{"t":"n","s":"バトンが、佐野から竜馬へ。ほんの少し、遅れて渡った。青組との差は、三メートル。","f":"ryoma"},{"t":"d","s":"「くそ……！」","f":"ryoma"},{"t":"n","s":"竜馬が、地面を蹴った。","f":"ryoma"},{"t":"n","s":"速い。小さい頃から鍛えてきた脚が、校庭を切り裂いていく。一歩ごとに差が縮まる。歓声が、どよめきに変わった。","f":"ryoma"},{"t":"d","s":"「いけ、竜馬ー！」","f":"ryoma"},{"t":"n","s":"気づけば、耀平も叫んでいた。自分でも驚くほど、大きな声で。","f":"yohei"},{"t":"n","s":"竜馬が、青組のエースを抜いた。わずかに、ほんのわずかに、胸一つ分。テープを切る。","f":"ryoma"},{"t":"d","s":"「おおおっ！」","f":"ryoma"},{"t":"n","s":"歓声と拍手が、校庭に響いた。竜馬は膝に手をついて、荒い息を吐いた。ゆっくりと顔を上げる。その視線が、赤組の応援席に向いた。","f":"ryoma"},{"t":"n","s":"耀平と、目が合った。","f":"yohei"},{"t":"n","s":"竜馬は、一瞬だけ固まって、それから、ふいと顔を背けた。けれど、その口元が、ほんの少しだけ、緩んでいた。","f":"ryoma"},{"t":"d","s":"「……竜馬、笑ってた」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「あんた、嬉しそう」","f":"ryoma"},{"t":"d","s":"「うん。嬉しい」","f":"ryoma"},{"t":"n","s":"耀平は、小さく頷いた。","f":"yohei"},{"t":"n","s":"夕暮れの校庭で、片付けをしていると、背後から声がした。","f":"yohei"},{"t":"d","s":"「おい」","f":"yohei"},{"t":"d","s":"「竜馬」","f":"yohei"},{"t":"d","s":"「……さっき、叫んでたろ」","f":"yohei"},{"t":"d","s":"「聞こえた？」","f":"yohei"},{"t":"d","s":"「あんだけでかい声、聞こえねえわけねえだろ」","f":"yohei"},{"t":"n","s":"竜馬は、頭をがしがしと掻いた。","f":"ryoma"},{"t":"d","s":"「……ありがとな」","f":"ryoma"},{"t":"d","s":"「え」","f":"ryoma"},{"t":"d","s":"「一回しか言わねえからな」","f":"ryoma"},{"t":"d","s":"「うん。聞こえた」","f":"ryoma"},{"t":"d","s":"「聞こえてたなら、いい」","f":"ryoma"},{"t":"n","s":"竜馬は、それだけ言って、足早に去っていった。耀平は、その背中を見送りながら、小さく笑った。","f":"ryoma","m":"happy"}]},{"key":"12-2","title":"お化け屋敷","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily4","cast":["ryoma","yohei","noa"],"lines":[{"t":"n","s":"十一月。文化祭の出し物は、お化け屋敷に決まった。"},{"t":"d","s":"「なんでお化け屋敷なの……」"},{"t":"d","s":"「去年の肝試しが、不完全燃焼だったから！」"},{"t":"d","s":"「あんた、あの夜、さんざんな目に遭ったでしょ」"},{"t":"d","s":"「だからこそ！　今度は、俺たちが驚かせる側だ！」"},{"t":"n","s":"佐野が、胸を張って宣言する。教室中が、おお、と沸いた。もちろん、あの夜の本当のことを知っているのは、ほんの数人だけだった。"},{"t":"d","s":"「耀平は何の役やる？」"},{"t":"d","s":"「寝てる幽霊」"},{"t":"d","s":"「それ、ただの地味な人じゃないか」"},{"t":"d","s":"「じゃあ、ずっと布団に入ってる人」"},{"t":"d","s":"「採用！」"},{"t":"n","s":"結局、耀平は教室の隅の布団の中で、じっとしている係になった。お客さんが通りかかると、突然むくりと起き上がる。ただそれだけの役だった。","f":"yohei"},{"t":"n","s":"本番の日。意外にも、評判は上々だった。","f":"yohei"},{"t":"d","s":"「きゃああっ！」","f":"yohei"},{"t":"d","s":"「うわあああっ！」","f":"yohei"},{"t":"d","s":"「寝てたはずなのに、すごい勢いで起き上がった……！」","f":"yohei"},{"t":"n","s":"悲鳴が、ひっきりなしに聞こえてくる。耀平は、布団の中でぼんやりと考える。","f":"yohei"},{"t":"i","s":"（……おれ、そんなに怖いかな）","f":"yohei"},{"t":"d","s":"「耀平、お疲れ」","f":"yohei"},{"t":"d","s":"「乃亜」","f":"yohei"},{"t":"d","s":"「お客さんが、あんたの起き上がり方、一番怖いって言ってた」","f":"yohei"},{"t":"d","s":"「そうなの」","f":"yohei"},{"t":"d","s":"「うん。あの勢いは、反則」","f":"yohei"},{"t":"d","s":"「普通に起きただけなのに」","f":"yohei"},{"t":"d","s":"「それが一番怖いのよ」","f":"yohei"},{"t":"n","s":"乃亜は、くすくすと笑った。","f":"noa","m":"happy"},{"t":"n","s":"休憩時間、二人は校内を歩いた。屋台の匂い。呼び込みの声。教室ごとに違う飾り付け。","f":"noa"},{"t":"d","s":"「あ」","f":"noa"},{"t":"n","s":"乃亜が、ふと足を止めた。廊下の突き当たりに、竜馬のクラスの出し物があった。大きな看板に「焼き鳥」と書いてある。","f":"noa"},{"t":"d","s":"「竜馬、焼いてるよ」","f":"noa"},{"t":"d","s":"「ほんとだ。火加減が、うまい」","f":"noa"},{"t":"d","s":"「そりゃ、火のスキルだからでしょ」","f":"noa"},{"t":"n","s":"煙の向こうで、竜馬は真剣な顔で串を回していた。ふと顔を上げて、こちらに気づく。","f":"ryoma"},{"t":"d","s":"「……」","f":"ryoma"},{"t":"d","s":"「……」","f":"ryoma"},{"t":"n","s":"竜馬は、無言で串を二本、紙皿に載せて差し出した。","f":"ryoma"},{"t":"d","s":"「え」","f":"ryoma"},{"t":"d","s":"「余ってんだよ。食え」","f":"ryoma"},{"t":"d","s":"「いいの？」","f":"ryoma"},{"t":"d","s":"「いいから食え」","f":"ryoma"},{"t":"n","s":"耀平は、おそるおそる受け取って、一口かじった。皮がぱりっとして、中がじゅわりと柔らかい。","f":"yohei"},{"t":"d","s":"「おいしい」","f":"yohei"},{"t":"d","s":"「当たり前だ」","f":"yohei"},{"t":"d","s":"「ほんとに。すごく、おいしい」","f":"yohei"},{"t":"d","s":"「……そうかよ」","f":"yohei"},{"t":"n","s":"竜馬は、鼻をこすって、そっぽを向いた。乃亜が、小さく笑った。","f":"ryoma","m":"happy"}]},{"key":"12-3","title":"進路","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily5","cast":["yohei","noa","ryoma"],"lines":[{"t":"n","s":"三年生の春。進路面談の日がやってきた。"},{"t":"d","s":"「耀平。志望校は決まっているか」"},{"t":"d","s":"「はい。学園の高等部を」"},{"t":"d","s":"「そうか。倍率は高いぞ。成績も、最近は上がってきているが」"},{"t":"d","s":"「がんばります」"},{"t":"d","s":"「眠そうな顔で言われると、説得力に欠けるんだがな」"},{"t":"d","s":"「すみません」"},{"t":"n","s":"担任の木村が、苦笑いで書類をめくった。","m":"sweat"},{"t":"n","s":"学園。国内でも名の知られた、スキル持ちの子どもたちが集まる高等部。入るには、筆記試験と実技の両方に合格しなければならない。"},{"t":"i","s":"（そこに行けば、おじいちゃんが、話してくれなかったことも、わかるかもしれない）"},{"t":"n","s":"耀平は、そう思っていた。何かが、あの学園にある気がしていた。","f":"yohei"},{"t":"d","s":"「耀平」","f":"yohei"},{"t":"d","s":"「はい」","f":"yohei"},{"t":"d","s":"「君は、きっと受かる」","f":"yohei"},{"t":"d","s":"「ありがとうございます」","f":"yohei"},{"t":"d","s":"「根拠は、毎朝の素振りだ。続けられる人間は、強い」","f":"yohei"},{"t":"n","s":"耀平は、小さく頭を下げた。","f":"yohei"},{"t":"n","s":"受験勉強は、乃亜が仕切った。","f":"noa"},{"t":"d","s":"「耀平、ここ。さっきも間違えた」","f":"noa"},{"t":"d","s":"「ごめん」","f":"noa"},{"t":"d","s":"「謝るなら解いて」","f":"noa"},{"t":"d","s":"「がんばる」","f":"noa"},{"t":"d","s":"「がんばれてない」","f":"noa"},{"t":"d","s":"「……ねむい」","f":"noa"},{"t":"d","s":"「寝たら、水かける」","f":"noa"},{"t":"d","s":"「それは、いやだ」","f":"noa"},{"t":"d","s":"「じゃあ、起きて」","f":"noa"},{"t":"n","s":"寮の談話室。ノートと参考書が積まれた机の向かいで、乃亜はずっと耀平の隣に座っていた。自分の勉強もあるのに、耀平の手元ばかり見ている。","f":"noa"},{"t":"d","s":"「乃亜は、自分のやらなくていいの」","f":"noa"},{"t":"d","s":"「わたしは、大丈夫」","f":"noa"},{"t":"d","s":"「ほんとに？」","f":"noa"},{"t":"d","s":"「あんたよりは、ね」","f":"noa"},{"t":"d","s":"「ひどい」","f":"noa"},{"t":"d","s":"「事実」","f":"noa"},{"t":"n","s":"夜が更けても、乃亜は部屋に戻らなかった。やがて、耀平のノートの上に、こて、と頭が落ちる。","f":"noa"},{"t":"d","s":"「……」","f":"noa"},{"t":"n","s":"寝息が聞こえた。耀平は、そっと自分のマフラーを乃亜の肩にかけた。","f":"yohei"},{"t":"i","s":"（いつも、ありがとう）","f":"yohei"},{"t":"n","s":"声には出さずに、そう呟いた。","f":"yohei"},{"t":"n","s":"図書室では、時々、竜馬を見かけた。机に向かって、参考書をにらんでいる。目が合っても、お互い会釈をするだけ。それでも、以前の刺々しさは、もうなかった。","f":"ryoma"}]},{"key":"12-4","title":"文化祭と先輩","bg":"bg_classroom_middle","dark":false,"mood":"soft","bgm":"soft4","cast":["ren","yohei"],"lines":[{"t":"n","s":"三年生の文化祭は、受験前の最後の思い出作りだった。"},{"t":"d","s":"「耀平、見て。ほら、お客さんが一杯」"},{"t":"d","s":"「ほんとだ」"},{"t":"d","s":"「今年は、喫茶店だもんね」"},{"t":"d","s":"「楽だ」"},{"t":"d","s":"「楽じゃない。注文取るの、あんたの係」"},{"t":"d","s":"「え」"},{"t":"n","s":"耀平がエプロン姿でお盆を運んでいると、見覚えのある背中が、入口に現れた。","f":"yohei"},{"t":"n","s":"制服ではない、紺色のブレザー。学園の高等部の制服だった。","f":"yohei"},{"t":"d","s":"「久しぶりだな」","f":"yohei"},{"t":"n","s":"九条蓮だった。","f":"ren"},{"t":"d","s":"「九条先輩」","f":"ren"},{"t":"d","s":"「元気そうだ。いい店だな」","f":"ren"},{"t":"d","s":"「ありがとうございます。……どうして、ここに」","f":"ren"},{"t":"d","s":"「高等部の代表として、母校の文化祭を見に来た。受験生に、少し話もしたくてな」","f":"ren"},{"t":"n","s":"蓮は、窓際の席に腰を下ろし、コーヒーを注文した。耀平が運んでいくと、静かに口を開いた。","f":"ren"},{"t":"d","s":"「学園を、受けるそうだな」","f":"ren"},{"t":"d","s":"「はい」","f":"ren"},{"t":"d","s":"「いい選択だ。待っている」","f":"ren"},{"t":"d","s":"「待って、ますか」","f":"ren"},{"t":"d","s":"「ああ。高等部の生徒会長は、三年生が務める。私は、君が入学する年に、会長になる」","f":"ren"},{"t":"n","s":"蓮は、コーヒーを一口飲んで、続けた。","f":"ren"},{"t":"d","s":"「あの学園は、強い人間が集まる。同時に、危険も多い。だが、君ならきっと、うまくやれる」","f":"ren"},{"t":"d","s":"「どうして、そう思うんですか」","f":"ren"},{"t":"d","s":"「勘だ」","f":"ren"},{"t":"d","s":"「勘、ですか」","f":"ren"},{"t":"d","s":"「勘が当たる人間は、案外、強いんだ」","f":"ren"},{"t":"n","s":"蓮は、少しだけ笑った。それは、中学の入学式で見た、完璧な笑顔とは違う、自然な笑顔だった。","f":"ren","m":"happy"},{"t":"i","s":"（……やっぱり、この人は、いい人だ）","f":"ren"},{"t":"n","s":"耀平は、そう思った。そして同時に、胸のどこかで、小さく警鐘が鳴るのを感じていた。この人は、いつか、自分の秘密に辿り着くかもしれない。","f":"yohei"},{"t":"i","s":"（でも、その時は、その時だ）","f":"yohei"},{"t":"d","s":"「ごゆっくりどうぞ」","f":"yohei"},{"t":"n","s":"耀平は、軽く頭を下げて、持ち場に戻った。","f":"yohei"}]},{"key":"12-5","title":"卒業式","bg":"bg_graduation","dark":false,"mood":"climax","bgm":"climax1","cast":["noa","ryoma","yohei"],"lines":[{"t":"n","s":"三月。寒さの残る朝。"},{"t":"n","s":"合格発表の日、耀平は掲示板の前に立っていた。人だかりの向こう、自分の受験番号を探す。","f":"yohei"},{"t":"d","s":"「……あった」","f":"yohei"},{"t":"n","s":"小さく、息を吐いた。隣では、乃亜が自分の番号を見つけて、ほっとしたように肩の力を抜いている。","f":"noa"},{"t":"d","s":"「やった」","f":"noa"},{"t":"d","s":"「おめでとう、乃亜」","f":"noa"},{"t":"d","s":"「あんたもね。……あ、竜馬」","f":"noa"},{"t":"n","s":"少し離れたところに、竜馬が立っていた。掲示板を見上げたまま、何も言わない。やがて、ゆっくりとこちらを振り向いた。","f":"ryoma"},{"t":"d","s":"「……受かった」","f":"ryoma"},{"t":"d","s":"「おれも」","f":"ryoma"},{"t":"d","s":"「おまえも、か」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「そうか。……じゃあ、高校でも、決着つけられるな」","f":"ryoma"},{"t":"d","s":"「いいよ。約束したから」","f":"ryoma"},{"t":"d","s":"「おう」","f":"ryoma"},{"t":"n","s":"竜馬は、短く頷いて、背を向けた。耀平は、その背中に、小さな声で呼びかけた。","f":"ryoma"},{"t":"d","s":"「竜馬」","f":"ryoma"},{"t":"d","s":"「あ？」","f":"ryoma"},{"t":"d","s":"「また、よろしく」","f":"ryoma"},{"t":"d","s":"「……ああ」","f":"ryoma"},{"t":"n","s":"振り返らずに、竜馬は片手を上げた。それだけだった。","f":"ryoma"},{"t":"n","s":"そして、卒業式の日。","f":"ryoma"},{"t":"n","s":"講堂での式は、粛々と進んだ。卒業証書を受け取り、校歌を歌い、拍手の中で退場する。三年間。いろいろなことがあった。祖父を見送ったこと。桜の力に目覚めたこと。竜馬と、ぶつかったこと。","f":"ryoma"},{"t":"n","s":"校庭に出ると、桜の枝が、風に揺れていた。蕾が、少しだけ膨らんでいる。","f":"ryoma"},{"t":"d","s":"「耀平」","f":"ryoma"},{"t":"d","s":"「乃亜」","f":"ryoma"},{"t":"d","s":"「卒業、したね」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「次は、高校だね」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"n","s":"乃亜は、一歩、耀平に近づいた。","f":"noa"},{"t":"d","s":"「ねえ、耀平」","f":"noa"},{"t":"d","s":"「なに」","f":"noa"},{"t":"d","s":"「高校でも、約束、覚えてる？」","f":"noa"},{"t":"d","s":"「覚えてる」","f":"noa"},{"t":"d","s":"「どこに行っても？」","f":"noa"},{"t":"d","s":"「どこに行っても」","f":"noa"},{"t":"d","s":"「……ありがと」","f":"noa"},{"t":"n","s":"乃亜は、小さく笑った。その瞳が、少し潤んでいる。","f":"noa","m":"happy"},{"t":"d","s":"「次は、どんな三年間になるのかな」","f":"noa"},{"t":"d","s":"「分からない。でも」","f":"noa"},{"t":"d","s":"「でも？」","f":"noa"},{"t":"d","s":"「たぶん、楽しいと思う」","f":"noa"},{"t":"d","s":"「根拠は？」","f":"noa"},{"t":"d","s":"「乃亜がいるから」","f":"noa"},{"t":"n","s":"乃亜の顔が、一瞬で真っ赤になった。","f":"noa"},{"t":"d","s":"「……ばか」","f":"noa"},{"t":"d","s":"「ごめん」","f":"noa"},{"t":"d","s":"「謝らなくていい」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"n","s":"桜の蕾が、風に揺れる。二人の足元に、一枚、薄桃色の花びらが、ひらりと舞い降りた。","f":"noa"}]}]},{"n":13,"title":"入学と、E組","sub":"高校・1年4月","era":"high","lead":"四月。桜並木の学園で、耀平は一人の少女を背負って走り、クラス分けに間に合わなかった。","scenes":[{"key":"13-1","title":"入学式","bg":"bg_graduation","dark":false,"mood":"daily","bgm":"daily4","cast":["ren","yohei","ryoma"],"lines":[{"t":"cg","v":"cg_reunion"},{"t":"n","s":"学園の正門から校舎までは、長い桜並木が続いていた。"},{"t":"n","s":"満開の花が風に揺れて、足元には薄桃色の絨毯ができている。新入生たちは、真新しい制服の襟を正しながら、その下を歩いていく。"},{"t":"d","s":"「すごい……」"},{"t":"d","s":"「耀平、口、開いてる」"},{"t":"d","s":"「あ」"},{"t":"d","s":"「あんた、桜の前だとすぐそうなる」"},{"t":"d","s":"「だって、きれいだから」"},{"t":"d","s":"「はいはい。行くよ」"},{"t":"n","s":"乃亜に袖を引かれて、耀平は歩き出す。肩にかかった花びらが、一枚だけ、ふわりと落ちた。","f":"noa"},{"t":"n","s":"講堂には、新入生が四百人ほど集まっていた。学園長の鷹野が短い訓示を述べ、そのあとで、紺色のブレザーを着た青年が壇上に立った。","f":"principal"},{"t":"n","s":"九条蓮だった。","f":"ren"},{"t":"d","s":"「新入生の皆さん。入学おめでとう。生徒会長の九条蓮です」","f":"ren"},{"t":"n","s":"落ち着いた声が、講堂の隅々まで届く。ざわめいていた新入生が、自然と口をつぐんだ。","f":"ren"},{"t":"d","s":"「強さは、誰かを守るためにある。三年間、それだけを覚えていてほしい」","f":"ren"},{"t":"n","s":"拍手が起きた。蓮は、ゆっくりと講堂を見渡す。その視線が、一瞬だけ、後ろのほうの一人の新入生で止まった。","f":"ren"},{"t":"n","s":"あくびをかみ殺している、眠そうな少年だった。","f":"ren"},{"t":"i","s":"（……まさかな）","f":"ren"},{"t":"n","s":"中学の修学旅行の夜。森に降っていた、季節外れの桜。蓮は小さく首を振って、壇を降りた。","f":"ren"},{"t":"d","s":"「耀平、見て。竜馬いる」","f":"ren"},{"t":"d","s":"「どこ」","f":"ren"},{"t":"d","s":"「前から三列目。背筋、ぴんとしてる」","f":"ren"},{"t":"d","s":"「ほんとだ」","f":"ren"},{"t":"n","s":"三列目の端に、見覚えのある頭があった。竜馬は、壇上を睨みつけるように見ていた。たぶん、睨んでいるつもりはない。ただ、真剣なだけだ。","f":"ryoma","m":"anger"},{"t":"d","s":"「クラス分けは、昼から掲示板だって。あたし、先に見てくる」","f":"ryoma"},{"t":"d","s":"「うん。おれ、寮に荷物置いてから行く」","f":"ryoma"},{"t":"d","s":"「遅れないでよ」","f":"ryoma"},{"t":"d","s":"「遅れないよ」","f":"ryoma"}]},{"key":"13-2","title":"倒れていた少女","bg":"bg_gate","dark":false,"mood":"daily","bgm":"daily5","cast":["yohei","noa"],"lines":[{"t":"n","s":"寮から校舎へ戻る近道は、旧校舎の渡り廊下だった。"},{"t":"n","s":"人のいない廊下に、窓から桜の花びらが吹き込んでいる。耀平は、その花びらを目で追いながら歩いて、ふと足を止めた。","f":"yohei"},{"t":"cg","v":"cg_collapsed"},{"t":"n","s":"水色の髪の少女が、そこに倒れていた。","f":"yohei"},{"t":"n","s":"壁にもたれるように崩れ落ちて、肩で小さく息をしている。顔色が、ひどく青白い。片方の手に、水色の髪留めを握りしめていた。","f":"yohei"},{"t":"d","s":"「大丈夫ですか」","f":"yohei"},{"t":"n","s":"駆け寄って、肩に触れる。冷たい。まるで、雪に触れたような肌だった。","f":"yohei"},{"t":"n","s":"少女の瞼が、ゆっくりと持ち上がった。潤んだ瞳が、耀平を見る。","f":"yohei"},{"t":"i","s":"（……あ）","f":"yohei"},{"t":"n","s":"耀平の心臓が、どくんと鳴った。","f":"yohei"},{"t":"n","s":"修学旅行の夜。乃亜が倒れ、自分も倒れた、あの森。痛みが消えていく感覚と、白い光と、やさしい声。","f":"noa"},{"t":"d","s":"「保健室、行きましょう。歩けますか」","f":"noa"},{"t":"d","s":"「……むり、みたい」","f":"noa"},{"t":"d","s":"「じゃあ、背負います」","f":"noa"},{"t":"n","s":"少女を背負って、耀平は走った。軽い。冷たい。でも、背中に伝わる鼓動は、確かに生きている。","f":"yohei"},{"t":"n","s":"遠くで、昼を告げるチャイムが鳴った。","f":"yohei"},{"t":"i","s":"（クラス分け……）","f":"yohei"},{"t":"n","s":"一瞬だけ、頭をよぎった。けれど、耀平は足を止めなかった。","f":"yohei"}]},{"key":"13-3","title":"保健室","bg":"bg_classroom_e","dark":false,"mood":"soft","bgm":"soft4","cast":["yohei","yuzuki"],"lines":[{"t":"cg","v":"cg_yuzuki_infirmary"},{"t":"n","s":"保健医の神崎は、少女をベッドに寝かせると、手早く診てくれた。"},{"t":"d","s":"「熱はないわね。脈も安定してる。力の使いすぎと、寝不足かしら。少し休めば大丈夫」"},{"t":"d","s":"「よかった」"},{"t":"d","s":"「あなた、この子の知り合い？」"},{"t":"d","s":"「……たぶん」"},{"t":"n","s":"神崎が出ていくと、保健室は静かになった。窓のカーテンが、春の風に揺れている。"},{"t":"n","s":"しばらくして、少女が目を開けた。天井を見て、それから、ベッドの横の椅子に座る耀平を見た。","f":"yohei"},{"t":"d","s":"「……耀平くん」","f":"yohei"},{"t":"n","s":"名前を呼ばれて、耀平は少し驚いた。","f":"yohei"},{"t":"d","s":"「覚えてたんですか」","f":"yohei"},{"t":"d","s":"「覚えてます。桜の人」","f":"yohei"},{"t":"n","s":"少女は、枕に頭を預けたまま、ふわりと笑った。","f":"yohei","m":"happy"},{"t":"d","s":"「朝霧柚月です。……また、会えたね」","f":"yohei"},{"t":"d","s":"「うん。また会えた」","f":"yohei"},{"t":"n","s":"耀平の返事は、いつもどおり淡々としていた。柚月は、少しだけ拍子抜けしたように瞬きをして、それから、くすりと笑った。","f":"yohei","m":"happy"},{"t":"d","s":"「変わらないんですね」","f":"yohei"},{"t":"d","s":"「何が」","f":"yohei"},{"t":"d","s":"「なんでもないです」","f":"yohei"},{"t":"n","s":"その時、廊下の向こうで、放送が鳴った。","f":"yohei"},{"t":"n","s":"〈クラス分けの掲示に来なかった新入生は、規定によりE組に編入となります。該当者は——〉","f":"yohei"},{"t":"n","s":"二人分の名前が、読み上げられた。","f":"yohei"},{"t":"n","s":"金井耀平。朝霧柚月。","f":"yohei"},{"t":"d","s":"「……あ」","f":"yohei"},{"t":"d","s":"「……あ」","f":"yohei"},{"t":"n","s":"二人は、顔を見合わせた。","f":"yohei"},{"t":"d","s":"「ごめんなさい。私のせいで」","f":"yohei"},{"t":"d","s":"「いいよ。どうせ、実技は普通にやったし」","f":"yohei"},{"t":"d","s":"「普通に？」","f":"yohei"},{"t":"d","s":"「ちゃんと、普通に」","f":"yohei"},{"t":"n","s":"柚月は、じっと耀平の顔を見た。そして、また、小さく笑った。","f":"yuzuki","m":"happy"},{"t":"d","s":"「……やっぱり、変わらない」","f":"yuzuki"}]},{"key":"13-4","title":"E組の初日","bg":"bg_classroom_e","dark":false,"mood":"daily","bgm":"daily2","cast":["yohei","yuzuki"],"lines":[{"t":"n","s":"E組の教室は、校舎のいちばん端にあった。窓の外には、古い桜の木が一本だけ立っている。"},{"t":"n","s":"担任の日下部が、出席簿を閉じた。"},{"t":"d","s":"「E組へようこそ。成績でも評価でも、いちばん下のクラスだ。だが、いちばん下から見える景色もある。一人ずつ、自己紹介をしてくれ」"},{"t":"n","s":"二十人の自己紹介が始まった。"},{"t":"d","s":"「相馬陽太です！　スキルは陽気伝染、周りを明るくします！　以上！」"},{"t":"n","s":"それだけで、教室がどっと笑った。陽太は、満足そうに胸を張る。","m":"happy"},{"t":"d","s":"「羽鳥琴音です。鳥と話せます。……あの、窓の外の雀が、さっきから、こっちを見てるって言ってます」"},{"t":"d","s":"「雀に見られてんのかよ！」"},{"t":"n","s":"また、笑いが起きた。"},{"t":"n","s":"大和田巌は「体が硬くなります。動けなくなります」と言って頭を掻き、神田慎吾は小さな声で「影武者を作れます……動きません」と付け足した。白石小春は「小さな傷なら、治せます」と、心配そうに教室を見回した。"},{"t":"n","s":"耀平の番が来た頃には、教室はすっかり温まっていた。","f":"yohei"},{"t":"d","s":"「金井耀平です。スキルは、一花心舞。桜が、少し舞います」","f":"yohei"},{"t":"n","s":"窓際の席で、耀平は小さく欠伸をした。","f":"yohei"},{"t":"d","s":"「……以上です」","f":"yohei"},{"t":"d","s":"「短っ！」","f":"yohei"},{"t":"d","s":"「眠そう！」","f":"yohei"},{"t":"n","s":"陽太の声に、また笑いが起きる。耀平はそのまま、机に頬杖をついて、目を閉じた。","f":"yohei"},{"t":"cg","v":"cg_yuzuki_seat"},{"t":"n","s":"隣の席で、柚月が、呆れたように、でも少しだけ楽しそうに、その横顔を見ていた。","f":"yuzuki"}]},{"key":"13-5","title":"乃亜の乱入","bg":"bg_classroom_e","dark":false,"mood":"soft","bgm":"soft2","cast":["yohei","noa","yuzuki"],"lines":[{"t":"n","s":"昼休み。E組の扉が、勢いよく開いた。"},{"t":"d","s":"「耀平」"},{"t":"n","s":"C組の乃亜だった。教室の空気が、一瞬で変わる。","f":"noa"},{"t":"d","s":"「うわ、C組の……」","f":"noa"},{"t":"d","s":"「めっちゃ可愛い」","f":"noa"},{"t":"d","s":"「なんでE組に」","f":"noa"},{"t":"n","s":"ざわめきを気にも留めず、乃亜はまっすぐ耀平の席まで歩いてきた。手には、包みが一つ。","f":"noa"},{"t":"d","s":"「あんた、クラス分けに来なかったでしょ。何してたの」","f":"noa"},{"t":"d","s":"「人を、保健室に運んでた」","f":"noa"},{"t":"d","s":"「人？」","f":"noa"},{"t":"n","s":"乃亜の視線が、耀平の隣の席に移った。","f":"noa"},{"t":"n","s":"水色の髪の少女が、静かにこちらを見ていた。","f":"noa"},{"t":"d","s":"「……誰」","f":"noa"},{"t":"d","s":"「朝霧柚月です。金井くんに、助けてもらいました」","f":"noa"},{"t":"d","s":"「ふうん」","f":"noa"},{"t":"n","s":"乃亜の目が、すっと細くなった。柚月は、穏やかに微笑んだまま、その視線を受け止めている。","f":"noa","m":"happy"},{"t":"d","s":"「……これ」","f":"noa"},{"t":"n","s":"乃亜は、包みを耀平の机に、とん、と置いた。","f":"noa"},{"t":"d","s":"「お弁当。作りすぎたから」","f":"noa"},{"t":"d","s":"「ありがとう」","f":"noa"},{"t":"d","s":"「余っただけだから」","f":"noa"},{"t":"n","s":"それだけ言って、乃亜は踵を返した。扉の前で、一度だけ振り返る。","f":"noa"},{"t":"d","s":"「耀平。……ちゃんと、食べなさいよ」","f":"noa"},{"t":"n","s":"扉が閉まった。教室中の視線が、耀平に集まる。","f":"yohei"},{"t":"d","s":"「金井、今の誰！」","f":"yohei"},{"t":"d","s":"「幼馴染」","f":"yohei"},{"t":"d","s":"「幼馴染であのお弁当！？」","f":"yohei"},{"t":"n","s":"陽太が叫ぶ。耀平は、包みをほどきながら首をかしげた。","f":"yohei"},{"t":"n","s":"隣で、柚月が、窓の外を見ていた。その横顔は、さっきより、ほんの少しだけ、つまらなさそうだった。","f":"yuzuki"}]}]},{"n":14,"title":"春の行事","sub":"高校・1年4〜5月","era":"high","lead":"E組の日々は、思っていたよりも穏やかに始まった。強さランキングと体育祭で、E組は少しずつ、ひとつになっていく。","scenes":[{"key":"14-1","title":"教科書","bg":"bg_classroom_e","dark":false,"mood":"soft","bgm":"soft3","cast":["yuzuki","yohei"],"lines":[{"t":"cg","v":"cg_yuzuki_textbook"},{"t":"n","s":"数学の時間。耀平は、鞄の中を三回探して、ようやく諦めた。","f":"yohei"},{"t":"i","s":"（教科書、寮に置いてきた）","f":"yohei"},{"t":"n","s":"隣から、机の脚が床をこする小さな音がした。柚月が、黙って自分の机を寄せてくる。","f":"yuzuki"},{"t":"d","s":"「……見れば」","f":"yuzuki"},{"t":"d","s":"「ありがとう、朝霧さん」","f":"yuzuki"},{"t":"d","s":"「別に。先生に当てられて、あなたが答えられないと、隣の私まで目立つから」","f":"yuzuki"},{"t":"n","s":"教科書が、二人の机のちょうど真ん中に置かれた。肩と肩が、触れそうで触れない。","f":"yuzuki"},{"t":"n","s":"耀平は、黒板と教科書を見比べながら、ノートを取った。ふと横を見ると、柚月はページではなく、窓の外を見ていた。耳の先が、ほんの少しだけ赤い。","f":"yohei","m":"blush"},{"t":"d","s":"「……何」","f":"yohei"},{"t":"d","s":"「なんでもない」","f":"yohei"},{"t":"d","s":"「前を見て」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"n","s":"授業が終わるまで、教科書は、真ん中から一ミリも動かなかった。","f":"yohei"}]},{"key":"14-2","title":"強さランキング","bg":"bg_classroom_e","dark":false,"mood":"daily","bgm":"daily1","cast":["yohei","ryoma","yuzuki"],"lines":[{"t":"n","s":"五月の初め。昇降口の掲示板に、一枚の大きな紙が貼り出された。"},{"t":"n","s":"〈一年生　強さランキング〉"},{"t":"n","s":"入学試験の実技と、四月の実技テストの結果から、一年生全員を順位付けしたものだ。人だかりの前の方で、誰かが叫んだ。"},{"t":"d","s":"「一位、A組の九十九巡！　入試首席の！」"},{"t":"d","s":"「やっぱりな」"},{"t":"d","s":"「竜馬も上の方にいるぞ！」"},{"t":"n","s":"耀平は、人混みの後ろから紙を見上げた。A組、B組、C組。E組の名前は、ほとんどが下の方に固まっている。","f":"yohei"},{"t":"n","s":"そして、いちばん下の欄外に、二つの名前があった。","f":"yohei"},{"t":"n","s":"〈順位外　金井耀平　朝霧柚月（クラス分け不参加のため）〉","f":"yohei"},{"t":"d","s":"「順位外って……」","f":"yohei"},{"t":"d","s":"「最下位より下じゃん」","f":"yohei"},{"t":"n","s":"くすくすと、笑い声が聞こえる。E組の何人かが、気まずそうに目を伏せた。","f":"yohei"},{"t":"d","s":"「おい」","f":"yohei"},{"t":"n","s":"人混みが割れた。竜馬だった。","f":"ryoma"},{"t":"d","s":"「誰だ、今笑ったの」","f":"ryoma"},{"t":"n","s":"笑い声が、ぴたりと止んだ。竜馬は、しばらく周りを睨みつけて、それから耀平を見た。","f":"ryoma","m":"anger"},{"t":"d","s":"「……順位なんて、どうでもいい」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「でも、どうでもよくねえ奴もいる。おまえのクラスの連中、見てみろ」","f":"ryoma"},{"t":"n","s":"耀平は振り返った。陽太が、無理に笑っていた。琴音が、俯いていた。","f":"yohei"},{"t":"n","s":"竜馬は、それ以上何も言わずに去っていった。","f":"ryoma"}]},{"key":"14-3","title":"体育祭","bg":"bg_schoolyard_middle","dark":false,"mood":"daily","bgm":"daily2","cast":["yohei","ryoma"],"lines":[{"t":"n","s":"五月の体育祭は、クラス対抗だった。"},{"t":"d","s":"「E組は、どうせ最下位だろ」"},{"t":"d","s":"「去年のE組も、全種目ビリだったらしいぜ」"},{"t":"n","s":"開会式の列で、そんな声が聞こえてくる。E組の列は、なんとなく元気がなかった。"},{"t":"d","s":"「よし！　E組、円陣組むぞ！」"},{"t":"n","s":"陽太が叫んだ。誰も動かない。陽太は、もう一度叫んだ。"},{"t":"d","s":"「陽気伝染！」"},{"t":"n","s":"ふわり、と空気が軽くなった。誰かが吹き出し、誰かが肩を組み、気づけば二十人の円ができていた。"},{"t":"d","s":"「いいか！　勝たなくていい！　ビリでも、最高に楽しいビリになろうぜ！」"},{"t":"d","s":"「なんだそれ」"},{"t":"d","s":"「最高に楽しいビリ！」"},{"t":"n","s":"笑いながら、E組は種目に散っていった。"},{"t":"n","s":"大縄跳びでは、巌が体を硬くして地面に足を固定し、縄の支点になった。綱引きでは、南が腕力だけを強化して、意外な粘りを見せた。玉入れでは、琴音が鳥たちに頼んで、かごの位置を教えてもらった。"},{"t":"d","s":"「ずるくない？」"},{"t":"d","s":"「スキル使用は自由です！」"},{"t":"n","s":"E組の順位は、少しずつ上がっていった。"},{"t":"n","s":"最後の種目は、クラス対抗リレーだった。E組のアンカーは、耀平だった。","f":"yohei"},{"t":"d","s":"「金井、頼んだぞ！」","f":"yohei"},{"t":"d","s":"「なんでおれ」","f":"yohei"},{"t":"d","s":"「眠そうな奴ほど足が速いって、陽太が言ってた！」","f":"yohei"},{"t":"d","s":"「根拠は」","f":"yohei"},{"t":"d","s":"「ない！」","f":"yohei"},{"t":"n","s":"バトンを受け取った時、E組は五クラス中の四位だった。","f":"yohei"},{"t":"n","s":"前を走るのは、A組のアンカー。竜馬だった。","f":"ryoma"},{"t":"i","s":"（……力は、抑える）","f":"ryoma"},{"t":"n","s":"耀平は、普通に走った。普通に、全力で。スキルは使わない。ただ、毎朝の素振りで鍛えた脚で、地面を蹴った。","f":"yohei"},{"t":"n","s":"差が、縮まっていく。","f":"yohei"},{"t":"n","s":"竜馬が、ちらりと振り返った。その目が、一瞬だけ、楽しそうに光った。","f":"ryoma","fx":"flash"},{"t":"d","s":"「来いよ、耀平！」","f":"ryoma"},{"t":"n","s":"二人は、並んだ。","f":"ryoma"},{"t":"n","s":"ゴールテープを切ったのは、竜馬の胸だった。半歩の差だった。","f":"ryoma"},{"t":"n","s":"けれど、E組の応援席は、優勝したみたいに沸いていた。","f":"ryoma"},{"t":"d","s":"「金井、すげえ！」","f":"ryoma"},{"t":"d","s":"「A組と並んだぞ！」","f":"ryoma"},{"t":"d","s":"「最高に楽しいビリ、どころじゃねえ！」","f":"ryoma"},{"t":"n","s":"総合順位は、四位だった。最下位ではなかった。","f":"ryoma"},{"t":"n","s":"その夜、E組は寮の食堂で、ジュースで乾杯をした。陽太が音頭を取り、巌が照れ、琴音が笑った。","f":"ryoma","m":"happy"},{"t":"n","s":"耀平は、少し離れた席で、その光景を見ていた。","f":"yohei"},{"t":"i","s":"（……このクラス、いいな）","f":"yohei"},{"t":"n","s":"窓の外で、桜の若葉が揺れていた。","f":"yohei"}]},{"key":"14-4","title":"昼休みの屋上","bg":"bg_rooftop","dark":false,"mood":"soft","bgm":"soft2","cast":["yohei","noa","yuzuki"],"lines":[{"t":"n","s":"体育祭の翌週。昼休みの廊下で、それは起きた。"},{"t":"d","s":"「耀平。お昼、屋上ね」"},{"t":"n","s":"C組の教室から出てきた乃亜が、当たり前のように言った。その手には、包みが二つある。","f":"noa"},{"t":"d","s":"「金井くん。今日、購買のパンが売り切れていたでしょう」","f":"noa"},{"t":"n","s":"反対側から、柚月の静かな声がした。その手にも、包みが二つ。","f":"yuzuki"},{"t":"cg","v":"cg_rival_glare"},{"t":"n","s":"乃亜と柚月の目が、廊下の真ん中で、ぶつかった。","f":"noa"},{"t":"d","s":"「……また、あなた」","f":"noa"},{"t":"d","s":"「同じクラスの、朝霧です。覚えてくださいね」","f":"noa"},{"t":"d","s":"「幼馴染の、乃亜」","f":"noa"},{"t":"d","s":"「そう。幼馴染の」","f":"noa"},{"t":"d","s":"「うん。幼馴染の」","f":"noa"},{"t":"n","s":"二人とも、笑っていた。笑っているのに、廊下の温度が、三度くらい下がった気がした。耀平の背中を、冷たい汗が伝う。","f":"yohei","m":"sweat"},{"t":"d","s":"「えっと……三人で、食べる？」","f":"yohei"},{"t":"n","s":"二人が、同時に耀平を見た。","f":"yohei"},{"t":"cg","v":"cg_rival_lunch"},{"t":"n","s":"屋上のベンチに、三人で並んだ。","f":"yohei"},{"t":"d","s":"「はい。卵焼き、甘いほう」","f":"yohei"},{"t":"d","s":"「金井くん。こちらは、だし巻きです」","f":"yohei"},{"t":"n","s":"左右から、同時に弁当箱が差し出される。耀平は、箸を持ったまま固まった。","f":"yohei"},{"t":"d","s":"「……どっちから、食べればいいの」","f":"yohei"},{"t":"d","s":"「好きなほうから」","f":"yohei"},{"t":"d","s":"「好きなほうからで、いいですよ」","f":"yohei"},{"t":"n","s":"声は優しい。目は、まったく優しくない。","f":"yohei"},{"t":"n","s":"耀平は、両方の卵焼きを一切れずつ取って、同時に口に入れた。","f":"yohei"},{"t":"d","s":"「……どっちも、おいしい」","f":"yohei"},{"t":"n","s":"乃亜が、ため息をついた。柚月が、小さく吹き出した。","f":"noa"},{"t":"d","s":"「ずるい答え」","f":"noa"},{"t":"d","s":"「ずるいですね」","f":"noa"},{"t":"n","s":"その日、二人の意見が合ったのは、それだけだった。","f":"noa"}]}]},{"n":15,"title":"迅と、夏","sub":"高校・1年6〜9月","era":"high","lead":"梅雨の帰り道で、耀平は名乗らない剣士と刀を交える。夏祭りと文化祭を経て、E組の夏は過ぎていく。","scenes":[{"key":"15-1","title":"帰り道の剣士","bg":"bg_riverside","dark":false,"mood":"daily","bgm":"daily1","cast":["yohei"],"lines":[{"t":"n","s":"六月。放課後の河川敷は、雨上がりの匂いがした。"},{"t":"n","s":"鍛錬のつもりで、耀平は遠回りをして帰っていた。土手の上で、腰の刃引き刀に手を添えて、歩きながら呼吸を整える。","f":"yohei"},{"t":"d","s":"「おい」","f":"yohei"},{"t":"n","s":"橋の下から、声がした。","f":"yohei"},{"t":"n","s":"黒い髪。鋭い目。耀平と同じくらいの年の少年が、一本の刀を肩に担いで立っていた。","f":"yohei"},{"t":"d","s":"「その刀。飾りか」","f":"yohei"},{"t":"d","s":"「……練習用です」","f":"yohei"},{"t":"d","s":"「抜け」","f":"yohei"},{"t":"n","s":"少年は、それだけ言って、刀を構えた。","f":"yohei"},{"t":"d","s":"「え、ちょっと」","f":"yohei"},{"t":"d","s":"「強い奴を探してる。おまえ、歩き方が違う。抜け」","f":"yohei"},{"t":"n","s":"返事を待たずに、少年が踏み込んだ。","f":"yohei"},{"t":"n","s":"速い。","f":"yohei"},{"t":"n","s":"耀平は、反射的に刀を抜いていた。刃と刃がぶつかり、火花が散る。一合。二合。三合。少年の刀は、雷みたいに速く、重い。","f":"yohei"},{"t":"i","s":"（この人、強い）","f":"yohei"},{"t":"n","s":"四合目で、耀平の足元に、桜の花びらが一枚、舞った。","f":"yohei"},{"t":"n","s":"少年の目が、わずかに見開かれた。","f":"yohei"},{"t":"d","s":"「……今の、何だ」","f":"yohei"},{"t":"d","s":"「スキルです。桜が、舞うだけの」","f":"yohei"},{"t":"d","s":"「舞うだけ、か」","f":"yohei"},{"t":"n","s":"少年は、刀を引いた。そして、じっと耀平を見た。","f":"yohei"},{"t":"d","s":"「おまえ、手を抜いてるな」","f":"yohei"},{"t":"d","s":"「抜いてません」","f":"yohei"},{"t":"d","s":"「抜いてる。目が、半分寝てる」","f":"yohei"},{"t":"n","s":"耀平は、言葉に詰まった。少年は、鼻で笑って、刀を鞘に収めた。","f":"yohei"},{"t":"d","s":"「名前は」","f":"yohei"},{"t":"d","s":"「金井耀平です。あなたは」","f":"yohei"},{"t":"d","s":"「名乗るほどの者じゃない」","f":"yohei"},{"t":"n","s":"少年は、背を向けた。","f":"yohei"},{"t":"d","s":"「次に会う時は、手を抜くな。抜いたら、斬る」","f":"yohei"},{"t":"n","s":"雨上がりの風が吹いて、少年の姿は、土手の向こうに消えた。","f":"yohei"},{"t":"n","s":"耀平は、刀を握ったまま、しばらく立ち尽くしていた。手のひらが、まだ、少し痺れていた。","f":"yohei"}]},{"key":"15-2","title":"雨の帰り道","bg":"bg_gate","dark":false,"mood":"soft","bgm":"soft1","cast":["yuzuki","yohei"],"lines":[{"t":"cg","v":"cg_yuzuki_umbrella"},{"t":"n","s":"数日後の放課後、昇降口の外は、どしゃ降りだった。"},{"t":"n","s":"柚月は、空を見上げたまま立ち尽くしていた。傘を持っていないらしい。","f":"yuzuki"},{"t":"d","s":"「朝霧さん。これ」","f":"yuzuki"},{"t":"d","s":"「……あなたの分は」","f":"yuzuki"},{"t":"d","s":"「一本しかないから、一緒に入ろう。寮まで、同じ方向だし」","f":"yuzuki"},{"t":"n","s":"柚月は少し迷ってから、傘の下に入ってきた。","f":"yuzuki"},{"t":"n","s":"並んで歩く。雨の音が、二人だけを閉じ込める。","f":"yuzuki"},{"t":"n","s":"しばらく歩いて、柚月が、ふと耀平の肩を見た。傘は、ずっと柚月のほうに傾いていて、耀平の左肩は、ぐっしょりと濡れていた。","f":"yuzuki"},{"t":"d","s":"「……濡れてる」","f":"yuzuki"},{"t":"d","s":"「平気。すぐ乾く」","f":"yuzuki"},{"t":"d","s":"「平気じゃない」","f":"yuzuki"},{"t":"n","s":"柚月は、傘の柄に、そっと手を添えた。傘が、少しだけ耀平のほうへ戻る。","f":"yuzuki"},{"t":"d","s":"「……これで、半分ずつ」","f":"yuzuki"},{"t":"n","s":"雨の中で、その声だけが、妙にはっきりと聞こえた。","f":"yuzuki"}]},{"key":"15-3","title":"夏祭り","bg":"bg_riverside","dark":true,"mood":"night","bgm":"night1","cast":["yohei","noa","yuzuki"],"lines":[{"t":"n","s":"七月。E組は、全員で町の夏祭りに行くことになった。"},{"t":"d","s":"「浴衣着てこいよ、浴衣！」"},{"t":"d","s":"「陽太、仕切りすぎ」"},{"t":"n","s":"神社の鳥居の前に、E組が集まっていく。耀平は、いつもの私服で、眠そうに立っていた。","f":"yohei"},{"t":"d","s":"「耀平」","f":"yohei"},{"t":"n","s":"振り向くと、乃亜が立っていた。紺地に、白い朝顔の柄の浴衣。髪には、水色の石の髪留め。","f":"noa"},{"t":"d","s":"「……C組なのに、来たの」","f":"noa"},{"t":"d","s":"「陽太くんに誘われたの。悪い？」","f":"noa"},{"t":"d","s":"「悪くない」","f":"noa"},{"t":"n","s":"その時、反対側から、からん、と下駄の音がした。","f":"noa"},{"t":"n","s":"柚月だった。淡い水色の浴衣に、雪の結晶の帯飾り。E組の男子たちが、一斉に息を呑んだ。","f":"yuzuki","m":"surprise"},{"t":"d","s":"「朝霧さん、やば……」","f":"yuzuki"},{"t":"d","s":"「乃亜さんも、やば……」","f":"yuzuki"},{"t":"n","s":"陽太が、耀平の脇腹を肘でつついた。","f":"yohei"},{"t":"d","s":"「おい金井。なんか言えよ。浴衣だぞ、浴衣」","f":"yohei"},{"t":"d","s":"「浴衣だね」","f":"yohei"},{"t":"d","s":"「それだけ！？」","f":"yohei"},{"t":"n","s":"耀平は、首をかしげた。乃亜と柚月が、同時に、小さく溜息をついた。","f":"yohei"},{"t":"d","s":"「……知ってた」","f":"yohei"},{"t":"d","s":"「……知ってました」","f":"yohei"},{"t":"n","s":"二人は顔を見合わせて、ばちり、と火花を散らした。それから、ぷいと顔をそむけた。","f":"yohei"},{"t":"n","s":"屋台の明かりの下を、E組がぞろぞろと歩いていく。金魚すくいで巌がポイを十枚破り、射的で慎吾が影武者に撃たせようとして失敗し、小春がりんご飴を三本持たされていた。","f":"yohei"},{"t":"n","s":"花火が上がった時、耀平は、ふと隣を見た。","f":"yohei"},{"t":"n","s":"右に乃亜。左に柚月。二人とも、空を見上げていた。","f":"noa"},{"t":"i","s":"（……きれいだな）","f":"noa"},{"t":"n","s":"それが花火のことなのか、自分でも分からないまま、耀平は夜空を見上げた。","f":"yohei"}]},{"key":"15-4","title":"文化祭","bg":"bg_classroom_e","dark":false,"mood":"daily","bgm":"daily4","cast":["yohei"],"lines":[{"t":"n","s":"九月。文化祭のE組の出し物は、お化け屋敷に決まった。"},{"t":"d","s":"「金井はお化け役な」"},{"t":"d","s":"「何の」"},{"t":"d","s":"「寝てる幽霊」"},{"t":"d","s":"「それ、ただの寝てる人」"},{"t":"d","s":"「採用！」"},{"t":"n","s":"準備期間のあいだ、E組の教室は毎日騒がしかった。黒川が壁をすり抜けて驚かす練習をし、日向が小さな灯りで不気味な雰囲気を作り、星野が「夢で見た」という怖い話を書いた。"},{"t":"n","s":"耀平は、だいたい寝ていた。","f":"yohei"},{"t":"d","s":"「金井、本番まで寝る気か」","f":"yohei"},{"t":"d","s":"「本番も寝る役だから」","f":"yohei"},{"t":"d","s":"「理屈は合ってる……」","f":"yohei"},{"t":"n","s":"文化祭当日。E組のお化け屋敷には、長い列ができた。","f":"yohei"},{"t":"n","s":"暗い廊下の奥で、布団に入って本当に寝ている耀平を見て、客たちは首をかしげて通り過ぎていった。けれど、黒川が壁から顔を出すたびに悲鳴が上がり、日向の灯りがふっと消えるたびに、また悲鳴が上がった。","f":"yohei"},{"t":"n","s":"夕方、教室の片付けをしながら、陽太が言った。","f":"yohei"},{"t":"d","s":"「なあ。E組で、よかったな」","f":"yohei"},{"t":"n","s":"誰も、言い返さなかった。","f":"yohei"},{"t":"n","s":"窓の外の桜の木が、少しだけ、葉の色を変え始めていた。","f":"yohei"}]}]},{"n":16,"title":"剣聖の死","sub":"高校・1年10月","era":"high","lead":"十月、剣聖が死んだ。耀平にとって、三度目の喪失だった。","scenes":[{"key":"16-1","title":"訃報","bg":"bg_dorm","dark":true,"mood":"sad","bgm":"sad2","cast":["yohei","noa"],"lines":[{"t":"n","s":"その朝、寮の食堂のテレビが、同じニュースを繰り返していた。"},{"t":"n","s":"〈剣聖、死去。国内最強の剣士、何者かに襲われたか〉"},{"t":"n","s":"画面には、見覚えのある顔が映っていた。四歳の夜、祖父の家のテレビで見た、あの剣士だった。"},{"t":"n","s":"耀平は、箸を持ったまま動けなかった。","f":"yohei"},{"t":"d","s":"「……耀平」","f":"yohei"},{"t":"n","s":"隣の席の乃亜が、そっと声をかけた。返事はできなかった。","f":"noa"},{"t":"i","s":"（両親。おじいちゃん。それから）","f":"noa"},{"t":"n","s":"会ったこともない人だった。言葉を交わしたこともない。それでも、耀平が剣を握った理由の、いちばん最初にいた人だった。","f":"yohei"},{"t":"n","s":"ニュースは続いていた。","f":"yohei"},{"t":"n","s":"〈現場には争った跡があり、警察は、組織的な犯行の可能性も視野に——〉","f":"yohei"},{"t":"d","s":"「組織的……」","f":"yohei"},{"t":"n","s":"食堂の誰かが呟いた。その言葉は、湯気の立つ味噌汁の上で、冷たく浮いていた。","f":"yohei"}]},{"key":"16-2","title":"雨の中庭","bg":"bg_schoolyard_middle","dark":false,"mood":"sad","bgm":"sad2","cast":["yohei","noa"],"lines":[{"t":"n","s":"昼休み。耀平は、傘を差して中庭に出た。","f":"yohei"},{"t":"n","s":"雨が降っていた。誰もいない中庭の真ん中で、古い桜の木が、濡れた葉を光らせている。","f":"yohei"},{"t":"d","s":"「やっぱり、ここだった」","f":"yohei"},{"t":"n","s":"後ろから声がした。乃亜だった。傘の下で、腕を組んでいる。","f":"noa"},{"t":"d","s":"「教室にいなかったから」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「……剣聖のこと？」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"n","s":"乃亜は、耀平の隣に立った。二つの傘が、少しだけ重なる。","f":"noa"},{"t":"d","s":"「会ったこと、ないんでしょ」","f":"noa"},{"t":"d","s":"「ない」","f":"noa"},{"t":"d","s":"「それでも、悲しい？」","f":"noa"},{"t":"d","s":"「……分からない。悲しいのか、悔しいのか」","f":"noa"},{"t":"n","s":"耀平は、桜の木を見上げた。","f":"yohei"},{"t":"d","s":"「おれ、あの人みたいになりたかった。今でも、なりたい。でも、あの人でも、殺されるんだって思ったら」","f":"yohei"},{"t":"n","s":"言葉が、続かなかった。","f":"yohei"},{"t":"n","s":"乃亜は、何も言わなかった。ただ、自分の傘を少し傾けて、耀平の肩にかかる雨を、そっと遮った。","f":"noa"},{"t":"d","s":"「……ありがと」","f":"noa"},{"t":"d","s":"「別に。あんたが風邪ひくと、面倒だから」","f":"noa"},{"t":"n","s":"雨の音だけが、しばらく二人を包んでいた。","f":"noa"}]},{"key":"16-3","title":"会長","bg":"bg_arena","dark":false,"mood":"daily","bgm":"daily4","cast":["ren","yohei","principal"],"lines":[{"t":"n","s":"放課後。剣道場の前で、耀平は九条蓮に呼び止められた。","f":"yohei"},{"t":"d","s":"「金井くん、だったな」","f":"yohei"},{"t":"d","s":"「はい」","f":"yohei"},{"t":"d","s":"「剣聖の件、聞いたか」","f":"yohei"},{"t":"d","s":"「……はい」","f":"yohei"},{"t":"n","s":"蓮は、いつもの穏やかな笑顔ではなかった。目の下に、うっすらと影がある。","f":"ren"},{"t":"d","s":"「学園長と剣聖は、古い友人だった。葬儀は三日後だ。学園長と先生方の多くが参列する。私も行く」","f":"ren"},{"t":"d","s":"「そう、ですか」","f":"ren"},{"t":"d","s":"「君は、剣聖に会ったことは」","f":"ren"},{"t":"d","s":"「ありません。テレビで、見ただけです」","f":"ren"},{"t":"d","s":"「そうか」","f":"ren"},{"t":"n","s":"蓮は、少しだけ黙った。それから、耀平の腰の刀に目を落とした。","f":"ren"},{"t":"d","s":"「その刀。いい刀だな」","f":"ren"},{"t":"d","s":"「中学の時に、刀鍛冶に打ち直してもらいました」","f":"ren"},{"t":"d","s":"「大事にするといい。剣聖も、刀を大事にする人だった」","f":"ren"},{"t":"n","s":"蓮は、それだけ言って、去っていった。","f":"ren"},{"t":"n","s":"その背中は、いつもより少しだけ、小さく見えた。","f":"ren"}]},{"key":"16-4","title":"葬儀の朝","bg":"bg_classroom_e","dark":true,"mood":"tense","bgm":"tense2","cast":["yuzuki","principal","ren"],"lines":[{"t":"n","s":"葬儀の日。学園は、朝から静かだった。"},{"t":"n","s":"学園長と先生たちの多くは、喪服を着て、早朝のバスで出ていった。生徒会長の九条も、数人の上級生と一緒に、それに付き添った。","f":"principal"},{"t":"n","s":"E組の教室には、日下部だけが残った。","f":"principal"},{"t":"d","s":"「今日は、一日自習だ。私も職員室と教室を行き来する。何かあれば、すぐに呼べ」","f":"principal"},{"t":"n","s":"それだけ言って、日下部は教室を出ていった。","f":"principal"},{"t":"n","s":"自習の教室は、ゆるい空気に包まれた。陽太がトランプを取り出し、琴音が窓の外の雀と話し、小春が誰かの指のささくれを治していた。","f":"principal"},{"t":"n","s":"耀平は、窓際の席で、机に突っ伏して眠っていた。","f":"yohei"},{"t":"d","s":"「金井、また寝てる」","f":"yohei"},{"t":"d","s":"「あいつ、いつも寝てるよな」","f":"yohei"},{"t":"d","s":"「強いのか弱いのか、わかんねえやつ」","f":"yohei"},{"t":"n","s":"そんな声が、ぼんやりと遠くに聞こえる。","f":"yohei"},{"t":"n","s":"隣の席で、柚月が、窓の外を見ていた。","f":"yuzuki"},{"t":"n","s":"空が、少しずつ、暗くなり始めていた。雨雲ではなかった。もっと重くて、もっと黒い何かが、学園の上に広がりつつあった。","f":"yuzuki"},{"t":"d","s":"「……琴音さん」","f":"yuzuki"},{"t":"n","s":"柚月が、静かに言った。","f":"yuzuki"},{"t":"d","s":"「鳥たち、何か言っていませんか」","f":"yuzuki"},{"t":"n","s":"琴音の顔から、すっと血の気が引いた。","f":"yuzuki"},{"t":"d","s":"「……みんな、逃げてる。全部の鳥が、学園から、逃げてる」","f":"yuzuki"}]}]},{"n":17,"title":"1度目の襲撃・E組","sub":"高校・1年10月","era":"high","lead":"剣聖の葬儀で先生が出払った日、天冠が学園を襲う。E組に現れたのは、紫の光をまとった幹部だった。","scenes":[{"key":"17-1","title":"影の兵","bg":"bg_classroom_e","dark":true,"mood":"battle","bgm":"battle1","cast":[],"lines":[{"t":"n","s":"窓ガラスが、一斉に震えた。"},{"t":"n","s":"校庭に、黒い影が湧き出していた。人の形をしているのに、顔がない。赤い目だけが、ぼうっと光っている。何十、何百という影が、校舎に向かって押し寄せてくる。"},{"t":"d","s":"「な、なんだよ、あれ……」"},{"t":"d","s":"「先生！　日下部先生！」"},{"t":"n","s":"廊下の向こうから、日下部が瞬間移動で現れた。"},{"t":"d","s":"「全員、窓から離れろ！　廊下側の壁に寄れ！」"},{"t":"n","s":"ガラスが割れた。影の兵が、教室に雪崩れ込んでくる。"},{"t":"d","s":"「巌、前！」"},{"t":"d","s":"「お、おう！　頑強不動！」"},{"t":"n","s":"巌が体を硬くして、扉の前に立ちはだかる。影の腕が、その肩に叩きつけられた。巌は動かない。けれど、動けないまま、少しずつ押し込まれていく。","fx":"shake"},{"t":"d","s":"「南、腕！」"},{"t":"d","s":"「筋力増強！」"},{"t":"n","s":"南の拳が、影の一体を吹き飛ばした。","fx":"shake"},{"t":"d","s":"「七瀬、足元に糸！」"},{"t":"d","s":"「う、うん！　糸結小縁！」"},{"t":"n","s":"細い糸が、影の足に絡みつく。影が、もつれて倒れる。"},{"t":"n","s":"普通のスキルたちが、驚くほど緻密につながっていく。けれど、影の数は、減らない。"},{"t":"d","s":"「痛っ……！」"},{"t":"n","s":"慎吾の腕が、影の爪に裂かれた。血が、床に落ちる。"},{"t":"d","s":"「慎吾くん！」"},{"t":"n","s":"小春が駆け寄ろうとした。けれど、別の影がその前に立ちはだかる。"},{"t":"n","s":"その時、冷たい風が、教室を吹き抜けた。"}]},{"key":"17-2","title":"淡雪","bg":"bg_classroom_e","dark":true,"mood":"tense","bgm":"tense1","cast":["yuzuki","yohei"],"lines":[{"t":"d","s":"「淡雪」"},{"t":"n","s":"静かな声だった。"},{"t":"n","s":"柚月が、慎吾の傷に、そっと手をかざしていた。白い光が、傷口を包む。裂けた肉が、ゆっくりと塞がっていく。","f":"yuzuki"},{"t":"d","s":"「え……痛く、ない」","f":"yuzuki"},{"t":"d","s":"「痛みを、拒絶しました。少し、休んでいて」","f":"yuzuki"},{"t":"n","s":"柚月は立ち上がり、次の怪我人のもとへ歩いていく。影の兵が、その背中に飛びかかった。","f":"yuzuki"},{"t":"d","s":"「風花」","f":"yuzuki"},{"t":"n","s":"柚月が振り返りもせずに指を振ると、見えない壁が、影を弾き飛ばした。","f":"yuzuki"},{"t":"n","s":"教室が、しんとなった。","f":"yuzuki"},{"t":"d","s":"「朝霧さん……今の、何」","f":"yuzuki"},{"t":"d","s":"「傷が、一瞬で」","f":"yuzuki"},{"t":"d","s":"「普通のスキルじゃ、ねえだろ……」","f":"yuzuki"},{"t":"n","s":"誰かが、震える声で言った。","f":"yuzuki"},{"t":"d","s":"「……規格外」","f":"yuzuki"},{"t":"n","s":"柚月は、答えなかった。ただ、静かに、次の怪我人の傷に手をかざした。","f":"yuzuki"},{"t":"n","s":"その間も、耀平は、机に突っ伏して眠っていた。","f":"yohei"}]},{"key":"17-3","title":"紫の女","bg":"bg_classroom_e","dark":true,"mood":"battle","bgm":"battle1","cast":["hotaru","yuzuki","yohei"],"lines":[{"t":"n","s":"廊下の奥から、硬い靴音が一つ、ゆっくりと近づいてきた。"},{"t":"n","s":"この影の兵とは、明らかに違う。もっと、重い。もっと、深い。"},{"t":"d","s":"「……あら。面白い」"},{"t":"n","s":"甘い声が、廊下に響いた。"},{"t":"d","s":"「最弱のクラスに、規格外が一輪。報告にはなかったわね」"},{"t":"n","s":"紫の光が、ひとつ、ふたつ。蛍のように、暗い廊下を漂ってくる。その光に照らされて、一人の女が、教室の入口に現れた。","f":"hotaru"},{"t":"n","s":"緩く波打つ、薄紫の長い髪。深い紫のコートに、銀の鎖。指先を頬に添えて、彼女は、楽しそうに目を細めた。","f":"hotaru"},{"t":"d","s":"「誰だ、てめえ！」","f":"hotaru"},{"t":"n","s":"南が、拳を振り上げて飛びかかった。","f":"hotaru"},{"t":"n","s":"女は、指を一本、動かしただけだった。紫の光の粒が、南の腕に触れる。","f":"hotaru"},{"t":"d","s":"「ぐ、あ……っ！」","f":"hotaru"},{"t":"n","s":"南が、腕を押さえて床に転がった。腕が、紫色に腫れ上がっている。","f":"hotaru"},{"t":"d","s":"「動かないほうがいいわよ。わたしの子たちは、触れるだけで効くの」","f":"hotaru"},{"t":"n","s":"光の粒の正体は、小さな虫だった。光る羽を持った、紫の毒虫。","f":"hotaru"},{"t":"n","s":"糸が飛んだ。巌が踏み出した。陽太が叫んだ。そのすべてが、紫の群れの前で、あっけなく崩れていった。","f":"hotaru"},{"t":"d","s":"「天冠、第六席。紫苑蛍」","f":"hotaru"},{"t":"n","s":"女は、スカートの裾をつまんで、優雅に一礼した。","f":"hotaru"},{"t":"d","s":"「規格外の子は、回収しろって言われてるの。でも、抵抗するなら、壊していいとも言われてる」","f":"hotaru"},{"t":"n","s":"蛍の視線が、柚月に向いた。","f":"hotaru"},{"t":"d","s":"「あなた、ずいぶん目立つことをしたわね」","f":"hotaru"},{"t":"n","s":"柚月は、小春をかばうように立ち上がった。","f":"yuzuki"},{"t":"d","s":"「……近づかないで」","f":"yuzuki"},{"t":"d","s":"「残念。近づくわ」","f":"yuzuki"},{"t":"n","s":"蛍の手に、紫の光が集まった。それは、細い刃の形になった。毒を凝らせた、紫の刃だった。","f":"hotaru"},{"t":"n","s":"蛍が、床を蹴った。","f":"hotaru"},{"t":"n","s":"速い。柚月の拒絶が間に合わない。紫の刃が、柚月の喉元に——","f":"yuzuki"},{"t":"n","s":"ぱしん、と。","f":"yuzuki"},{"t":"n","s":"乾いた音がした。","f":"yuzuki"},{"t":"n","s":"紫の刃が、止まっていた。一本の刃引きの刀が、それを受け止めていた。","f":"yuzuki"},{"t":"n","s":"刀身に、薄紅の花びらが、まとわりついている。","f":"yuzuki"},{"t":"d","s":"「……うるさい」","f":"yuzuki"},{"t":"n","s":"耀平だった。","f":"yohei"},{"t":"n","s":"寝起きの、半分閉じた目で、耀平は蛍を見上げていた。足元に、桜の花びらが、渦を巻いている。","f":"yohei"},{"t":"n","s":"百花繚乱。","f":"yohei","fx":"bloom"},{"t":"d","s":"「……誰？」","f":"yohei"},{"t":"n","s":"蛍は、刃を引いて、一歩下がった。その顔から、初めて、笑みが消えた。","f":"hotaru"},{"t":"d","s":"「今、寝てたわよね、あなた」","f":"hotaru"},{"t":"d","s":"「寝てました。うるさかったので」","f":"hotaru"},{"t":"d","s":"「それで、わたしの刃を受けたの？」","f":"hotaru"},{"t":"d","s":"「受けました」","f":"hotaru"},{"t":"n","s":"教室中が、言葉を失っていた。","f":"hotaru"},{"t":"d","s":"「金井……？」","f":"hotaru"},{"t":"d","s":"「あいつ、寝てたやつだよな……？」","f":"hotaru"},{"t":"n","s":"蛍の目が、耀平の刀にまとわりつく花びらに注がれた。","f":"hotaru"},{"t":"d","s":"「……色のついた花」","f":"hotaru"},{"t":"n","s":"その声は、さっきまでと違って、どこか熱を帯びていた。","f":"hotaru"},{"t":"d","s":"「見つけた。報告にあった、桜の子」","f":"hotaru"}]}]},{"n":18,"title":"1度目の襲撃・C組、A組、上級生","sub":"高校・1年10月","era":"high","lead":"同じ黒い空の下で、天冠の幹部たちが、規格外のいる教室を襲っていた。","scenes":[{"key":"18-1","title":"C組の乃亜","bg":"bg_classroom_middle","dark":true,"mood":"battle","bgm":"battle2","cast":["noa"],"lines":[{"t":"n","s":"C組の教室にも、影の兵が雪崩れ込んでいた。"},{"t":"d","s":"「乃亜ちゃん、こっち！」"},{"t":"d","s":"「うん。ありがと、真帆」"},{"t":"n","s":"友達に袖を引かれて、乃亜は壁際に身を寄せた。","f":"noa"},{"t":"n","s":"その時、教室中のガラスが、内側から粉々に砕けた。音だった。耳を塞いでも防げない、骨に響く音。","f":"noa","fx":"shake"},{"t":"d","s":"「天冠、第七席。鳴海響」","f":"noa"},{"t":"n","s":"教室の入口に、ヘッドホンを首にかけた細身の男が立っていた。","f":"noa"},{"t":"d","s":"「規格外が一人、いるはずだ。出てきてもらおうか」","f":"noa"},{"t":"n","s":"答えるように、一人の男子生徒が前に出た。結城蒼。見た目も態度も普通で、本人も自分が規格外だという自覚が薄い。","f":"noa"},{"t":"d","s":"「……たぶん、俺のことです」","f":"noa"},{"t":"d","s":"「お前か」","f":"noa"},{"t":"d","s":"「みんなには、手を出さないでください」","f":"noa"},{"t":"n","s":"蒼の背中の後ろで、乃亜が息を呑んだ。蒼は、ちらりと振り返って、乃亜に小さく笑いかけた。","f":"noa","m":"surprise"},{"t":"d","s":"「乃亜さん、下がってて」","f":"noa"},{"t":"n","s":"蒼の手に、音の波が生まれた。さっき鳴海が使ったのと、同じ音だった。","f":"noa"},{"t":"d","s":"「模倣再現。……見たスキルなら、真似できるんです」","f":"noa"},{"t":"d","s":"「面白い。だが、真似は真似だ」","f":"noa"},{"t":"n","s":"鳴海の音が、蒼の音を飲み込んだ。蒼の体が、教室の後ろの壁まで吹き飛ぶ。","f":"noa","fx":"shake"},{"t":"n","s":"立ち上がる。また吹き飛ぶ。立ち上がる。","f":"noa","fx":"shake"},{"t":"d","s":"「蒼くん、もういい！」","f":"noa"},{"t":"d","s":"「よくない、です。乃亜さんが、いるから」","f":"noa"},{"t":"n","s":"血を流しながら、蒼は、乃亜の前から一歩も退かなかった。","f":"noa"},{"t":"n","s":"乃亜の拳が、震えた。肘の内側が、ちりちりと痛む。","f":"noa"},{"t":"i","s":"（見られてはいけない。でも）","f":"noa"},{"t":"d","s":"「……碧水心希」","f":"noa"},{"t":"n","s":"薄い水の膜が、鳴海の音波を、ほんの一瞬だけ逸らした。その一瞬で、蒼は、膝をつきながらも倒れずにすんだ。","f":"noa"},{"t":"n","s":"鳴海の目が、乃亜に向いた。","f":"noa"},{"t":"d","s":"「……もう一人、面白いのがいるな」","f":"noa"}]},{"key":"18-2","title":"A組の竜馬","bg":"bg_classroom_middle","dark":true,"mood":"battle","bgm":"battle2","cast":["ryoma","tsukumo","yohei"],"lines":[{"t":"n","s":"A組は、光に満ちていた。"},{"t":"d","s":"「天冠、第八席。白銀煌」"},{"t":"n","s":"天井近くに浮かんだ男の指先から、細い光線が走る。机が、椅子が、黒板が、音もなく両断されていく。"},{"t":"d","s":"「規格外は、九十九巡。お前だな」"},{"t":"d","s":"「……そうだが」"},{"t":"n","s":"九十九巡は、入試首席の落ち着いた顔で立ち上がった。","f":"tsukumo"},{"t":"d","s":"「九十九変化」","f":"tsukumo"},{"t":"n","s":"巡の体が、次々と姿を変える。炎をまとい、岩を纏い、風になる。九十九通りの能力を、息をするように切り替えて、巡は白銀を押し込んでいった。","f":"tsukumo"},{"t":"d","s":"「やるな、坊や」","f":"tsukumo"},{"t":"d","s":"「まだです」","f":"tsukumo"},{"t":"n","s":"けれど、白銀は笑っていた。","f":"tsukumo"},{"t":"d","s":"「九十九通り。どれも、器用だ。だが、どれも、浅い」","f":"tsukumo"},{"t":"n","s":"一本の光線が、巡の切り替えの、ほんの一瞬の隙を貫いた。巡が、床に崩れ落ちる。","f":"tsukumo"},{"t":"d","s":"「巡！」","f":"tsukumo"},{"t":"n","s":"竜馬が飛び出した。","f":"ryoma"},{"t":"d","s":"「紅蓮爆炎！」","f":"ryoma"},{"t":"n","s":"赤い炎が、光の中を走る。白銀は、それを光の壁で受け止めて、首をかしげた。","f":"ryoma"},{"t":"d","s":"「規格外でもない子供が、何の用だ」","f":"ryoma"},{"t":"d","s":"「うるせえ！　うちのクラスに手ぇ出すな！」","f":"ryoma"},{"t":"n","s":"光線が、竜馬の肩を貫いた。もう一本が、脚を貫いた。竜馬は、膝をついた。","f":"ryoma"},{"t":"d","s":"「……まだ、だ」","f":"ryoma"},{"t":"d","s":"「いや。終わりだ」","f":"ryoma"},{"t":"n","s":"白銀の指先に、これまででいちばん強い光が集まった。竜馬の胸を、まっすぐ狙っている。","f":"ryoma"},{"t":"i","s":"（ここまで、か）","f":"ryoma"},{"t":"n","s":"竜馬は、目を閉じなかった。最後まで、光を睨みつけていた。","f":"ryoma","m":"anger"},{"t":"i","s":"（耀平。決着、つけられなくて、わりぃ）","f":"ryoma"}]},{"key":"18-3","title":"上級生たち","bg":"bg_gate","dark":true,"mood":"battle","bgm":"battle2","cast":["ren","saku"],"lines":[{"t":"n","s":"校門の前では、上級生たちが戦っていた。"},{"t":"d","s":"「数が、多いな」"},{"t":"d","s":"「笑っている場合じゃありません、獅子堂先輩」"},{"t":"n","s":"金色の咆哮が、影の兵を吹き飛ばす。獅子堂豪の隣で、書記の水無月紬が、淡々と避難の指示を出していた。荒神猛が獣のように影を薙ぎ、朱雀院灯の幻が実体になって門を塞ぎ、金子守が崩れた壁を別の物に作り替えていく。","fx":"shake"},{"t":"n","s":"けれど、その前に立ちはだかっていたのは、影の兵だけではなかった。"},{"t":"n","s":"天冠の第二席から第五席。四人の幹部が、上級生たちを押し込んでいた。"},{"t":"d","s":"「くそ……一人一人が、桁違いだ」"},{"t":"n","s":"獅子堂の拳が、鋼の体の男に弾かれた。時計を持った青年が、指を鳴らすたびに、紬の視界から消える。"},{"t":"n","s":"その時、校門の上に、一つの影が降り立った。"},{"t":"n","s":"紺色のブレザー。濡れたような黒髪。右手に、一本の刀。葬儀の黒い喪章を、胸につけたままだった。"},{"t":"d","s":"「……遅れたな」"},{"t":"n","s":"九条蓮だった。葬儀場から、知らせを受けて一人で引き返してきたのだ。","f":"ren"},{"t":"d","s":"「会長！」","f":"ren"},{"t":"d","s":"「豪、下がれ。ここからは、私が引き受ける」","f":"ren"},{"t":"n","s":"蓮の刀が、空を切った。斬撃が、距離を無視して、校庭の向こうの影の群れを両断する。","f":"ren"},{"t":"n","s":"空間断裂。","f":"ren"},{"t":"n","s":"その斬撃を、一つの影が、するりと抜けた。","f":"ren"},{"t":"d","s":"「九条蓮。噂どおりだ」","f":"ren"},{"t":"n","s":"細身の男が、蓮の影の中から、ぬるりと立ち上がった。","f":"ren"},{"t":"d","s":"「天冠、第二席。宵待朔」","f":"ren"},{"t":"d","s":"「影の中から喋るな。気味が悪い」","f":"ren"},{"t":"n","s":"蓮の刀と、朔の影が、ぶつかった。斬っても、斬っても、影は戻る。蓮の刀は、それでも止まらない。","f":"ren"},{"t":"n","s":"互角だった。","f":"ren"},{"t":"n","s":"二人の周りだけ、校庭の音が、遠のいていた。","f":"ren"}]}]},{"n":19,"title":"春雷","sub":"高校・1年10月","era":"high","lead":"E組で、耀平は初めて本気で刀を振るう。その一撃は、壁を突き抜けて、A組まで届いた。","scenes":[{"key":"19-1","title":"桜と毒","bg":"bg_classroom_e","dark":true,"mood":"battle","bgm":"battle1","cast":["hotaru","yohei","yuzuki"],"lines":[{"t":"n","s":"E組の教室で、蛍が両手を広げた。","f":"hotaru"},{"t":"d","s":"「千毒万蠱」","f":"hotaru"},{"t":"n","s":"光の粒が、一斉に羽を広げた。何百、何千という紫の蛍が、教室の天井を埋め尽くす。","f":"hotaru"},{"t":"d","s":"「みんな、伏せて！」","f":"hotaru"},{"t":"n","s":"柚月の拒絶が、クラスメイトたちを包んだ。毒の虫が、見えない壁に弾かれる。けれど、壁の外側には、まだ数え切れない群れが渦を巻いている。","f":"yuzuki"},{"t":"d","s":"「長くは、もちません」","f":"yuzuki"},{"t":"d","s":"「分かった」","f":"yuzuki"},{"t":"n","s":"耀平は、一歩前に出た。","f":"yohei"},{"t":"i","s":"（もう、隠せない）","f":"yohei"},{"t":"n","s":"隠そうとしていた。目立たないように、普通に。けれど、後ろには、E組がいる。陽太がいる。巌がいる。慎吾が、琴音が、小春がいる。","f":"yohei"},{"t":"d","s":"「朝霧さん」","f":"yohei"},{"t":"d","s":"「はい」","f":"yohei"},{"t":"d","s":"「みんなを、お願い」","f":"yohei"},{"t":"n","s":"耀平は、目を閉じた。","f":"yohei"},{"t":"n","s":"花びらが、教室いっぱいに咲いた。これまで見せてきた薄い花びらとは違う。濃く、深く、渦を巻く桜の嵐だった。","f":"yohei"},{"t":"n","s":"虫が、花びらに触れる。そのたびに、耀平の身体が、勝手に半歩ずれる。刀が、勝手に向きを変える。","f":"yohei"},{"t":"n","s":"一歩。また一歩。","f":"yohei"},{"t":"n","s":"毒の群れの真ん中を、耀平は、一度も触れられずに歩いていった。","f":"yohei"},{"t":"d","s":"「……当たらない？」","f":"yohei"},{"t":"n","s":"蛍の目が、見開かれた。","f":"hotaru"},{"t":"d","s":"「どうして。わたしの子たちが、一匹も」","f":"hotaru"},{"t":"d","s":"「花びらが、教えてくれるんです。どこから来るか」","f":"hotaru"},{"t":"n","s":"蛍の顔から、笑みが消えた。代わりに浮かんだのは、もっと熱い何かだった。","f":"hotaru"},{"t":"d","s":"「……いいわ。本気で、相手してあげる」","f":"hotaru"}]},{"key":"19-2","title":"百花繚乱　春雷","bg":"bg_classroom_e","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["hotaru","yohei","noa"],"lines":[{"t":"n","s":"紫の群れが、一つに集まった。巨大な、紫の壁。毒の蛍が、壁のように耀平の前に積み重なる。","f":"hotaru"},{"t":"d","s":"「千毒万蠱——蠱壁！」","f":"hotaru"},{"t":"n","s":"耀平は、刀を引いた。","f":"yohei"},{"t":"n","s":"花びらが、刀身に吸い込まれていく。一枚、また一枚。刃引きの刀が、薄紅の光をまとっていく。","f":"yohei"},{"t":"n","s":"祖父の家の縁側で振った、桜の枝。テレビの中の剣聖。中学の森で、乃亜を守った夜。全部が、この一振りの中に、流れ込んでいく気がした。","f":"noa"},{"t":"d","s":"「百花繚乱——」","f":"noa","fx":"bloom"},{"t":"n","s":"踏み込む。","f":"noa"},{"t":"d","s":"「春雷」","f":"noa"},{"t":"n","s":"桜色の稲妻が、教室を走った。","f":"noa"},{"t":"n","s":"紫の壁が、真っ二つに裂けた。その向こうにいた蛍の体が、桜の奔流に呑まれて、宙を舞う。","f":"hotaru"},{"t":"n","s":"教室の壁を、突き抜けた。","f":"hotaru"},{"t":"n","s":"隣の教室の壁を、突き抜けた。","f":"hotaru"},{"t":"n","s":"その隣も。その隣も。","f":"hotaru"},{"t":"n","s":"桜の奔流は、校舎を一直線に貫いて——","f":"hotaru"}]},{"key":"19-3","title":"A組","bg":"bg_classroom_middle","dark":true,"mood":"battle","bgm":"battle1","cast":["ryoma","yohei"],"lines":[{"t":"n","s":"A組の教室で、白銀煌の指先から、最後の光線が放たれようとしていた。"},{"t":"n","s":"その瞬間、教室の横の壁が、爆発した。","fx":"shake"},{"t":"n","s":"桜色の光と一緒に、何かが飛び込んできた。紫の髪の女だった。女は、白銀と竜馬のちょうど真ん中に転がり込んで、そのまま床に倒れ伏した。","f":"ryoma"},{"t":"n","s":"光線は、逸れた。天井を貫いて、空へ消えた。","f":"ryoma"},{"t":"d","s":"「……は？」","f":"ryoma"},{"t":"n","s":"白銀が、呆然と女を見下ろした。","f":"ryoma"},{"t":"d","s":"「蛍……？　第六席が、なぜ、ここに」","f":"ryoma"},{"t":"n","s":"竜馬も、呆然としていた。壁にぽっかりと空いた穴の向こうに、まっすぐ、廊下が見えた。その先も、その先も、壁に穴が空いている。","f":"ryoma"},{"t":"n","s":"いちばん奥の穴の向こうに、刀を下げた人影が立っていた。","f":"ryoma"},{"t":"n","s":"薄紅の花びらが、その周りで、静かに舞っていた。","f":"ryoma"},{"t":"d","s":"「……耀平」","f":"ryoma"},{"t":"n","s":"竜馬は、笑った。肩と脚から血を流しながら、それでも、笑った。","f":"ryoma","m":"happy"},{"t":"d","s":"「おまえ……やっぱ、すげえな」","f":"ryoma"}]},{"key":"19-4","title":"……きれい","bg":"bg_classroom_middle","dark":false,"mood":"soft","bgm":"soft3","cast":["hotaru","yohei","ryoma"],"lines":[{"t":"n","s":"瓦礫の中で、蛍は、ゆっくりと体を起こした。","f":"hotaru"},{"t":"n","s":"体中が痛い。毒の虫は、もう一匹も残っていない。こんな負け方をしたのは、生まれて初めてだった。","f":"hotaru"},{"t":"n","s":"穴の向こうから、足音が近づいてくる。","f":"hotaru"},{"t":"n","s":"耀平が、A組の教室に入ってきた。刀の先を、蛍の喉元に向ける。それ以上は、振らなかった。","f":"yohei"},{"t":"d","s":"「……もう、やめてください」","f":"yohei"},{"t":"n","s":"蛍は、床に手をついたまま、顔を上げた。","f":"hotaru"},{"t":"n","s":"薄紅の花びらが、ひらり、と彼女の髪に落ちた。窓からの逆光の中に、桜をまとった少年が立っていた。","f":"hotaru"},{"t":"i","s":"（……なに、これ）","f":"hotaru"},{"t":"cg","v":"cg_hotaru_kirei"},{"t":"n","s":"蛍の頬が、ゆっくりと、赤く染まった。","f":"hotaru","m":"blush"},{"t":"d","s":"「……きれい」","f":"hotaru"},{"t":"d","s":"「え」","f":"hotaru"},{"t":"d","s":"「ねえ、あなた。名前は」","f":"hotaru"},{"t":"d","s":"「……金井、耀平です」","f":"hotaru"},{"t":"d","s":"「耀平くん」","f":"hotaru"},{"t":"n","s":"蛍は、その名前を、舌の上で転がすように繰り返した。それから、なぜか、とても嬉しそうに笑った。","f":"hotaru","m":"happy"},{"t":"d","s":"「ふふ。負けちゃった」","f":"hotaru"},{"t":"n","s":"白銀が、眉をひそめた。竜馬が、ぽかんと口を開けた。","f":"ryoma"}]},{"key":"19-5","title":"帰還命令","bg":"bg_schoolyard_middle","dark":true,"mood":"tense","bgm":"tense1","cast":["hotaru","principal","saku"],"lines":[{"t":"n","s":"その時、窓の外の空に、黒い亀裂が走った。"},{"t":"n","s":"校庭の向こうで、天冠の幹部たちの気配が、一斉に引いていく。誰かの声が、空から降ってきた。穏やかで、感情のない声だった。"},{"t":"n","s":"〈目的は果たした。全員、戻れ〉"},{"t":"d","s":"「……帰還命令」"},{"t":"n","s":"白銀が、舌打ちをした。それから、倒れている蛍の腕を掴もうとした。","f":"hotaru"},{"t":"d","s":"「第六席は、回収する」","f":"hotaru"},{"t":"d","s":"「させるか」","f":"hotaru"},{"t":"n","s":"地面が、揺れた。","f":"hotaru"},{"t":"n","s":"A組の窓の外で、校庭の地面が、山のように持ち上がっていた。その頂に、白髪まじりの紳士が立っていた。黒い喪服のまま、静かにこちらを見ている。","f":"hotaru"},{"t":"n","s":"学園長の鷹野だった。","f":"principal"},{"t":"d","s":"「山河崩壊」","f":"principal"},{"t":"n","s":"持ち上がった大地が、白銀の足元から崩れ落ちた。白銀は、光になって空へ逃げる。その手は、蛍に届かなかった。","f":"principal"},{"t":"d","s":"「天冠第六席、紫苑蛍。身柄は、学園が預かる」","f":"principal"},{"t":"d","s":"「……はあい」","f":"principal"},{"t":"n","s":"蛍は、抵抗しなかった。連れて行かれる途中で、彼女は一度だけ、振り返った。","f":"hotaru"},{"t":"d","s":"「また会いに来てね、耀平くん。……ううん。わたしが、会いに行く」","f":"hotaru"},{"t":"n","s":"校門の前では、蓮と朔が、まだ刃を交えていた。帰還命令を聞いて、朔が影の中へ沈んでいく。","f":"saku"},{"t":"d","s":"「また会おう、九条蓮」","f":"saku"},{"t":"d","s":"「次は、逃がさない」","f":"saku"},{"t":"n","s":"黒い空が、少しずつ、晴れていった。","f":"saku"},{"t":"n","s":"天井の穴から、雲の切れ間の光が差し込んできた。","f":"saku"}]},{"key":"19-6","title":"墓前、ふたたび","bg":"bg_grave","dark":false,"mood":"sad","bgm":"sad1","cast":["yohei","jin"],"lines":[{"t":"n","s":"襲撃から数日後の日曜日。耀平は、剣聖の墓を訪れた。","f":"yohei"},{"t":"n","s":"町外れの丘の上。真新しい墓石の前には、花束と供物が、山のように積まれている。","f":"yohei"},{"t":"i","s":"（葬儀には、行けなかったから）","f":"yohei"},{"t":"n","s":"耀平は、白い花を一輪、そっと供えた。手を合わせて、目を閉じる。","f":"yohei"},{"t":"d","s":"「……花は、嫌いだと言ったはずだ」","f":"yohei"},{"t":"n","s":"背後から、聞き覚えのある声がした。","f":"yohei"},{"t":"n","s":"振り向くと、六月の河川敷で刀を交えた少年が立っていた。黒い髪。鋭い目。腰に、一本の刀。","f":"yohei"},{"t":"d","s":"「あの時の」","f":"yohei"},{"t":"d","s":"「覚えてたか」","f":"yohei"},{"t":"d","s":"「名乗らなかった人です」","f":"yohei"},{"t":"n","s":"少年は、鼻で笑った。それから、墓石に目を向けた。","f":"yohei","m":"happy"},{"t":"d","s":"「ここに眠ってるのは、俺の親父だ」","f":"yohei"},{"t":"n","s":"耀平は、息を呑んだ。","f":"yohei","m":"surprise"},{"t":"d","s":"「剣聖、が」","f":"yohei"},{"t":"d","s":"「ああ。天宮迅。それが俺の名前だ」","f":"yohei"},{"t":"n","s":"迅は、拳を握った。","f":"jin"},{"t":"d","s":"「親父は、天冠に殺された。……学園を襲ったのと、同じ連中だ」","f":"jin"},{"t":"n","s":"風が、墓地を吹き抜けた。","f":"jin"},{"t":"d","s":"「お前、学園の生徒だろう。噂は聞いた。天冠の幹部を、壁ごとぶち抜いた一年がいる、とな」","f":"jin"},{"t":"d","s":"「……はい」","f":"jin"},{"t":"d","s":"「やっぱり、手を抜いてたな」","f":"jin"},{"t":"n","s":"迅は、耀平の腰の刀に目をやった。","f":"jin"},{"t":"d","s":"「いずれ、本気のお前とやりたい。それまで、死ぬなよ」","f":"jin"},{"t":"n","s":"迅は、それだけ言うと、背を向けて歩き出した。丘を下りる背中は、やっぱり、どこか孤独に見えた。","f":"jin"}]}]},{"n":20,"title":"実力がバレる","sub":"高校・1年11月","era":"high","lead":"実力がバレた耀平は、なぜかモテ始める。乃亜と柚月の火花は、日に日に強くなっていく。","scenes":[{"key":"20-1","title":"E組の笑い","bg":"bg_classroom_e","dark":false,"mood":"daily","bgm":"daily1","cast":["yohei","yuzuki"],"lines":[{"t":"n","s":"襲撃の翌朝。E組の教室に入ると、全員が、耀平を見た。","f":"yohei"},{"t":"n","s":"誰も何も言わない。ただ、全員が、耀平を見ていた。","f":"yohei"},{"t":"d","s":"「……おはよう」","f":"yohei"},{"t":"n","s":"一瞬の沈黙のあと、陽太が、ぼそりと言った。","f":"yohei"},{"t":"d","s":"「金井。お前、ポケットに桜の花びら、どんだけ入れてたんだ」","f":"yohei"},{"t":"n","s":"教室中が、どっと笑った。","f":"yohei","m":"happy"},{"t":"d","s":"「いや、もう無理があるって」","f":"yohei"},{"t":"d","s":"「ごめん……」","f":"yohei"},{"t":"d","s":"「謝んなよ。助けてもらったんだ」","f":"yohei"},{"t":"d","s":"「……ありがと、金井」","f":"yohei"},{"t":"n","s":"南が、まだ包帯を巻いた腕で、耀平の背中を叩いた。巌が、照れくさそうに頭を掻いた。琴音が、雀から聞いたという話を始めた。A組の壁に、まだ穴が空いているらしい。","f":"yohei"},{"t":"n","s":"笑いながら、目の端に涙を浮かべている生徒もいた。耀平は、どう返していいか分からず、ただ頭を掻いた。","f":"yohei","m":"sad"},{"t":"n","s":"隣の席で、柚月が、小さく笑っていた。","f":"yuzuki"},{"t":"d","s":"「……私の秘密も、バレてしまいましたね」","f":"yuzuki"},{"t":"d","s":"「うん」","f":"yuzuki"},{"t":"d","s":"「でも、悪くないです。このクラスなら」","f":"yuzuki"}]},{"key":"20-2","title":"学園長室","bg":"bg_principal","dark":false,"mood":"daily","bgm":"daily2","cast":["principal","ren","yohei"],"lines":[{"t":"n","s":"放課後。耀平は、学園長室に呼ばれた。","f":"yohei"},{"t":"n","s":"部屋には、学園長の鷹野と、日下部と、九条蓮がいた。","f":"principal"},{"t":"d","s":"「座りなさい、金井くん」","f":"principal"},{"t":"n","s":"学園長は、穏やかな目をした、白髪まじりの紳士だった。仕立てのいい黒いスーツの襟を、ゆっくりと正している。","f":"principal"},{"t":"d","s":"「単刀直入に聞こう。君は、規格外だね」","f":"principal"},{"t":"d","s":"「……はい。中学一年の、修学旅行の夜からです」","f":"principal"},{"t":"n","s":"蓮が、小さく息を吐いた。","f":"ren"},{"t":"d","s":"「やはり、あの夜の桜は、君だったのか。……まさかな、と思っていた」","f":"ren"},{"t":"n","s":"日下部が、わずかに眉を寄せた。","f":"ren"},{"t":"d","s":"「実技テストで、君は明らかに手を抜いていた。評価を最下位に留めたのは、私の判断だ。規格外は、天冠に狙われる。目立たないほうが、守りやすいと思った」","f":"ren"},{"t":"d","s":"「先生……」","f":"ren"},{"t":"d","s":"「だが、もう隠し通すことは難しい。だから、君に選んでほしい」","f":"ren"},{"t":"n","s":"学園長が、穏やかに言った。","f":"principal"},{"t":"d","s":"「力を隠して、E組に留まるか。それとも、上のクラスで堂々と力を磨くか」","f":"principal"},{"t":"d","s":"「E組に、いたいです。あのクラスの人たちが、好きだから」","f":"principal"},{"t":"n","s":"学園長は、にこりと笑った。","f":"principal","m":"happy"},{"t":"d","s":"「よろしい。ただし、授業とは別に、九条くんと鍛錬の時間を持ちなさい」","f":"principal"},{"t":"d","s":"「私でよければ、喜んで」","f":"principal"},{"t":"n","s":"それから、学園長は、困ったように顎を撫でた。","f":"principal"},{"t":"d","s":"「それと、第六席の件だ。彼女の身柄は、学園の地下で預かっている。取り調べには、何ひとつ答えん。そのくせ、君の名前ばかり口にしているそうだ」","f":"principal"},{"t":"d","s":"「……え」","f":"principal"},{"t":"d","s":"「『耀平くんに会わせてくれたら考える』、だそうだ」","f":"principal"},{"t":"n","s":"蓮が、小さく咳払いをした。耀平は、どんな顔をすればいいのか分からなかった。","f":"ren"}]},{"key":"20-3","title":"モテる","bg":"bg_gate","dark":false,"mood":"daily","bgm":"daily3","cast":["noa","yohei","yuzuki"],"lines":[{"t":"n","s":"それから一週間。耀平の周りは、急に騒がしくなった。","f":"yohei"},{"t":"d","s":"「金井くん、お弁当作ってきたんだけど……」","f":"yohei"},{"t":"d","s":"「金井先輩、サインください！」","f":"yohei"},{"t":"d","s":"「E組の金井って、あの寝てる人？　えっ、かっこよくない？」","f":"yohei"},{"t":"n","s":"廊下を歩けば、知らない生徒に話しかけられる。下駄箱には、手紙が入っている。耀平は、そのたびに首をかしげた。","f":"yohei"},{"t":"d","s":"「なんで、急に」","f":"yohei"},{"t":"d","s":"「知らないの？　あんた、学園中の噂になってるのよ」","f":"yohei"},{"t":"n","s":"乃亜が、昇降口で腕を組んでいた。不機嫌だった。","f":"noa"},{"t":"d","s":"「乃亜、E組に来ないの？　昼とか」","f":"noa"},{"t":"d","s":"「……行きたいけど。C組とE組、今ちょっと、空気悪いの。E組だけ英雄扱いで、C組の子たちが拗ねてて」","f":"noa"},{"t":"d","s":"「そっか」","f":"noa"},{"t":"d","s":"「そっか、じゃないわよ」","f":"noa"},{"t":"n","s":"その時、後ろから、すっと影が差した。","f":"noa"},{"t":"d","s":"「金井くん。今日の鍛錬、私も見学していいですか」","f":"noa"},{"t":"n","s":"柚月だった。乃亜の目が、すっと細くなる。","f":"yuzuki"},{"t":"d","s":"「……朝霧さん。耀平と、同じクラスでいいわね」","f":"yuzuki"},{"t":"d","s":"「はい。隣の席です」","f":"yuzuki"},{"t":"d","s":"「知ってる」","f":"yuzuki"},{"t":"d","s":"「毎日、隣です」","f":"yuzuki"},{"t":"n","s":"柚月は、にっこりと笑った。それから、乃亜にだけ見えるように、ほんの少しだけ、舌を出した。","f":"yuzuki","m":"happy"},{"t":"d","s":"「べーっ」","f":"yuzuki"},{"t":"n","s":"乃亜の眉が、ぴくりと跳ねた。","f":"noa"},{"t":"d","s":"「……耀平。あたし、帰る」","f":"noa"},{"t":"d","s":"「え、うん」","f":"noa"},{"t":"d","s":"「あんたも、気をつけなさいよ。いろいろと」","f":"noa"},{"t":"n","s":"ずかずかと去っていく乃亜の背中を、耀平はぽかんと見送った。隣で、柚月が、何事もなかったように微笑んでいた。","f":"noa","m":"happy"}]},{"key":"20-4","title":"放課後の校門","bg":"bg_gate","dark":false,"mood":"daily","bgm":"daily4","cast":["yohei","noa","yuzuki"],"lines":[{"t":"cg","v":"cg_rival_tug"},{"t":"n","s":"数日後。放課後の校門で、耀平は、両腕を同時に掴まれていた。","f":"yohei"},{"t":"d","s":"「耀平。今日は、寮でご飯作るから。食べに来て」","f":"yohei"},{"t":"d","s":"「金井くん。今日は、会長との鍛錬の前に、練習に付き合ってくれる約束です」","f":"yohei"},{"t":"n","s":"左に乃亜。右に柚月。二人とも、静かな顔で、少しずつ腕を引っ張っている。","f":"noa"},{"t":"d","s":"「あの、両方、行けるかも」","f":"noa"},{"t":"d","s":"「時間、かぶってる」","f":"noa"},{"t":"d","s":"「かぶっていますね」","f":"noa"},{"t":"n","s":"遠巻きに見ていたE組のクラスメイトたちが、腹を抱えて笑っていた。","f":"noa"},{"t":"d","s":"「金井、規格外なのは剣だけじゃなかったな！」","f":"noa"},{"t":"d","s":"「両手に花ってやつだ！」","f":"noa"},{"t":"d","s":"「花びらだけに！」","f":"noa"},{"t":"d","s":"「うまくないから！」","f":"noa"},{"t":"n","s":"耀平の叫びが、夕方の校門に響いた。","f":"yohei"}]},{"key":"20-5","title":"袖","bg":"bg_classroom_e","dark":false,"mood":"soft","bgm":"soft1","cast":["yuzuki","yohei"],"lines":[{"t":"n","s":"十二月。学園の警備は、目に見えて強化されていた。"},{"t":"n","s":"校門には、見慣れない大人たちが立つようになった。夜の見回りが増え、生徒の外出には許可が必要になった。それでも、E組は、E組だった。"},{"t":"d","s":"「クリスマス会、やるぞ！」"},{"t":"n","s":"陽太の一声で、E組の教室は飾り付けられた。日向の小さな灯りがツリーの代わりになり、琴音が鳥たちに頼んで、窓の外に冬の小鳥を集めた。"},{"t":"cg","v":"cg_yuzuki_sleeve"},{"t":"n","s":"会の終わり。片付けを抜け出して、耀平が廊下に出ると、背中の袖を、くい、と引かれた。","f":"yohei"},{"t":"n","s":"振り向くと、柚月が、袖の端をつまんだまま、俯いていた。","f":"yuzuki"},{"t":"d","s":"「……朝霧さん？」","f":"yuzuki"},{"t":"d","s":"「これ」","f":"yuzuki"},{"t":"n","s":"差し出されたのは、小さな包みだった。開けると、雪の結晶の形をした、小さな刀の飾り紐が入っていた。","f":"yuzuki"},{"t":"d","s":"「お守りの隣に、付けてください。……あの夜、助けてもらったお礼です。森の夜と、今年の分」","f":"yuzuki"},{"t":"d","s":"「ありがとう。大事にする」","f":"yuzuki"},{"t":"d","s":"「……顔を見れば、分かります。本当に、そう思ってくれてる」","f":"yuzuki"},{"t":"n","s":"柚月は、袖を離した。夕日が、廊下を橙色に染めていた。","f":"yuzuki"},{"t":"d","s":"「来年も、隣の席だといいですね」","f":"yuzuki"},{"t":"d","s":"「うん」","f":"yuzuki"},{"t":"n","s":"その約束が、どれほど重いものになるのか。この時の二人は、まだ知らなかった。","f":"yuzuki"}]}]},{"n":21,"title":"2度目の襲撃","sub":"高校・1年12月","era":"high","lead":"警備が強化された十二月、第一席がE組に来る。寝坊した耀平が駆けつけた時、教室はもう壊れていた。","scenes":[{"key":"21-1","title":"寝坊","bg":"bg_dorm","dark":true,"mood":"tense","bgm":"tense1","cast":["yohei"],"lines":[{"t":"n","s":"その朝、耀平は、目覚ましを止めた記憶がなかった。","f":"yohei"},{"t":"n","s":"前の晩、蓮との鍛錬が夜遅くまで続いた。部屋に戻って、刀を手入れして、気づいたら窓の外が明るかった。","f":"yohei"},{"t":"d","s":"「……やばい」","f":"yohei"},{"t":"n","s":"時計は、一時間目の始まりを、とっくに過ぎていた。","f":"yohei"},{"t":"n","s":"制服に袖を通しながら、耀平は窓の外を見た。冬の空は、晴れていた。けれど、学園の方角の空だけが、妙に低く、重く見えた。","f":"yohei"},{"t":"i","s":"（……何だ、あれ）","f":"yohei"},{"t":"n","s":"ずしん、と。","f":"yohei"},{"t":"n","s":"寮の床が、揺れた。","f":"yohei"}]},{"key":"21-2","title":"第一席","bg":"bg_classroom_e","dark":true,"mood":"battle","bgm":"battle1","cast":["genzo"],"lines":[{"t":"n","s":"E組の教室では、一時間目の授業が始まったばかりだった。"},{"t":"d","s":"「……雀が、騒いでる」"},{"t":"n","s":"琴音が、窓の外を見て、顔色を変えた。"},{"t":"d","s":"「先生！　何か来る！　空から、すごく重いものが——」"},{"t":"n","s":"言い終わる前に、教室の天井が、軋んだ。"},{"t":"n","s":"重い。空気が、鉛のように重い。机が床にめり込み、窓ガラスが内側にたわむ。生徒たちが、椅子ごと床に押しつけられた。"},{"t":"d","s":"「重力……!?」"},{"t":"n","s":"日下部が、瞬間移動で教室の前に立った。その体も、床に縫いつけられるように沈んでいく。"},{"t":"n","s":"天井が、静かに裂けた。"},{"t":"n","s":"その裂け目から、一人の巨漢が、ゆっくりと降りてきた。黒い軍服のような長いコート。刈り込んだ髪。顔を斜めに走る傷。"},{"t":"d","s":"「八天、第一席。黒鉄玄蔵」"},{"t":"n","s":"低い声だった。"},{"t":"d","s":"「桜の規格外と、拒絶の規格外。この教室にいると聞いた。どこだ」"},{"t":"n","s":"誰も答えなかった。答えられなかった。重さで、息をするのもやっとだった。"},{"t":"n","s":"琴音の窓の外で、鳥たちが一斉に鳴いた。玄蔵の目が、そちらを向いた。","f":"genzo"},{"t":"d","s":"「鳥と話すスキルか。……仲間に知らせたな」","f":"genzo"},{"t":"n","s":"玄蔵が、指を一本、琴音に向けた。","f":"genzo"},{"t":"d","s":"「最初に、知らせる者を潰す。戦の常道だ」","f":"genzo"},{"t":"d","s":"「琴音！」","f":"genzo"},{"t":"n","s":"重さが、琴音一人に集まった。","f":"genzo"},{"t":"n","s":"鳥たちの悲鳴が、冬の空に散っていった。","f":"genzo"}]},{"key":"21-3","title":"盾","bg":"bg_classroom_e","dark":false,"mood":"sad","bgm":"sad1","cast":["genzo"],"lines":[{"t":"d","s":"「頑強不動！」"},{"t":"n","s":"巌が、立ち上がった。動けないはずの体で、玄蔵とクラスメイトの間に、一歩、踏み出した。","f":"genzo"},{"t":"d","s":"「……ははっ、重いな、これ。俺のスキル、こういう時、何の役にも立たねえのが悔しいわ」","f":"genzo"},{"t":"d","s":"「巌、よせ！」","f":"genzo"},{"t":"d","s":"「よせねえよ。俺、動けないのが悩みだったけど」","f":"genzo"},{"t":"n","s":"巌の体が、硬く、硬く、固まっていく。玄蔵の重さが、その一点に集まる。","f":"genzo"},{"t":"d","s":"「動かなくていい場面も、あるんだな」","f":"genzo"},{"t":"n","s":"巌の足元の床が、砕けた。それでも、巌は倒れなかった。最後まで、立ったまま、盾になっていた。","f":"genzo","fx":"shake"},{"t":"d","s":"「身代分身」","f":"genzo"},{"t":"n","s":"慎吾の影武者が、小春の前に立った。重力の槍が、影武者を貫く。次の一撃は、慎吾自身を貫いた。","f":"genzo"},{"t":"d","s":"「小春ちゃん、走って。治癒の風、まだ必要な人がいる」","f":"genzo"},{"t":"d","s":"「慎吾くん……！」","f":"genzo"},{"t":"d","s":"「俺、臆病だからさ。最後くらい」","f":"genzo"},{"t":"n","s":"慎吾は、笑っていた。","f":"genzo"},{"t":"d","s":"「陽気伝染！」","f":"genzo"},{"t":"n","s":"陽太の声が、重い空気の中に響いた。","f":"genzo"},{"t":"d","s":"「みんな、顔上げろ！　大丈夫だ！　E組は、最高に楽しいクラスだろ！」","f":"genzo"},{"t":"n","s":"ふわり、と空気が、ほんの少しだけ軽くなった。誰かが、泣きながら笑った。誰かが、陽太の名前を呼んだ。","f":"genzo","m":"sad"},{"t":"n","s":"陽太は、最後まで、みんなを励まし続けていた。重さが、その背中に落ちるまで。","f":"genzo"}]},{"key":"21-4","title":"遅すぎた","bg":"bg_classroom_e","dark":true,"mood":"battle","bgm":"battle1","cast":["yohei","genzo","yuzuki"],"lines":[{"t":"n","s":"耀平が教室に飛び込んだ時、そこにはもう、教室の形が残っていなかった。","f":"yohei"},{"t":"n","s":"崩れた天井。砕けた床。動かない人影。","f":"yohei","fx":"shake"},{"t":"d","s":"「……陽太」","f":"yohei"},{"t":"n","s":"返事はなかった。","f":"yohei"},{"t":"d","s":"「巌。慎吾。琴音」","f":"yohei"},{"t":"n","s":"返事は、なかった。","f":"yohei"},{"t":"d","s":"「来たか、桜の子」","f":"yohei"},{"t":"n","s":"瓦礫の向こうに、玄蔵が立っていた。その足元で、柚月が、膝をついていた。拒絶の壁で、残りのクラスメイトを必死に守っている。壁に、細かいひびが走っていた。","f":"genzo"},{"t":"n","s":"耀平の中で、何かが切れた。","f":"yohei"},{"t":"d","s":"「百花繚乱——！」","f":"yohei","fx":"bloom"},{"t":"n","s":"花びらが、教室を埋め尽くした。耀平は、床を蹴った。","f":"yohei"},{"t":"n","s":"刀が、玄蔵に届く前に、止まった。","f":"genzo"},{"t":"n","s":"重い。体が、床に縫いつけられる。花びらが、一枚、また一枚と、地面に落ちていく。","f":"genzo"},{"t":"d","s":"「剣聖と同じ技だ」","f":"genzo"},{"t":"n","s":"玄蔵が、静かに言った。","f":"genzo"},{"t":"d","s":"「あの男も、これで死んだ」","f":"genzo"},{"t":"n","s":"耀平は、床に叩きつけられた。立ち上がろうとして、また叩きつけられる。刀が、手から離れた。","f":"yohei","fx":"shake"},{"t":"n","s":"全く、届かなかった。","f":"yohei"},{"t":"d","s":"「……これが、規格外か。期待外れだな」","f":"yohei"},{"t":"n","s":"玄蔵の拳が、耀平の頭上に振り上げられた。","f":"genzo"}]},{"key":"21-5","title":"万花繚乱","bg":"bg_classroom_e","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["yohei","genzo","yuzuki"],"lines":[{"t":"d","s":"「させない」"},{"t":"n","s":"白い風が、耀平の前に立った。","f":"yohei"},{"t":"n","s":"柚月だった。拒絶の壁を捨てて、耀平と玄蔵の間に、両腕を広げて立っていた。","f":"yuzuki"},{"t":"n","s":"玄蔵の拳から放たれた重力の杭が、柚月の胸を、貫いた。","f":"genzo"},{"t":"d","s":"「……朝霧、さん」","f":"genzo"},{"t":"n","s":"柚月の体が、ゆっくりと、耀平の腕の中に倒れ込んできた。冷たい。いつもより、ずっと冷たい。","f":"yuzuki"},{"t":"d","s":"「……耀平、くん。無事、ですか」","f":"yuzuki"},{"t":"d","s":"「しゃべらないで」","f":"yuzuki"},{"t":"d","s":"「よかった」","f":"yuzuki"},{"t":"n","s":"柚月は、微笑んだ。そして、目を閉じた。","f":"yuzuki","m":"happy"},{"t":"n","s":"耀平の中で、何かが、音を立てて開いた。","f":"yohei"},{"t":"i","s":"（守れなかった。陽太も。巌も。慎吾も。琴音も）","f":"yohei"},{"t":"i","s":"（それでも）","f":"yohei"},{"t":"i","s":"（この人だけは）","f":"yohei"},{"t":"n","s":"花びらが、舞った。","f":"yohei"},{"t":"n","s":"桜だけではなかった。梅が。藤が。菫が。椿が。菊が。名前も知らない花が。色とりどりの花びらが、渦を巻いて、教室を、校舎を、空を埋め尽くしていく。","f":"yohei"},{"t":"cg","v":"cg_banka"},{"t":"d","s":"「万花繚乱」","f":"yohei","fx":"bloom"},{"t":"n","s":"重さが、消えた。","f":"yohei"},{"t":"n","s":"いや、消えたのではない。無数の花びらが、重さの隙間を、ふわりと抜けていく。重力が、花びらを捕まえられない。","f":"yohei"},{"t":"n","s":"耀平は、刀を拾い上げた。","f":"yohei"},{"t":"n","s":"一閃。","f":"yohei","fx":"flash"},{"t":"n","s":"玄蔵の胸から肩にかけて、深い傷が走った。同時に、耀平の脇腹にも、重力の杭が食い込んでいた。","f":"genzo"},{"t":"n","s":"二人は、同時に膝をついた。","f":"genzo"},{"t":"n","s":"玄蔵は、自分の胸の傷を見下ろした。そして、笑った。初めて見せる、心の底から楽しそうな笑みだった。","f":"genzo","m":"happy"},{"t":"d","s":"「……認める。お前は、強い」","f":"genzo"},{"t":"n","s":"玄蔵は、ゆっくりと立ち上がった。","f":"genzo"},{"t":"d","s":"「次は、互いに本気でやろう。桜の少年」","f":"genzo"},{"t":"n","s":"天井の裂け目から、玄蔵の姿が、空へ消えていった。","f":"genzo"}]},{"key":"21-6","title":"雪月風花","bg":"bg_classroom_e","dark":false,"mood":"climax","bgm":"climax2","cast":["yuzuki","yohei","tsukumo"],"lines":[{"t":"d","s":"「朝霧さん」"},{"t":"n","s":"耀平は、腕の中の柚月を見下ろした。息が、ない。","f":"yohei"},{"t":"d","s":"「朝霧さん。起きて」","f":"yohei"},{"t":"n","s":"花びらが、柚月の上に、ひらひらと降り積もっていく。","f":"yuzuki"},{"t":"n","s":"その時だった。","f":"yuzuki"},{"t":"n","s":"柚月の胸の傷が、白く光った。","f":"yuzuki","fx":"flash"},{"t":"n","s":"痛みを拒む力が、柚月自身に向かっていた。傷を拒み、死を拒み、凍りついていた心臓が、もう一度、拍を打つ。","f":"yuzuki"},{"t":"n","s":"雪が降った。月の光のような、白い光が満ちた。風が吹き、花が舞った。","f":"yuzuki"},{"t":"cg","v":"cg_yuzuki_standalone"},{"t":"d","s":"「……雪月風花」","f":"yuzuki"},{"t":"n","s":"柚月の唇が、かすかに動いた。","f":"yuzuki"},{"t":"n","s":"目が、開いた。","f":"yuzuki"},{"t":"d","s":"「……耀平くん。泣いて、ますか」","f":"yuzuki"},{"t":"d","s":"「泣いてない」","f":"yuzuki"},{"t":"d","s":"「嘘」","f":"yuzuki"},{"t":"n","s":"柚月は、震える手で、耀平の頬に触れた。傷は、跡形もなく消えていた。","f":"yuzuki"},{"t":"n","s":"教室の外でも、同じことが起きていた。","f":"yuzuki"},{"t":"n","s":"廊下で、九十九巡の体が、見たことのない色に輝いていた。C組では、結城蒼が、誰も見たことのない技を再現していた。追い詰められた規格外たちが、次々と、一段上の力に目覚めていく。","f":"tsukumo"},{"t":"n","s":"それでも、ギリギリだった。押し返し、押し込まれ、また押し返す。崩れかけた学園で、生徒たちは、誰一人、逃げなかった。","f":"tsukumo"}]},{"key":"21-7","title":"天城無明","bg":"bg_schoolyard_middle","dark":true,"mood":"tense","bgm":"tense1","cast":["mumyo","ren","principal"],"lines":[{"t":"n","s":"その時、空が、夜になった。"},{"t":"n","s":"昼間だったはずの空から、光が消えた。星もない、月もない、底のない夜。"},{"t":"d","s":"「無明長夜」"},{"t":"n","s":"校庭の真ん中に、一人の男が立っていた。長い白髪。黒い長いコート。ほとんど閉じたような目で、穏やかに微笑んでいる。","m":"happy"},{"t":"d","s":"「初めまして。天冠の、天城無明です」"},{"t":"n","s":"学園中のスキルが、鈍った。花びらが、色を失っていく。柚月の雪が、溶けていく。","f":"yuzuki"},{"t":"d","s":"「下がりなさい、生徒たち」","f":"yuzuki"},{"t":"n","s":"学園長の鷹野が、校庭に降り立った。その隣に、九条蓮が並ぶ。","f":"principal"},{"t":"d","s":"「山河崩壊」","f":"principal"},{"t":"d","s":"「空間断裂」","f":"principal"},{"t":"n","s":"大地が裂け、空間が裂けた。学園で最も強い二人の、全力の一撃だった。","f":"principal"},{"t":"n","s":"無明は、動かなかった。夜の中で、二人の技が、まるで最初からなかったかのように、ほどけて消えていく。","f":"mumyo"},{"t":"d","s":"「反転鏡面！」","f":"mumyo"},{"t":"n","s":"副会長の一ノ瀬凛が、無明の前に鏡のような壁を張った。無明の夜を、跳ね返そうとした。","f":"ren"},{"t":"n","s":"鏡に、ひびが入った。一ノ瀬は、それでも手を下ろさなかった。鏡が砕け散るまで、最後まで。","f":"ren","fx":"shake"},{"t":"d","s":"「会長、学園長、下がって！」","f":"ren"},{"t":"n","s":"風紀委員長の鬼塚剛が、二人の前に立った。拳を握り、夜に向かって叩きつける。","f":"ren","fx":"shake"},{"t":"d","s":"「鉄拳制裁！」","f":"ren"},{"t":"n","s":"夜は、揺らぎもしなかった。鬼塚は、二人の盾になったまま、倒れた。","f":"ren"},{"t":"n","s":"学園長が、膝をついた。蓮が、刀を杖にして、かろうじて立っていた。","f":"principal"},{"t":"d","s":"「強いね、学園の皆さん。でも、今日はここまでにしよう」","f":"principal"},{"t":"n","s":"無明は、穏やかに言った。","f":"mumyo"},{"t":"d","s":"「第一席も、楽しそうだったしね。また、会いに来るよ」","f":"mumyo"},{"t":"n","s":"夜が、晴れた。","f":"mumyo"},{"t":"n","s":"冬の青空の下に、壊れた学園だけが残っていた。","f":"mumyo"}]}]},{"n":22,"title":"別れ、SHIT","sub":"高校・1年12月〜1月","era":"high","lead":"六人の葬式のあと、耀平は学校に来なくなる。国家機密部隊SHITで、耀平は明鏡止水を会得する。","scenes":[{"key":"22-1","title":"六人","bg":"bg_graduation","dark":false,"mood":"sad","bgm":"sad2","cast":["yohei","ren","yuzuki"],"lines":[{"t":"n","s":"体育館で、六人の葬式が行われた。"},{"t":"n","s":"E組の相馬陽太、大和田巌、神田慎吾、羽鳥琴音。生徒会副会長の一ノ瀬凛。風紀委員長の鬼塚剛。","f":"ren"},{"t":"n","s":"E組の席には、四つの空席があった。","f":"ren"},{"t":"n","s":"柚月は、最前列に座っていた。傷は治っていた。けれど、その背中は、ひどく小さく見えた。","f":"yuzuki"},{"t":"n","s":"耀平は、一番後ろの席で、ただ、前を見ていた。","f":"yohei"},{"t":"i","s":"（陽太。最高に楽しいビリ、だったよな）","f":"yohei"},{"t":"n","s":"涙は、出なかった。出し方を、忘れてしまったみたいだった。","f":"yohei","m":"sad"},{"t":"n","s":"葬式の翌日から、耀平は、学校に来なくなった。","f":"yohei"}]},{"key":"22-2","title":"来なくなった","bg":"bg_dorm","dark":false,"mood":"sad","bgm":"sad2","cast":["yohei","yuzuki"],"lines":[{"t":"n","s":"〈学園襲撃、死者六名。警備体制に重大な欠陥か〉"},{"t":"n","s":"テレビも新聞も、毎日、同じ話をしていた。保護者からの抗議が殺到し、国会で質問が飛び、最後に、大臣が会見で頭を下げた。"},{"t":"n","s":"〈国の威信をかけて、子どもたちを守り抜く〉"},{"t":"n","s":"その言葉を、耀平は寮の部屋で、音を消したテレビで見ていた。","f":"yohei"},{"t":"n","s":"ノックの音がした。","f":"yohei"},{"t":"d","s":"「……金井くん。いますか」","f":"yohei"},{"t":"n","s":"柚月だった。耀平は、扉を開けなかった。","f":"yuzuki"},{"t":"d","s":"「今日も、ご飯、置いておきます。……天冠は、私のことも、まだ狙っています。だから、私の様子も、たまには見に来てください。約束です」","f":"yuzuki"},{"t":"n","s":"足音が、遠ざかっていった。","f":"yuzuki"},{"t":"n","s":"耀平は、扉の前に置かれた包みを見た。それから、窓の外を見た。","f":"yohei"},{"t":"i","s":"（おれが、近くにいるから、みんな狙われる）","f":"yohei"},{"t":"n","s":"それでも、耀平は、二日に一度、夜中にそっと、柚月の寮の窓の下を歩いた。灯りがついているのを確かめて、また自分の部屋に戻った。","f":"yohei"}]},{"key":"22-3","title":"屋上","bg":"bg_rooftop","dark":true,"mood":"climax","bgm":"climax2","cast":["noa","principal","yohei"],"lines":[{"t":"cg","v":"cg_rooftop_farewell"},{"t":"n","s":"一月の初め。夜の寮の屋上に、乃亜が来た。","f":"noa"},{"t":"n","s":"星が、よく見えた。","f":"noa"},{"t":"d","s":"「行くんでしょ」","f":"noa"},{"t":"d","s":"「……なんで分かるの」","f":"noa"},{"t":"d","s":"「分かるわよ。何年、あんたの幼馴染やってると思ってるの」","f":"noa"},{"t":"n","s":"昼間、学園長に呼ばれた。そこで、ある組織からの誘いを聞いた。国家機密部隊。規格外だけで作られた、天冠と真正面から戦える、唯一の部隊。","f":"principal"},{"t":"d","s":"「SHIT、っていうんだって」","f":"principal"},{"t":"d","s":"「ひどい名前」","f":"principal"},{"t":"d","s":"「うん。ひどい名前」","f":"principal"},{"t":"n","s":"二人は、少しだけ笑った。","f":"principal","m":"happy"},{"t":"d","s":"「……止めないの」","f":"principal"},{"t":"d","s":"「止めても行くでしょ」","f":"principal"},{"t":"d","s":"「うん」","f":"principal"},{"t":"d","s":"「じゃあ、止めない」","f":"principal"},{"t":"n","s":"乃亜は、耀平の袖を掴んだ。強く。","f":"noa"},{"t":"d","s":"「その代わり。強くなって、帰ってきて」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「……帰ってこなかったら、許さないから」","f":"noa"},{"t":"n","s":"乃亜の目から、涙がこぼれた。それでも、乃亜は笑っていた。","f":"noa","m":"sad"},{"t":"d","s":"「約束」","f":"noa"},{"t":"d","s":"「約束」","f":"noa"},{"t":"n","s":"冬の風が、二人の間を吹き抜けていった。","f":"noa"}]},{"key":"22-4","title":"SHIT","bg":"bg_shit_base","dark":false,"mood":"daily","bgm":"daily1","cast":["yohei","ren","rio"],"lines":[{"t":"n","s":"SHITの拠点は、廃線になった地下鉄の駅の、さらに下にあった。"},{"t":"d","s":"「お、来た来た。例の桜の子だ」"},{"t":"n","s":"大柄な男が、手を振った。無精髭を生やして、豪快に笑っている。"},{"t":"d","s":"「隊長の大神総一郎だ。スキルは森羅万象。目に映るものなら、だいたい動かせる」"},{"t":"n","s":"隣の女が、眼鏡の奥から耀平を値踏みするように見た。","f":"yohei"},{"t":"d","s":"「藤堂凪沙。絶対領域。この部隊の作戦は、私が立てる」","f":"yohei"},{"t":"n","s":"無口な青年が、壁にもたれたまま、片手を上げた。鷹見隼。神速無影。次の瞬間には、もう耀平の背後に立っていた。","f":"yohei"},{"t":"n","s":"穏やかな顔の女が、お茶を差し出した。三宅慈雨。生命循環。","f":"yohei"},{"t":"n","s":"そして、ソファの上で、小学生くらいの子供が、足をぶらぶらさせてお菓子を食べていた。","f":"yohei"},{"t":"d","s":"「柏木理央。全知解析。……ふーん。おにいちゃん、思ってたより弱そう」","f":"yohei"},{"t":"d","s":"「理央、初対面だぞ」","f":"yohei"},{"t":"d","s":"「だって、本当のことだもん」","f":"yohei"},{"t":"n","s":"理央は、耀平をじっと見た。その目は、子供の目ではなかった。","f":"rio"},{"t":"d","s":"「でも、伸びしろは、この部屋で一番。……スキルの奥に、まだ何かある」","f":"rio"},{"t":"n","s":"扉が開いて、もう一人、入ってきた。","f":"rio"},{"t":"n","s":"九条蓮だった。","f":"ren"},{"t":"d","s":"「会長」","f":"ren"},{"t":"d","s":"「私も、スカウトを受けていた。君を推薦したのも、私だ」","f":"ren"},{"t":"n","s":"蓮は、少し痩せていた。それでも、背筋は変わらなかった。","f":"ren"},{"t":"d","s":"「一ノ瀬と鬼塚を、私は守れなかった。だから、ここに来た」","f":"ren"}]},{"key":"22-5","title":"地下の蛍","bg":"bg_shit_base","dark":true,"mood":"tense","bgm":"tense2","cast":["hotaru","yohei","todo"],"lines":[{"t":"n","s":"拠点のさらに奥に、分厚い硝子で仕切られた部屋があった。"},{"t":"d","s":"「第六席は、学園から、うちが預かった」"},{"t":"n","s":"藤堂が、硝子の前で腕を組んだ。","f":"todo"},{"t":"d","s":"「何を聞いても答えない。『耀平くんを連れてきて』の一点張りだ」","f":"todo"},{"t":"n","s":"硝子の向こうで、蛍は、簡素な椅子に脚を組んで座っていた。耀平の顔を見た瞬間、その目が、ぱっと輝いた。","f":"hotaru"},{"t":"d","s":"「耀平くん！　やっと来てくれた」","f":"hotaru"},{"t":"d","s":"「……元気そうですね」","f":"hotaru"},{"t":"d","s":"「元気じゃないわよ。ここ、ごはんがまずいの。……でも、今、元気になった」","f":"hotaru"},{"t":"n","s":"蛍は、硝子に両手をついて、子供のように笑った。","f":"hotaru","m":"happy"},{"t":"d","s":"「天冠のボスのこと、聞きに来たんでしょ。いいわよ。耀平くんにだけ、教えてあげる」","f":"hotaru"},{"t":"n","s":"蛍の声から、ふっと、甘さが消えた。","f":"hotaru"},{"t":"d","s":"「無明長夜。あの人の領域に入ったら、スキルは全部鈍る。……でもね。領域を張る、その瞬間だけ。あの人、ほんの一瞬、目を閉じるの。息を吸うみたいに」","f":"hotaru"},{"t":"d","s":"「どうして、それを、おれに」","f":"hotaru"},{"t":"d","s":"「決まってるじゃない。耀平くんが死んじゃうの、いやだもの」","f":"hotaru"},{"t":"n","s":"冗談めかした口調だった。けれど、その目だけは、少しも笑っていなかった。","f":"hotaru"},{"t":"d","s":"「それとね。決戦の日は、わたしもここから出して。天冠を裏切るんだから、どうせもう戻れないし。……その代わり」","f":"hotaru"},{"t":"d","s":"「その代わり？」","f":"hotaru"},{"t":"d","s":"「終わったら、デートして」","f":"hotaru"},{"t":"n","s":"硝子の向こうで、蛍が片目をつぶった。後ろで、藤堂が、深いため息をついた。","f":"hotaru"},{"t":"d","s":"「……理央。今の話、裏は取れるか」","f":"hotaru"},{"t":"d","s":"「取れるよ。前に一回だけ、あのおじさんの映像を解析したことある。張る瞬間、確かに目、閉じてた」","f":"hotaru"},{"t":"n","s":"理央は、お菓子の包み紙を丁寧に畳みながら言った。","f":"rio"},{"t":"d","s":"「おにいちゃんの花びら、先に撒いとけばいいんじゃない？　夜が来る前に咲いてる花なら、鈍らない」","f":"rio"}]},{"key":"22-6","title":"明鏡止水","bg":"bg_shit_base","dark":false,"mood":"climax","bgm":"climax2","cast":["yohei","rio","todo"],"lines":[{"t":"n","s":"一月。耀平の修行が始まった。","f":"yohei"},{"t":"n","s":"大神の森羅万象に吹き飛ばされ、藤堂の絶対領域に閉じ込められ、鷹見の神速に一度も触れられず、三宅に何度も傷を治された。","f":"todo","fx":"shake"},{"t":"d","s":"「おにいちゃん、心が、うるさい」","f":"todo"},{"t":"n","s":"ある夜、理央が言った。","f":"rio"},{"t":"d","s":"「……うるさい？」","f":"rio"},{"t":"d","s":"「怒ってる。悲しんでる。悔しがってる。全部、花びらに出てる。だから、花びらの動きが、読めちゃう」","f":"rio"},{"t":"n","s":"理央は、耀平の胸を、小さな指でつついた。","f":"rio"},{"t":"d","s":"「水みたいに、静かにしてみて。何も映らない水」","f":"rio"},{"t":"n","s":"その夜、耀平は、一人で訓練場の真ん中に座った。","f":"yohei"},{"t":"n","s":"誰もいない。灯りも落ちている。","f":"yohei"},{"t":"cg","v":"cg_meikyo"},{"t":"n","s":"暗闇の中で、耀平は目を閉じた。","f":"yohei"},{"t":"i","s":"（陽太。巌。慎吾。琴音。一ノ瀬先輩。鬼塚先輩）","f":"yohei"},{"t":"n","s":"名前を、順番に呼んだ。悲しみも、悔しさも、消えなかった。消そうとするのを、やめた。","f":"yohei"},{"t":"i","s":"（全部、持ったままでいい）","f":"yohei"},{"t":"i","s":"（ただ、波を立てない）","f":"yohei"},{"t":"n","s":"花びらが、舞った。","f":"yohei"},{"t":"n","s":"ひらり、ひらりと、ゆっくりと。花びらは、空中で、ぴたりと止まった。一枚も落ちない。一枚も揺れない。まるで、静かな水面に浮かんでいるみたいだった。","f":"yohei"},{"t":"d","s":"「万花繚乱——明鏡止水」","f":"yohei","fx":"bloom"},{"t":"n","s":"耀平は、目を開けた。","f":"yohei"},{"t":"n","s":"訓練場の入口で、大神と藤堂と理央が、黙ってこちらを見ていた。","f":"todo"},{"t":"d","s":"「……できたな」","f":"todo"},{"t":"d","s":"「できたね」","f":"todo"},{"t":"n","s":"理央が、にっと笑った。","f":"rio","m":"happy"}]}]},{"n":23,"title":"竜馬と、学園へ","sub":"高校・1年2月","era":"high","lead":"SHITの隊長に背中を押されて、耀平は学園へ戻る。その途中で、竜馬が待っていた。","scenes":[{"key":"23-1","title":"戻れ","bg":"bg_shit_base","dark":false,"mood":"daily","bgm":"daily4","cast":["yohei"],"lines":[{"t":"n","s":"二月。大神が、耀平を呼んだ。","f":"yohei"},{"t":"d","s":"「学園に戻れ、耀平」","f":"yohei"},{"t":"d","s":"「え」","f":"yohei"},{"t":"d","s":"「明鏡止水を会得した。お前はもう、俺たちと並べる。だが、お前の強さの源は、ここにはない」","f":"yohei"},{"t":"n","s":"大神は、耀平の胸を、拳で軽く叩いた。","f":"yohei"},{"t":"d","s":"「天冠は、俺たちが見張ってる。学園の警備にも、うちの手を回した。安心して戻れ」","f":"yohei"},{"t":"d","s":"「……でも、おれが近くにいると、みんなが」","f":"yohei"},{"t":"d","s":"「狙われる。分かってる。だから、俺たちがいるんだ」","f":"yohei"},{"t":"n","s":"大神は、豪快に笑った。","f":"yohei","m":"happy"},{"t":"d","s":"「守るのは、お前一人の仕事じゃない。それを覚えたら、お前はもっと強くなる」","f":"yohei"}]},{"key":"23-2","title":"竜馬","bg":"bg_riverside","dark":true,"mood":"battle","bgm":"battle1","cast":["ryoma","yohei","noa"],"lines":[{"t":"n","s":"地下から地上に出ると、冬の夕暮れだった。"},{"t":"n","s":"学園へ向かう坂の途中に、一人の男が立っていた。ポケットに両手を突っ込んで、待ちくたびれたような顔をしている。"},{"t":"n","s":"竜馬だった。","f":"ryoma"},{"t":"d","s":"「……よお」","f":"ryoma"},{"t":"d","s":"「竜馬」","f":"ryoma"},{"t":"d","s":"「二か月も、どこ行ってた」","f":"ryoma"},{"t":"d","s":"「……ちょっと、修行」","f":"ryoma"},{"t":"d","s":"「そうか」","f":"ryoma"},{"t":"n","s":"竜馬は、ポケットから手を出した。拳を、握った。","f":"ryoma"},{"t":"d","s":"「一発、殴らせろ」","f":"ryoma"},{"t":"d","s":"「え」","f":"ryoma"},{"t":"d","s":"「乃亜が、毎晩泣いてた。朝霧も、毎日おまえの部屋の前に飯置いてた。おれは……おれは、何もできなかった」","f":"ryoma"},{"t":"cg","v":"cg_fistfight"},{"t":"n","s":"竜馬の拳が、耀平の頬を打った。","f":"ryoma"},{"t":"n","s":"スキルは、使っていなかった。ただの、拳だった。","f":"ryoma"},{"t":"n","s":"耀平は、よろけて、踏みとどまった。それから、殴り返した。","f":"yohei"},{"t":"n","s":"二人は、坂道の上で、殴り合った。炎も桜も、使わなかった。小学生の頃みたいに、ただ、拳と拳で。","f":"yohei"},{"t":"n","s":"やがて、二人とも、地面に大の字になった。","f":"yohei"},{"t":"d","s":"「……竜馬」","f":"yohei"},{"t":"d","s":"「なんだ」","f":"yohei"},{"t":"d","s":"「小学校の時、おれのこと、陰で笑ってた奴ら。殴ってくれてたの、竜馬だったんだって」","f":"yohei"},{"t":"n","s":"竜馬が、跳ね起きた。","f":"ryoma"},{"t":"d","s":"「……誰に聞いた」","f":"ryoma"},{"t":"d","s":"「乃亜」","f":"ryoma"},{"t":"d","s":"「あいつ……」","f":"ryoma"},{"t":"n","s":"竜馬は、しばらく黙っていた。それから、空を見上げたまま、ぼそりと言った。","f":"ryoma"},{"t":"d","s":"「おれ、おまえの剣に憧れてた。一花だって分かった時、勝手にがっかりして、勝手に突っかかった」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「……いじめて、ごめん」","f":"ryoma"},{"t":"n","s":"耀平は、少しだけ笑った。","f":"yohei","m":"happy"},{"t":"d","s":"「いいよ。ずっと、知ってた気がする」","f":"yohei"},{"t":"d","s":"「嘘つけ」","f":"yohei"},{"t":"d","s":"「ほんと」","f":"yohei"},{"t":"n","s":"竜馬は、鼻をすすった。それから、立ち上がって、耀平に手を差し出した。","f":"ryoma"},{"t":"d","s":"「帰るぞ、親友」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"n","s":"耀平は、その手を掴んだ。","f":"yohei"},{"t":"n","s":"坂の上で、乃亜と柚月が、二人を待っていた。乃亜は泣いていて、柚月は笑っていた。","f":"noa","m":"sad"},{"t":"d","s":"「おかえり」","f":"noa"},{"t":"d","s":"「……ただいま」","f":"noa"},{"t":"n","s":"竜馬が、乃亜の泣き顔を見て、ほんの少しだけ、目をそらした。その頬が、夕日のせいだけではなく、赤かった。","f":"ryoma","m":"sad"}]},{"key":"23-3","title":"学園へ","bg":"bg_classroom_e","dark":false,"mood":"soft","bgm":"soft2","cast":["yohei","yuzuki","noa"],"lines":[{"t":"n","s":"翌朝。E組の教室に入ると、四つの空席が、きれいに拭かれていた。"},{"t":"d","s":"「……毎日、誰かが拭いてたんだ」"},{"t":"n","s":"小春が、小さな声で言った。"},{"t":"d","s":"「金井くんの席も。いつ戻ってきてもいいように」"},{"t":"cg","v":"cg_yuzuki_window"},{"t":"n","s":"耀平は、自分の席に座った。隣で、柚月が、静かに微笑んでいた。","f":"yohei","m":"happy"},{"t":"d","s":"「おかえりなさい」","f":"yohei"},{"t":"d","s":"「ただいま」","f":"yohei"},{"t":"n","s":"その日から、耀平は、E組の日常に戻った。","f":"yohei"},{"t":"n","s":"二月十四日。耀平の机の上には、三つの包みが並んでいた。","f":"yohei"},{"t":"n","s":"一つは、乃亜から。「いつもの」と書かれた、ぶっきらぼうなメモ付き。","f":"noa"},{"t":"n","s":"一つは、柚月から。雪の結晶の形をした、手作りのチョコレート。","f":"yuzuki"},{"t":"n","s":"そしてもう一つは、差出人の書かれていない、紫の包み紙だった。中には、蛍の形をしたチョコと、一枚のカードが入っていた。","f":"hotaru"},{"t":"n","s":"〈デートの約束、忘れないでね〉","f":"hotaru"},{"t":"d","s":"「……誰から」","f":"hotaru"},{"t":"d","s":"「……誰からですか」","f":"hotaru"},{"t":"n","s":"乃亜と柚月の声が、左右から同時に飛んできた。耀平は、黙ってカードを裏返した。","f":"noa"}]},{"key":"23-4","title":"予告","bg":"bg_shit_base","dark":true,"mood":"tense","bgm":"tense1","cast":["mumyo","yohei","principal"],"lines":[{"t":"n","s":"二月の終わり。学園中のスピーカーが、ひとりでに鳴った。"},{"t":"n","s":"〈こんにちは、学園の皆さん。天冠の、天城無明です〉","f":"mumyo"},{"t":"n","s":"穏やかな声だった。","f":"mumyo"},{"t":"n","s":"〈卒業式の日に、会いに行きます。今度は、全員で〉","f":"mumyo"},{"t":"n","s":"放送は、それだけで途切れた。","f":"mumyo"},{"t":"n","s":"その夜、SHITと学園の主だった者たちが、地下の作戦室に集まった。","f":"mumyo"},{"t":"d","s":"「卒業式は、予定どおり行う」","f":"mumyo"},{"t":"n","s":"学園長の鷹野が言った。","f":"principal"},{"t":"d","s":"「逃げれば、天冠はどこまでも追ってくる。ならば、迎え撃つ」","f":"principal"},{"t":"n","s":"藤堂が、作戦図を広げた。","f":"todo"},{"t":"d","s":"「無明長夜の発動の瞬間に、耀平の花びらを撃ち込む。そのために、前日のうちに、校庭中に花びらを撒いておく」","f":"todo"},{"t":"d","s":"「そんなこと、できるの？」","f":"todo"},{"t":"n","s":"乃亜が聞いた。耀平は、頷いた。","f":"noa"},{"t":"d","s":"「明鏡止水なら、一晩中、花びらを止めておける」","f":"noa"},{"t":"n","s":"理央が、ソファの上で、にやりと笑った。","f":"rio","m":"happy"},{"t":"d","s":"「じゃあ、決まりだね。卒業式、おにいちゃんの桜で、迎えようよ」","f":"rio"}]}]},{"n":24,"title":"決戦と卒業式","sub":"高校・1年3月","era":"high","lead":"卒業式の朝、天冠が総攻撃をかける。第一席との再戦で、耀平は最後の花を咲かせる。","scenes":[{"key":"24-1","title":"一瞬","bg":"bg_schoolyard_middle","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["mumyo","yohei","todo"],"lines":[{"t":"n","s":"卒業式の朝。校庭には、薄紅の花びらが、一面に止まっていた。"},{"t":"n","s":"風が吹いても、揺れない。一晩中、耀平が明鏡止水で止めておいた花びらだった。","f":"yohei"},{"t":"n","s":"講堂から、卒業生たちが出てきた。その時、空が、ひび割れた。","f":"yohei"},{"t":"n","s":"天冠が、来た。","f":"yohei"},{"t":"n","s":"空の裂け目から、一般の兵が、数え切れないほど降ってくる。その先頭に、八天が並んでいた。第六席を欠いた、七人。","f":"yohei"},{"t":"n","s":"そして、一番後ろを、あの男が歩いていた。","f":"yohei"},{"t":"d","s":"「やあ、約束通り来たよ」","f":"yohei"},{"t":"n","s":"天城無明は、穏やかに微笑んだ。校庭を見渡して、止まった花びらに目を留め、少し首を傾げる。","f":"mumyo","m":"happy"},{"t":"d","s":"「ほう。準備をしてきたのか。感心だね。では、始めようか」","f":"mumyo"},{"t":"n","s":"無明が、手を上げた。","f":"mumyo"},{"t":"d","s":"「無明長夜」","f":"mumyo"},{"t":"n","s":"その瞬間。","f":"mumyo"},{"t":"n","s":"無明の瞼が、ほんの一瞬、閉じた。","f":"mumyo"},{"t":"i","s":"（今だ）","f":"mumyo"},{"t":"n","s":"耀平は、拳を握った。","f":"yohei"},{"t":"n","s":"足元の花びらが、一斉に光った。夜が来る前に、そこにあった花びらは、鈍らなかった。","f":"yohei","fx":"flash"},{"t":"cg","v":"cg_first_bloom"},{"t":"d","s":"「咲け——！」","f":"yohei"},{"t":"n","s":"千の花びらが、無明に向かって飛んだ。","f":"mumyo"},{"t":"n","s":"夜が、一瞬だけ、揺らいだ。","f":"mumyo"},{"t":"d","s":"「……ほう」","f":"mumyo"},{"t":"d","s":"「今です！」","f":"mumyo"},{"t":"n","s":"藤堂の声が飛んだ。","f":"todo"},{"t":"n","s":"大神の森羅万象が大地を動かし、鷹見が音より速く走り、三宅が命をつなぐ光を広げる。そして、柏木理央が、ソファではなく、戦場の真ん中に立っていた。","f":"rio"},{"t":"d","s":"「おじさん、ひさしぶり。……今日は、ぼくが全部、読んであげる」","f":"rio"}]},{"key":"24-2","title":"それぞれの相手","bg":"bg_schoolyard_middle","dark":true,"mood":"battle","bgm":"battle2","cast":["ren","saku","noa"],"lines":[{"t":"n","s":"戦場が、いくつにも割れた。"},{"t":"n","s":"九条蓮は、第二席の宵待朔と向き合っていた。","f":"ren"},{"t":"d","s":"「今度は、逃がさないと言ったはずだ」","f":"ren"},{"t":"d","s":"「影縫幻夢」","f":"ren"},{"t":"n","s":"影が、蓮の足元に絡みつく。斬っても、斬っても、影は増える。蓮は、刀を鞘に収めた。","f":"ren"},{"t":"d","s":"「斬るほど増える影なら、影を斬らなければいい。……影を作っているものを、斬る」","f":"ren"},{"t":"n","s":"空間断裂。距離を無視した斬撃が、影の向こうの、朔本人だけを断ち切った。","f":"saku"},{"t":"n","s":"第四席の剛田錬磨には、獅子堂豪と荒神猛と金子守が向かった。鋼の体を、獅子堂の咆哮が揺らし、荒神の牙が削り、金子が鋼そのものを砂に作り替えた。","f":"saku"},{"t":"n","s":"第五席の時任刻には、柚月と水無月紬が向かった。時間が止まる。その数秒の間に、紬は、止まる直前の全てを記録していた。","f":"yuzuki"},{"t":"d","s":"「次に止まるのは、三秒後です。朝霧さん」","f":"yuzuki"},{"t":"d","s":"「はい。……拒絶します。止まる時間ごと」","f":"yuzuki"},{"t":"n","s":"雪月風花が、刹那停止を拒んだ。","f":"yuzuki"},{"t":"n","s":"第七席の鳴海響には、結城蒼と朱雀院灯と乃亜が向かった。","f":"noa"},{"t":"d","s":"「今度は、真似じゃない」","f":"noa"},{"t":"n","s":"蒼が、あの日に覚醒した力で、音を音で打ち消す。灯の幻が、鳴海の耳を塞ぐ。そして、乃亜の水が、静かに、鳴海を包み込んだ。","f":"noa"},{"t":"d","s":"「碧水心希。……もう、隠さない」","f":"noa"},{"t":"n","s":"第八席の白銀煌には、九十九巡と竜馬が向かった。","f":"tsukumo"},{"t":"d","s":"「借りを返しに来たぞ、光野郎」","f":"tsukumo"},{"t":"d","s":"「規格外でもない子供が、また来たか」","f":"tsukumo"},{"t":"d","s":"「規格外じゃねえ。でも、こいつの親友だ」","f":"tsukumo"},{"t":"n","s":"竜馬の炎が、巡の九十九の力に乗って、光を焼き尽くした。","f":"ryoma"}]},{"key":"24-3","title":"第一席","bg":"bg_schoolyard_middle","dark":true,"mood":"battle","bgm":"battle2","cast":["suiran","yohei","genzo"],"lines":[{"t":"cg","v":"cg_vs_genzo"},{"t":"n","s":"校庭の中央で、黒鉄玄蔵が待っていた。","f":"genzo"},{"t":"d","s":"「来い、桜の少年。約束通り、本気でやろう」","f":"genzo"},{"t":"d","s":"「はい」","f":"genzo"},{"t":"n","s":"重圧が、落ちた。耀平は、明鏡止水で、花びらを静かに浮かべた。重さの隙間を、花びらがすり抜けていく。","f":"yohei"},{"t":"n","s":"刀と拳が、ぶつかった。","f":"yohei"},{"t":"n","s":"一合。十合。百合。","f":"yohei"},{"t":"n","s":"互角だった。","f":"yohei"},{"t":"n","s":"重力が花びらを押し潰そうとし、花びらが重力をすり抜ける。玄蔵の拳が耀平の肩を砕きかけ、耀平の刀が玄蔵の腕を裂く。","f":"genzo"},{"t":"d","s":"「楽しいな、桜の少年」","f":"genzo"},{"t":"d","s":"「……はい」","f":"genzo"},{"t":"n","s":"自分でも、驚いた。","f":"genzo"},{"t":"n","s":"楽しかった。","f":"genzo"},{"t":"n","s":"その時、空から、鋭い風が吹き下ろした。","f":"genzo"},{"t":"d","s":"「第一席。手こずっているようね」","f":"genzo"},{"t":"n","s":"第三席の鳳翠嵐だった。風を纏って、上空から、耀平を見下ろしている。","f":"suiran"},{"t":"d","s":"「余計なことをするな、翠嵐」","f":"suiran"},{"t":"d","s":"「ボスの命令よ。桜の子は、確実に潰せって」","f":"suiran"},{"t":"n","s":"風の刃が、耀平の背中を狙った。前には玄蔵。上には翠嵐。","f":"yohei"},{"t":"i","s":"（……避けきれない）","f":"yohei"},{"t":"n","s":"雷が、落ちた。","f":"yohei"},{"t":"n","s":"紫の雷光が、風の刃を、真っ二つに断ち割った。","f":"yohei"},{"t":"d","s":"「……邪魔をするな」","f":"yohei"},{"t":"n","s":"耀平の背中に、一人の少年が立っていた。黒い髪。鋭い目。刀に、紫電をまとわせて。","f":"yohei"},{"t":"d","s":"「迅さん」","f":"yohei"},{"t":"d","s":"「勘違いするな。親父の仇の仲間が、ここにいると聞いただけだ」","f":"yohei"},{"t":"n","s":"迅は、上空の翠嵐を睨んだ。","f":"jin","m":"anger"},{"t":"d","s":"「それに、言ったはずだ。本気のお前とやるのは、俺だ。こんなところで、死なれちゃ困る」","f":"jin"},{"t":"n","s":"その肩越しに、紫の光が、ふわりと舞い上がった。","f":"jin"},{"t":"d","s":"「わたしも、手伝ってあげる。耀平くんのお友達でしょ」","f":"jin"},{"t":"d","s":"「……誰が友達だ」","f":"jin"},{"t":"n","s":"蛍だった。SHITに連れられて、この日だけ地下から出ることを許された、元第六席。","f":"hotaru"},{"t":"d","s":"「翠嵐ちゃん。風で毒を散らすのは得意だけど、自分の羽までは守れないのよね」","f":"hotaru"},{"t":"n","s":"紫の群れが、細い糸のように空へ昇っていく。翠嵐の纏う風に、紫の粉が、ほんのわずかに混じった。","f":"suiran"},{"t":"d","s":"「——っ、蛍、貴様！」","f":"suiran"},{"t":"d","s":"「ごめんね。わたし、もう、そっちじゃないの」","f":"suiran"},{"t":"n","s":"翠嵐の風が、乱れた。迅が、刀を低く構えた。","f":"suiran"},{"t":"d","s":"「紫電断空」","f":"suiran"},{"t":"n","s":"雷が、空を裂いた。","f":"suiran"}]},{"key":"24-4","title":"夜桜繚蘭","bg":"bg_schoolyard_middle","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["genzo","yohei","jin"],"lines":[{"t":"n","s":"玄蔵が、笑っていた。","f":"genzo"},{"t":"d","s":"「面白い。剣聖の息子まで来たか」","f":"genzo"},{"t":"n","s":"玄蔵の体から、黒い光が噴き上がった。重力が、これまでの倍に、さらにその倍に膨れ上がる。","f":"genzo"},{"t":"d","s":"「……第一席も、覚醒した」","f":"genzo"},{"t":"n","s":"翠嵐を叩き落とした迅が、耀平の隣に降り立った。","f":"suiran"},{"t":"n","s":"二人は、並んで、玄蔵と向き合った。","f":"genzo"},{"t":"d","s":"「足、引っ張るなよ」","f":"genzo"},{"t":"d","s":"「迅さんこそ」","f":"genzo"},{"t":"n","s":"迅が、左から。耀平が、右から。","f":"jin"},{"t":"n","s":"雷と桜が、同時に走った。","f":"jin"},{"t":"n","s":"重さが、二人を押し潰そうとする。迅の雷がそれを裂き、耀平の花びらが隙間を抜ける。迅が斬った場所に、耀平の刀が届く。耀平が開いた道を、迅の雷が駆け抜ける。","f":"jin"},{"t":"n","s":"息が、合っていた。まるで、ずっと前から、一緒に振ってきたかのように。","f":"jin"},{"t":"i","s":"（……楽しい）","f":"jin"},{"t":"n","s":"心臓が、高鳴った。","f":"jin"},{"t":"n","s":"テレビの中の剣聖に憧れた、四歳の夜みたいに。桜の枝を振り回した、あの春の庭みたいに。","f":"jin"},{"t":"n","s":"腰の刀が、熱を持った。","f":"jin"},{"t":"n","s":"花びらが、刀に吸い込まれていく。一枚。二枚。やがて、刀身いっぱいに、桜が咲いた。刃文が、ゆっくりと、花びらの形に変わっていく。","f":"jin"},{"t":"n","s":"夜の空の下で、白く光る桜。","f":"jin"},{"t":"d","s":"「……何だ、それは」","f":"jin"},{"t":"n","s":"玄蔵の声に、初めて、驚きが混じった。","f":"genzo"},{"t":"cg","v":"cg_yozakura"},{"t":"d","s":"「夜桜繚蘭」","f":"genzo","fx":"yozakura"},{"t":"n","s":"耀平の声は、静かだった。","f":"yohei"},{"t":"d","s":"「花は、夜があるから、綺麗に見えるんです」","f":"yohei"},{"t":"n","s":"一閃。","f":"yohei","fx":"flash"},{"t":"n","s":"桜の刃が、重力ごと、玄蔵を斬った。","f":"genzo"},{"t":"n","s":"玄蔵は、ゆっくりと膝をついた。胸の傷を見下ろして、それから、満足そうに笑った。","f":"genzo","m":"happy"},{"t":"d","s":"「……見事だ」","f":"genzo"}]},{"key":"24-5","title":"撤退","bg":"bg_schoolyard_middle","dark":true,"mood":"tense","bgm":"tense2","cast":["mumyo","rio","todo"],"lines":[{"t":"n","s":"校庭の端で、無明の夜が、少しずつ薄れていた。","f":"mumyo"},{"t":"n","s":"SHITの五人と、無明が、互角に戦い続けていた。理央が無明の全てを読み、藤堂がその隙を領域で塞ぎ、大神が世界ごと押し返す。","f":"mumyo"},{"t":"d","s":"「……やれやれ」","f":"mumyo"},{"t":"n","s":"無明は、穏やかに息をついた。","f":"mumyo"},{"t":"d","s":"「第一席も、第二席も、第三席も、落とされたか。今日は、ここまでにしよう」","f":"mumyo"},{"t":"n","s":"夜が、無明の体を包んだ。","f":"mumyo"},{"t":"d","s":"「次は、新しい八天を連れてくるよ。楽しみにしていてね、桜の少年」","f":"mumyo"},{"t":"n","s":"夜が晴れた時、無明の姿は、もうなかった。","f":"mumyo"},{"t":"n","s":"倒れた幹部たちは、置き去りにされていた。SHITの隊員たちが、静かに彼らを拘束していく。","f":"mumyo"},{"t":"n","s":"三月の空は、青かった。","f":"mumyo"}]},{"key":"24-6","title":"卒業式","bg":"bg_graduation","dark":false,"mood":"climax","bgm":"climax2","cast":["yohei","noa","ryoma"],"lines":[{"t":"n","s":"その日の午後。半分壊れた講堂で、卒業式が行われた。"},{"t":"d","s":"「答辞。卒業生代表、九条蓮」"},{"t":"n","s":"蓮が、壇上に立った。","f":"ren"},{"t":"d","s":"「私たちは、この一年で、六人の仲間を失いました。その名前を、ここで呼ばせてください」","f":"ren"},{"t":"n","s":"六つの名前が、講堂に響いた。誰も、泣き声を止めなかった。","f":"ren","m":"sad"},{"t":"d","s":"「強さは、誰かを守るためにある。入学式で、私はそう言いました。守れなかったものの数を、私は一生忘れません。だから、在校生の諸君。私は、先に行く。だが、いつでも、ここに戻ってくる」","f":"ren"},{"t":"n","s":"拍手が、長く続いた。","f":"ren"},{"t":"n","s":"式のあと、校庭の桜の下で、竜馬が耀平の肩を叩いた。","f":"ryoma"},{"t":"d","s":"「卒業したら、決着つけるぞ。今度は、スキルありでな」","f":"ryoma"},{"t":"d","s":"「うん。待ってて」","f":"ryoma"},{"t":"d","s":"「待たせんなよ」","f":"ryoma"},{"t":"n","s":"竜馬は、少し離れたところにいる乃亜を、ちらりと見た。それから、何も言わずに、背を向けた。","f":"ryoma"},{"t":"n","s":"乃亜が、耀平の隣に来た。","f":"noa"},{"t":"d","s":"「泣き虫」","f":"noa"},{"t":"d","s":"「泣いてない」","f":"noa"},{"t":"d","s":"「……ねえ、耀平」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"cg","v":"cg_graduation"},{"t":"d","s":"「どこに行っても、あんたはあんただからね」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「約束」","f":"noa"},{"t":"d","s":"「約束」","f":"noa"},{"t":"n","s":"反対側から、柚月が来た。","f":"yuzuki"},{"t":"d","s":"「金井くん。来年も、隣の席ですよ」","f":"yuzuki"},{"t":"d","s":"「うん」","f":"yuzuki"},{"t":"d","s":"「……約束です」","f":"yuzuki"},{"t":"n","s":"その時、校門の向こうから、よく通る声が飛んできた。","f":"yuzuki"},{"t":"d","s":"「耀平くーん！　デートの約束も、忘れないでねー！」","f":"yuzuki"},{"t":"n","s":"SHITの車の窓から、薄紫の髪が手を振っていた。","f":"yuzuki"},{"t":"n","s":"乃亜が、深く、深くため息をついた。柚月が、にっこりと笑ったまま、目だけ笑っていなかった。","f":"noa","m":"happy"},{"t":"d","s":"「……台無し」","f":"noa"},{"t":"d","s":"「……台無しですね」","f":"noa"},{"t":"d","s":"「おれのせいじゃないよ」","f":"noa"},{"t":"n","s":"三人の上に、桜の花びらが、ひらひらと降り続けていた。","f":"noa"},{"t":"n","s":"春は、まだ始まったばかりだった。","f":"noa"}]}]},{"n":25,"title":"眠そうな二年生と、隣の席","sub":"高校・2年4月","era":"high2","lead":"二年生の春。学園が大きく変わろうとしている朝も、耀平は眠い。隣の席には、約束どおり、柚月がいる。","scenes":[{"key":"25-1","title":"始業式の放送","bg":"bg_classroom_e","dark":false,"mood":"daily","bgm":"daily1","cast":["yohei","yuzuki"],"lines":[{"t":"n","s":"四月の朝は、あたたかかった。"},{"t":"n","s":"窓際の席に、春の日差しが落ちている。二年E組の教室は、去年と同じ、校舎のいちばん端にあった。窓の外には、古い桜の木が一本。去年より、花が少しだけ多い気がした。"},{"t":"n","s":"〈——以上が、今年度の学園の方針です。続いて、国の方針についてお伝えします〉"},{"t":"n","s":"教室のスピーカーから、学園長の声が流れてくる。始業式は、全校放送だった。去年の襲撃で、講堂の半分がまだ直っていないからだ。","f":"principal"},{"t":"n","s":"〈昨年の事件を受け、国は、学園と、SHITの体制を、大きく見直すことを決定しました。具体的には——〉","f":"principal"},{"t":"n","s":"声は、穏やかで、長かった。","f":"principal"},{"t":"n","s":"耀平は、頬杖をついた。まぶたが、ゆっくり下がる。","f":"yohei"},{"t":"i","s":"（……長い）","f":"yohei"},{"t":"d","s":"「金井くん」","f":"yohei"},{"t":"n","s":"隣から、小さな声がした。","f":"yohei"},{"t":"d","s":"「起きてください」","f":"yohei"},{"t":"d","s":"「起きてる」","f":"yohei"},{"t":"d","s":"「目、閉じてますよ」","f":"yohei"},{"t":"d","s":"「閉じてるだけ」","f":"yohei"},{"t":"n","s":"柚月は、小さくため息をついた。去年より、少しだけ髪が伸びている。水色の髪が、肩のあたりで揺れていた。","f":"yuzuki"},{"t":"d","s":"「……約束、守ってますからね」","f":"yuzuki"},{"t":"d","s":"「何の」","f":"yuzuki"},{"t":"d","s":"「隣の席」","f":"yuzuki"},{"t":"d","s":"「うん。ありがとう」","f":"yuzuki"},{"t":"d","s":"「お礼を言うところじゃなくて、ちゃんと聞くところです」","f":"yuzuki"},{"t":"n","s":"〈なお、今年度は、一年生と二年生による、合同の取り組みを予定しています。詳細は、追ってお知らせしますが、ペアを組んで——〉","f":"yuzuki"},{"t":"d","s":"「ペア？」","f":"yuzuki"},{"t":"n","s":"耀平は、ぼんやりと呟いた。","f":"yohei"},{"t":"n","s":"〈——ペアを組んで、一年生と二年生が、共同で——〉","f":"yohei"},{"t":"d","s":"「……そんなの、あるんだ」","f":"yohei"},{"t":"n","s":"それが、耀平の、その日の最後の記憶だった。","f":"yohei"},{"t":"d","s":"「金井くん」","f":"yohei"},{"t":"d","s":"「金井くん？」","f":"yohei"},{"t":"d","s":"「……寝ちゃった」","f":"yohei"},{"t":"n","s":"柚月は、頬杖をついたまま眠る耀平の横顔を、しばらく見つめた。それから、自分のブレザーを、そっと彼の肩にかけた。","f":"yuzuki"},{"t":"d","s":"「もう。二年生になっても、変わらないんだから」","f":"yuzuki"},{"t":"n","s":"その声は、放送にかき消されて、誰にも聞こえなかった。","f":"yuzuki"}]},{"key":"25-2","title":"屋上の昼休み","bg":"bg_rooftop","dark":false,"mood":"daily","bgm":"daily2","cast":["ryoma","yohei","noa"],"lines":[{"t":"n","s":"昼休みの屋上は、いつもの三人と、ひとり増えた四人だった。"},{"t":"d","s":"「で、お前、放送、聞いてたのか」"},{"t":"d","s":"「聞いてた」"},{"t":"d","s":"「嘘つけ。寝てただろ」"},{"t":"d","s":"「……ちょっと」"},{"t":"n","s":"竜馬が、焼きそばパンを片手に、呆れた顔をした。A組の竜馬は、二年になっても背が伸びている。耀平との差は、もう三センチほどしかない。","f":"ryoma"},{"t":"d","s":"「二年になって最初の放送で寝るやつがあるか」","f":"ryoma"},{"t":"d","s":"「だって、長かったから」","f":"ryoma"},{"t":"d","s":"「長いのは認めるけどよ」","f":"ryoma"},{"t":"n","s":"乃亜が、卵焼きを箸でつまみながら、ぼそりと言った。","f":"noa"},{"t":"d","s":"「どうせ、聞いてても、頭に入らないでしょ」","f":"noa"},{"t":"d","s":"「それは、そう」","f":"noa"},{"t":"d","s":"「認めるんだ」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"n","s":"乃亜は、呆れたように目を細めた。けれど、口の端が、ほんの少しだけ上がっている。その隣で、柚月が、にこにこしながら、お弁当の蓋を開けた。","f":"noa"},{"t":"d","s":"「金井くん、卵焼き、食べますか」","f":"noa"},{"t":"d","s":"「あ、うん」","f":"noa"},{"t":"d","s":"「ちょっと」","f":"noa"},{"t":"n","s":"乃亜の箸が、ぴたりと止まった。","f":"noa"},{"t":"d","s":"「それ、わたしのと同じ卵焼きじゃない。ずるい」","f":"noa"},{"t":"d","s":"「ずるくないです。ただのお弁当です」","f":"noa"},{"t":"d","s":"「……いつから、同じ味になったの」","f":"noa"},{"t":"d","s":"「たまたまです」","f":"noa"},{"t":"n","s":"竜馬が、肩を震わせて笑っていた。","f":"ryoma"},{"t":"d","s":"「お前ら、二年になっても変わんねえな」","f":"ryoma"},{"t":"d","s":"「竜馬、笑わない」","f":"ryoma"},{"t":"d","s":"「笑ってねえよ」","f":"ryoma"},{"t":"d","s":"「笑ってる」","f":"ryoma"},{"t":"n","s":"春の風が、屋上を吹き抜けた。四人の間に、桜の花びらが、ひらりと落ちた。","f":"ryoma"},{"t":"n","s":"竜馬が、ふと、耀平を見た。","f":"ryoma"},{"t":"d","s":"「卒業したら、決着つけるって話、忘れてねえだろうな」","f":"ryoma"},{"t":"d","s":"「忘れてないよ」","f":"ryoma"},{"t":"d","s":"「ならいい」","f":"ryoma"},{"t":"n","s":"それだけ言って、竜馬は、パンの残りをかじった。耀平は、空を見上げた。青い。眠い。","f":"ryoma"},{"t":"i","s":"（……平和だ）","f":"ryoma"},{"t":"n","s":"そう思った。この平和が、そう長くは続かないことを、その時は、まだ誰も知らなかった。","f":"ryoma"}]},{"key":"25-3","title":"地下の第一席","bg":"bg_shit_base","dark":true,"mood":"tense","bgm":"tense1","cast":["yohei","genzo"],"lines":[{"t":"n","s":"放課後。耀平は、ひとりでSHITの拠点を訪ねた。","f":"yohei"},{"t":"n","s":"廃線になった地下鉄の駅の、さらに下。長い階段を降りた先に、硝子張りの拘束室が並んでいる。見張りの隊員が、耀平を見て、軽く頭を下げた。","f":"yohei"},{"t":"d","s":"「面会ですね。十分だけです」","f":"yohei"},{"t":"d","s":"「ありがとうございます」","f":"yohei"},{"t":"n","s":"いちばん奥の部屋に、その人はいた。","f":"yohei"},{"t":"n","s":"重力を封じる枷を両手足につけて、それでも背筋を伸ばして、椅子に座っている。黒鉄玄蔵。かつての八天、第一席。","f":"genzo"},{"t":"d","s":"「……来たか、桜の小僧」","f":"genzo"},{"t":"d","s":"「お久しぶりです。調子はどうですか」","f":"genzo"},{"t":"d","s":"「見てのとおりだ。退屈している」","f":"genzo"},{"t":"n","s":"玄蔵は、にやりと笑った。顔の傷が、笑うと少しだけ歪む。去年、校庭で刃を交えた時とは、まるで別の人間のように見えた。","f":"genzo","m":"happy"},{"t":"d","s":"「調子を聞きに来たのか。敵に」","f":"genzo"},{"t":"d","s":"「敵、ですか」","f":"genzo"},{"t":"d","s":"「違うのか」","f":"genzo"},{"t":"d","s":"「……どうでしょう」","f":"genzo"},{"t":"n","s":"耀平は、硝子の前の椅子に座った。拘束された相手と向き合っているのに、不思議と、落ち着いていた。","f":"yohei"},{"t":"n","s":"玄蔵は、しばらく耀平の顔を眺めていた。それから、ふっと、真面目な目になった。","f":"genzo"},{"t":"d","s":"「小僧。お前、最近、自分の強さに満足しているだろう」","f":"genzo"},{"t":"d","s":"「……してないつもりですけど」","f":"genzo"},{"t":"d","s":"「してる。顔に書いてある」","f":"genzo"},{"t":"n","s":"耀平は、言葉に詰まった。","f":"yohei"},{"t":"d","s":"「お前の桜は、見事だった。あの夜桜は、俺が見た中で、いちばん美しい斬撃だった。だが、あれは、技じゃない。状態だ」","f":"yohei"},{"t":"d","s":"「状態」","f":"yohei"},{"t":"d","s":"「桜が舞う。体が勝手に動く。刀が速くなる。重くなる。すべて、お前の中の力が、そうなっているだけだ。強さの土台としては、これ以上のものはない。だが、決め手がない」","f":"yohei"},{"t":"n","s":"玄蔵は、枷のついた指を、一本立てた。","f":"genzo"},{"t":"d","s":"「必殺技は、見た目が格好いいだけじゃない。相手に、これを食らったら終わりだと思わせる。味方に、あいつなら決めてくれると思わせる。決め手というのは、そういうものだ」","f":"genzo"},{"t":"d","s":"「……はい」","f":"genzo"},{"t":"d","s":"「お前の強さは、純粋すぎる。だから、そろそろ、二つ三つ、持っておけ。技を」","f":"genzo"},{"t":"n","s":"敵とは思えない口調だった。けれど、その言葉は、芯を食っていた。","f":"genzo"},{"t":"n","s":"耀平は、黙って頷いた。胸の奥に、小さな石が落ちたような感覚があった。","f":"yohei"},{"t":"d","s":"「……ありがとうございます」","f":"yohei"},{"t":"d","s":"「礼を言うな。敵だぞ、俺は」","f":"yohei"},{"t":"d","s":"「そうでしたね」","f":"yohei"},{"t":"n","s":"面会の十分が、終わった。","f":"yohei"},{"t":"n","s":"階段を上りながら、耀平は、自分の手を見つめた。桜の花びらが、指先で、くるりと回っていた。","f":"yohei"},{"t":"i","s":"（技、か）","f":"yohei"},{"t":"n","s":"考えるか。耀平は、小さく息を吐いた。","f":"yohei"}]},{"key":"25-4","title":"夢","bg":"bg_grandpa_house","dark":false,"mood":"soft","bgm":"soft2","cast":["yohei"],"lines":[{"t":"n","s":"その夜、耀平は、夢を見た。","f":"yohei"},{"t":"n","s":"縁側に、祖父が座っている。夕方の光の中で、皺だらけの手が、お茶の湯呑みを包んでいる。","f":"yohei"},{"t":"n","s":"四歳の耀平は、庭で枝を振っていた。","f":"yohei"},{"t":"d","s":"「じいちゃん、見て」","f":"yohei"},{"t":"d","s":"「見とるぞ」","f":"yohei"},{"t":"d","s":"「かっこいい？」","f":"yohei"},{"t":"d","s":"「ああ。かっこええ」","f":"yohei"},{"t":"n","s":"祖父は、不器用に笑った。その顔が、とても、懐かしかった。","f":"yohei","m":"happy"},{"t":"d","s":"「じいちゃんな、剣のことは、何も分からん」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「でも、お前が、楽しそうに振っとるのは、分かる」","f":"yohei"},{"t":"n","s":"縁側の日だまりが、ゆっくり遠のいていく。","f":"yohei"},{"t":"d","s":"「楽しく、やれ」","f":"yohei"},{"t":"n","s":"目が覚めた時、耀平の頬は、少し濡れていた。窓の外で、夜桜が、風に揺れていた。","f":"yohei"},{"t":"n","s":"まだ、四月だった。","f":"yohei"}]}]},{"n":26,"title":"学園強化プロジェクトと、小さな後輩","sub":"高校・2年4月","era":"high2","lead":"放送の内容を、耀平は、ほとんど聞いていなかった。乃亜に教わった翌日、昼休みの自販機の前で、黒髪の後輩に声をかけられる。","scenes":[{"key":"26-1","title":"乃亜のまとめ","bg":"bg_classroom_e","dark":false,"mood":"soft","bgm":"soft3","cast":["noa","yohei"],"lines":[{"t":"d","s":"「……というわけで、昨日の放送は、全部で四つのことを言ってたの」"},{"t":"n","s":"翌朝のE組の教室に、乃亜が来ていた。C組の乃亜が、わざわざ廊下を歩いてくるのは、去年の春から、もう日課のようになっている。","f":"noa"},{"t":"d","s":"「ちゃんと聞いてた？」","f":"noa"},{"t":"d","s":"「聞いてる」","f":"noa"},{"t":"d","s":"「うそ。目が半分閉じてる」","f":"noa"},{"t":"d","s":"「これは、通常運転」","f":"noa"},{"t":"n","s":"乃亜は、ため息をついて、ノートを開いた。細い字で、きれいに箇条書きがされている。","f":"noa"},{"t":"d","s":"「学園強化プロジェクト。去年の襲撃のあと、学園とSHITが一緒に決めた計画なんだって。まず、学園を拡大する。校舎を増やして、生徒も増やす。次に、教育の強化。実技の時間が増える。それから、他校との交流。合同の行事が増える」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「最後に、SHITの強化。人も、装備も、倍にするって」","f":"noa"},{"t":"d","s":"「へえ」","f":"noa"},{"t":"n","s":"耀平は、うとうとしながら頷いた。乃亜は、そこで、少し声を落とした。","f":"yohei"},{"t":"d","s":"「あとね。新しい生徒会ができるの」","f":"yohei"},{"t":"d","s":"「新しい、生徒会」","f":"yohei"},{"t":"d","s":"「九条先輩が卒業して、空いたでしょ。だから、新体制。会長が、九十九くん」","f":"yohei"},{"t":"d","s":"「ああ、入試首席の」","f":"yohei"},{"t":"d","s":"「そう。副会長が結城くん。風紀、会計、書記、保健まで、去年の同学年から選ばれたって」","f":"yohei"},{"t":"n","s":"耀平は、ふっと目を開けた。","f":"yohei"},{"t":"d","s":"「みんな、まあまあ強かったもんな」","f":"yohei"},{"t":"d","s":"「まあまあって言い方……去年、一緒に戦った仲間でしょ」","f":"yohei"},{"t":"d","s":"「うん。だから、まあまあ強かった」","f":"yohei"},{"t":"n","s":"乃亜は、ふっと笑った。","f":"noa","m":"happy"},{"t":"d","s":"「それ、本人たちに言わないでね」","f":"noa"},{"t":"d","s":"「言わないよ」","f":"noa"},{"t":"d","s":"「言いそうなんだもん」","f":"noa"}]},{"key":"26-2","title":"ペアの期限","bg":"bg_classroom_e","dark":false,"mood":"daily","bgm":"daily3","cast":["yuzuki","yohei"],"lines":[{"t":"n","s":"朝のホームルームで、担任の日下部が、黒板に大きく文字を書いた。"},{"t":"n","s":"〈ペア　期限・今週中〉"},{"t":"d","s":"「えー、昨日の放送で言っていたとおり、今年は一年生と二年生で、ペアを組んでもらう。相手が決まっていないやつは、今週中に申し出ろ。決まらなければ、こっちで決める」"},{"t":"d","s":"「先生！　誰と組むんですか！」と陽太が叫んだ。"},{"t":"d","s":"「だから、一年生とだ」"},{"t":"d","s":"「かわいい子がいいです！」"},{"t":"d","s":"「却下」"},{"t":"n","s":"教室が、どっと笑った。その中で、耀平だけが、きょとんとしていた。","f":"yohei","m":"happy"},{"t":"d","s":"「……ん？　なにそれ」","f":"yohei"},{"t":"n","s":"隣の柚月が、ゆっくりこちらを見た。","f":"yuzuki"},{"t":"d","s":"「金井くん」","f":"yuzuki"},{"t":"d","s":"「うん」","f":"yuzuki"},{"t":"d","s":"「昨日の放送、本当に、一言も聞いてなかったんですね」","f":"yuzuki"},{"t":"d","s":"「……ちょっとは聞いてた」","f":"yuzuki"},{"t":"d","s":"「ちょっとって、どこまで」","f":"yuzuki"},{"t":"d","s":"「ペアを組む、まで」","f":"yuzuki"},{"t":"d","s":"「その先が大事なんです」","f":"yuzuki"},{"t":"n","s":"柚月は、ため息をついて、ノートを開いた。去年の春と同じ、きれいな字だ。","f":"yuzuki"},{"t":"d","s":"「今年の春から、年に一度、一年生と二年生のペアで、合宿に行くことになったんです。六月の初めに、一週間の、実技の合宿です。船で島に渡って、訓練をするそうです。それまでに、ペアを決めておく必要があります」","f":"yuzuki"},{"t":"d","s":"「一年生と、二年生で」","f":"yuzuki"},{"t":"d","s":"「そう。ペアの相手は、自分で選べます。去年の事件があったから、実戦的な訓練が増えたそうです」","f":"yuzuki"},{"t":"n","s":"耀平は、ぼんやりと頷いた。","f":"yohei"},{"t":"d","s":"「じゃあ、一年生の誰かと組めばいいのか」","f":"yohei"},{"t":"d","s":"「そうです。ただ……」","f":"yohei"},{"t":"n","s":"柚月は、少し言いにくそうに、続けた。","f":"yuzuki"},{"t":"d","s":"「金井くんと組みたいという一年生は、たくさんいるみたいです。去年の噂が、広まっているので」","f":"yuzuki"},{"t":"d","s":"「そうなの」","f":"yuzuki"},{"t":"d","s":"「でも、同時に、『やる気が出なさそう』とも言われているので、結局、申し込んできたのは、ほんの数人だとか」","f":"yuzuki"},{"t":"d","s":"「……それは、否定できない」","f":"yuzuki"},{"t":"d","s":"「否定してください」","f":"yuzuki"}]},{"key":"26-3","title":"自販機の前で","bg":"bg_schoolyard_middle","dark":false,"mood":"daily","bgm":"daily4","cast":["yohei","rika","yuzuki"],"lines":[{"t":"n","s":"昼休み。耀平は、ひとりで、中庭の自販機の前に立っていた。","f":"yohei"},{"t":"n","s":"校舎の裏の、桜並木に囲まれた、小さな広場。ベンチが一つあって、自販機が二台並んでいる。今日は、風が気持ちいい。","f":"yohei"},{"t":"i","s":"（コーヒー……いや、ミルクティーか）","f":"yohei"},{"t":"n","s":"迷っているうちに、背後から、声がした。","f":"yohei"},{"t":"d","s":"「せんぱーい❤︎」","f":"yohei"},{"t":"n","s":"振り返ると、そこに、小さな女の子が立っていた。","f":"yohei"},{"t":"cg","v":"cg_rika_first"},{"t":"n","s":"黒髪のボブ。ぴょこんと跳ねたアホ毛。左の耳の上に、白い花のリボンが揺れている。学園の制服ではなく、黒いカーディガンの袖には、白いリボンが編み上げになっていて、紫のチェックのスカートが、春の風にふわりと揺れた。背は、耀平の胸のあたりまでしかない。","f":"yohei"},{"t":"d","s":"「金井耀平せんぱい、ですよね？」","f":"yohei"},{"t":"d","s":"「……そう、だけど」","f":"yohei"},{"t":"d","s":"「やっぱり！　お会いできて、嬉しいです❤︎」","f":"yohei"},{"t":"n","s":"少女は、両手を後ろに組んで、ひょい、と体を傾けた。笑顔が、咲いたように明るい。","f":"yohei"},{"t":"i","s":"（……強い）","f":"yohei"},{"t":"n","s":"耀平の目が、無意識に、少女の足元を見ていた。立ち方が、いい。重心が、まるでぶれていない。小柄な体の、どこにも無駄な力が入っていないのに、隙がなかった。","f":"yohei"},{"t":"d","s":"「一年の、莉花っていいます。せんぱいのこと、ずっと前から、知ってるんですよ❤︎」","f":"yohei"},{"t":"d","s":"「ずっと前から」","f":"yohei"},{"t":"d","s":"「はい。ずーっと、前から」","f":"yohei"},{"t":"n","s":"莉花は、楽しそうに、くすくす笑った。","f":"rika","m":"happy"},{"t":"d","s":"「それでですね、せんぱい。お願いがあるんです」","f":"rika"},{"t":"d","s":"「うん」","f":"rika"},{"t":"d","s":"「わたしと、ペアになってください❤︎」","f":"rika"},{"t":"n","s":"耀平は、缶のミルクティーを握ったまま、しばらく固まった。","f":"yohei"},{"t":"d","s":"「……ペア」","f":"yohei"},{"t":"d","s":"「はい。合宿の、ペアです」","f":"yohei"},{"t":"d","s":"「他にも、申し込みが……」","f":"yohei"},{"t":"d","s":"「ありますよね。でも、わたし、せんぱいがいいんです」","f":"yohei"},{"t":"n","s":"莉花は、一歩、近づいた。上目遣いで、耀平を見上げる。","f":"rika"},{"t":"d","s":"「だめですか？」","f":"rika"},{"t":"n","s":"耀平は、頭をかいた。","f":"yohei"},{"t":"i","s":"（柚月と乃亜に、何か言われそうだ）","f":"yohei"},{"t":"n","s":"そう思ったのは、直感だった。去年の春から、この二人の機嫌には、なぜか敏感になっている。","f":"yohei"},{"t":"d","s":"「……勝負、しようか」","f":"yohei"},{"t":"d","s":"「勝負？」","f":"yohei"},{"t":"d","s":"「おれに勝ったら、ペアになる。それでどう」","f":"yohei"},{"t":"d","s":"「わあ、いいんですか？　せんぱい、強いのに」","f":"yohei"},{"t":"d","s":"「強さの勝負じゃなくて」","f":"yohei"},{"t":"n","s":"耀平は、少し考えてから、言った。","f":"yohei"},{"t":"d","s":"「頭の勝負で」","f":"yohei"}]},{"key":"26-4","title":"知恵比べ","bg":"bg_classroom_e","dark":false,"mood":"daily","bgm":"daily2","cast":["rika","yuzuki","noa"],"lines":[{"t":"n","s":"放課後の教室は、思いのほか、見物人が多かった。"},{"t":"n","s":"莉花が、昼休みのうちに、ふれ回っていたらしい。E組の窓際には、陽太と琴音をはじめ、クラスの半分が集まっている。その最前列に、乃亜と柚月が並んで立っていた。","f":"rika"},{"t":"d","s":"「……どうして、こうなったの」","f":"rika"},{"t":"d","s":"「わたしにも、わかりません」","f":"rika"},{"t":"n","s":"二人の声は、とても低かった。","f":"rika"},{"t":"n","s":"教卓の前で、莉花が、人差し指を立てた。","f":"rika"},{"t":"d","s":"「ルールは簡単です！　わたしが、問題を三つ出します。せんぱいは、それに答える。二つ以上正解できたら、せんぱいの勝ち。一つ以下なら、わたしの勝ちです❤︎」","f":"rika"},{"t":"d","s":"「わかった」","f":"rika"},{"t":"d","s":"「では、第一問！」","f":"rika"},{"t":"n","s":"莉花は、くるりと振り返って、にっこり笑った。","f":"rika","m":"happy"},{"t":"d","s":"「昨日の始業式の放送で、学園長先生が最初に言った言葉は、何でしょう？」","f":"rika"},{"t":"n","s":"耀平は、固まった。","f":"yohei"},{"t":"d","s":"「……おはようございます」","f":"yohei"},{"t":"d","s":"「ぶー。不正解です❤︎」","f":"yohei"},{"t":"n","s":"教室が、どっと沸いた。","f":"yohei"},{"t":"d","s":"「第二問！　今年度から増える実技の時間は、週に何時間でしょう？」","f":"yohei"},{"t":"d","s":"「……三時間」","f":"yohei"},{"t":"d","s":"「ぶー。正解は、五時間でーす」","f":"yohei"},{"t":"d","s":"「柚月、後ろで笑ってない？」","f":"yohei"},{"t":"d","s":"「笑ってません」","f":"yohei"},{"t":"n","s":"柚月は、口元を押さえていた。肩が、小刻みに震えている。","f":"yuzuki"},{"t":"d","s":"「第三問。ペアを組む合宿の、期間は？」","f":"yuzuki"},{"t":"d","s":"「……一週間」","f":"yuzuki"},{"t":"d","s":"「あっ」","f":"yuzuki"},{"t":"d","s":"「あっ」","f":"yuzuki"},{"t":"n","s":"莉花が、本当に、少し驚いた顔をした。","f":"rika"},{"t":"d","s":"「正解です！　どうして、知ってたんですか？」","f":"rika"},{"t":"d","s":"「さっき、柚月に教わった」","f":"rika"},{"t":"d","s":"「えーっ、ずるいです！」","f":"rika"},{"t":"d","s":"「でも、答えられたのは、おれ」","f":"rika"},{"t":"n","s":"莉花は、ぷくっと頬を膨らませた。それから、ふっと、にんまり笑った。","f":"rika","m":"happy"},{"t":"d","s":"「一問正解。つまり、わたしの勝ちです❤︎」","f":"rika"},{"t":"n","s":"教室が、爆笑に包まれた。","f":"rika"},{"t":"d","s":"「金井くん」","f":"rika"},{"t":"n","s":"低い声が、背後から聞こえた。柚月だった。笑顔のまま、こめかみに、うっすらと筋が立っている。","f":"yuzuki"},{"t":"d","s":"「はい」","f":"yuzuki"},{"t":"d","s":"「そこに、座ってください」","f":"yuzuki"},{"t":"d","s":"「……はい」","f":"yuzuki"},{"t":"d","s":"「放送は、ちゃんと聞いてくださいと、昨日も、今日も、言いましたよね」","f":"yuzuki"},{"t":"d","s":"「言われた」","f":"yuzuki"},{"t":"d","s":"「言われたのに、聞いてなかったんですよね」","f":"yuzuki"},{"t":"d","s":"「うん」","f":"yuzuki"},{"t":"d","s":"「約束を守ってもらうだけでは、足りないんです。もう少し、ちゃんとしてください」","f":"yuzuki"},{"t":"d","s":"「……すみません」","f":"yuzuki"},{"t":"n","s":"教室の前で、耀平は、正座をさせられていた。柚月の説教は、五分続いた。莉花は、その横で、にこにこしながら、ひらひらと手を振っていた。","f":"yohei"},{"t":"d","s":"「というわけで、せんぱい。ペア、成立ですね❤︎」","f":"yohei"},{"t":"d","s":"「……そうだね」","f":"yohei"},{"t":"d","s":"「いーっぱい、教えてくださいね、せんぱい❤︎」","f":"yohei"},{"t":"n","s":"教室の端で、乃亜が、ぼそりと呟いた。","f":"noa"},{"t":"d","s":"「……泥棒猫」","f":"noa"},{"t":"d","s":"「乃亜さん、今、何か」","f":"noa"},{"t":"d","s":"「何でもない」","f":"noa"},{"t":"d","s":"「何でもなくないですよね」","f":"noa"},{"t":"d","s":"「柚月こそ、顔が怖い」","f":"noa"},{"t":"n","s":"二人の背後で、陽太が、小さく呟いた。","f":"noa"},{"t":"d","s":"「……おれ、この空気、無理かもしれない」","f":"noa"},{"t":"n","s":"窓の外の桜が、風に揺れていた。","f":"noa"}]}]},{"n":27,"title":"状態ではなく、技を","sub":"高校・2年4〜5月","era":"high2","lead":"ペアが決まった。合宿は、六月の頭。耀平は、ふと、地下の第一席の言葉を思い出す。","scenes":[{"key":"27-1","title":"玄蔵の言葉","bg":"bg_classroom_e","dark":false,"mood":"soft","bgm":"soft4","cast":["yohei","genzo"],"lines":[{"t":"n","s":"その夜、耀平は、寮の部屋で、天井を見ていた。","f":"yohei"},{"t":"n","s":"ペアが決まった。合宿は、六月の初め。あと二ヶ月ほどある。それなのに、頭の中には、別のことばかりが浮かんでいた。","f":"yohei"},{"t":"i","s":"（……状態ではなく、技を作れ）","f":"yohei"},{"t":"n","s":"黒鉄玄蔵の声が、耳の奥に残っている。","f":"genzo"},{"t":"n","s":"あの人は、去年の冬に、校庭で、耀平と刃を交えた。重力で教室ごと押しつぶそうとした、八天の第一席だ。それなのに、今は、まるで、道場の師匠のような目で、耀平を見ていた。","f":"yohei"},{"t":"d","s":"「お前の桜は、状態だ。だが、技じゃない」","f":"yohei"},{"t":"n","s":"その言葉は、悔しいくらい、正しかった。","f":"yohei"},{"t":"n","s":"耀平のスキルは、桜が舞うこと。花びらに触れると、体が勝手に反応する。刀に桜を纏えば、斬撃が重くなる。夜桜繚蘭になれば、世界が夜に染まって、すべてが、耀平の味方になる。","f":"yohei","fx":"yozakura"},{"t":"n","s":"けれど、それは、どれも、環境を作る力だった。","f":"yohei"},{"t":"d","s":"「決め手が、ない」","f":"yohei"},{"t":"n","s":"声に出してみると、その響きが、妙に、胸に沈んだ。","f":"yohei"},{"t":"i","s":"（……技、か）","f":"yohei"},{"t":"n","s":"寝返りを打った。窓の外の桜が、月の光に透けていた。","f":"yohei"}]},{"key":"27-2","title":"九条先輩に聞く","bg":"bg_shit_base","dark":false,"mood":"daily","bgm":"daily4","cast":["yohei","ren","genzo"],"lines":[{"t":"n","s":"週末。耀平は、SHITの訓練場を訪ねた。","f":"yohei"},{"t":"n","s":"SHITの拠点の、地上にある広い場所だ。去年の暮れに、ここで、何度も鍛えてもらった。","f":"yohei"},{"t":"d","s":"「ほう。技を作りたい、か」","f":"yohei"},{"t":"n","s":"九条蓮は、木刀を肩にかけて、耀平を見下ろした。卒業して、SHITの正式な隊員になってから、少しだけ、顔つきが引き締まった気がする。","f":"ren"},{"t":"d","s":"「はい。玄蔵さんに、言われました」","f":"ren"},{"t":"d","s":"「第一席に？　面会に行ったのか」","f":"ren"},{"t":"d","s":"「はい」","f":"ren"},{"t":"d","s":"「……物好きな奴だ」","f":"ren"},{"t":"n","s":"蓮は、苦笑した。それから、少しだけ、真面目な顔になった。","f":"ren","m":"sweat"},{"t":"d","s":"「結論から言う。私に、教えられることはない」","f":"ren"},{"t":"d","s":"「え」","f":"ren"},{"t":"d","s":"「技というのは、自分の中から出てくるものだ。人に教わった技は、人の技にしかならない。私が、お前に、型を渡すことはできる。だが、それは、お前の技ではない」","f":"ren"},{"t":"n","s":"耀平は、少し考えてから、頷いた。","f":"yohei"},{"t":"d","s":"「じゃあ、どうすれば」","f":"yohei"},{"t":"d","s":"「見つかるまで、考えろ。ただ、ひとつだけ、助言をやろう」","f":"yohei"},{"t":"n","s":"蓮は、空を見上げた。","f":"yohei"},{"t":"d","s":"「お前は、何のために、刀を振る」","f":"yohei"},{"t":"d","s":"「……守るため、です」","f":"yohei"},{"t":"d","s":"「それは、理由だ。技には、形が要る。お前が守りたいものは、どんな形をしている」","f":"yohei"},{"t":"n","s":"耀平は、しばらく黙っていた。","f":"yohei"},{"t":"d","s":"「……分かりません」","f":"yohei"},{"t":"d","s":"「そうか。なら、それが、宿題だな」","f":"yohei"},{"t":"n","s":"蓮は、にやりと笑って、木刀を投げた。","f":"yohei"},{"t":"d","s":"「受け取れ。今日の稽古は、考えながらやってみろ」","f":"yohei"},{"t":"d","s":"「はい」","f":"yohei"},{"t":"n","s":"その日は、結局、答えは、出なかった。","f":"yohei"}]},{"key":"27-3","title":"体育の時間","bg":"bg_schoolyard_middle","dark":false,"mood":"daily","bgm":"daily5","cast":["yohei","yuzuki","noa"],"lines":[{"t":"n","s":"月曜日の二時間目は、実技の時間だった。"},{"t":"n","s":"今年度から、週に五時間に増えた。運動場に集まった二年生が、模擬戦の組み合わせを、先生から告げられる。"},{"t":"d","s":"「次、金井、前へ。相手は——」"},{"t":"n","s":"耀平の前に立ったのは、去年の秋まで、ほとんど話したことのない、B組の生徒だった。","f":"yohei"},{"t":"d","s":"「よろしくな、金井。噂は聞いてるぜ」","f":"yohei"},{"t":"d","s":"「よろしく」","f":"yohei"},{"t":"d","s":"「去年の襲撃、すごかったらしいな。でも、実技の授業は、俺も、手加減しねえぞ」","f":"yohei"},{"t":"d","s":"「うん。おれも」","f":"yohei"},{"t":"n","s":"耀平は、木刀を構えた。","f":"yohei"},{"t":"n","s":"去年なら、少し、手を抜いていたかもしれない。目立たないように、ほどほどに、負けない程度に。","f":"yohei"},{"t":"n","s":"けれど、今年は、違った。","f":"yohei"},{"t":"i","s":"（……考えながら、やってみろ）","f":"yohei"},{"t":"n","s":"蓮の言葉を、思い出した。","f":"yohei"},{"t":"d","s":"「始め！」","f":"yohei"},{"t":"n","s":"B組の生徒が、地面を蹴った。速い。去年より、ずっと。","f":"yohei"},{"t":"n","s":"耀平は、半歩だけ、横にずれた。花びらが一枚、頬をかすめる。木刀が、静かに、相手の手首を押さえた。","f":"yohei"},{"t":"d","s":"「……え」","f":"yohei"},{"t":"n","s":"気づいた時には、相手の木刀は、地面に落ちていた。","f":"yohei"},{"t":"d","s":"「そこまで！」","f":"yohei"},{"t":"n","s":"校庭が、しんと静まり返った。","f":"yohei"},{"t":"d","s":"「……おい」","f":"yohei"},{"t":"d","s":"「今、何した？」","f":"yohei"},{"t":"d","s":"「見えなかった」","f":"yohei"},{"t":"n","s":"ざわめきが、波のように広がった。陽太が、拳を突き上げた。","f":"yohei"},{"t":"d","s":"「うおおお！　金井、手え抜かなくなった！」","f":"yohei"},{"t":"d","s":"「抜いてない、前から」","f":"yohei"},{"t":"d","s":"「嘘つけ！」","f":"yohei"},{"t":"n","s":"校庭の端で、乃亜が、腕を組んで、じっと耀平を見ていた。その隣で、柚月が、小さく、息をついていた。","f":"noa"},{"t":"d","s":"「……本気、出してますね」","f":"noa"},{"t":"d","s":"「出してるっていうか」","f":"noa"},{"t":"d","s":"「何か、迷ってる顔」","f":"noa"},{"t":"d","s":"「……分かるの」","f":"noa"},{"t":"d","s":"「分かります。隣の席ですから」","f":"noa"},{"t":"n","s":"柚月は、静かに、微笑んだ。","f":"yuzuki","m":"happy"},{"t":"n","s":"その様子を、校舎の三階の窓から、じっと見下ろしている小さな影があった。黒髪のボブに、白い花のリボン。","f":"yuzuki"},{"t":"n","s":"莉花は、窓枠に頬杖をついて、口元だけで、笑っていた。","f":"rika"},{"t":"d","s":"「……やっぱり、せんぱいは、すごいなあ」","f":"rika"},{"t":"n","s":"その声は、春の風にまぎれて、誰にも届かなかった。","f":"rika"}]}]},{"n":28,"title":"生意気な新入生と、SHITの二人","sub":"高校・2年5月","era":"high2","lead":"竜馬に、生意気な新入生が突っかかる。そして学園に、SHITの藤堂と理央がやってくる。","scenes":[{"key":"28-1","title":"A組の前で","bg":"bg_schoolyard_middle","dark":true,"mood":"battle","bgm":"battle2","cast":["ryoma","yohei"],"lines":[{"t":"n","s":"五月の初め。昼休みの校庭の隅で、小さな人だかりができていた。"},{"t":"d","s":"「何だ、あれ」"},{"t":"d","s":"「A組の竜馬と、一年が揉めてるって」"},{"t":"n","s":"耀平が、陽太に引っぱられて、人垣の後ろからのぞくと、竜馬の前に、ひとりの一年生が立っていた。","f":"yohei"},{"t":"n","s":"灰色がかった髪が、あちこちに跳ねている。竜馬より頭ひとつ小さいのに、顔は、まるで負けていない。","f":"ryoma"},{"t":"d","s":"「あんたが、竜馬先輩っすよね。紅蓮爆炎の」","f":"ryoma"},{"t":"d","s":"「……だったら、何だ」","f":"ryoma"},{"t":"d","s":"「いや、思ってたより、大したことなさそうだなって」","f":"ryoma"},{"t":"n","s":"周りが、息を呑んだ。","f":"ryoma","m":"surprise"},{"t":"n","s":"竜馬の眉が、ぴくりと動いた。","f":"ryoma"},{"t":"d","s":"「もういっぺん、言ってみろ」","f":"ryoma"},{"t":"d","s":"「何度でも言いますよ。去年の襲撃で、竜馬先輩が、第八席に負けかけたって聞きました。炎なんて、風で吹き消せるんで」","f":"ryoma"},{"t":"n","s":"一年生は、にやりと笑った。その足元で、小さな風が、くるくると渦を巻いた。","f":"ryoma","m":"happy"},{"t":"d","s":"「神崎隼。スキルは、烈風斬刃。覚えといてください」","f":"ryoma"},{"t":"d","s":"「……神崎、ね」","f":"ryoma"},{"t":"n","s":"竜馬は、ゆっくりと、拳を握った。炎が、指の隙間からこぼれた。","f":"ryoma"},{"t":"n","s":"周りの生徒たちが、一歩、下がる。","f":"ryoma"},{"t":"d","s":"「いい度胸だ」","f":"ryoma"},{"t":"n","s":"次の瞬間、二人が、同時に、地面を蹴った。","f":"ryoma"},{"t":"n","s":"炎と風が、ぶつかった。火の粉が舞い、風が刃になって、校庭の砂を切り裂いていく。隼の動きは、速かった。竜馬の拳を、紙一重でかわして、懐に潜り込む。","f":"ryoma"},{"t":"d","s":"「おお」","f":"ryoma"},{"t":"n","s":"耀平は、思わず、声を漏らした。","f":"yohei"},{"t":"d","s":"「……あいつ、強いな」","f":"yohei"},{"t":"d","s":"「だよな！　一年の中では、ダントツだって噂だぜ」","f":"yohei"},{"t":"n","s":"陽太が、興奮して、耀平の肩を叩いた。","f":"yohei"},{"t":"n","s":"最後は、竜馬の炎が、隼の風を、まるごと包んだ。風の刃が、炎の中で、ぱっと消える。隼は、尻もちをついた。","f":"ryoma"},{"t":"d","s":"「……くそっ」","f":"ryoma"},{"t":"d","s":"「まあ、悪くねえ」","f":"ryoma"},{"t":"n","s":"竜馬は、笑っていた。顔中が、火の粉で少し黒くなっている。","f":"ryoma"},{"t":"d","s":"「お前、名前、もう一度言え」","f":"ryoma"},{"t":"d","s":"「神崎、隼」","f":"ryoma"},{"t":"d","s":"「覚えとく」","f":"ryoma"},{"t":"n","s":"隼は、悔しそうに、竜馬を睨んだ。それから、ぷいと顔をそむけた。","f":"ryoma","m":"anger"},{"t":"d","s":"「……次は、勝ちますから」","f":"ryoma"},{"t":"d","s":"「おう。いつでも来い」","f":"ryoma"},{"t":"n","s":"その様子を見ていた耀平の肩を、陽太が、ぽんと叩いた。","f":"yohei"},{"t":"d","s":"「あれ、ペアになるな」","f":"yohei"},{"t":"d","s":"「ペア？」","f":"yohei"},{"t":"d","s":"「あいつら、絶対、同じ匂いがするだろ」","f":"yohei"},{"t":"n","s":"耀平は、竜馬の横顔を見た。竜馬の口元が、ほんの少しだけ、楽しそうに緩んでいた。","f":"yohei"},{"t":"i","s":"（……確かに）","f":"yohei"}]},{"key":"28-2","title":"SHITがやってくる","bg":"bg_graduation","dark":false,"mood":"daily","bgm":"daily5","cast":["todo","rio"],"lines":[{"t":"n","s":"その日の午後。全校生徒が、半分だけ直った講堂に集められた。"},{"t":"n","s":"壇上に立っていたのは、見覚えのある二人だった。"},{"t":"n","s":"一人は、眼鏡の奥から、全員を見渡す、すらりとした女性。黒髪を低い位置で結んで、黒いコートの肩に、銀の紋章が光っている。"},{"t":"n","s":"もう一人は、その隣で、足をぶらぶらさせている、小学生くらいの子供。大きな黒いジャケットの袖が、手の先まで隠れている。"},{"t":"d","s":"「SHIT作戦参謀の、藤堂凪沙だ」"},{"t":"n","s":"女性の声は、静かで、よく通った。"},{"t":"d","s":"「学園強化プロジェクトの一環として、今日から、SHITの隊員が、学園に常駐する。実技の補助、校内の警備、そして、合同合宿の運営を担当する。以上、質問は、受け付けない」"},{"t":"d","s":"「受け付けないんですか」と、陽太が小声で呟いた。"},{"t":"d","s":"「受け付けないと言っている」"},{"t":"n","s":"藤堂が、眼鏡の位置を、指で直した。","f":"todo"},{"t":"d","s":"「……聞こえてるのか」","f":"todo"},{"t":"d","s":"「地獄耳なんだ。この子もだ」","f":"todo"},{"t":"n","s":"隣の子供が、にやっと笑った。","f":"todo","m":"happy"},{"t":"d","s":"「柏木理央。全知解析。よろしくね、お兄ちゃん、お姉ちゃんたち」","f":"todo"},{"t":"n","s":"講堂が、どよめいた。去年の襲撃で、無明の全てを読んだと噂されたのが、この子だと、誰かが囁いている。","f":"mumyo"},{"t":"n","s":"耀平は、その子と、目が合った。","f":"yohei"},{"t":"n","s":"理央は、ひらひらと手を振った。","f":"rio"},{"t":"i","s":"（……あ）","f":"rio"},{"t":"n","s":"去年の冬、SHITの拠点で、「思ってたより弱そう」と言われたことを、思い出した。","f":"rio"}]},{"key":"28-3","title":"理央の映像","bg":"bg_classroom_e","dark":false,"mood":"daily","bgm":"daily1","cast":["yohei","todo","rio"],"lines":[{"t":"n","s":"説明会のあと。耀平は、藤堂に呼ばれて、講堂の裏の小さな会議室に入った。","f":"yohei"},{"t":"d","s":"「呼び出して、すまない。君に、ひとつ、見てもらいたいものがある」","f":"yohei"},{"t":"d","s":"「はい」","f":"yohei"},{"t":"d","s":"「理央」","f":"yohei"},{"t":"n","s":"藤堂が顎をしゃくると、理央は、お菓子の包み紙を机に置いて、ぴょんと立ち上がった。","f":"todo"},{"t":"d","s":"「じゃあ、見せるね」","f":"todo"},{"t":"n","s":"理央が、指先を、すっと空に向けた。","f":"rio"},{"t":"n","s":"空中に、光が灯った。それが、薄い膜のように広がって、画面になる。そこに、見覚えのある校庭が、映った。","f":"rio"},{"t":"d","s":"「あっ」","f":"rio"},{"t":"n","s":"耀平の模擬戦だった。先週の月曜日、B組の生徒の木刀を、花びらが一枚、頬をかすめた瞬間に、押さえていた、あの場面。","f":"yohei"},{"t":"d","s":"「全知解析の、基本の使い方。その場に残った『痕跡』を、映像として再生できるの。今のは、先週の校庭の痕跡」","f":"yohei"},{"t":"d","s":"「すごい……」","f":"yohei"},{"t":"d","s":"「お兄ちゃん、右足の踏み込みが、毎回、半拍遅いよ。ほら、ここ」","f":"yohei"},{"t":"n","s":"映像が、ゆっくりと巻き戻った。確かに、耀平の右足が、ほんの少しだけ、遅れて動いている。","f":"yohei"},{"t":"d","s":"「……自分では、気づかなかった」","f":"yohei"},{"t":"d","s":"「分析は、私の仕事だから」","f":"yohei"},{"t":"n","s":"理央は、得意げに、胸を張った。藤堂が、静かに補足する。","f":"rio"},{"t":"d","s":"「彼女の能力は、人の記憶を読むものではない。場所や物に残った痕跡を、映像に変えるものだ。だから、手に触れたものや、書かれたものほど、精度が高い」","f":"rio"},{"t":"d","s":"「書かれたもの、ですか」","f":"rio"},{"t":"d","s":"「そうだ。手紙や、日記や、ノートの跡のようなもの。人の手が、強く関わったものは、痕跡が深く残る」","f":"rio"},{"t":"n","s":"理央が、うんうんと頷いた。","f":"rio"},{"t":"d","s":"「おじいちゃんが書いた古い手紙でも、だいたいは、見えるよ」","f":"rio"},{"t":"n","s":"耀平は、ふっと、箪笥の中の手紙を、思い出した。","f":"yohei"},{"t":"d","s":"「……おじいちゃんの、手紙」","f":"yohei"},{"t":"d","s":"「あれ、どうしたの、お兄ちゃん」","f":"yohei"},{"t":"d","s":"「いや。何でもない」","f":"yohei"},{"t":"n","s":"何でもない。そう言いながら、胸の奥が、ほんの少し、ざわついた。理由は、分からなかった。","f":"yohei"},{"t":"n","s":"藤堂が、咳払いをした。","f":"todo"},{"t":"d","s":"「本題に入ろう。六月の合宿は、SHITが運営に回る。参加者の安全確保が、最優先だ。君には、万一の時の、戦力として、期待している」","f":"todo"},{"t":"d","s":"「はい」","f":"todo"},{"t":"d","s":"「それから、もう一つ。この子と、もう一人、運営側のスタッフが、君に会いたがっていた」","f":"todo"},{"t":"d","s":"「もう一人？」","f":"todo"},{"t":"n","s":"会議室の扉が、がちゃりと開いた。","f":"todo"},{"t":"d","s":"「耀平くーん！　久しぶり！」","f":"todo"},{"t":"n","s":"薄紫の髪が、扉の隙間から、勢いよく飛び込んできた。","f":"todo"},{"t":"d","s":"「……蛍さん」","f":"todo"},{"t":"d","s":"「覚えててくれた！　嬉しいなあ！」","f":"todo"},{"t":"n","s":"蛍は、嬉しそうに、耀平の腕にぎゅっと抱きついた。藤堂が、こめかみを押さえた。","f":"hotaru"},{"t":"d","s":"「運営に回る、紫苑蛍だ。元八天の協力者として、特別に参加している。……扱いには、気をつけろ」","f":"hotaru"},{"t":"d","s":"「失礼ね。協力者って、ちゃんと言って」","f":"hotaru"},{"t":"d","s":"「協力者だ」","f":"hotaru"},{"t":"n","s":"蛍は、頬を膨らませてから、耀平を見上げた。","f":"hotaru"},{"t":"d","s":"「ねえ、耀平くん。合宿が始まる前に、デートの約束、ちゃんと、決めよっか」","f":"hotaru"},{"t":"d","s":"「……えっと」","f":"hotaru"},{"t":"d","s":"「忘れたなんて、言わせないからね」","f":"hotaru"},{"t":"n","s":"耀平は、蛍の腕を、やんわりと外した。","f":"yohei"},{"t":"d","s":"「……考えておきます」","f":"yohei"},{"t":"d","s":"「ほんと？　約束だよ？」","f":"yohei"},{"t":"n","s":"理央が、ぼそりと呟いた。","f":"rio"},{"t":"d","s":"「お兄ちゃん、困ってる」","f":"rio"},{"t":"d","s":"「困ってない」","f":"rio"},{"t":"d","s":"「顔に出てるよ」","f":"rio"},{"t":"n","s":"藤堂は、疲れたように、ため息をついた。","f":"todo"},{"t":"n","s":"窓の外では、夕方の光が、廊下に長い影を落としていた。この日、この会議室で交わされた言葉が、のちに、すべてを動かす鍵になるなんて、誰も、気づいていなかった。","f":"todo"}]}]},{"n":29,"title":"放課後の特訓と、莉花の笑顔","sub":"高校・2年5月","era":"high2","lead":"莉花との放課後の特訓。乃亜と柚月の機嫌は、少しずつ悪くなっていく。","scenes":[{"key":"29-1","title":"河原の特訓","bg":"bg_riverside","dark":true,"mood":"battle","bgm":"battle1","cast":["rika","yohei"],"lines":[{"t":"d","s":"「せんぱーい、こっちですよー！」"},{"t":"n","s":"放課後の河原に、莉花の明るい声が響いた。","f":"rika"},{"t":"n","s":"夕方の風が、気持ちいい。土手の草が、さらさらと揺れる。莉花は、黒いカーディガンの袖を、ぱたぱたと振って、手を上げていた。","f":"rika"},{"t":"d","s":"「ペアの特訓、始めましょう！」","f":"rika"},{"t":"d","s":"「何をするの」","f":"rika"},{"t":"d","s":"「もちろん、実戦です！」","f":"rika"},{"t":"n","s":"莉花は、背中から、細身の刀を、すらりと抜いた。","f":"rika"},{"t":"n","s":"刃が、夕日を反射した。柄に近いところに、小さな紫の花の模様が、彫られている。","f":"rika"},{"t":"d","s":"「……きれいな刀だ」","f":"rika"},{"t":"d","s":"「ありがとうございます❤︎　おじいちゃんの形見なんです」","f":"rika"},{"t":"d","s":"「おじいちゃん」","f":"rika"},{"t":"d","s":"「はい。刀を打つ、職人さんだったんです」","f":"rika"},{"t":"n","s":"莉花は、さらりと言った。その声は、いつもの甘い響きのままだった。耀平は、それ以上、聞かなかった。","f":"rika"},{"t":"d","s":"「じゃあ、いきますね！」","f":"rika"},{"t":"n","s":"莉花が、地面を蹴った。","f":"rika"},{"t":"n","s":"速い。","f":"rika"},{"t":"n","s":"耀平の目が、見開かれた。小柄な体が、一瞬で、懐に入り込んでいる。刃が、下から跳ね上がった。耀平は、体を引いて、紙一重でかわした。","f":"yohei"},{"t":"d","s":"「わっ、避けられた！」","f":"yohei"},{"t":"d","s":"「危ない」","f":"yohei"},{"t":"d","s":"「でも、楽しい！」","f":"yohei"},{"t":"n","s":"莉花は、くるりと回って、もう一撃を放った。軌道が、読めない。右かと思えば左、上かと思えば下。子供の遊びのような軽やかさで、本物の殺意だけが、刃の先にあった。","f":"rika"},{"t":"i","s":"（……やっぱり、強い）","f":"rika"},{"t":"n","s":"耀平は、花びらを、一枚、指先に呼んだ。","f":"yohei"},{"t":"n","s":"次の瞬間、二人の刀が、ぶつかった。","f":"yohei"},{"t":"n","s":"火花が、散った。","f":"yohei"},{"t":"n","s":"しばらくして、二人は、息を弾ませて、土手に並んで座っていた。","f":"yohei"},{"t":"d","s":"「はあ……はあ……やっぱり、せんぱい、本気出してくれないんですね」","f":"yohei"},{"t":"d","s":"「出してるよ」","f":"yohei"},{"t":"d","s":"「嘘です。半分くらいですよね？」","f":"yohei"},{"t":"d","s":"「……分かった？」","f":"yohei"},{"t":"d","s":"「分かりますよー。わたし、人を見る目には、自信があるんです」","f":"yohei"},{"t":"n","s":"莉花は、膝を抱えて、くすくすと笑った。","f":"rika","m":"happy"},{"t":"d","s":"「せんぱいは、優しいから。強い人は、優しいんですよね」","f":"rika"},{"t":"d","s":"「そんなことないよ」","f":"rika"},{"t":"d","s":"「あります。……わたしが、知ってるせんぱいは、そうでした」","f":"rika"},{"t":"n","s":"莉花の声が、ほんの少しだけ、静かになった。耀平は、その横顔を見た。夕日に染まった頬が、赤く光っている。","f":"rika","m":"blush"},{"t":"d","s":"「それ、どういう意味」","f":"rika"},{"t":"d","s":"「ふふ、秘密です❤︎」","f":"rika"},{"t":"n","s":"莉花は、ぴょんと立ち上がった。","f":"rika"},{"t":"d","s":"「さあ、もう一戦、いきましょう！」","f":"rika"}]},{"key":"29-2","title":"食堂の火花","bg":"bg_classroom_e","dark":false,"mood":"daily","bgm":"daily2","cast":["yohei","yuzuki","rika"],"lines":[{"t":"n","s":"翌日の昼休み。食堂のテーブルに、四人が座っていた。"},{"t":"n","s":"耀平と莉花が、並んで。向かいに、乃亜と柚月が、並んで。","f":"yohei"},{"t":"d","s":"「……どうして、ここに座るの」","f":"yohei"},{"t":"d","s":"「だって、せんぱいと、ペアですから❤︎」","f":"yohei"},{"t":"d","s":"「ペアは、食堂で座る席まで、決まってるわけじゃないでしょ」","f":"yohei"},{"t":"d","s":"「でも、せんぱいの隣は、ペアの特権じゃないですか？」","f":"yohei"},{"t":"d","s":"「特権？」","f":"yohei"},{"t":"n","s":"乃亜の眉が、ぴくりと動いた。柚月が、微笑みを崩さないまま、静かに箸を置いた。","f":"noa","m":"happy"},{"t":"d","s":"「莉花さん」","f":"noa"},{"t":"d","s":"「はい、柚月先輩❤︎」","f":"noa"},{"t":"d","s":"「隣の席というのは、とても大切なものなんです」","f":"noa"},{"t":"d","s":"「そうなんですか？」","f":"noa"},{"t":"d","s":"「はい。毎日、毎日、同じ場所に座って、同じ時間を過ごす。それが、隣の席です」","f":"noa"},{"t":"d","s":"「じゃあ、わたしは、特訓の時間に、隣にいますね」","f":"noa"},{"t":"d","s":"「……」","f":"noa"},{"t":"n","s":"柚月の笑顔が、一瞬、固まった。","f":"yuzuki"},{"t":"n","s":"耀平は、カレーを食べながら、ぼんやりと、三人を見ていた。","f":"yohei"},{"t":"d","s":"「何か、空気が重い」","f":"yohei"},{"t":"d","s":"「重くなんてありません」","f":"yohei"},{"t":"d","s":"「重くなんてないよ」","f":"yohei"},{"t":"d","s":"「全然、重くないです❤︎」","f":"yohei"},{"t":"n","s":"三人の声が、揃った。耀平は、そっと、カレーのスプーンを置いた。","f":"yohei"},{"t":"d","s":"「……おれ、トイレ」","f":"yohei"},{"t":"d","s":"「逃げないで」","f":"yohei"},{"t":"d","s":"「逃げないでください」","f":"yohei"},{"t":"n","s":"その横で、莉花だけが、にこにこと笑っていた。その目の奥が、ほんの一瞬だけ、ひどく静かだったことに、耀平は、気づかなかった。","f":"rika"}]},{"key":"29-3","title":"夜桜の話","bg":"bg_rooftop","dark":true,"mood":"night","bgm":"night3","cast":["rika","yohei"],"lines":[{"t":"n","s":"夜。寮の屋上の手すりに、耀平は、一人で寄りかかっていた。","f":"yohei"},{"t":"i","s":"（技……）","f":"yohei"},{"t":"n","s":"考えているうちに、後ろから、ひょいと、小さな影が現れた。","f":"yohei"},{"t":"d","s":"「せんぱーい。やっぱり、ここにいた」","f":"yohei"},{"t":"d","s":"「莉花」","f":"yohei"},{"t":"d","s":"「寮の屋上って、立ち入り禁止じゃなかったでしたっけ」","f":"yohei"},{"t":"d","s":"「禁止だけど」","f":"yohei"},{"t":"d","s":"「じゃあ、わたしも、共犯ですね❤︎」","f":"yohei"},{"t":"n","s":"莉花は、手すりに、ぴょんと飛び乗って、耀平の隣に座った。夜風が、二人の髪を揺らす。","f":"rika"},{"t":"d","s":"「せんぱいの桜、綺麗ですよね」","f":"rika"},{"t":"d","s":"「そう？」","f":"rika"},{"t":"d","s":"「はい。でも、昼より、夜の方が、ずっと綺麗だと思いません？」","f":"rika"},{"t":"d","s":"「夜」","f":"rika"},{"t":"d","s":"「桜って、夜の方が、強いんです。昼間は、ただ咲いているだけ。でも、夜になると、月の光を借りて、本当の姿が見えるんです」","f":"rika"},{"t":"n","s":"耀平は、ふと、莉花の横顔を見た。","f":"yohei"},{"t":"n","s":"夜の色が、彼女の目に、静かに映っていた。いつもの小悪魔めいた笑顔は、そこになかった。","f":"yohei"},{"t":"d","s":"「……詳しいんだな」","f":"yohei"},{"t":"d","s":"「おじいちゃんが、そう言ってたんです」","f":"yohei"},{"t":"d","s":"「そっか」","f":"yohei"},{"t":"n","s":"莉花は、足をぶらぶらさせながら、星空を見上げた。","f":"rika"},{"t":"d","s":"「せんぱい」","f":"rika"},{"t":"d","s":"「うん」","f":"rika"},{"t":"d","s":"「せんぱいは、今、何を悩んでるんですか」","f":"rika"},{"t":"d","s":"「……どうして」","f":"rika"},{"t":"d","s":"「顔に書いてあります」","f":"rika"},{"t":"n","s":"耀平は、しばらく黙っていた。それから、ぽつりと言った。","f":"yohei"},{"t":"d","s":"「技を、作りたいんだ」","f":"yohei"},{"t":"d","s":"「技」","f":"yohei"},{"t":"d","s":"「今のおれの強さは、状態でしかないって言われた。決め手が、ない」","f":"yohei"},{"t":"d","s":"「なるほど」","f":"yohei"},{"t":"n","s":"莉花は、うんうんと頷いた。","f":"rika"},{"t":"d","s":"「それなら、きっと、せんぱいの中に、もう、答えはありますよ」","f":"rika"},{"t":"d","s":"「そうかな」","f":"rika"},{"t":"d","s":"「はい。だって、せんぱいは、桜ですから」","f":"rika"},{"t":"n","s":"その言葉の意味は、分からなかった。けれど、不思議と、胸が軽くなった。","f":"rika"},{"t":"d","s":"「……ありがとう」","f":"rika"},{"t":"d","s":"「どういたしまして❤︎」","f":"rika"},{"t":"n","s":"莉花は、にっこりと笑った。その笑顔は、まるで、本物の、ただの後輩のようだった。","f":"rika","m":"happy"}]}]},{"n":30,"title":"祖父の命日と、紫の花","sub":"高校・2年5月下旬","era":"high2","lead":"五月の終わり。祖父の命日に、耀平は乃亜と墓を訪ねる。そこには、誰かが先に供えた、紫の花があった。","scenes":[{"key":"30-1","title":"玄関の乃亜","bg":"bg_dorm","dark":false,"mood":"soft","bgm":"soft3","cast":["noa","yohei"],"lines":[{"t":"n","s":"五月の最後の土曜日。朝の寮の玄関に、乃亜が、立っていた。","f":"noa"},{"t":"n","s":"去年と、同じ場所。同じ時間。","f":"noa"},{"t":"d","s":"「……おはよう」","f":"noa"},{"t":"d","s":"「おはよう」","f":"noa"},{"t":"d","s":"「また、ここで待ってたの」","f":"noa"},{"t":"d","s":"「去年も、そうだったでしょ。今年も」","f":"noa"},{"t":"n","s":"乃亜は、小さな花束を、胸の前で抱えていた。白い花が、ふんわりと咲いている。","f":"noa"},{"t":"d","s":"「行こう。おじいちゃんの、お墓」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"n","s":"耀平は、頷いて、靴を履いた。","f":"yohei"},{"t":"n","s":"寮の玄関を出ると、五月の空は、よく晴れていた。去年の、この日とは、まるで違う。それでも、足取りは、少しだけ、重かった。","f":"yohei"},{"t":"d","s":"「……もう、四年になるんだね」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「早いね」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「ねえ、耀平」","f":"yohei"},{"t":"d","s":"「ん」","f":"yohei"},{"t":"d","s":"「泣いても、いいんだよ」","f":"yohei"},{"t":"d","s":"「泣かないよ」","f":"yohei"},{"t":"d","s":"「うそ」","f":"yohei"},{"t":"n","s":"乃亜は、ふっと笑った。耀平は、前を向いたまま、小さく頷いた。","f":"noa","m":"happy"}]},{"key":"30-2","title":"紫の花","bg":"bg_grave","dark":false,"mood":"sad","bgm":"sad1","cast":["noa","yohei"],"lines":[{"t":"n","s":"墓地は、街の外れの、小高い丘の上にあった。"},{"t":"n","s":"桜の木が、一本、墓石の隣に立っている。もう、花は散って、若葉が揺れていた。"},{"t":"d","s":"「……あれ」"},{"t":"n","s":"先に気づいたのは、乃亜だった。","f":"noa"},{"t":"n","s":"墓石の前に、一輪の花が、供えられていた。","f":"noa"},{"t":"n","s":"紫の、桔梗だった。","f":"noa"},{"t":"n","s":"星の形に開いた花びらが、朝の光を受けて、静かに揺れている。まだ、新しい。露が、花びらの上で、きらきらと光っていた。","f":"noa"},{"t":"d","s":"「誰か、来たのかな」","f":"noa"},{"t":"d","s":"「……分からない」","f":"noa"},{"t":"d","s":"「おじいちゃんの命日、知ってる人なんて、わたしたちくらいしか、いないよね」","f":"noa"},{"t":"d","s":"「うん。親戚も、いないし」","f":"noa"},{"t":"n","s":"耀平は、墓石の前に、膝をついた。紫の花に、そっと、指を触れる。","f":"yohei"},{"t":"d","s":"「……きれいだ」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"n","s":"乃亜が、持ってきた白い花束を、隣に置いた。二つの花が、並んで揺れた。","f":"noa"},{"t":"n","s":"耀平は、目を閉じて、手を合わせた。","f":"yohei"},{"t":"i","s":"（じいちゃん。おれ、二年生になったよ）","f":"yohei"},{"t":"n","s":"返事は、なかった。ただ、風が、若葉を揺らす音だけがした。","f":"yohei"},{"t":"n","s":"病室で、祖父が笑っていた顔を、思い出した。","f":"yohei"},{"t":"d","s":"『歳じゃ。ただの、歳』","f":"yohei"},{"t":"n","s":"あの日の祖父の声は、とても静かだった。そして、手紙。『強くなれ。優しくなれ。そして、ちゃんと、笑え』。","f":"yohei"},{"t":"i","s":"（……ちゃんと、笑えてるかな）","f":"yohei"},{"t":"n","s":"目を開けると、乃亜が、じっとこちらを見ていた。","f":"noa"},{"t":"d","s":"「何」","f":"noa"},{"t":"d","s":"「ううん。何も」","f":"noa"},{"t":"d","s":"「変な顔、してた？」","f":"noa"},{"t":"d","s":"「してた。でも、悪くなかった」","f":"noa"},{"t":"n","s":"乃亜は、少しだけ、顔をそむけた。耳の先が、ほんの少し、赤かった。","f":"noa","m":"blush"}]},{"key":"30-3","title":"帰り道","bg":"bg_riverside","dark":false,"mood":"daily","bgm":"daily2","cast":["ryoma","yuzuki","noa"],"lines":[{"t":"n","s":"墓地の下の河原に、竜馬と柚月が、並んで待っていた。","f":"ryoma"},{"t":"d","s":"「よお」","f":"ryoma"},{"t":"d","s":"「竜馬。柚月も」","f":"ryoma"},{"t":"d","s":"「お墓参りには、遠慮したんです。邪魔になるかと思って」","f":"ryoma"},{"t":"n","s":"柚月は、小さな和菓子の包みを差し出した。","f":"yuzuki"},{"t":"d","s":"「おじいさんに、お供えしてください。後で、一緒に」","f":"yuzuki"},{"t":"d","s":"「ありがとう」","f":"yuzuki"},{"t":"d","s":"「その代わり、お昼は、わたしが選んでもいいですか」","f":"yuzuki"},{"t":"d","s":"「あっ、ずるい」","f":"yuzuki"},{"t":"n","s":"乃亜が、むっとした顔をした。竜馬が、腹を抱えて、笑い出した。","f":"noa"},{"t":"d","s":"「お前ら、毎回それやるな」","f":"noa"},{"t":"d","s":"「やってない」","f":"noa"},{"t":"d","s":"「やってません」","f":"noa"},{"t":"d","s":"「やってるって」","f":"noa"},{"t":"n","s":"四人は、並んで、河原の道を歩いた。","f":"noa"},{"t":"n","s":"初夏の風が、頬を撫でていく。耀平は、さっきの紫の花のことを、まだ考えていた。","f":"yohei"},{"t":"i","s":"（誰が、供えたんだろう）","f":"yohei"},{"t":"n","s":"分からない。けれど、悪い感じはしなかった。ただ、胸の奥の、小さな引っかかりだけが、いつまでも、消えなかった。","f":"yohei"},{"t":"n","s":"川面が、きらきらと光っていた。合宿まで、あと、一週間だった。","f":"yohei"}]}]},{"n":31,"title":"おじいちゃんの工房","sub":"高校・2年6月","era":"high2","lead":"合宿の前の日。耀平は、莉花に、「どうしてペアになろうとしたの」と聞く。返ってきたのは、中学の冬の、小さな記憶だった。","scenes":[{"key":"31-1","title":"明日の準備","bg":"bg_schoolyard_middle","dark":false,"mood":"daily","bgm":"daily2","cast":["rika","yohei"],"lines":[{"t":"n","s":"合宿の前日。放課後の校庭は、荷物を抱えた生徒たちで、ごった返していた。"},{"t":"d","s":"「船の荷物は、これで全部か」"},{"t":"d","s":"「ええと、寝袋と、水筒と、救急セット……」"},{"t":"n","s":"耀平は、リストを見ながら、ぼんやりしていた。その横で、莉花が、ぴょんぴょんと跳ねて、荷物を数えている。","f":"yohei"},{"t":"d","s":"「せんぱい、これも持っていきます？」","f":"yohei"},{"t":"d","s":"「それは、何」","f":"yohei"},{"t":"d","s":"「お菓子です❤︎」","f":"yohei"},{"t":"d","s":"「持ってく」","f":"yohei"},{"t":"d","s":"「やった！」","f":"yohei"},{"t":"n","s":"莉花は、嬉しそうに、お菓子の袋をリュックに詰めた。耀平は、その様子を、横目で眺めていた。","f":"rika"},{"t":"n","s":"ふと、前から、聞いてみたいと思っていたことが、口をついて出た。","f":"rika"},{"t":"d","s":"「ねえ、莉花」","f":"rika"},{"t":"d","s":"「はい？」","f":"rika"},{"t":"d","s":"「どうして、おれを、選んだの」","f":"rika"},{"t":"d","s":"「ペアの、ですか？」","f":"rika"},{"t":"d","s":"「うん。他にも、申し込んだ人はいたって聞いた。莉花ほど強いなら、もっと、別の相手も選べたはずだ」","f":"rika"},{"t":"n","s":"莉花の手が、ぴたりと止まった。","f":"rika"},{"t":"n","s":"それから、ゆっくりと、耀平の方を向いた。いつもの甘い笑顔が、少しだけ、消えていた。","f":"yohei"},{"t":"d","s":"「……聞いてくれるんですね」","f":"yohei"},{"t":"d","s":"「うん。気になったから」","f":"yohei"},{"t":"d","s":"「ふふ。せんぱい、鈍いのに、たまに、鋭いんですから」","f":"yohei"},{"t":"n","s":"莉花は、荷物の山に腰を下ろした。耀平も、その隣に座った。","f":"rika"},{"t":"n","s":"夕日が、校庭を、橙に染めていた。","f":"rika"},{"t":"d","s":"「わたし、せんぱいに、会ったことがあるんです」","f":"rika"},{"t":"d","s":"「え」","f":"rika"},{"t":"d","s":"「中学一年の、冬でした」","f":"rika"}]},{"key":"31-2","title":"冬の工房","bg":"bg_schoolyard_middle","dark":false,"mood":"soft","bgm":"soft3","cast":["rika","yohei"],"lines":[{"t":"d","s":"「その日は、すごく寒くて。わたしは、おじいちゃんの工房の、奥の部屋にいたんです」"},{"t":"n","s":"莉花の声は、静かだった。","f":"rika"},{"t":"d","s":"「おじいちゃんは、街外れで、刀を打っていました。わたしは、両親が小さい頃に亡くなったので、おじいちゃんと、二人暮らしでした。工房の奥が、わたしの部屋で」","f":"rika"},{"t":"d","s":"「……莉花も」","f":"rika"},{"t":"d","s":"「はい。せんぱいと、同じです」","f":"rika"},{"t":"n","s":"耀平の胸が、小さく、鳴った。","f":"yohei"},{"t":"d","s":"「その日、工房に、お客さんが来たんです。学校の先生に紹介されたって。中学生の男の子と、女の子が、二人で」","f":"yohei"},{"t":"n","s":"耀平は、はっとした。","f":"yohei"},{"t":"i","s":"（……あの時の）","f":"yohei"},{"t":"d","s":"「男の子は、一本ずつ、刀を握っていきました。ゆっくり、慎重に。わたし、奥の障子の隙間から、ずっと、見てたんです」","f":"yohei"},{"t":"d","s":"「……見られてたのか」","f":"yohei"},{"t":"d","s":"「はい。だって、そんなふうに刀を握る人、初めて見たんですもの」","f":"yohei"},{"t":"n","s":"莉花は、小さく笑った。","f":"rika","m":"happy"},{"t":"d","s":"「それで、黒い鞘の、地味な刀を、握った時です。窓の隙間から、桜の花びらが、ひらりと、入ってきて」","f":"rika"},{"t":"d","s":"「うん」","f":"rika"},{"t":"d","s":"「男の子は、その花びらを、ふわっと、見上げたんです。すごく、優しい顔で。わたし、息ができなくなりました」","f":"rika"},{"t":"n","s":"莉花は、自分の胸に、手を当てた。","f":"rika"},{"t":"d","s":"「おじいちゃんは、その後、言ったんです。『あの子は、いい剣士になる』って」","f":"rika"},{"t":"d","s":"「……」","f":"rika"},{"t":"d","s":"「そして、わたしが、聞いたんです。『ねえ、おじいちゃん、今の子は？』」","f":"rika"},{"t":"n","s":"その言葉を口にした時、莉花の声は、とても、小さかった。","f":"rika"},{"t":"d","s":"「おじいちゃんは、笑って、答えませんでした。ただ、頭を撫でてくれました」","f":"rika"},{"t":"d","s":"「……それから」","f":"rika"},{"t":"d","s":"「それから、ずっと、せんぱいのことが、頭から離れなかったんです」","f":"rika"},{"t":"n","s":"莉花は、耀平を見て、にっこりと笑った。いつもの笑顔だった。それなのに、どこか、涙の気配があった。","f":"rika","m":"sad"},{"t":"cg","v":"cg_rika_smile"},{"t":"d","s":"「だから、一目惚れです。せんぱいに、ずっと、会いたかったんです」","f":"rika"},{"t":"n","s":"耀平は、言葉を失った。","f":"yohei"},{"t":"d","s":"「……おれ、全然、覚えてなかった」","f":"yohei"},{"t":"d","s":"「当たり前ですよ。わたしは、奥の障子の向こうにいたんですから」","f":"yohei"},{"t":"d","s":"「でも、あの工房の、おじいさんは……」","f":"yohei"},{"t":"d","s":"「あっ」","f":"yohei"},{"t":"n","s":"莉花が、急に、耀平の言葉をさえぎるように、立ち上がった。","f":"rika"},{"t":"d","s":"「すみません、せんぱい。この話は、またにしましょう。明日から、合宿ですから！」","f":"rika"},{"t":"d","s":"「あ、うん」","f":"rika"},{"t":"d","s":"「お菓子、もっと買ってきますね！」","f":"rika"},{"t":"n","s":"莉花は、駆け足で、校庭を走っていった。その背中が、夕日の中で、いつもより、ずっと小さく見えた。","f":"rika"},{"t":"n","s":"耀平は、その場に座ったまま、遠ざかる後ろ姿を、じっと見つめた。","f":"yohei"},{"t":"i","s":"（あのおじいさんは、今、どうしているんだろう）","f":"yohei"},{"t":"n","s":"聞こうとして、言葉が出なかった理由を、耀平は、まだ、知らなかった。","f":"yohei"}]},{"key":"31-3","title":"最後の夜","bg":"bg_dorm","dark":true,"mood":"night","bgm":"night2","cast":["yohei"],"lines":[{"t":"n","s":"その夜。寮の部屋で、耀平は、荷造りを終えた鞄を、じっと見つめていた。","f":"yohei"},{"t":"n","s":"箪笥の中の、祖父の手紙。それを、ほんの一瞬、手に取った。","f":"yohei"},{"t":"i","s":"（……持っていこう）","f":"yohei"},{"t":"n","s":"どうして、そう思ったのか、自分でも分からなかった。","f":"yohei"},{"t":"n","s":"けれど、そっと、鞄の底に、しまった。","f":"yohei"},{"t":"n","s":"窓の外の桜は、緑の若葉を、夜風に揺らしていた。","f":"yohei"},{"t":"n","s":"明日、船が出る。","f":"yohei"}]}]},{"n":32,"title":"船出と、甲板の夜","sub":"高校・2年6月","era":"high2","lead":"ペアが出そろい、合宿のルールが告げられる。夜の甲板で、乃亜は耀平の夢の話を聞く。","scenes":[{"key":"32-1","title":"出港の朝","bg":"bg_ship","dark":false,"mood":"daily","bgm":"daily3","cast":["noa","todo","yuzuki"],"lines":[{"t":"n","s":"六月の第一週。港には、白い大きな船が、ゆったりと横づけされていた。"},{"t":"d","s":"「でっか……」"},{"t":"d","s":"「ホテルみたいだな」"},{"t":"n","s":"陽太と竜馬が、口をぽかんと開けて見上げている。船体の横には、学園の紋章と、SHITの銀の紋章が並んで描かれていた。","f":"ryoma"},{"t":"n","s":"甲板の上では、藤堂が、名簿を手に生徒たちを数えていた。","f":"todo"},{"t":"d","s":"「ペアは、点呼のときに確認する。ペア以外の組み合わせは、認めない」","f":"todo"},{"t":"n","s":"整列した生徒たちの中で、ペアが次々と読み上げられていく。","f":"todo"},{"t":"d","s":"「乃亜、一年・朝比奈つばさ」","f":"todo"},{"t":"d","s":"「はい。よろしくお願いします」","f":"todo"},{"t":"n","s":"乃亜の隣で、小柄な一年生が、ぺこりと頭を下げた。乃亜は、先輩らしく、ぎこちなく微笑んだ。","f":"noa","m":"happy"},{"t":"d","s":"「朝霧柚月、一年・白雪夢」","f":"noa"},{"t":"d","s":"「……はぁい。よろしく、お願いします……すぅ」","f":"noa"},{"t":"d","s":"「……寝ないでくださいね」と、柚月がくすりと笑った。","f":"noa"},{"t":"d","s":"「竜馬、新入生・神崎隼」","f":"noa"},{"t":"d","s":"「…………」","f":"noa"},{"t":"d","s":"「…………」","f":"noa"},{"t":"n","s":"呼ばれた二人は、互いに、そっぽを向いていた。","f":"noa"},{"t":"d","s":"「返事は」","f":"noa"},{"t":"d","s":"「「…………はい」」","f":"noa"},{"t":"d","s":"「よろしい」","f":"noa"},{"t":"n","s":"藤堂は、淡々と続けた。","f":"todo"},{"t":"d","s":"「耀平、一年・莉花」","f":"todo"},{"t":"d","s":"「はーい❤︎　せんぱいのペアでーす！」","f":"todo"},{"t":"n","s":"莉花が、耀平の腕に、ぎゅっとしがみついた。乃亜と柚月の視線が、同時に、刺さった。","f":"rika"},{"t":"d","s":"「……莉花。離れて」","f":"rika"},{"t":"d","s":"「えー、いやです」","f":"rika"},{"t":"d","s":"「歩きにくい」","f":"rika"},{"t":"d","s":"「歩かなくていいですよ。わたしが、運びますから！」","f":"rika"},{"t":"d","s":"「運べないだろ」","f":"rika"},{"t":"n","s":"藤堂が、咳払いをした。","f":"todo"},{"t":"d","s":"「イチャつくのは、船に乗ってからにしろ」","f":"todo"},{"t":"d","s":"「してません」","f":"todo"},{"t":"d","s":"「してません！」","f":"todo"},{"t":"n","s":"乃亜と柚月の声が、重なった。","f":"noa"}]},{"key":"32-2","title":"四つのルール","bg":"bg_ship","dark":false,"mood":"daily","bgm":"daily4","cast":["rika","todo","yohei"],"lines":[{"t":"n","s":"出港して間もない船内の大広間で、藤堂が、ルールを説明した。","f":"todo"},{"t":"d","s":"「合宿は、一週間。前半の三日間は、航海と、交流。後半の二日間は、島に上陸して、サバイバル。残りの二日は、移動と予備だ」","f":"todo"},{"t":"n","s":"壇上の画面に、箇条書きが映る。","f":"todo"},{"t":"d","s":"「一つ。サバイバルは、ペアで行動する。単独行動は、失格。二つ。島では、他校の生徒と、模擬戦闘を行う。ただし、命に関わる攻撃は、禁止する」","f":"todo"},{"t":"d","s":"「三つ。生存すれば、ポイントはゼロ。勝てば、プラス百。負ければ、マイナス百」","f":"todo"},{"t":"d","s":"「四つ。危険を感じたら、すぐに救難信号を出せ。SHITの隊員が、駆けつける」","f":"todo"},{"t":"n","s":"説明が終わると、生徒たちが、わっと盛り上がった。","f":"todo"},{"t":"d","s":"「勝てばプラス百か。燃えるな」","f":"todo"},{"t":"d","s":"「負けたらマイナスって、きついよ」","f":"todo"},{"t":"d","s":"「生き残るだけなら、ゼロなんだな」","f":"todo"},{"t":"n","s":"耀平は、画面を眺めていた。","f":"yohei"},{"t":"i","s":"（生き残るだけで、いい）","f":"yohei"},{"t":"n","s":"隣で、莉花が、小さく囁いた。","f":"rika"},{"t":"d","s":"「せんぱいは、勝つほうがいいですか」","f":"rika"},{"t":"d","s":"「いや。生き残れれば、それでいい」","f":"rika"},{"t":"d","s":"「ふふ。せんぱいらしいです」","f":"rika"},{"t":"n","s":"莉花の声は、いつもの甘さだった。ただ、その目は、画面の「島」という文字に、じっと向けられていた。","f":"rika"}]},{"key":"32-3","title":"夜の甲板","bg":"bg_ship","dark":true,"mood":"night","bgm":"night1","cast":["yohei","noa"],"lines":[{"t":"n","s":"その夜。耀平は、一人で、甲板に出た。","f":"yohei"},{"t":"n","s":"海風が、冷たかった。空には、満天の星。遠くで、船の灯りが、波に砕けて光っている。","f":"yohei","fx":"shake"},{"t":"d","s":"「……耀平」","f":"yohei"},{"t":"n","s":"振り返ると、乃亜が、手すりのところに立っていた。","f":"noa"},{"t":"d","s":"「眠れない？」","f":"noa"},{"t":"d","s":"「うん。ちょっと、船に酔ったかも」","f":"noa"},{"t":"d","s":"「嘘。揺れてないよ、全然」","f":"noa"},{"t":"d","s":"「バレた」","f":"noa"},{"t":"n","s":"乃亜は、くすっと笑って、耀平の隣に並んだ。","f":"noa"},{"t":"n","s":"しばらく、二人は黙って、波を眺めていた。","f":"noa"},{"t":"d","s":"「ねえ、耀平」","f":"noa"},{"t":"d","s":"「ん」","f":"noa"},{"t":"d","s":"「最近、夢、見る？」","f":"noa"},{"t":"d","s":"「……見る」","f":"noa"},{"t":"d","s":"「どんな」","f":"noa"},{"t":"d","s":"「じいちゃんが、縁側に座ってる夢」","f":"noa"},{"t":"n","s":"乃亜は、静かに耳を傾けた。","f":"noa"},{"t":"d","s":"「何も言わない日もある。ただ、笑ってる。でも、昨日の夢は、違った」","f":"noa"},{"t":"d","s":"「どう違ったの」","f":"noa"},{"t":"d","s":"「じいちゃんが、おれの顔を見て、言ったんだ。『まだ、探しているのか』って」","f":"noa"},{"t":"d","s":"「探してる？　何を」","f":"noa"},{"t":"d","s":"「分からない」","f":"noa"},{"t":"n","s":"耀平は、手すりを握りしめた。","f":"yohei"},{"t":"d","s":"「目が覚めたら、泣いてた。理由は、分からないけど」","f":"yohei"},{"t":"d","s":"「……」","f":"yohei"},{"t":"d","s":"「変だよな」","f":"yohei"},{"t":"d","s":"「変じゃないよ」","f":"yohei"},{"t":"d","s":"「……でも、話せてよかった。じいちゃんの夢のこと、誰かに」","f":"yohei"},{"t":"d","s":"「うん。忘れなくていいよ。無理に、忘れなくて」","f":"yohei"},{"t":"n","s":"乃亜は、そっと、耀平の肩に、自分の肩を寄せた。","f":"noa"},{"t":"d","s":"「耀平がそう感じるなら、きっと、意味があるんだと思う」","f":"noa"},{"t":"d","s":"「そう、かな」","f":"noa"},{"t":"d","s":"「うん。わたしは、そう思う」","f":"noa"},{"t":"n","s":"波の音が、二人の間に落ちた。","f":"noa"},{"t":"n","s":"遠い水平線の向こうに、まだ見えない島があった。そこで何が待っているのか、二人は、まだ知らなかった。","f":"noa"},{"t":"d","s":"「ねえ、耀平」","f":"noa"},{"t":"d","s":"「ん」","f":"noa"},{"t":"d","s":"「何があっても、わたしは、隣にいるから」","f":"noa"},{"t":"d","s":"「……うん。ありがとう」","f":"noa"},{"t":"n","s":"乃亜は、少しだけ、頬を赤くして、笑った。","f":"noa","m":"happy"}]}]},{"n":33,"title":"ホテルみたいな船と、交流会","sub":"高校・2年6月","era":"high2","lead":"航海の最初の二日。船内の生活は、思った以上に、のどかだった。","scenes":[{"key":"33-1","title":"朝食バイキング","bg":"bg_ship","dark":false,"mood":"daily","bgm":"daily4","cast":["noa","yohei","rika"],"lines":[{"t":"d","s":"「うわあ、すごい！」"},{"t":"n","s":"大食堂に足を踏み入れた陽太が、目を輝かせた。長いテーブルに、パン、スープ、サラダ、フルーツ。どれも、見たことがないほど、きれいに並んでいる。"},{"t":"d","s":"「合宿とは思えない……」"},{"t":"d","s":"「SHITの予算だとさ。去年の件で、国から追加が出たらしい」"},{"t":"d","s":"「へえ」"},{"t":"n","s":"耀平は、トレーを持って、行列に並んだ。後ろから、小さな足音がぱたぱたと近づいてくる。","f":"yohei"},{"t":"d","s":"「せんぱーい！　一緒に食べましょう！」","f":"yohei"},{"t":"d","s":"「莉花。もう、決めてあるのか」","f":"yohei"},{"t":"d","s":"「窓際の席、確保しました！」","f":"yohei"},{"t":"n","s":"莉花は、得意げに、窓際の二人席を指差した。そこには、すでに、紙のナプキンが二つ、きちんと置かれていた。","f":"rika"},{"t":"d","s":"「……いつの間に」","f":"rika"},{"t":"d","s":"「早起きは、得意なんです❤︎」","f":"rika"},{"t":"n","s":"耀平は、苦笑して、席に着いた。窓の外には、青い海が広がっていた。","f":"yohei","m":"sweat"},{"t":"d","s":"「せんぱい、あーん」","f":"yohei"},{"t":"d","s":"「自分で食べられる」","f":"yohei"},{"t":"d","s":"「あーん」","f":"yohei"},{"t":"d","s":"「やめろって」","f":"yohei"},{"t":"d","s":"「ひどいです〜」","f":"yohei"},{"t":"n","s":"その様子を、少し離れた席から、乃亜と柚月が、じっと眺めていた。","f":"noa"},{"t":"d","s":"「…………」","f":"noa"},{"t":"d","s":"「…………」","f":"noa"},{"t":"d","s":"「乃亜先輩、パンが、さっきから、ちぎれてます」","f":"noa"},{"t":"d","s":"「え？　あ、ごめん」","f":"noa"},{"t":"n","s":"乃亜は、握りしめていたパンを、そっと皿に戻した。","f":"noa"}]},{"key":"33-2","title":"他校との会合","bg":"bg_ship","dark":false,"mood":"daily","bgm":"daily5","cast":["yohei","noa","tsukumo"],"lines":[{"t":"n","s":"午後。船の大広間で、他校の代表との会合が開かれた。"},{"t":"n","s":"壇上に並んだのは、二つの学校の代表だった。白鷺女学園と、蒼嵐学院。どちらも、学園連盟の新しい枠組みに名を連ねた学校だ。"},{"t":"n","s":"最初に口を開いたのは、白鷺女学園の代表だった。背筋の伸びた、物腰の柔らかな女子生徒。"},{"t":"d","s":"「白鷺女学園、二年の一条雪乃と申します。本日は、お招きいただき、ありがとうございます」"},{"t":"n","s":"雪乃が頭を下げると、肩口で、氷の花びらがひとひら、きらりと舞って消えた。"},{"t":"d","s":"「私たちは、学園連盟の新たな枠組みに、期待しています。互いの技を、ここで磨き合いましょう」"},{"t":"n","s":"拍手が起こった。その隣で、豪奢な金の髪を巻いた女子生徒が、つんと顎を上げた。"},{"t":"d","s":"「同じく、鳳麗華ですわ。……ま、せいぜい、足を引っ張らないでくださいましね」"},{"t":"n","s":"乃亜の眉が、ぴくりと動いた。","f":"noa"},{"t":"n","s":"続いて、蒼嵐学院の代表が、にやりと笑って前に出た。短く刈った髪の、鋭い目つきの男子生徒だった。","f":"noa"},{"t":"d","s":"「蒼嵐学院、嵐堂刃。うちは、遠慮しないぜ。去年は、あんたらの学園、えらいことになったそうだが、強さは、本物なのか？」","f":"noa"},{"t":"n","s":"会場が、ざわついた。隣にいた小柄な女子生徒が、慌てて、刃の袖を引いた。","f":"noa"},{"t":"d","s":"「お兄ちゃん、失礼でしょ！　……妹の、嵐堂灯里です。すみません、兄が」","f":"noa"},{"t":"n","s":"藤堂が、一歩前に出ようとするのを、九十九が、静かに手で制した。","f":"todo"},{"t":"d","s":"「ご心配なく。ご自身の目で、確かめていただければ」","f":"todo"},{"t":"n","s":"九十九は、穏やかな笑みを浮かべていた。それなのに、刃は、一瞬、言葉に詰まった。","f":"tsukumo"},{"t":"d","s":"「……ああ。楽しみにしてるよ。特に、夜桜の剣士とやらをな」","f":"tsukumo"},{"t":"n","s":"刃の視線が、まっすぐ、耀平を射抜いた。耀平は、目をそらさずに、小さく会釈だけを返した。","f":"yohei"},{"t":"n","s":"会合が終わると、生徒たちが、思い思いに交流を始めた。他校の生徒に、竜馬が声をかけられている。","f":"ryoma"},{"t":"d","s":"「お前、あの炎の人だろ。去年の襲撃のとき、前に出てた」","f":"ryoma"},{"t":"d","s":"「ああ。そうだが」","f":"ryoma"},{"t":"d","s":"「握手してくれ！」","f":"ryoma"},{"t":"d","s":"「は？」","f":"ryoma"},{"t":"n","s":"その横で、隼が、むすっと腕を組んでいた。","f":"ryoma"},{"t":"d","s":"「……先輩、意外と、人気あるんですね」","f":"ryoma"},{"t":"d","s":"「意外とは何だ」","f":"ryoma"},{"t":"n","s":"柚月のそばには、雪乃が来ていた。二人は、すぐに、お茶の話で盛り上がっている。","f":"yuzuki"},{"t":"d","s":"「朝霧さんは、どちらのお茶を？」","f":"yuzuki"},{"t":"d","s":"「宇治のものを、少しだけ。一条さんは」","f":"yuzuki"},{"t":"d","s":"「まあ、わたしもですわ」","f":"yuzuki"},{"t":"n","s":"乃亜の前には、麗華が仁王立ちしていた。","f":"noa"},{"t":"d","s":"「あなたが、水の規格外ですの？　ふうん。思ったより、地味ですわね」","f":"noa"},{"t":"d","s":"「……あなたこそ、思ったより、声が大きい」","f":"noa"},{"t":"d","s":"「なっ」","f":"noa"},{"t":"n","s":"二人の間に、火花と水しぶきが、見えた気がした。","f":"noa"},{"t":"n","s":"耀平は、遠くからその様子を見ていた。隣にいた陽太が、肘で小突いた。","f":"yohei"},{"t":"d","s":"「お前も、人気あるぞ」","f":"yohei"},{"t":"d","s":"「おれ？」","f":"yohei"},{"t":"d","s":"「あの、白鷺の子たち、さっきからこっち見てる」","f":"yohei"},{"t":"n","s":"見ると、確かに、数人の女子生徒が、ひそひそと耀平のほうを指差している。","f":"yohei"},{"t":"d","s":"「夜桜の人だ」","f":"yohei"},{"t":"d","s":"「去年の、あの」","f":"yohei"},{"t":"d","s":"「かっこいい……」","f":"yohei"},{"t":"n","s":"耀平は、思わず目をそらした。","f":"yohei"},{"t":"d","s":"「……何か、恥ずかしい」","f":"yohei"},{"t":"d","s":"「あ、柚月さんと乃亜さんが、見てる」","f":"yohei"},{"t":"d","s":"「見てない見てない」","f":"yohei"}]},{"key":"33-3","title":"ピアノの夕べ","bg":"bg_ship","dark":false,"mood":"soft","bgm":"soft4","cast":["rika","noa","yohei"],"lines":[{"t":"n","s":"その夜。船のラウンジで、小さな演奏会が開かれた。"},{"t":"n","s":"ラウンジの片隅には、黒いグランドピアノが置かれていた。誰かが弾く気配はなかったが、ふと、一人の少女が、椅子に腰を下ろした。"},{"t":"n","s":"莉花だった。","f":"rika"},{"t":"d","s":"「ちょっとだけ、弾いてもいいですか」","f":"rika"},{"t":"d","s":"「え、莉花が？」","f":"rika"},{"t":"d","s":"「はい。おじいちゃんが、教えてくれたんです」","f":"rika"},{"t":"n","s":"莉花は、指を鍵盤に置いた。","f":"rika"},{"t":"n","s":"最初の音が、ラウンジに響いた。","f":"rika"},{"t":"n","s":"やわらかくて、少し寂しい、ゆっくりした曲だった。聞いたことがあるようで、ない。ざわざわしていた生徒たちが、一人、また一人と、黙っていった。","f":"rika"},{"t":"n","s":"耀平は、グラスを持ったまま、立ち尽くしていた。","f":"yohei"},{"t":"i","s":"（……きれいだ）","f":"yohei"},{"t":"n","s":"莉花の横顔は、普段の甘い笑顔とは、まるで違っていた。目を閉じて、鍵盤に身を預けている。長い睫毛が、ランプの光に濡れていた。","f":"rika"},{"t":"n","s":"曲が終わると、短い静寂のあとに、拍手が起こった。","f":"rika"},{"t":"d","s":"「すごい」","f":"rika"},{"t":"d","s":"「どこで習ったの」","f":"rika"},{"t":"d","s":"「ただの、趣味ですよー」","f":"rika"},{"t":"n","s":"莉花は、いつもの笑顔に戻って、頭をかいた。","f":"rika"},{"t":"n","s":"その後ろで、乃亜がぽつりと呟いた。","f":"noa"},{"t":"d","s":"「……あの子、ほんとに、何者なんだろう」","f":"noa"},{"t":"d","s":"「乃亜先輩？」","f":"noa"},{"t":"d","s":"「ううん。何でもない」","f":"noa"},{"t":"n","s":"柚月が、静かに首を傾げた。ラウンジの窓の外では、星が、一つ、流れた。","f":"yuzuki"}]}]},{"n":34,"title":"船の上の鍛錬と、莉花の距離","sub":"高校・2年6月","era":"high2","lead":"三日間の航海。耀平は、毎朝、莉花に連れ出されて、甲板で剣を交える。","scenes":[{"key":"34-1","title":"朝の甲板","bg":"bg_ship","dark":false,"mood":"daily","bgm":"daily5","cast":["rika","yohei"],"lines":[{"t":"d","s":"「せんぱい、朝ですよー！」"},{"t":"n","s":"ばん、と部屋の扉が開いた。耀平は、布団の中で、うなった。","f":"yohei"},{"t":"d","s":"「……まだ五時」","f":"yohei"},{"t":"d","s":"「五時です！　鍛錬の時間です！」","f":"yohei"},{"t":"d","s":"「船の上、でも？」","f":"yohei"},{"t":"d","s":"「船の上だから、いいんです！」","f":"yohei"},{"t":"n","s":"莉花に引きずられて、甲板に出ると、朝焼けが、海を金色に染めていた。","f":"rika"},{"t":"d","s":"「うわ……」","f":"rika"},{"t":"d","s":"「きれいでしょう？」","f":"rika"},{"t":"d","s":"「うん」","f":"rika"},{"t":"n","s":"莉花は、木刀を二本、持ってきていた。一本を耀平に放る。","f":"rika"},{"t":"d","s":"「さあ、行きますよ」","f":"rika"},{"t":"n","s":"甲板の上で、二人は、木刀を交わした。揺れる床の上でも、莉花の足取りは、少しも乱れない。","f":"rika"},{"t":"d","s":"「船の上、慣れてるな」","f":"rika"},{"t":"d","s":"「おじいちゃんの工房に、小さな舟があったんです。よく乗せてもらいました」","f":"rika"},{"t":"d","s":"「そうか」","f":"rika"},{"t":"d","s":"「はい」","f":"rika"},{"t":"n","s":"莉花は、一歩、踏み込んだ。木刀が、耀平の脇腹をかすめる。","f":"rika"},{"t":"d","s":"「ほら、また半拍、遅いです」","f":"rika"},{"t":"d","s":"「理央にも言われた」","f":"rika"},{"t":"d","s":"「誰ですか、その子」","f":"rika"},{"t":"d","s":"「SHITの、小さい子」","f":"rika"},{"t":"d","s":"「あ、柏木理央ちゃん。……あの子、頭いいですよね」","f":"rika"},{"t":"n","s":"莉花の声が、ほんの少しだけ、固くなった。耀平は、気づかなかった。","f":"rika"}]},{"key":"34-2","title":"近すぎる距離","bg":"bg_ship","dark":false,"mood":"daily","bgm":"daily1","cast":["rika","yohei","yuzuki"],"lines":[{"t":"n","s":"鍛錬のあと。二人は、甲板のベンチで、並んで水を飲んでいた。"},{"t":"d","s":"「せんぱい、汗」"},{"t":"d","s":"「大丈夫」"},{"t":"d","s":"「だめです、拭かなきゃ」"},{"t":"n","s":"莉花は、ポケットからハンカチを出して、耀平の額に、ぽんぽんと当てた。距離が、近い。花のような匂いがした。","f":"rika"},{"t":"d","s":"「ちょ、莉花」","f":"rika"},{"t":"d","s":"「動かないでください」","f":"rika"},{"t":"d","s":"「近い」","f":"rika"},{"t":"d","s":"「近くないと、拭けません」","f":"rika"},{"t":"d","s":"「…………」","f":"rika"},{"t":"n","s":"耀平は、固まった。莉花の指先が、頬に触れた。","f":"yohei"},{"t":"d","s":"「ふふ」","f":"yohei"},{"t":"d","s":"「何」","f":"yohei"},{"t":"d","s":"「せんぱい、耳、真っ赤です」","f":"yohei"},{"t":"n","s":"莉花は、いたずらっぽく笑って、ハンカチを引っ込めた。","f":"rika"},{"t":"d","s":"「……からかうな」","f":"rika"},{"t":"d","s":"「からかってませんよ。本当に、かわいいなって思ったんです」","f":"rika"},{"t":"n","s":"耀平は、ふいっと顔をそむけた。心臓が、いつもより早く打っていた。","f":"yohei"},{"t":"n","s":"そのとき、背後から、ごほん、と咳払いが聞こえた。","f":"yohei"},{"t":"d","s":"「朝から、何をしているんですか」","f":"yohei"},{"t":"n","s":"柚月だった。後ろには、乃亜もいる。二人とも、笑顔が、少しだけ、硬い。","f":"yuzuki"},{"t":"d","s":"「鍛錬だよ」","f":"yuzuki"},{"t":"d","s":"「ハンカチで、ですか」","f":"yuzuki"},{"t":"d","s":"「莉花が、拭いてくれて」","f":"yuzuki"},{"t":"d","s":"「そうですか。では、わたしたちも、お手伝いしましょう」","f":"yuzuki"},{"t":"d","s":"「お手伝い？」","f":"yuzuki"},{"t":"d","s":"「汗、わたしも、拭いてあげます」","f":"yuzuki"},{"t":"d","s":"「わたしも」","f":"yuzuki"},{"t":"n","s":"乃亜と柚月が、同時にハンカチを取り出した。","f":"noa"},{"t":"d","s":"「いや、もう、拭いたから！」","f":"noa"},{"t":"d","s":"「遠慮しないで」","f":"noa"},{"t":"d","s":"「遠慮してないって！」","f":"noa"},{"t":"n","s":"莉花が、横で、口を押さえて笑っていた。","f":"rika"}]},{"key":"34-3","title":"三日目の夕暮れ","bg":"bg_ship","dark":false,"mood":"daily","bgm":"daily2","cast":["rika","yohei"],"lines":[{"t":"n","s":"三日目の夕方。船は、島の沖合に近づいていた。"},{"t":"n","s":"甲板の手すりに、莉花が一人で立っていた。海風が、髪を揺らしている。","f":"rika"},{"t":"d","s":"「……莉花」","f":"rika"},{"t":"d","s":"「あ、せんぱい」","f":"rika"},{"t":"d","s":"「何を見てるの」","f":"rika"},{"t":"d","s":"「島です」","f":"rika"},{"t":"n","s":"遠くに、緑の島影が、見え始めていた。","f":"rika"},{"t":"d","s":"「きれいな島ですね」","f":"rika"},{"t":"d","s":"「うん」","f":"rika"},{"t":"d","s":"「あそこで、もうすぐ、始まるんですね」","f":"rika"},{"t":"d","s":"「サバイバル？」","f":"rika"},{"t":"d","s":"「はい。いろんなことが」","f":"rika"},{"t":"n","s":"莉花は、島を見つめたまま、囁いた。","f":"rika"},{"t":"d","s":"「せんぱい」","f":"rika"},{"t":"d","s":"「ん」","f":"rika"},{"t":"d","s":"「もし、わたしが、せんぱいに、嘘をついていたら」","f":"rika"},{"t":"d","s":"「うん」","f":"rika"},{"t":"d","s":"「怒りますか」","f":"rika"},{"t":"n","s":"耀平は、少し考えた。それから、答えた。","f":"yohei"},{"t":"d","s":"「理由によると思う」","f":"yohei"},{"t":"d","s":"「理由」","f":"yohei"},{"t":"d","s":"「でも、莉花が、意味もなく嘘をつく人だとは、思ってない」","f":"yohei"},{"t":"n","s":"莉花は、振り返った。","f":"rika"},{"t":"n","s":"目が、ほんの少し、潤んでいた。","f":"rika"},{"t":"d","s":"「……ありがとうございます」","f":"rika"},{"t":"d","s":"「え、何で」","f":"rika"},{"t":"d","s":"「いえ。何でもないです」","f":"rika"},{"t":"n","s":"莉花は、にっこり笑って、手すりから離れた。","f":"rika"},{"t":"d","s":"「ごはん、行きましょう！　今日は、お魚ですって！」","f":"rika"},{"t":"n","s":"その背中を見送りながら、耀平は、首をかしげた。","f":"yohei"},{"t":"i","s":"（……嘘？）","f":"yohei"},{"t":"n","s":"聞き返そうとしたとき、莉花の姿は、もう、廊下の角に消えていた。","f":"rika"}]}]},{"n":35,"title":"夜のラウンジと、仲間たち","sub":"高校・2年6月","era":"high2","lead":"出航から三日目の夜。島に着く前の最後の夜を、五人はラウンジで過ごす。","scenes":[{"key":"35-1","title":"トランプ","bg":"bg_ship","dark":false,"mood":"daily","bgm":"daily1","cast":["yohei","noa","yuzuki"],"lines":[{"t":"d","s":"「ババ抜きしようぜ」"},{"t":"d","s":"「なんで、ババ抜き」"},{"t":"d","s":"「合宿っぽいだろ」"},{"t":"n","s":"竜馬が、トランプの箱を、どんとテーブルに置いた。ラウンジの窓際のテーブルに、耀平、乃亜、柚月、竜馬、そして陽太が集まる。","f":"ryoma"},{"t":"d","s":"「莉花は？」","f":"ryoma"},{"t":"d","s":"「隼と、どこか行った」","f":"ryoma"},{"t":"d","s":"「そうなのか」","f":"ryoma"},{"t":"n","s":"カードが配られた。ゲームは、静かに始まった。","f":"ryoma"},{"t":"d","s":"「あ、耀平、顔に出てる」","f":"ryoma"},{"t":"d","s":"「出てない」","f":"ryoma"},{"t":"d","s":"「ババ持ってるでしょ」","f":"ryoma"},{"t":"d","s":"「持ってない」","f":"ryoma"},{"t":"d","s":"「持ってますね」","f":"ryoma"},{"t":"d","s":"「持ってるな」","f":"ryoma"},{"t":"n","s":"三人の声が、揃った。耀平は、カードを握りしめた。","f":"yohei"},{"t":"d","s":"「くそ……」","f":"yohei"},{"t":"n","s":"結局、最初に負けたのは、耀平だった。","f":"yohei"},{"t":"d","s":"「罰ゲームな」","f":"yohei"},{"t":"d","s":"「え、決まってたのか」","f":"yohei"},{"t":"d","s":"「当たり前だろ。負けたやつは、みんなに一個ずつ、秘密を話す」","f":"yohei"},{"t":"d","s":"「聞いてない」","f":"yohei"},{"t":"d","s":"「今決めた」","f":"yohei"},{"t":"n","s":"竜馬が、にやにやと笑った。耀平は、観念して、天井を見上げた。","f":"ryoma","m":"happy"},{"t":"d","s":"「……分かった。一個ずつな」","f":"ryoma"},{"t":"d","s":"「まず、俺から聞くぜ。乃亜のこと、どう思ってる」","f":"ryoma"},{"t":"d","s":"「竜馬！」","f":"ryoma"},{"t":"n","s":"乃亜が、真っ赤になった。柚月が、くすくすと肩を揺らす。","f":"noa"},{"t":"n","s":"耀平は、少し間を置いてから、答えた。","f":"yohei"},{"t":"d","s":"「……大事な人」","f":"yohei"},{"t":"d","s":"「それだけ？」","f":"yohei"},{"t":"d","s":"「それだけ。今は」","f":"yohei"},{"t":"n","s":"乃亜は、うつむいたまま、小さく頷いた。柚月は、微笑んだまま、何も言わなかった。","f":"noa","m":"happy"}]},{"key":"35-2","title":"竜馬の本音","bg":"bg_ship","dark":true,"mood":"night","bgm":"night1","cast":["ryoma","yohei","yuzuki"],"lines":[{"t":"n","s":"トランプが終わった頃。竜馬は、耀平を、ラウンジの外のデッキに誘った。","f":"ryoma"},{"t":"n","s":"夜風が、涼しかった。","f":"ryoma"},{"t":"d","s":"「なあ、耀平」","f":"ryoma"},{"t":"d","s":"「ん」","f":"ryoma"},{"t":"d","s":"「去年の襲撃のとき、おれ、第八席に負けかけたろ」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「あれ、悔しかったんだ」","f":"ryoma"},{"t":"n","s":"竜馬は、手すりに肘をついた。","f":"ryoma"},{"t":"d","s":"「お前は、あのとき、隣にいなかったけど、柚月や乃亜を守るので、必死だった。でも、おれは、自分のことで、精一杯だった」","f":"ryoma"},{"t":"d","s":"「そんなこと」","f":"ryoma"},{"t":"d","s":"「あるんだよ」","f":"ryoma"},{"t":"n","s":"竜馬は、笑った。いつもの豪快な笑いではなかった。","f":"ryoma","m":"happy"},{"t":"d","s":"「だから、あの一年に絡まれたとき、ちょっと嬉しかったんだ」","f":"ryoma"},{"t":"d","s":"「嬉しい？」","f":"ryoma"},{"t":"d","s":"「おれを、目標にしてくれるやつがいるってな。……まあ、口は悪いが」","f":"ryoma"},{"t":"n","s":"耀平は、頬を緩めた。","f":"yohei"},{"t":"d","s":"「竜馬は、いい先輩になるよ」","f":"yohei"},{"t":"d","s":"「やめろよ、照れる」","f":"yohei"},{"t":"d","s":"「本当に」","f":"yohei"},{"t":"d","s":"「お前もだ。耀平」","f":"yohei"},{"t":"n","s":"竜馬は、拳を、耀平の肩に軽くぶつけた。","f":"ryoma"},{"t":"d","s":"「卒業したら、決着だ。忘れるな」","f":"ryoma"},{"t":"d","s":"「忘れないよ」","f":"ryoma"},{"t":"d","s":"「よし」","f":"ryoma"},{"t":"n","s":"二人は、並んで、夜の海を眺めた。","f":"ryoma"},{"t":"d","s":"「なあ」","f":"ryoma"},{"t":"d","s":"「ん」","f":"ryoma"},{"t":"d","s":"「あの莉花ってやつ、大丈夫か」","f":"ryoma"},{"t":"d","s":"「……どういう意味」","f":"ryoma"},{"t":"d","s":"「いや。ただ、なんか、ひっかかるんだよな。可愛い顔して、目が、全然笑ってないときがある」","f":"ryoma"},{"t":"n","s":"耀平は、答えなかった。胸の奥の、小さな引っかかりが、また、疼いた。","f":"yohei"},{"t":"d","s":"「気のせいかもしれねえけどな」","f":"yohei"},{"t":"d","s":"「……うん。気を付けておく」","f":"yohei"},{"t":"n","s":"竜馬は、頷いた。海の向こうに、島の灯りが、ぽつりと見えていた。","f":"ryoma"}]},{"key":"35-3","title":"隼の独り言","bg":"bg_ship","dark":false,"mood":"daily","bgm":"daily3","cast":["rika","ryoma"],"lines":[{"t":"n","s":"同じ頃。船の後部デッキで、隼は、一人で、手すりに寄りかかっていた。"},{"t":"d","s":"「…………」"},{"t":"n","s":"足元に、小さな風が渦を巻いている。そこへ、莉花が、ぴょこんと現れた。","f":"rika"},{"t":"d","s":"「隼くん、見つけた」","f":"rika"},{"t":"d","s":"「……莉花さん」","f":"rika"},{"t":"d","s":"「何、してるの」","f":"rika"},{"t":"d","s":"「別に。風、気持ちいいから」","f":"rika"},{"t":"d","s":"「ふうん」","f":"rika"},{"t":"n","s":"莉花は、隣に並んだ。二人とも、海を見ている。","f":"rika"},{"t":"d","s":"「隼くんは、竜馬先輩のこと、好きなの」","f":"rika"},{"t":"d","s":"「は？　何で」","f":"rika"},{"t":"d","s":"「だって、ペアになってから、ずっと一緒にいるし」","f":"rika"},{"t":"d","s":"「それは、ペアだからです」","f":"rika"},{"t":"d","s":"「ふふ」","f":"rika"},{"t":"n","s":"隼は、むすっとして、顔をそむけた。","f":"rika"},{"t":"d","s":"「……竜馬先輩は、強いから。それだけです」","f":"rika"},{"t":"d","s":"「うん」","f":"rika"},{"t":"d","s":"「それだけです」","f":"rika"},{"t":"d","s":"「うん、分かってる」","f":"rika"},{"t":"n","s":"莉花は、笑った。それから、静かに、囁いた。","f":"rika","m":"happy"},{"t":"d","s":"「いいなあ。普通の、先輩後輩で」","f":"rika"},{"t":"d","s":"「え？」","f":"rika"},{"t":"d","s":"「ううん。何でもないよ」","f":"rika"},{"t":"n","s":"隼は、首を傾げた。その横顔は、夜の闇に溶けるように、どこか遠かった。","f":"rika"}]}]},{"n":36,"title":"技を、みんなで考える","sub":"高校・2年6月","era":"high2","lead":"島に着く前日の昼。耀平は、新しい技のヒントを、みんなに聞いて回る。","scenes":[{"key":"36-1","title":"乃亜の答え","bg":"bg_ship","dark":false,"mood":"daily","bgm":"daily2","cast":["noa","yohei"],"lines":[{"t":"d","s":"「技を、作りたい？」"},{"t":"n","s":"船の食堂の隅で、乃亜が、紅茶のカップを置いた。","f":"noa"},{"t":"d","s":"「うん。夜桜の状態だけじゃ、足りないって言われて」","f":"noa"},{"t":"d","s":"「誰に」","f":"noa"},{"t":"d","s":"「玄蔵さん」","f":"noa"},{"t":"d","s":"「あの、地下のお爺さんね」","f":"noa"},{"t":"n","s":"乃亜は、少し考えてから、ゆっくりと口を開いた。","f":"noa"},{"t":"d","s":"「わたしが、耀平の剣を見て、一番好きなところ、言っていい？」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「優しいところ」","f":"noa"},{"t":"d","s":"「優しい？」","f":"noa"},{"t":"d","s":"「うん。誰かを傷つけるための剣じゃなくて、守るための剣。それが、一番強いと思う」","f":"noa"},{"t":"n","s":"耀平は、頷いた。","f":"yohei"},{"t":"d","s":"「……なら、守るための技、か」","f":"yohei"},{"t":"d","s":"「そう。たとえば、一度に、たくさんの人を、守れるような」","f":"yohei"},{"t":"n","s":"乃亜は、手の中のカップを、ゆっくり回した。","f":"noa"},{"t":"d","s":"「わたしの水も、そういう風に使うつもり。誰かを、守るために」","f":"noa"},{"t":"d","s":"「乃亜の水は、もう十分すごいよ」","f":"noa"},{"t":"d","s":"「ありがとう。……でも、まだ、足りない。去年、あなたを、守れなかったから」","f":"noa"},{"t":"n","s":"乃亜の瞳は、真っ直ぐだった。耀平は、その視線を、受け止めた。","f":"noa"}]},{"key":"36-2","title":"竜馬と柚月","bg":"bg_ship","dark":false,"mood":"soft","bgm":"soft2","cast":["yohei","yuzuki","ryoma"],"lines":[{"t":"n","s":"甲板で、竜馬は、木刀を肩にかけて、腕を組んでいた。","f":"ryoma"},{"t":"d","s":"「技ねえ。そんなの、考えてるうちに、できるもんじゃねえだろ」","f":"ryoma"},{"t":"d","s":"「そうなの」","f":"ryoma"},{"t":"d","s":"「おれはな、殴ってるうちに、勝手にできた」","f":"ryoma"},{"t":"d","s":"「勝手に」","f":"ryoma"},{"t":"d","s":"「そうだ。技ってのは、感覚だ」","f":"ryoma"},{"t":"n","s":"竜馬は、拳を握って、炎を灯した。","f":"ryoma"},{"t":"d","s":"「お前の場合は、花びらを、もっと信じていい」","f":"ryoma"},{"t":"d","s":"「信じる」","f":"ryoma"},{"t":"d","s":"「そうだ。お前は、いつも、花びらを、手加減してるだろ。もっと、出してみろ。百枚でも、千枚でも」","f":"ryoma"},{"t":"d","s":"「増やす……」","f":"ryoma"},{"t":"d","s":"「それとな。お前の花びら、一枚一枚が、ばらばらなんだよ。おれの炎は、ひとつながりだ。だから、でかくなる」","f":"ryoma"},{"t":"n","s":"竜馬は、空を指差した。遠くの雲の中で、ごろごろと、雷が鳴っていた。","f":"ryoma"},{"t":"d","s":"「ああいう感じだ。雷みたいに、花と花を、繋げてみろ」","f":"ryoma"},{"t":"d","s":"「繋げる……」","f":"ryoma"},{"t":"n","s":"耀平は、はっとした。","f":"yohei"},{"t":"i","s":"（……手加減）","f":"yohei"},{"t":"n","s":"玄蔵の言葉が、頭の中で、鳴った。","f":"genzo"},{"t":"d","s":"「それから、柚月にも聞けよ。あいつ、なんだかんだ、一番鋭いぞ」","f":"genzo"},{"t":"n","s":"柚月は、ラウンジの隅で、本を読んでいた。耀平が近づくと、すっと顔を上げた。","f":"yuzuki"},{"t":"d","s":"「耀平さん。お話ですか」","f":"yuzuki"},{"t":"d","s":"「技のことで」","f":"yuzuki"},{"t":"d","s":"「ああ、そのことですね」","f":"yuzuki"},{"t":"n","s":"柚月は、本を閉じた。","f":"yuzuki"},{"t":"d","s":"「わたしは、耀平さんの剣を、何度も見ています。いつも、きれいだなと思います。でも、その美しさは、散るための美しさにも見えるんです」","f":"yuzuki"},{"t":"d","s":"「散る」","f":"yuzuki"},{"t":"d","s":"「はい。花は、散るから、美しい。でも、散らないで、咲いたままの花もあります」","f":"yuzuki"},{"t":"d","s":"「咲いたまま……」","f":"yuzuki"},{"t":"d","s":"「たとえば、夜桜は、月の光を借りて、一晩だけ、咲いているものですよね」","f":"yuzuki"},{"t":"n","s":"耀平は、はっとして、莉花の言葉を思い出した。","f":"yohei"},{"t":"d","s":"『桜って、夜の方が、強いんです』","f":"yohei"},{"t":"d","s":"「……ありがとう、柚月」","f":"yohei"},{"t":"d","s":"「いえ。お役に立てましたか」","f":"yohei"},{"t":"d","s":"「たぶん」","f":"yohei"},{"t":"n","s":"柚月は、静かに微笑んだ。","f":"yuzuki","m":"happy"}]},{"key":"36-3","title":"莉花の問い","bg":"bg_ship","dark":false,"mood":"daily","bgm":"daily4","cast":["rika","yohei"],"lines":[{"t":"n","s":"夕方。デッキの端で、莉花が、一人で空を見上げていた。","f":"rika"},{"t":"d","s":"「莉花」","f":"rika"},{"t":"d","s":"「あ、せんぱい。何か、悩みごとですか」","f":"rika"},{"t":"d","s":"「技のこと、みんなに聞いて回ってて」","f":"rika"},{"t":"d","s":"「ふふ、頑張ってますね」","f":"rika"},{"t":"n","s":"莉花は、手すりに寄りかかった。","f":"rika"},{"t":"d","s":"「それで、答えは出ました？」","f":"rika"},{"t":"d","s":"「まだ。でも、みんなに言われると、見えてくるな」","f":"rika"},{"t":"d","s":"「どんな」","f":"rika"},{"t":"d","s":"「守るための、技。花びらを、手加減しない、技」","f":"rika"},{"t":"n","s":"莉花は、目を細めた。","f":"rika"},{"t":"d","s":"「素敵です」","f":"rika"},{"t":"d","s":"「そう？」","f":"rika"},{"t":"d","s":"「はい。それなら、きっと、すごい技になります」","f":"rika"},{"t":"n","s":"莉花の声が、少し震えた。","f":"rika"},{"t":"d","s":"「せんぱい」","f":"rika"},{"t":"d","s":"「ん」","f":"rika"},{"t":"d","s":"「その技が、できたら、一番最初に、見せてくださいね」","f":"rika"},{"t":"d","s":"「莉花に？」","f":"rika"},{"t":"d","s":"「はい。わたしに」","f":"rika"},{"t":"n","s":"耀平は、頷いた。","f":"yohei"},{"t":"d","s":"「分かった。約束する」","f":"yohei"},{"t":"d","s":"「約束、ですよ」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"n","s":"莉花は、笑った。それは、とても、きれいな笑顔だった。","f":"rika","m":"happy"},{"t":"n","s":"けれど、この約束が、のちに、どんな形で果たされることになるのか、そのときの二人は、まだ、知らなかった。","f":"rika"},{"t":"n","s":"夕日が、海に沈んでいく。船は、静かに、島へと進んでいた。","f":"rika"}]}]},{"n":37,"title":"蛍の約束","sub":"回想・高校・2年5月","era":"high2","lead":"出航前、耀平が思い出す、ひとつの夜の話。ソレイユの報せと、蛍との約束。","scenes":[{"key":"37-1","title":"ソレイユの噂","bg":"bg_shit_base","dark":true,"mood":"tense","bgm":"tense2","cast":["todo","rio","tsukumo"],"lines":[{"t":"n","s":"それは、合宿の少し前、五月の終わりのことだった。"},{"t":"n","s":"SHITの会議室には、遅い時間まで灯りが残っていた。窓の外は、すっかり暗い。長い机の上に、藤堂が、数枚の写真を並べていく。ぱち、ぱち、と紙が机を打つ音だけが、やけに大きく響いた。","f":"todo"},{"t":"d","s":"「ソレイユが、各地で暴れている」","f":"todo"},{"t":"n","s":"写真には、壊れた建物と、崩れた道路が写っていた。どれも、傷の種類が同じだった。刃物で切られたようでいて、同時に、焼け焦げてもいる。","f":"todo"},{"t":"d","s":"「被害は三か所。いずれも深夜。目撃者は、ほとんどいない」","f":"todo"},{"t":"d","s":"「ソレイユ……去年の襲撃の、残党ですか」と、九十九が尋ねた。","f":"todo"},{"t":"d","s":"「そう見ている。だが、規模が違う。去年より、動きが組織的だ」","f":"todo"},{"t":"n","s":"九十九は、写真の一枚を手に取って、しばらく眺めていた。それから、静かに戻した。","f":"tsukumo"},{"t":"d","s":"「学園側は、どこまで警戒すべきでしょうか」","f":"tsukumo"},{"t":"d","s":"「合宿の間は、SHITが運営に回る。参加者の安全は、こちらで担保する」","f":"tsukumo"},{"t":"d","s":"「分かりました。生徒会としても、協力します」","f":"tsukumo"},{"t":"n","s":"理央が、お菓子の袋を抱えたまま、写真をのぞき込んだ。小さな指が、一枚ずつ、写真の縁をなぞっていく。","f":"rio"},{"t":"d","s":"「痕跡、読んだよ。ぜんぶ、同じ人たちの仕業」","f":"rio"},{"t":"d","s":"「何人だ」","f":"rio"},{"t":"d","s":"「うーん、三人。足跡が、道化みたいに変なの。くるくる回ってる」","f":"rio"},{"t":"d","s":"「道化」","f":"rio"},{"t":"d","s":"「うん。楽しそうに、壊してる」","f":"rio"},{"t":"n","s":"その言い方が、妙に、耀平の耳に残った。楽しそうに、壊している。","f":"yohei"},{"t":"n","s":"耀平は、会議の端の席で、写真から目を離せずにいた。","f":"yohei"},{"t":"i","s":"（また、始まるのか）","f":"yohei"},{"t":"n","s":"去年の冬の記憶が、胸の奥で、疼いた。割れた窓。倒れた仲間。冷たい床の感触。やっと取り戻した日常が、またどこかで、音もなく崩れていく気がした。","f":"yohei"},{"t":"d","s":"「耀平くん」","f":"yohei"},{"t":"d","s":"「はい」","f":"yohei"},{"t":"d","s":"「君にも、合宿の間、戦力として動いてもらう。構わないか」","f":"yohei"},{"t":"d","s":"「はい。大丈夫です」","f":"yohei"},{"t":"n","s":"そう答えた自分の声が、思ったより硬かったことに、耀平は、少しだけ驚いた。","f":"yohei"}]},{"key":"37-2","title":"廊下の窓辺","bg":"bg_shit_base","dark":false,"mood":"soft","bgm":"soft1","cast":["hotaru","yohei"],"lines":[{"t":"n","s":"会議のあと。長い廊下の窓際に、蛍が、一人で立っていた。","f":"hotaru"},{"t":"n","s":"窓の外には、細い月。夕方の雨が上がった後の空気は、しっとりと冷たかった。","f":"hotaru"},{"t":"d","s":"「耀平くん」","f":"hotaru"},{"t":"d","s":"「蛍さん。会議、出てたんですね」","f":"hotaru"},{"t":"d","s":"「運営側だからね。……ねえ、少し、いい？」","f":"hotaru"},{"t":"n","s":"蛍は、いつもの明るさを、半分だけ引っ込めて、窓の外を見ていた。薄紫の髪が、窓ガラスに映って、ぼんやりと揺れている。","f":"hotaru"},{"t":"d","s":"「合宿が終わったら、わたしと、デートしてくれる？」","f":"hotaru"},{"t":"d","s":"「また、それですか」","f":"hotaru"},{"t":"d","s":"「今回は、本気」","f":"hotaru"},{"t":"n","s":"蛍は、くるりと振り返って、にこりと笑った。","f":"hotaru","m":"happy"},{"t":"d","s":"「前に、約束したでしょ。忘れないでねって」","f":"hotaru"},{"t":"d","s":"「覚えてます」","f":"hotaru"},{"t":"d","s":"「ほんと？」","f":"hotaru"},{"t":"d","s":"「はい。……でも、どうして、そんなに」","f":"hotaru"},{"t":"d","s":"「だって、楽しみがないと、頑張れないじゃない」","f":"hotaru"},{"t":"n","s":"蛍は、指を一本、立てた。","f":"hotaru"},{"t":"d","s":"「わたしね、ずっと、そういうの、縁がなかったの。八天にいた頃は、任務と、命令と、次の任務。休みの日に、誰かと出かけるなんて、考えたこともなかった」","f":"hotaru"},{"t":"d","s":"「……」","f":"hotaru"},{"t":"d","s":"「だから、憧れてるのよ。普通のデートってやつに」","f":"hotaru"},{"t":"n","s":"軽い口調だった。けれど、その横顔は、少しだけ、遠くを見ていた。","f":"hotaru"},{"t":"d","s":"「もし、わたしが、ちゃんと生きて、合宿を終えられたら、ご褒美が欲しいの」","f":"hotaru"},{"t":"d","s":"「生きて、って」","f":"hotaru"},{"t":"d","s":"「冗談よ、冗談」","f":"hotaru"},{"t":"n","s":"蛍は、ぱたぱたと手を振った。笑っている。けれど、笑い終わるのが、ほんの少しだけ、早かった。","f":"hotaru"},{"t":"d","s":"「……蛍さん」","f":"hotaru"},{"t":"d","s":"「なあに」","f":"hotaru"},{"t":"d","s":"「何かあったら、言ってください」","f":"hotaru"},{"t":"d","s":"「あら。優しいのね」","f":"hotaru"},{"t":"n","s":"蛍は、くすくす笑った。それから、耀平の頬を、指先で、ぽんと軽く叩いた。","f":"hotaru","m":"happy"},{"t":"d","s":"「そういうところ、ちょっとだけ、ずるいわ」","f":"hotaru"},{"t":"d","s":"「何がですか」","f":"hotaru"},{"t":"d","s":"「ううん、こっちの話」","f":"hotaru"},{"t":"n","s":"蛍は、窓の外に目を戻した。","f":"hotaru"},{"t":"d","s":"「ねえ、耀平くん。わたしね、今の居場所が、けっこう好きなの」","f":"hotaru"},{"t":"d","s":"「SHITが、ですか」","f":"hotaru"},{"t":"d","s":"「うん。みんな、わたしのことを、まだ疑ってるけど。それでも、理央ちゃんは、お菓子をくれるし、藤堂さんは、文句を言いながら、書類を回してくれる」","f":"hotaru"},{"t":"d","s":"「はい」","f":"hotaru"},{"t":"d","s":"「それが、嬉しいの。変よね」","f":"hotaru"},{"t":"d","s":"「変じゃないです」","f":"hotaru"},{"t":"n","s":"蛍は、少しだけ、目を見開いた。それから、ふっと、肩の力を抜いて笑った。","f":"hotaru","m":"surprise"},{"t":"d","s":"「約束ね。島を出たら、デート。場所は、わたしが決めるから」","f":"hotaru"},{"t":"d","s":"「分かりました」","f":"hotaru"},{"t":"d","s":"「ふふ。楽しみ」","f":"hotaru"},{"t":"n","s":"蛍は、小さく手を振って、廊下を歩いていった。窓から差す月の光が、その後ろ姿を、薄く照らしていた。","f":"hotaru"},{"t":"n","s":"耀平は、その背中を、見えなくなるまで、見送った。","f":"yohei"}]},{"key":"37-3","title":"帰り道の違和感","bg":"bg_riverside","dark":true,"mood":"night","bgm":"night2","cast":["yohei","hotaru"],"lines":[{"t":"n","s":"寮への帰り道。耀平は、一人で、夜の道を歩いていた。","f":"yohei"},{"t":"n","s":"街灯の下を、いくつも通り過ぎる。湿った空気に、草の匂いが混じっている。","f":"yohei"},{"t":"i","s":"（蛍さん、あの言い方）","f":"yohei"},{"t":"d","s":"「生きて、合宿を終えられたら」。冗談だと、本人は言った。それなのに、胸のどこかが、小さく引っかかったままだった。","f":"yohei"},{"t":"n","s":"立ち止まって、夜空を見上げた。月が、雲の隙間から、顔を出している。","f":"yohei"},{"t":"i","s":"（考えすぎだ）","f":"yohei"},{"t":"n","s":"そう、自分に言い聞かせた。蛍は、明るい人だ。軽口を言う人だ。深い意味なんて、ないはずだ。","f":"hotaru"},{"t":"n","s":"けれど、あの時の横顔を、もう一度、思い出してしまう。","f":"hotaru"},{"t":"n","s":"窓の外を見ていた目。笑い終わるのが、少しだけ早かった唇。","f":"hotaru"},{"t":"i","s":"（……ちゃんと、気をつけておこう）","f":"hotaru"},{"t":"n","s":"そう決めて、耀平は、また歩き出した。","f":"yohei"},{"t":"n","s":"それが、蛍と交わした、最後の約束になるなんて、その夜の耀平は、思いもしなかった。","f":"yohei"}]}]},{"n":38,"title":"島の沖で、告げられたこと","sub":"高校・2年6月","era":"high2","lead":"上陸の前夜。船に、思いもかけない報せが届く。","scenes":[{"key":"38-1","title":"緊急の報せ","bg":"bg_ship","dark":true,"mood":"tense","bgm":"tense1","cast":["rika","yohei","todo"],"lines":[{"t":"n","s":"島に着く前の夜。大広間で、全員の集合がかかった。"},{"t":"n","s":"壇上の藤堂の顔は、いつもの冷静さを保っていたが、手元の紙が、わずかに震えていた。","f":"todo"},{"t":"d","s":"「全員、聞いてくれ。先ほど、本部から連絡が入った」","f":"todo"},{"t":"n","s":"ざわついていた広間が、静まった。","f":"todo"},{"t":"d","s":"「勾留中だった、前八天の構成員が、全員、死亡した」","f":"todo"},{"t":"n","s":"誰かが、息を呑む音がした。","f":"todo","m":"surprise"},{"t":"d","s":"「全員、だ。第一席・黒鉄玄蔵を含め、拘束されていた者は、一人残らず。いずれも、同じ夜に、殺された」","f":"todo"},{"t":"d","s":"「どういうことですか」と、柚月が尋ねた。","f":"todo"},{"t":"d","s":"「犯人は、不明だ。拘束室の記録は、すべて消されていた」","f":"todo"},{"t":"n","s":"耀平は、膝の上の拳を、ぎゅっと握った。","f":"yohei"},{"t":"i","s":"（八天が、全員……玄蔵さんも）","f":"yohei"},{"t":"d","s":"「ただし、一人だけ、生き残っている」","f":"yohei"},{"t":"d","s":"「……蛍さん」","f":"yohei"},{"t":"n","s":"藤堂が、頷いた。","f":"todo"},{"t":"d","s":"「紫苑蛍。彼女は、協力者として、この船に乗っていた。そのため、難を逃れた」","f":"todo"},{"t":"d","s":"「…………」","f":"todo"},{"t":"n","s":"広間の隅で、蛍が、小さく手を上げた。いつもの明るさは、そこになかった。","f":"hotaru"},{"t":"d","s":"「……わたし、ずっとここにいたよ」","f":"hotaru"},{"t":"d","s":"「分かっている。君を疑ってはいない。ただ、情報を共有しておく」","f":"hotaru"},{"t":"n","s":"九十九が、静かに問うた。","f":"tsukumo"},{"t":"d","s":"「合宿は、中止されますか」","f":"tsukumo"},{"t":"d","s":"「検討した。犯人の目星は、まだない。島に上陸している間は、SHITが総力で警戒する。中止すれば、かえって危険だと判断した」","f":"tsukumo"},{"t":"n","s":"広間が、再び、ざわめいた。","f":"tsukumo"},{"t":"d","s":"「怖いよ……」","f":"tsukumo"},{"t":"d","s":"「大丈夫、SHITがいるんだから」","f":"tsukumo"},{"t":"d","s":"「でも、八天が全員って」","f":"tsukumo"},{"t":"d","s":"「どういうこと……？」","f":"tsukumo"},{"t":"n","s":"耀平の隣で、莉花が、小さく囁いた。","f":"yohei"},{"t":"d","s":"「せんぱい」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「怖いですか」","f":"yohei"},{"t":"d","s":"「……少し」","f":"yohei"},{"t":"d","s":"「わたしは、せんぱいの隣に、いますからね」","f":"yohei"},{"t":"n","s":"その声は、とても優しかった。ただ、耀平が、横目で見た莉花の顔は、ほんの一瞬だけ、まったく表情がなかった。","f":"yohei"},{"t":"d","s":"「莉花？」","f":"yohei"},{"t":"d","s":"「はい？」","f":"yohei"},{"t":"d","s":"「……いや」","f":"yohei"},{"t":"n","s":"莉花は、いつもの笑顔に戻っていた。","f":"rika"}]},{"key":"38-2","title":"玄蔵のいない地下","bg":"bg_ship","dark":true,"mood":"tense","bgm":"tense1","cast":["yohei","hotaru"],"lines":[{"t":"n","s":"その夜、耀平は、眠れなかった。","f":"yohei"},{"t":"n","s":"船室の小さな窓から、黒い海を見つめていた。波の音だけが、規則正しく続いている。","f":"yohei"},{"t":"i","s":"（玄蔵さんも、死んだ）","f":"yohei"},{"t":"n","s":"ほんの数か月前。地下の拘束施設のガラス越しに、あの老人は言った。","f":"yohei"},{"t":"d","s":"『おぬしの桜は、状態じゃ。技ではない。決め手を、二つ三つ持て』","f":"yohei"},{"t":"n","s":"敵だった。学園を襲い、教室ごと押しつぶそうとした男だった。それなのに、あの日の声は、道場の師匠のように穏やかだった。","f":"yohei"},{"t":"d","s":"「……まだ、技、できてないのに」","f":"yohei"},{"t":"n","s":"呟いた声が、自分でも驚くほど、掠れていた。","f":"yohei"},{"t":"n","s":"拳を握る。爪が、掌に食い込む。","f":"yohei"},{"t":"n","s":"誰が、なぜ。拘束され、もう何もできない人たちを。","f":"yohei"},{"t":"i","s":"（近くにいた人が、また、いなくなる）","f":"yohei"},{"t":"n","s":"祖父のときと、同じだった。何も知らないうちに、いなくなる。","f":"yohei"},{"t":"n","s":"扉が、こんこんと鳴った。","f":"yohei"},{"t":"d","s":"「耀平くん、起きてる？」","f":"yohei"},{"t":"n","s":"蛍だった。廊下の灯りを背にして、青ざめた顔で、立っていた。","f":"hotaru"},{"t":"d","s":"「眠れなくて。……少しだけ、いい？」","f":"hotaru"},{"t":"d","s":"「はい」","f":"hotaru"},{"t":"n","s":"蛍は、扉にもたれて、廊下に座り込んだ。耀平も、その隣に腰を下ろす。","f":"hotaru"},{"t":"d","s":"「みんな、殺されちゃったね」","f":"hotaru"},{"t":"d","s":"「……はい」","f":"hotaru"},{"t":"d","s":"「玄蔵のおじいちゃん、口は悪かったけど、わたしのこと、娘みたいに叱ってくれた人だったの」","f":"hotaru"},{"t":"n","s":"蛍は、膝を抱えた。","f":"hotaru"},{"t":"d","s":"「気をつけなきゃ。わたしも、耀平くんも」","f":"hotaru"},{"t":"d","s":"「蛍さんは、おれが守ります」","f":"hotaru"},{"t":"d","s":"「ふふ。また、そういうこと言う」","f":"hotaru"},{"t":"n","s":"蛍は、弱々しく笑った。それから、そっと小指を差し出した。","f":"hotaru","m":"happy"},{"t":"d","s":"「じゃあ、約束。島に着いたら、わたしのこと、守ってね」","f":"hotaru"},{"t":"d","s":"「約束します」","f":"hotaru"},{"t":"n","s":"小指が、絡んだ。蛍の指は、冷たかった。","f":"hotaru"},{"t":"d","s":"「デートも、忘れないでね」","f":"hotaru"},{"t":"d","s":"「忘れません」","f":"hotaru"},{"t":"d","s":"「言ったわね」","f":"hotaru"},{"t":"n","s":"蛍は立ち上がって、手を振った。廊下の奥へ消えていく背中を、耀平は、見えなくなるまで見送った。","f":"hotaru"},{"t":"n","s":"窓の外で、どういうことなんだ、と問いかけるように、波が、何度も、船腹を叩いていた。","f":"hotaru"}]}]},{"n":39,"title":"上陸、サバイバル開始","sub":"高校・2年6月","era":"high2","lead":"島に上陸した一行。他校の一年生・二年生も合流し、二日間のサバイバルが始まる。","scenes":[{"key":"39-1","title":"上陸","bg":"bg_riverside","dark":false,"mood":"daily","bgm":"daily5","cast":["rika","yohei","todo"],"lines":[{"t":"n","s":"朝の光の中、船は島の浅瀬に錨を下ろした。"},{"t":"n","s":"小舟に分乗した生徒たちが、次々と砂浜へ降り立つ。島は、緑が深く、波の音と鳥の声が、あたりに満ちていた。"},{"t":"d","s":"「着いたな」"},{"t":"d","s":"「空気が、違う」"},{"t":"n","s":"耀平は、砂浜に足を下ろし、深く息を吸った。莉花が、すぐ隣で、くるりと島を見渡している。","f":"yohei"},{"t":"d","s":"「せんぱい、ここ、いい島ですね」","f":"yohei"},{"t":"d","s":"「そうだね」","f":"yohei"},{"t":"d","s":"「わたし、島、好きなんです」","f":"yohei"},{"t":"d","s":"「どうして」","f":"yohei"},{"t":"d","s":"「静かだから」","f":"yohei"},{"t":"n","s":"莉花は、ふふっと笑った。","f":"rika","m":"happy"},{"t":"n","s":"砂浜には、すでに他校の生徒たちが集まっていた。白鷺女学園と、蒼嵐学院。学園の一・二年生と合わせて、総勢、百人ほどの二年生と一年生が、ずらりと並んでいる。","f":"rika"},{"t":"n","s":"壇上の代わりに用意された岩の上に、藤堂が立った。","f":"todo"},{"t":"d","s":"「これより、二日間のサバイバルを開始する。ルールは、船で説明したとおりだ」","f":"todo"},{"t":"n","s":"生徒たちが、緊張した顔で頷く。","f":"todo"},{"t":"d","s":"「一つ追加する。今回の件を受け、SHITの隊員を、島の各所に配置した。何かあれば、すぐに救難信号を出せ。以上。解散」","f":"todo"},{"t":"n","s":"生徒たちは、ペアごとに、ばらばらと散っていった。","f":"todo"}]},{"key":"39-2","title":"拠点探し","bg":"bg_forest","dark":false,"mood":"daily","bgm":"daily1","cast":["rika","yohei"],"lines":[{"t":"d","s":"「どこに行きましょうか」と、莉花が尋ねた。"},{"t":"n","s":"耀平は、島の地図を広げた。中央に小高い丘があり、その周囲を森が囲んでいる。北側には、岩場。南側には、海岸線。","f":"yohei"},{"t":"d","s":"「丘の近くの森、かな。見晴らしが取れて、水場も近い」","f":"yohei"},{"t":"d","s":"「いいですね。行きましょう」","f":"yohei"},{"t":"n","s":"森の中は、薄暗く、湿った土の匂いがした。木漏れ日が、斑に地面を照らしている。","f":"yohei"},{"t":"d","s":"「ここ、いい場所です」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"n","s":"少し開けた空き地に、大きな倒木が横たわっていた。その近くに、小さな小川が流れている。","f":"yohei"},{"t":"d","s":"「ここにしよう。とりあえず、生き残るか」","f":"yohei"},{"t":"d","s":"「はい！　じゃあ、せんぱい、まずはご飯のこと考えましょう❤︎」","f":"yohei"},{"t":"d","s":"「勝ち点は」","f":"yohei"},{"t":"d","s":"「ご飯が先です」","f":"yohei"},{"t":"n","s":"二人は、荷物を下ろした。","f":"yohei"},{"t":"n","s":"その瞬間。遠くから、爆音が聞こえた。","f":"yohei"},{"t":"d","s":"「……始まったな」","f":"yohei"},{"t":"d","s":"「みたいですね」","f":"yohei"},{"t":"n","s":"莉花は、軽く伸びをした。その横顔は、ひどく穏やかだった。","f":"rika"}]},{"key":"39-3","title":"最初の戦い","bg":"bg_forest","dark":true,"mood":"battle","bgm":"battle1","cast":["yohei","rika"],"lines":[{"t":"d","s":"「見つけたぞ！　夜桜！」"},{"t":"n","s":"昼前。森の中で、二人組が、耀平たちの前に飛び出してきた。蒼嵐学院の制服。船で睨んできた、嵐堂刃だった。後ろから、妹の灯里が、息を切らして追いかけてくる。","f":"yohei","m":"anger"},{"t":"d","s":"「お兄ちゃん、待ってってば！」","f":"yohei"},{"t":"d","s":"「待てるか。勝てばプラス百、それに、こいつの強さを確かめる機会だ」","f":"yohei"},{"t":"n","s":"刃の両手に、ばちばちと雷が走った。","f":"yohei"},{"t":"d","s":"「勝負しろ」","f":"yohei"},{"t":"d","s":"「いや、おれたちは」","f":"yohei"},{"t":"n","s":"言い終わる前に、刃の姿が、消えた。","f":"yohei"},{"t":"n","s":"雷光閃刃。雷を纏った、高速の踏み込み。気づいた時には、刃の手刀が、耀平の喉元に迫っていた。","f":"yohei"},{"t":"d","s":"「危ない」","f":"yohei"},{"t":"n","s":"耀平は、体をひねって、紙一重でかわした。足元の落ち葉が、ばっと舞い上がる。頬に、ぴりっとした痺れが残った。","f":"yohei"},{"t":"d","s":"「おお、かわしたか！」","f":"yohei"},{"t":"d","s":"「速いな」","f":"yohei"},{"t":"d","s":"「当たり前だ。蒼嵐の一番槍だぞ」","f":"yohei"},{"t":"n","s":"二撃目、三撃目。雷の軌跡が、木々の間を縫って、耀平を追う。耀平は、花びらを一枚、呼んだ。","f":"yohei"},{"t":"n","s":"花びらが、雷の刃先に触れた瞬間、耀平の体が、勝手に動いた。刃の腕を、木刀の柄で、こつんと払う。","f":"yohei"},{"t":"d","s":"「なっ」","f":"yohei"},{"t":"n","s":"次の瞬間、耀平の木刀が、刃の肩を、軽く叩いていた。","f":"yohei"},{"t":"d","s":"「そこまで」","f":"yohei"},{"t":"n","s":"その少し後ろで、灯里が、雷の結界を張ったまま、固まっていた。いつの間にか、莉花が、その結界の内側に入り込んでいる。細い刀の切っ先が、灯里の首筋の手前で、ぴたりと止まっていた。","f":"rika"},{"t":"d","s":"「ひっ」","f":"rika"},{"t":"d","s":"「降参、しますか」","f":"rika"},{"t":"n","s":"莉花は、にっこりと笑っていた。声は甘かった。けれど、その切っ先は、まったく震えていなかった。","f":"rika"},{"t":"d","s":"「……こ、降参です」","f":"rika"},{"t":"d","s":"「よろしい」","f":"rika"},{"t":"n","s":"刃は、肩を押さえて、しばらく呆然としていた。それから、悔しそうに、けれどどこか晴れやかに、笑った。","f":"rika","m":"happy"},{"t":"d","s":"「……本物だな。夜桜」","f":"rika"},{"t":"d","s":"「どうも」","f":"rika"},{"t":"d","s":"「次は、負けねえ。覚えとけ」","f":"rika"},{"t":"d","s":"「お兄ちゃん、それ、負けた人の台詞だよ……」","f":"rika"},{"t":"n","s":"灯里が、ぺこぺこと頭を下げて、兄を引きずっていった。","f":"rika"},{"t":"d","s":"「プラス百、ですね！」","f":"rika"},{"t":"d","s":"「うん」","f":"rika"},{"t":"d","s":"「せんぱい、やっぱり、強い」","f":"rika"},{"t":"d","s":"「莉花も」","f":"rika"},{"t":"n","s":"莉花は、刀を鞘に収めながら、誇らしげに胸を張った。","f":"rika"},{"t":"n","s":"遠くから、また、爆音が聞こえた。","f":"rika"}]}]},{"n":40,"title":"二人の寝床と、ソレイユ","sub":"高校・2年6月","era":"high2","lead":"夕暮れの森。耀平と莉花は、寝床を作る。そこに、ソレイユの一人が、現れる。","scenes":[{"key":"40-1","title":"寝床づくり","bg":"bg_forest","dark":false,"mood":"daily","bgm":"daily1","cast":["rika","yohei"],"lines":[{"t":"n","s":"夕方。倒木の陰に、二人は、簡単な寝床を作っていた。"},{"t":"d","s":"「枝を、こうして並べて」"},{"t":"d","s":"「葉っぱを、重ねて」"},{"t":"d","s":"「完成、ですね！」"},{"t":"n","s":"莉花が、満足げに両手を広げた。出来上がったのは、二人分には、ぎりぎりの広さの、小さな寝床だった。","f":"rika"},{"t":"d","s":"「狭くない？」","f":"rika"},{"t":"d","s":"「狭くないです。ぴったりです❤︎」","f":"rika"},{"t":"d","s":"「ぴったりすぎる気がする」","f":"rika"},{"t":"d","s":"「気のせいです」","f":"rika"},{"t":"n","s":"莉花は、寝床に、ぴょんと座った。","f":"rika"},{"t":"d","s":"「せんぱいも、座ってください」","f":"rika"},{"t":"d","s":"「うん」","f":"rika"},{"t":"n","s":"耀平は、隣に座った。肩が、触れた。莉花は、すぐに、耀平の腕に、頭を預けた。","f":"yohei"},{"t":"d","s":"「……莉花」","f":"yohei"},{"t":"d","s":"「すきすき、ですよ」","f":"yohei"},{"t":"d","s":"「また、それ」","f":"yohei"},{"t":"d","s":"「何回でも言います。せんぱい、すきすき、すきすき」","f":"yohei"},{"t":"d","s":"「やめろって」","f":"yohei"},{"t":"d","s":"「やめません」","f":"yohei"},{"t":"n","s":"莉花は、耀平の袖を、きゅっと掴んだ。いつもの甘い声だった。けれど、その指は、ほんの少し、震えていた。","f":"rika"},{"t":"d","s":"「……せんぱい」","f":"rika"},{"t":"d","s":"「ん」","f":"rika"},{"t":"d","s":"「今夜、寝る前に、ひとつ、お願いしてもいいですか」","f":"rika"},{"t":"d","s":"「何」","f":"rika"},{"t":"d","s":"「手、握っててください」","f":"rika"},{"t":"d","s":"「え」","f":"rika"},{"t":"d","s":"「怖いんです」","f":"rika"},{"t":"n","s":"耀平は、一瞬、言葉に詰まった。それから、静かに頷いた。","f":"yohei"},{"t":"d","s":"「分かった」","f":"yohei"},{"t":"d","s":"「ありがとうございます」","f":"yohei"},{"t":"n","s":"莉花は、嬉しそうに笑った。その笑顔は、いつもの小悪魔の笑顔ではなかった。ただの、ひとりの少女の笑顔だった。","f":"rika","m":"happy"}]},{"key":"40-2","title":"泥棒猫の気配","bg":"bg_riverside","dark":true,"mood":"night","bgm":"night2","cast":["noa","yuzuki","yohei"],"lines":[{"t":"n","s":"夕食の時間。小川のほとりで、乃亜と柚月が、それぞれのペアと一緒に、焚き火を囲んでいた。","f":"noa"},{"t":"d","s":"「ねえ、乃亜先輩」","f":"noa"},{"t":"d","s":"「何」","f":"noa"},{"t":"d","s":"「向こうの方から、また、いつもの気配がします」","f":"noa"},{"t":"d","s":"「……泥棒猫の気配ね」","f":"noa"},{"t":"n","s":"乃亜は、枝を、ぽきりと折った。","f":"noa"},{"t":"d","s":"「先輩、怖いです」と、後輩の朝比奈つばさが、小さな声で言った。","f":"noa"},{"t":"d","s":"「怖くない。普通」","f":"noa"},{"t":"d","s":"「すごく怖い顔してます」","f":"noa"},{"t":"d","s":"「してない」","f":"noa"},{"t":"n","s":"柚月も、静かに、手元の串焼きを回していた。","f":"yuzuki"},{"t":"d","s":"「わたしたち、何か、間違っているのでしょうか」","f":"yuzuki"},{"t":"d","s":"「間違ってない。ただ……」","f":"yuzuki"},{"t":"d","s":"「ただ？」","f":"yuzuki"},{"t":"d","s":"「ちょっと、悔しいだけ」","f":"yuzuki"},{"t":"n","s":"乃亜は、火を見つめた。","f":"noa"},{"t":"d","s":"「あの子、耀平のこと、本当に好きみたいだから、嫌いにはなれないの。でも、悔しい」","f":"noa"},{"t":"d","s":"「分かります」","f":"noa"},{"t":"n","s":"柚月は、小さく笑った。","f":"yuzuki","m":"happy"},{"t":"d","s":"「わたしも、同じ気持ちです」","f":"yuzuki"},{"t":"n","s":"二人は、顔を見合わせて、ふっと、息をついた。後輩のつばさと夢は、顔を見合わせて、首をかしげた。","f":"yuzuki"}]},{"key":"40-3","title":"夜の訪問者","bg":"bg_forest","dark":true,"mood":"battle","bgm":"battle2","cast":["soleil","yohei","rika"],"lines":[{"t":"n","s":"夜。耀平と莉花は、寝床に並んで座っていた。","f":"yohei"},{"t":"n","s":"月が、木々の隙間から差している。虫の声が、静かに響いていた。","f":"yohei"},{"t":"d","s":"「せんぱい、眠いですか」","f":"yohei"},{"t":"d","s":"「まだ」","f":"yohei"},{"t":"d","s":"「じゃあ、お話しましょう」","f":"yohei"},{"t":"d","s":"「何の話」","f":"yohei"},{"t":"d","s":"「何でもいいです」","f":"yohei"},{"t":"n","s":"そのとき。","f":"yohei"},{"t":"d","s":"「やっほー⭐︎」","f":"yohei"},{"t":"n","s":"森の闇の中から、軽やかな声が響いた。","f":"yohei"},{"t":"n","s":"耀平は、咄嗟に、莉花を背にかばった。","f":"yohei"},{"t":"n","s":"月明かりの下に、一人の人影が現れた。道化師のような、派手な衣装。顔には、笑った仮面。","f":"soleil","m":"happy"},{"t":"d","s":"「見つけた見つけた。夜桜の、耀平くんだ」","f":"soleil"},{"t":"d","s":"「……ソレイユ」","f":"soleil"},{"t":"d","s":"「正解！　ぱちぱち！」","f":"soleil"},{"t":"n","s":"道化は、おどけた様子で、手を叩いた。その足元から、黒い粉のようなものが、じわりと広がる。","f":"soleil"},{"t":"d","s":"「いやあ、探したよ。今日は、挨拶だけのつもりだったんだけど、ちょっとだけ、遊んでいかない？」","f":"soleil"},{"t":"d","s":"「遊ばない」","f":"soleil"},{"t":"d","s":"「つれないなあ」","f":"soleil"},{"t":"n","s":"道化の手が、ひらりと動いた。次の瞬間、数本の短剣が、空を裂いて飛んできた。","f":"soleil"},{"t":"n","s":"耀平は、花びらを展開して、短剣を弾いた。","f":"yohei"},{"t":"d","s":"「おっ、やるじゃん」","f":"yohei"},{"t":"d","s":"「莉花、下がってて」","f":"yohei"},{"t":"d","s":"「いいえ」","f":"yohei"},{"t":"n","s":"莉花は、耀平の前に、すっと出た。","f":"rika"},{"t":"d","s":"「せんぱいは、手出ししないでくださいねー」","f":"rika"},{"t":"d","s":"「は？」","f":"rika"},{"t":"d","s":"「わたしのペアなんですから、たまには、いいところ見せさせてください❤︎」","f":"rika"},{"t":"n","s":"その言葉が終わる前に、道化が、動いた。","f":"soleil"},{"t":"d","s":"「せんぱい、右です」","f":"soleil"},{"t":"d","s":"「え」","f":"soleil"},{"t":"n","s":"道化の姿が、瞬時に、耀平の右に回っていた。反応が、間に合わない。","f":"soleil"},{"t":"n","s":"その瞬間、銀色の閃光が、道化の腕を、弾いた。","f":"soleil","fx":"flash"},{"t":"d","s":"「え？」","f":"soleil"},{"t":"n","s":"莉花だった。細い刀が、道化の短剣を、真上から叩き落としていた。","f":"rika"},{"t":"d","s":"「わたしの、せんぱいに、触らないでください」","f":"rika"},{"t":"n","s":"その声は、まるで氷のようだった。","f":"rika"},{"t":"d","s":"「わお。怖い怖い」","f":"rika"},{"t":"d","s":"「消えてください」","f":"rika"},{"t":"n","s":"莉花の刀が、一閃した。道化は、慌てて身を引き、仮面の一部が、ぱらりと割れた。","f":"rika","fx":"flash"},{"t":"d","s":"「あーあ、やっちゃった」","f":"rika"},{"t":"d","s":"「…………」","f":"rika"},{"t":"d","s":"「今日は、ここまでにしておこう。またね、夜桜くん。……それと、小さな剣士さん」","f":"rika"},{"t":"n","s":"道化は、軽く手を振って、闇の中に消えた。","f":"soleil"},{"t":"n","s":"森は、再び、静寂に包まれた。","f":"soleil"}]},{"key":"40-4","title":"桔梗の剣","bg":"bg_forest","dark":true,"mood":"night","bgm":"night3","cast":["rika","yohei"],"lines":[{"t":"d","s":"「……莉花」"},{"t":"d","s":"「はい」"},{"t":"d","s":"「今の、技」"},{"t":"d","s":"「ただの、護身術です」"},{"t":"n","s":"莉花は、刀を鞘に収めた。その柄に彫られた紫の花の模様が、月明かりに光った。","f":"rika","fx":"flash"},{"t":"n","s":"耀平は、その模様を、じっと見つめた。","f":"yohei"},{"t":"d","s":"「……元会長と、同じくらい強いな」","f":"yohei"},{"t":"d","s":"「九条先輩ですか？　光栄です❤︎」","f":"yohei"},{"t":"d","s":"「莉花、その花」","f":"yohei"},{"t":"d","s":"「桔梗です」","f":"yohei"},{"t":"d","s":"「……桔梗」","f":"yohei"},{"t":"n","s":"耀平は、ふっと、祖父の墓の前の、紫の花を思い出した。","f":"yohei"},{"t":"i","s":"（同じ、花だ）","f":"yohei"},{"t":"n","s":"けれど、莉花の刀の動きには、もう一つ、気づいたことがあった。","f":"rika"},{"t":"d","s":"「さっきの動き。足を滑らせる、半拍の遅れ」","f":"rika"},{"t":"d","s":"「はい」","f":"rika"},{"t":"d","s":"「おれの、夜桜の動きに、似てた」","f":"rika"},{"t":"n","s":"莉花は、一瞬、固まった。それから、すぐに、笑った。","f":"rika","m":"happy"},{"t":"d","s":"「偶然ですよ」","f":"rika"},{"t":"d","s":"「そうかな」","f":"rika"},{"t":"d","s":"「そうです。きっと、せんぱいの戦い方に、似てしまったんです。たくさん、見てきたので」","f":"rika"},{"t":"n","s":"耀平は、頷いた。けれど、胸の中の引っかかりが、また一つ、増えていた。","f":"yohei"},{"t":"d","s":"「寝ましょう、せんぱい」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"n","s":"莉花は、耀平の隣に、すっと潜り込んだ。それから、そっと、耀平の手を握った。","f":"rika"},{"t":"d","s":"「約束、ですよ」","f":"rika"},{"t":"d","s":"「うん」","f":"rika"},{"t":"d","s":"「おやすみなさい」","f":"rika"},{"t":"n","s":"夜の森に、虫の声が響いていた。","f":"rika"}]}]},{"n":41,"title":"島の戦い、学園の力","sub":"高校・2年6月","era":"high2","lead":"サバイバル二日目の朝。各所で、他校の生徒と学園の生徒たちが、激しくぶつかり合う。","scenes":[{"key":"41-1","title":"竜馬と隼","bg":"bg_forest","dark":true,"mood":"battle","bgm":"battle1","cast":["ryoma"],"lines":[{"t":"n","s":"島の北側の岩場。炎と風が、乱れ飛んでいた。"},{"t":"d","s":"「紅蓮爆炎！」"},{"t":"d","s":"「烈風斬刃！」"},{"t":"n","s":"竜馬と隼の背中合わせの戦いは、息が合っていなかった。最初のうちは。","f":"ryoma"},{"t":"d","s":"「おい、隼！　お前の風、おれの炎を消してるぞ！」","f":"ryoma"},{"t":"d","s":"「竜馬先輩の炎が、でかすぎるんです！」","f":"ryoma"},{"t":"d","s":"「だったら、風を後ろに回せ！」","f":"ryoma"},{"t":"d","s":"「命令しないでください！」","f":"ryoma"},{"t":"n","s":"蒼嵐学院の三年生、三人組が、二人を包囲していた。","f":"ryoma"},{"t":"d","s":"「相談は、終わったか？」","f":"ryoma"},{"t":"d","s":"「……隼」","f":"ryoma"},{"t":"d","s":"「何ですか」","f":"ryoma"},{"t":"d","s":"「風で、おれの炎を、押せるか」","f":"ryoma"},{"t":"d","s":"「は？」","f":"ryoma"},{"t":"d","s":"「炎を、風に乗せる。そうすれば、でかいのが撃てる」","f":"ryoma"},{"t":"n","s":"隼は、一瞬、目を見開いた。それから、にやりと笑った。","f":"ryoma","m":"surprise"},{"t":"d","s":"「やってみます」","f":"ryoma"},{"t":"d","s":"「よし」","f":"ryoma"},{"t":"n","s":"竜馬の炎が、隼の風を受けて、渦を巻いた。炎の竜巻が、岩場をなぎ払う。","f":"ryoma"},{"t":"d","s":"「うわあああっ！」","f":"ryoma"},{"t":"d","s":"「ばかな、風と炎が……！」","f":"ryoma"},{"t":"n","s":"三人組は、一瞬で吹き飛ばされた。","f":"ryoma","fx":"shake"},{"t":"d","s":"「……できた」","f":"ryoma"},{"t":"d","s":"「できましたね」","f":"ryoma"},{"t":"n","s":"二人は、顔を見合わせた。それから、同時に、ぷいとそっぽを向いた。","f":"ryoma"},{"t":"d","s":"「まあ、悪くなかった」","f":"ryoma"},{"t":"d","s":"「先輩こそ」","f":"ryoma"},{"t":"n","s":"遠くで見ていた陽太が、小さく呟いた。","f":"ryoma"},{"t":"d","s":"「あいつら、いいペアだな」","f":"ryoma"}]},{"key":"41-2","title":"乃亜と柚月","bg":"bg_riverside","dark":true,"mood":"battle","bgm":"battle1","cast":["noa","yuzuki"],"lines":[{"t":"n","s":"島の南側の海岸。砂浜の上で、水と雪が、ぶつかっていた。"},{"t":"d","s":"「碧水心希」"},{"t":"n","s":"乃亜の足元から、澄んだ水が、渦を巻いて立ち上がった。波打ち際の海水が、乃亜の呼びかけに応えるように、うねりを増していく。","f":"noa"},{"t":"n","s":"その向かいに、白鷺女学園の二人が立っていた。一条雪乃と、鳳麗華。","f":"noa"},{"t":"d","s":"「待っていましたわ、水の規格外さん」","f":"noa"},{"t":"d","s":"「……どうも」","f":"noa"},{"t":"d","s":"「船での借り、ここで返させていただきますわよ！」","f":"noa"},{"t":"n","s":"麗華の両手に、蓮の花の形をした炎が、いくつも咲いた。業火蓮華。花びら一枚一枚が、灼けるような熱を放っている。","f":"noa"},{"t":"d","s":"「つばささん、夢さん、わたしの後ろに」","f":"noa"},{"t":"n","s":"柚月が、後輩二人を背中にかばった。朝比奈つばさは、羽衣をはためかせて身構え、白雪夢は、眠そうな目をこすりながら、それでも柚月の袖をしっかり掴んでいる。","f":"yuzuki"},{"t":"d","s":"「いきますわよ！」","f":"yuzuki"},{"t":"n","s":"炎の蓮が、一斉に飛んだ。","f":"yuzuki"},{"t":"d","s":"「淡雪」","f":"yuzuki"},{"t":"n","s":"柚月の前に、薄い雪の帳が、ふわりと降りた。炎の蓮が、その帳に触れた瞬間、まるで最初からなかったかのように、すっと消えていく。","f":"yuzuki"},{"t":"d","s":"「な……消えた？」","f":"yuzuki"},{"t":"d","s":"「拒絶、です。痛いものも、熱いものも、ここから先には通しません」","f":"yuzuki"},{"t":"n","s":"柚月は、静かに微笑んだ。","f":"yuzuki","m":"happy"},{"t":"n","s":"その隙に、雪乃が、氷の花びらを舞わせた。氷花舞踏。冷たい花吹雪が、乃亜を包み込もうとする。","f":"noa"},{"t":"n","s":"乃亜は、目を細めた。","f":"noa"},{"t":"d","s":"「……押し流す」","f":"noa"},{"t":"n","s":"立ち上がった水の壁が、一気に崩れ落ちた。津波のような水流が、氷の花びらも、炎の蓮も、まとめて呑み込んでいく。じゅう、と白い湯気が、砂浜いっぱいに広がった。","f":"noa"},{"t":"n","s":"湯気が晴れた時、麗華と雪乃は、腰まで水に浸かって、立ち尽くしていた。","f":"noa"},{"t":"d","s":"「……勝負あり、ですね」","f":"noa"},{"t":"d","s":"「……参りました」","f":"noa"},{"t":"n","s":"雪乃が、穏やかに頭を下げた。麗華は、ずぶ濡れの髪をかき上げて、唇を尖らせた。","f":"noa"},{"t":"d","s":"「き、今日のところは、引き分けにしておいて差し上げますわ」","f":"noa"},{"t":"d","s":"「負けでしょ」","f":"noa"},{"t":"d","s":"「引き分けですわ！」","f":"noa"},{"t":"n","s":"乃亜は、小さく肩をすくめた。それから、後ろの後輩を振り返った。","f":"noa"},{"t":"d","s":"「つばさ、夢、大丈夫？」","f":"noa"},{"t":"d","s":"「は、はい！」","f":"noa"},{"t":"d","s":"「先輩たち、かっこよかったです……すぅ」","f":"noa"},{"t":"d","s":"「夢さん、立ったまま寝ないでください」","f":"noa"},{"t":"n","s":"柚月にたしなめられて、夢が、はっと目を開けた。乃亜と柚月は、顔を見合わせて、少し照れたように笑った。","f":"yuzuki","m":"happy"}]},{"key":"41-3","title":"昼の休憩","bg":"bg_forest","dark":false,"mood":"daily","bgm":"daily4","cast":["rika","ryoma","yohei"],"lines":[{"t":"n","s":"正午。小川のほとりに、全員が、一度集まった。"},{"t":"d","s":"「ふう……疲れた」"},{"t":"d","s":"「お疲れ」"},{"t":"n","s":"耀平は、水筒の水を、ごくごくと飲んだ。莉花が、隣でお菓子を配っている。","f":"yohei"},{"t":"d","s":"「みなさん、どうぞ❤︎」","f":"yohei"},{"t":"d","s":"「ありがとう、莉花さん」","f":"yohei"},{"t":"d","s":"「いえいえ」","f":"yohei"},{"t":"n","s":"乃亜は、受け取ったお菓子を、じっと見つめた。","f":"noa"},{"t":"d","s":"「……毒、入ってないよね」","f":"noa"},{"t":"d","s":"「入ってませんよ！　ひどいです〜」","f":"noa"},{"t":"d","s":"「冗談」","f":"noa"},{"t":"d","s":"「冗談に聞こえません」","f":"noa"},{"t":"n","s":"柚月が、くすくすと笑った。竜馬が、お菓子を二つ、口に放り込んだ。","f":"yuzuki","m":"happy"},{"t":"d","s":"「うめえ」","f":"yuzuki"},{"t":"d","s":"「ちょっと、竜馬先輩、勝手に」","f":"yuzuki"},{"t":"d","s":"「いいだろ、別に」","f":"yuzuki"},{"t":"d","s":"「よくないです！」","f":"yuzuki"},{"t":"n","s":"隼が、むっとして、竜馬の袖を引いた。","f":"ryoma"},{"t":"n","s":"賑やかな昼の光景だった。耀平は、そっと、目を細めた。","f":"yohei"},{"t":"i","s":"（こういう時間が、ずっと続けばいいのに）","f":"yohei"},{"t":"n","s":"そう思った瞬間、遠くで、爆発音が響いた。","f":"yohei","fx":"shake"},{"t":"d","s":"「また、誰かが戦ってるな」","f":"yohei"},{"t":"d","s":"「午後も、頑張りましょう」","f":"yohei"},{"t":"n","s":"莉花は、お菓子の袋を、そっと閉じた。その目は、森の奥を、じっと見つめていた。","f":"rika"}]}]},{"n":42,"title":"新八天の知らせ","sub":"高校・2年6月","era":"high2","lead":"サバイバル二日目の夜。一通のメモが、耀平のもとに届く。","scenes":[{"key":"42-1","title":"メモ","bg":"bg_forest","dark":true,"mood":"tense","bgm":"tense2","cast":["yohei","rika","soleil"],"lines":[{"t":"n","s":"夕暮れ。耀平と莉花が、寝床に戻ると、入り口の枝に、一枚の紙が挟まっていた。","f":"yohei"},{"t":"d","s":"「……何だ、これ」","f":"yohei"},{"t":"n","s":"耀平は、紙を開いた。黒いインクで、短く書かれていた。","f":"yohei"},{"t":"d","s":"『新八天もいるよ⭐︎　見つけてね』","f":"yohei"},{"t":"d","s":"「新八天……？」","f":"yohei"},{"t":"d","s":"「ふうん」","f":"yohei"},{"t":"n","s":"莉花が、横から紙を覗き込んだ。","f":"rika"},{"t":"d","s":"「ソレイユの、いたずらですかね」","f":"rika"},{"t":"d","s":"「分からない。でも、新八天って、何だろう」","f":"rika"},{"t":"n","s":"耀平は、メモを握りしめた。","f":"yohei"},{"t":"d","s":"「前八天は、全員、死んだ。なのに、新しい八天が、いる……？」","f":"yohei"},{"t":"d","s":"「そういうことになりますね」","f":"yohei"},{"t":"n","s":"莉花は、淡々と答えた。その口調は、驚いているようにも、納得しているようにも聞こえた。","f":"rika"},{"t":"d","s":"「藤堂さんに、報告しよう」","f":"rika"},{"t":"d","s":"「はい」","f":"rika"},{"t":"n","s":"二人は、小川を渡って、SHITの臨時テントへ向かった。","f":"rika"}]},{"key":"42-2","title":"SHITのテント","bg":"bg_forest","dark":true,"mood":"tense","bgm":"tense2","cast":["todo","yohei"],"lines":[{"t":"n","s":"テントの中では、藤堂が、地図を前に、腕を組んでいた。","f":"todo"},{"t":"d","s":"「新八天」","f":"todo"},{"t":"d","s":"「はい。メモが、置いてありました」","f":"todo"},{"t":"n","s":"藤堂は、紙を受け取り、じっと見つめた。眼鏡の奥の目が、細くなる。","f":"todo"},{"t":"d","s":"「理央がいれば、痕跡を読ませるところなんだがな」","f":"todo"},{"t":"d","s":"「理央は」","f":"todo"},{"t":"d","s":"「本部に残っている。全知解析は、本部の防衛の要だ。……この星のマークは、ソレイユの癖だ。現場の傷にも、よく残っていた」","f":"todo"},{"t":"d","s":"「ソレイユが、わざわざ、教えてきたってことですか」","f":"todo"},{"t":"d","s":"「遊んでいるんだろう。奴らは、そういう連中だ」","f":"todo"},{"t":"n","s":"藤堂は、紙を机に置いた。","f":"todo"},{"t":"d","s":"「分かった。ご苦労。明日の朝までに、周囲の警戒を強化する」","f":"todo"},{"t":"d","s":"「お願いします」","f":"todo"},{"t":"d","s":"「耀平くん。君も、気を付けろ」","f":"todo"},{"t":"d","s":"「はい」","f":"todo"},{"t":"n","s":"テントを出ると、莉花が、外で待っていた。","f":"rika"},{"t":"d","s":"「どうでした」","f":"rika"},{"t":"d","s":"「警戒を強める、って」","f":"rika"},{"t":"d","s":"「そうですか」","f":"rika"},{"t":"n","s":"二人は、夜道を、並んで歩いた。","f":"rika"}]},{"key":"42-3","title":"おじいちゃんの話","bg":"bg_forest","dark":true,"mood":"night","bgm":"night3","cast":["rika","yohei"],"lines":[{"t":"n","s":"寝床に戻ると、莉花が、枝をくべて、小さな火を作った。","f":"rika"},{"t":"d","s":"「せんぱい、寒くないですか」","f":"rika"},{"t":"d","s":"「大丈夫」","f":"rika"},{"t":"d","s":"「じゃあ、お話の続き、しましょうか」","f":"rika"},{"t":"d","s":"「うん」","f":"rika"},{"t":"n","s":"火が、ぱちぱちと爆ぜた。","f":"rika"},{"t":"d","s":"「せんぱいには、おじいさんが、いたんですよね」","f":"rika"},{"t":"d","s":"「……うん」","f":"rika"},{"t":"d","s":"「どんな人でした」","f":"rika"},{"t":"n","s":"耀平は、火を見つめながら、ゆっくりと話し始めた。","f":"yohei"},{"t":"d","s":"「剣の師匠だった。優しくて、厳しくて。おれが小さい頃から、一緒に暮らしてた。ずっと、傍にいてくれた」","f":"yohei"},{"t":"d","s":"「素敵ですね」","f":"yohei"},{"t":"d","s":"「中学一年の春に、亡くなったんだ。病気って言われたけど……歳だって、本人は笑ってた」","f":"yohei"},{"t":"d","s":"「……そうですか」","f":"yohei"},{"t":"n","s":"莉花は、火の向こうで、静かに頷いた。","f":"rika"},{"t":"d","s":"「せんぱいの、おじいさんは、きっと、せんぱいのことが、大好きだったんだと思います」","f":"rika"},{"t":"d","s":"「どうして、分かる」","f":"rika"},{"t":"d","s":"「だって、せんぱいが、こんなに優しい人に、育ったから」","f":"rika"},{"t":"n","s":"耀平は、はっとして、莉花を見た。","f":"yohei"},{"t":"n","s":"莉花は、にこりと笑っていた。けれど、その目は、どこか、遠くを見ていた。","f":"rika"},{"t":"d","s":"「……莉花にも、おじいちゃんが、いたんだよな」","f":"rika"},{"t":"d","s":"「はい」","f":"rika"},{"t":"d","s":"「今は」","f":"rika"},{"t":"d","s":"「私も、いたんですよ〜」","f":"rika"},{"t":"n","s":"莉花の声は、いつもの軽い調子だった。それなのに、耀平は、それ以上、聞けなかった。","f":"rika"},{"t":"n","s":"火の向こうで、莉花の頬を、一粒の光が、伝って落ちた。","f":"rika"},{"t":"d","s":"「莉花」","f":"rika"},{"t":"d","s":"「煙が、目に入っただけです」","f":"rika"},{"t":"d","s":"「そうか」","f":"rika"},{"t":"n","s":"莉花は、目を擦って、笑った。","f":"rika","m":"happy"},{"t":"n","s":"夜は、静かに更けていった。この夜が、嵐の前の最後の静けさだったことを、耀平は、まだ知らない。","f":"yohei"}]}]},{"n":43,"title":"夜明けの爆発","sub":"高校・2年6月","era":"high2","lead":"サバイバル三日目の朝。静けさは、島のあちこちで同時に起きた爆発で、破られる。","scenes":[{"key":"43-1","title":"眠る莉花","bg":"bg_forest","dark":true,"mood":"tense","bgm":"tense1","cast":["rika","yohei","yuzuki"],"lines":[{"t":"n","s":"朝霧の中で、耀平は目を覚ました。","f":"yuzuki"},{"t":"n","s":"白い光が、木々の隙間から、ゆっくりと差し込んでいる。鳥の声が遠い。湿った土と、焚き火の消えた匂いがした。","f":"yuzuki"},{"t":"n","s":"左腕が、重い。","f":"yuzuki"},{"t":"n","s":"見ると、莉花が、耀平の腕にしがみついたまま、すうすうと眠っていた。それどころか、片足まで、耀平の足に絡めている。頬が、二の腕にぴったりとくっついていた。","f":"rika"},{"t":"d","s":"「…………」","f":"rika"},{"t":"n","s":"耀平は、固まった。","f":"yohei"},{"t":"n","s":"握った手は、夜のあいだ、一度も離れなかったらしい。そこまではいい。約束だった。けれど、いつの間に、ここまで近くに。","f":"yohei"},{"t":"d","s":"「……勘弁してくれ」","f":"yohei"},{"t":"n","s":"顔が、熱い。耳まで、熱い。","f":"yohei"},{"t":"n","s":"莉花は、むにゃむにゃと何かを呟いて、さらにぎゅっと腕を抱え込んだ。","f":"rika"},{"t":"d","s":"「せんぱい……すきすき……」","f":"rika"},{"t":"d","s":"「寝言でも言うのか」","f":"rika"},{"t":"n","s":"けれど、その頬には、乾いた涙の跡が、うっすらと残っていた。いつもの小悪魔めいた笑顔はない。眠っている顔は、思っていたよりずっと幼くて、頼りなかった。","f":"rika","m":"sad"},{"t":"i","s":"（……怖かったんだな）","f":"rika"},{"t":"n","s":"照れくささが、少しだけ、引いた。","f":"rika"},{"t":"n","s":"そのとき。","f":"rika"},{"t":"n","s":"遠くで、空気が、裂けた。","f":"rika"},{"t":"n","s":"どおん、と腹の底に響く音。続けて、二度、三度、四度。島のあちこちから。足元の地面が、びりびりと震えた。鳥の群れが、一斉に飛び立って、白い空を黒く染める。","f":"rika"},{"t":"d","s":"「莉花。起きろ」","f":"rika"},{"t":"d","s":"「……ん」","f":"rika"},{"t":"d","s":"「爆発だ」","f":"rika","fx":"shake"},{"t":"n","s":"莉花の目が、ぱちりと開いた。","f":"rika"},{"t":"n","s":"その瞬間、寝ぼけた顔は、どこにもなかった。起き上がるなり、もう刀に手を伸ばしている。","f":"rika"},{"t":"d","s":"「……あ」","f":"rika"},{"t":"d","s":"「何」","f":"rika"},{"t":"d","s":"「わたし、せんぱいに、抱きついてました？」","f":"rika"},{"t":"d","s":"「…………」","f":"rika"},{"t":"d","s":"「ふふ。役得です❤︎」","f":"rika"},{"t":"d","s":"「いいから、行くぞ」","f":"rika"},{"t":"n","s":"莉花は、くすっと笑って、それから、遠くの煙を見た。目が、すっと細くなる。","f":"rika"},{"t":"d","s":"「北の岩場、南の海岸、西の森。……それから、丘の向こう。一番大きいのは、丘の向こうです」","f":"rika"},{"t":"d","s":"「分かるのか」","f":"rika"},{"t":"d","s":"「音の大きさで」","f":"rika"},{"t":"n","s":"耀平は、花びらを一枚、手の中に呼んだ。","f":"yohei"},{"t":"d","s":"「丘の向こうへ」","f":"yohei"},{"t":"d","s":"「はい、せんぱい」","f":"yohei"}]},{"key":"43-2","title":"各地の戦い","bg":"bg_forest","dark":true,"mood":"battle","bgm":"battle2","cast":["noa","ryoma","tsukumo"],"lines":[{"t":"n","s":"同じ頃。島の各地で、黒い外套の者たちが、生徒たちを襲っていた。"},{"t":"n","s":"北の岩場。"},{"t":"d","s":"「新八天、第七席。凍上冬馬」"},{"t":"n","s":"外套の男が手をかざすと、岩場一面が、ばきばきと音を立てて凍りついた。逃げ遅れた他校の生徒の足が、氷に縫い止められる。"},{"t":"d","s":"「隼。そいつらを連れて、下がってろ」"},{"t":"d","s":"「でも、先輩」"},{"t":"d","s":"「こいつは、おれ一人でやる」"},{"t":"n","s":"竜馬の拳に、炎が灯った。いつもより、静かな炎だった。","f":"ryoma"},{"t":"d","s":"「絶対凍結。触れたものは、何でも凍る」","f":"ryoma"},{"t":"d","s":"「そうかよ」","f":"ryoma"},{"t":"n","s":"竜馬は、凍った岩を、素手で掴んだ。じゅう、と音を立てて、氷が溶ける。","f":"ryoma"},{"t":"d","s":"「溶けねえ氷はねえ」","f":"ryoma"},{"t":"n","s":"南の海岸。","f":"ryoma"},{"t":"d","s":"「新八天、第八席。毒島綾。……あら、かわいい子たち」","f":"ryoma"},{"t":"n","s":"紫の霧が、砂浜を這っていく。触れた草が、見る間に、黒く枯れていった。","f":"ryoma"},{"t":"d","s":"「つばさ、夢さん、下がって。息を止めて」","f":"ryoma"},{"t":"n","s":"柚月が淡雪を降らせ、毒の霧を拒む。その前に、乃亜が、一歩、出た。","f":"yuzuki"},{"t":"d","s":"「柚月。後輩たちを、お願い」","f":"yuzuki"},{"t":"d","s":"「乃亜先輩、一人で？」","f":"yuzuki"},{"t":"d","s":"「毒なら、流せばいい」","f":"yuzuki"},{"t":"n","s":"乃亜の足元で、海が、ゆっくりと持ち上がった。","f":"noa"},{"t":"n","s":"西の森。","f":"noa"},{"t":"d","s":"「霧が濃い……！」","f":"noa"},{"t":"d","s":"「刃が、四方から……！」","f":"noa"},{"t":"n","s":"新生徒会の六人が、背中合わせに円を作っていた。霧の中から、無数の刃が降り注ぐ。","f":"noa"},{"t":"d","s":"「北条、壁を！」","f":"noa"},{"t":"d","s":"「石壁堅陣！」","f":"noa"},{"t":"n","s":"九十九の声に、北条拓海の石壁が立ち上がり、刃を受け止める。久我司が磁力で刃を逸らし、柊澄花が、傷ついた仲間に薬草を押し当てていく。","f":"tsukumo"},{"t":"d","s":"「第二席と、第六席。二人がかりか」","f":"tsukumo"},{"t":"d","s":"「会長、霧の向こうに、本体が」","f":"tsukumo"},{"t":"d","s":"「慌てるな。一つずつだ」","f":"tsukumo"},{"t":"n","s":"九十九は、穏やかに、眼鏡を押し上げた。","f":"tsukumo"}]},{"key":"43-3","title":"笑う道化","bg":"bg_forest","dark":true,"mood":"battle","bgm":"battle2","cast":["soleil","yohei","rika"],"lines":[{"t":"n","s":"丘へ向かう途中の、開けた斜面で、耀平は足を止めた。","f":"yohei"},{"t":"n","s":"道化が、三人、いた。","f":"soleil"},{"t":"n","s":"小柄で、けたけたと笑い続ける道化。山のような巨体で、黙って立っている道化。細身で、気だるげに首を傾げている道化。","f":"soleil"},{"t":"d","s":"「やっほー⭐︎」","f":"soleil"},{"t":"d","s":"「…………」","f":"soleil"},{"t":"d","s":"「なんや、もう来たんか」","f":"soleil"},{"t":"n","s":"ソレイユだった。三人とも、笑った仮面をつけている。","f":"soleil","m":"happy"},{"t":"n","s":"その足元に、黒い外套の人影が、三つ、倒れていた。","f":"soleil"},{"t":"d","s":"「……何を、した」","f":"soleil"},{"t":"d","s":"「お掃除だよ⭐︎」","f":"soleil"},{"t":"n","s":"小柄な道化が、くるりと回った。","f":"soleil"},{"t":"d","s":"「新八天の、第三席、第四席、第五席。ちょーっと、偉そうだったから」","f":"soleil"},{"t":"d","s":"「同じ、仲間じゃないのか」","f":"soleil"},{"t":"d","s":"「仲間？　まさか！」","f":"soleil"},{"t":"n","s":"けたけたけた、と笑い声が、斜面に響いた。","f":"soleil"},{"t":"n","s":"倒れた一人が、かすかに、指を動かした。まだ、息がある。巨体の道化が、その上に、ゆっくりと手をかざした。","f":"soleil"},{"t":"d","s":"「やめ――」","f":"soleil"},{"t":"n","s":"じゅっ、と、音がした。","f":"soleil"},{"t":"n","s":"熱だった。巨体の道化の手のひらから放たれた熱が、外套ごと、すべてを焼いた。道化は、その時だけ、仮面の下で、くつくつと笑っていた。","f":"soleil"},{"t":"n","s":"耀平は、声が出なかった。","f":"yohei"},{"t":"d","s":"「ほな、行こか。ここは、もう、おもろないわ」","f":"yohei"},{"t":"n","s":"細身の道化が、影の中に、すうっと沈んでいく。","f":"soleil"},{"t":"d","s":"「夜桜くんも、またね⭐︎　この先、もっと、楽しいの、待ってるよ」","f":"soleil"},{"t":"n","s":"三人の姿が、ふっと消えた。","f":"soleil"},{"t":"n","s":"焼け焦げた草の匂いだけが、残った。","f":"soleil"},{"t":"n","s":"莉花は、黙って、倒れた外套の人影を見つめていた。まるで、知っている顔を、確かめるように。","f":"rika"}]},{"key":"43-4","title":"爆心地","bg":"bg_forest","dark":true,"mood":"tense","bgm":"tense2","cast":["yohei","mumyo"],"lines":[{"t":"n","s":"丘を越えた先は、深くえぐれた地面だった。"},{"t":"n","s":"折れた木々。焼けた草。黒い煙が、まだ、もうもうと立ちのぼっている。"},{"t":"n","s":"その真ん中に、人影が立っていた。"},{"t":"n","s":"長身の男。黒い髪、冷たい目。去年の冬、耀平が戦った、あの男。","f":"yohei"},{"t":"d","s":"「……無明」","f":"yohei"},{"t":"d","s":"「久しぶりだな、耀平」","f":"yohei"},{"t":"n","s":"無明は、静かに笑った。その足元に、二つの影が、横たわっている。","f":"mumyo","m":"happy"},{"t":"n","s":"一人は、血まみれの教師だった。実技担当の、顔をよく知っている先生。服は裂け、腕が、おかしな方向に曲がっている。","f":"mumyo"},{"t":"d","s":"「……耀平、か」","f":"mumyo"},{"t":"n","s":"先生が、かすれた声で言った。","f":"mumyo"},{"t":"d","s":"「逃げろ……。お前たちの、敵う相手じゃ……」","f":"mumyo"},{"t":"d","s":"「先生」","f":"mumyo"},{"t":"d","s":"「逃げろ……！」","f":"mumyo"},{"t":"n","s":"もう一人は。","f":"mumyo"},{"t":"n","s":"薄紫の髪が、土の上に、広がっていた。","f":"mumyo"},{"t":"d","s":"「…………蛍、さん」","f":"mumyo"},{"t":"n","s":"耀平の喉から、掠れた声が漏れた。","f":"yohei"},{"t":"n","s":"蛍は、目を閉じていた。眠っているように。唇の端に、血が一筋。その胸には、深い刃の跡があった。","f":"hotaru"},{"t":"n","s":"見間違いだと、思いたかった。けれど、足が、動かなかった。","f":"hotaru"},{"t":"n","s":"小指を絡めた感触が、まだ、指先に残っていた。","f":"hotaru"},{"t":"d","s":"『島に着いたら、わたしのこと、守ってね』","f":"hotaru"},{"t":"d","s":"『デートも、忘れないでね』","f":"hotaru"},{"t":"d","s":"「…………あ」","f":"hotaru"},{"t":"n","s":"耀平の手から、花びらが、ぱらぱらとこぼれ落ちた。","f":"yohei"},{"t":"d","s":"「裏切り者には、相応の末路がある」","f":"yohei"},{"t":"n","s":"無明は、事もなげに言った。","f":"mumyo"},{"t":"d","s":"「この女は、SHITに寝返った。八天を売った。裏切り者は、殺す。それだけのことだ」","f":"mumyo"},{"t":"d","s":"「…………お前が」","f":"mumyo"},{"t":"d","s":"「そうだ」","f":"mumyo"},{"t":"n","s":"島の空は、まだ、白く明るかった。その明るさが、ひどく、場違いだった。","f":"mumyo"}]}]},{"n":44,"title":"夜桜繚蘭、朝を夜に変える","sub":"高校・2年6月","era":"high2","lead":"怒りと悲しみに揺れる耀平。果たせなかった約束を思い出したとき、島の朝が、夜に変わる。","scenes":[{"key":"44-1","title":"なぜ","bg":"bg_forest","dark":true,"mood":"tense","bgm":"tense2","cast":["yohei","mumyo"],"lines":[{"t":"d","s":"「……どうして」"},{"t":"n","s":"耀平の声は、自分のものではないみたいに、遠かった。","f":"yohei"},{"t":"d","s":"「どうして、こんなことをするんだ」","f":"yohei"},{"t":"n","s":"道化たちは、笑いながら人を焼いた。無明は、仲間だった人を、裏切り者と呼んで斬った。拘束された八天たちは、まとめて、殺された。","f":"soleil"},{"t":"d","s":"「お前らは、なんで、こんなことができるんだ」","f":"soleil"},{"t":"d","s":"「答える必要があるか」","f":"soleil"},{"t":"n","s":"無明は、冷たい目で、耀平を見下ろしていた。そこには、怒りも、喜びもなかった。ただ、ひどく静かな、底のない目だった。","f":"mumyo"},{"t":"d","s":"「強い者が残り、弱い者が消える。それだけのことだ。お前の祖父も、そう言わなかったか」","f":"mumyo"},{"t":"d","s":"「じいちゃんを、お前が語るな」","f":"mumyo"},{"t":"n","s":"耀平は、腰の刀を抜いた。無銘の刀。柄が、驚くほど、熱かった。","f":"yohei"},{"t":"n","s":"踏み込む。花びらが、一斉に宙を舞う。","f":"yohei"},{"t":"n","s":"無明は、片手を上げただけだった。見えない壁に、耀平の剣が、弾かれた。","f":"mumyo"},{"t":"n","s":"びりびりと、腕の骨に響く衝撃。","f":"mumyo"},{"t":"d","s":"「軽い」","f":"mumyo"},{"t":"d","s":"「まだだ」","f":"mumyo"},{"t":"n","s":"二撃目。三撃目。四撃目。一つとして、届かない。","f":"mumyo"},{"t":"d","s":"「怒りで振る剣は、鈍い。……あの女を守れなかった自分を、斬りたいのではないか」","f":"mumyo"},{"t":"d","s":"「黙れ！」","f":"mumyo"},{"t":"n","s":"叫んだ拍子に、足がもつれた。その隙に、黒い波動が、横から叩きつけられた。","f":"mumyo","fx":"shake"},{"t":"n","s":"耀平の体が、宙を舞い、地面に叩きつけられた。肺から、空気が、押し出される。口の中に、土と、血の味がした。","f":"yohei","fx":"shake"}]},{"key":"44-2","title":"果たせなかった約束","bg":"bg_forest","dark":false,"mood":"sad","bgm":"sad2","cast":["yohei"],"lines":[{"t":"n","s":"仰向けのまま、白い空を見上げた。"},{"t":"n","s":"木の葉の隙間から、朝の光が、容赦なく降ってくる。"},{"t":"i","s":"（蛍さん）"},{"t":"n","s":"廊下の窓辺で、蛍は言った。","f":"hotaru"},{"t":"d","s":"『合宿が終わったら、わたしと、デートしてくれる？』","f":"hotaru"},{"t":"d","s":"『もし、わたしが、ちゃんと生きて合宿を終えられたら、ご褒美が欲しいの』","f":"hotaru"},{"t":"n","s":"冗談だと、笑っていた。笑い終わるのが、少しだけ早かった。","f":"hotaru"},{"t":"d","s":"『場所は、わたしが決めるから』","f":"hotaru"},{"t":"n","s":"決まらなかった。もう、決まることはない。","f":"hotaru"},{"t":"i","s":"（約束、したのに）","f":"hotaru"},{"t":"n","s":"涙が、目尻から、こめかみへ流れ落ちた。","f":"hotaru","m":"sad"},{"t":"i","s":"（デート、行けなかった。守るって、言ったのに）","f":"hotaru"},{"t":"n","s":"悔しかった。悲しかった。その二つが、胸の中で、ぐちゃぐちゃに絡まって、どうしようもなく、熱かった。","f":"hotaru"},{"t":"n","s":"耀平は、刀を杖にして、ゆっくりと、体を起こした。膝が、笑っていた。","f":"yohei"},{"t":"n","s":"立ち上がった瞬間、不思議なほど、頭の中が、静かになった。","f":"yohei"}]},{"key":"44-3","title":"夜桜繚蘭","bg":"bg_forest","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["yohei","mumyo"],"lines":[{"t":"n","s":"目を閉じる。"},{"t":"d","s":"『桜って、夜の方が、強いんです』"},{"t":"n","s":"寮の屋上で、莉花が言った言葉が、浮かんだ。","f":"rika"},{"t":"d","s":"『夜桜は、月の光を借りて、一晩だけ、咲いているものですよね』","f":"rika"},{"t":"n","s":"柚月の声が、重なる。","f":"yuzuki"},{"t":"i","s":"（夜、か）","f":"yuzuki"},{"t":"n","s":"今は、朝だ。白い光の中だ。","f":"yuzuki"},{"t":"n","s":"それなら。","f":"yuzuki"},{"t":"d","s":"「夜に、すればいい」","f":"yuzuki"},{"t":"n","s":"耀平は、刀を、天に掲げた。","f":"yohei"},{"t":"n","s":"無銘の刀が、淡く、あたたかく光る。そのぬくもりが、掌から、腕へ、胸へ、全身に広がっていく。","f":"yohei"},{"t":"n","s":"花びらが、ひとひら、舞い上がった。","f":"yohei"},{"t":"n","s":"二枚、三枚、十枚、百枚。","f":"yohei"},{"t":"n","s":"風もないのに、花びらは、上へ、上へと昇っていく。視界が、桜色に染まっていく。朝の光が、どんどん、翳っていく。","f":"yohei"},{"t":"n","s":"無明の目が、初めて、わずかに見開かれた。","f":"mumyo"},{"t":"n","s":"空が、暗くなる。朝霧が、夜霧に変わる。木々の隙間から、冷たい月が、顔をのぞかせた。星が、一つ、また一つと、瞬き始める。","f":"yuzuki"},{"t":"cg","v":"cg_yozakura_ryoran"},{"t":"d","s":"「夜桜、繚蘭」","f":"yuzuki"},{"t":"n","s":"耀平の唇から、静かに、言葉が漏れた。","f":"yohei"},{"t":"n","s":"島のすべてが、夜に沈んだ。","f":"yohei"},{"t":"n","s":"朝だったはずの空に、満月が浮かんでいる。桜の花びらが、淡く光りながら、はらはらと舞い散る。","f":"yohei"}]},{"key":"44-4","title":"遠くで","bg":"bg_forest","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["ryoma","noa","tsukumo"],"lines":[{"t":"n","s":"北の岩場で、竜馬が、拳を止めて空を見上げた。","f":"ryoma"},{"t":"d","s":"「……夜？」","f":"ryoma"},{"t":"n","s":"足元には、凍上冬馬が倒れていた。凍った岩場は、竜馬の炎で、すっかり溶けて、湯気を上げている。","f":"ryoma"},{"t":"d","s":"「先輩、これ……」","f":"ryoma"},{"t":"d","s":"「耀平だ」","f":"ryoma"},{"t":"n","s":"竜馬は、にやりと笑いかけて、すぐに真顔になった。","f":"ryoma"},{"t":"d","s":"「あいつが、本気出してる。……何か、あったな」","f":"ryoma"},{"t":"n","s":"南の海岸で、乃亜が、空を見上げた。","f":"noa"},{"t":"n","s":"砂浜は、海水で洗い流されていた。毒の霧は、もうない。波打ち際に、毒島綾が、ずぶ濡れで気を失っている。","f":"noa"},{"t":"d","s":"「乃亜先輩……空が」","f":"noa"},{"t":"d","s":"「耀平の、夜桜」","f":"noa"},{"t":"n","s":"乃亜は、震える手を、胸に当てた。","f":"noa"},{"t":"d","s":"「……行かなきゃ」","f":"noa"},{"t":"n","s":"西の森では、霧が、晴れていた。","f":"noa"},{"t":"n","s":"夜の月光を浴びて、早乙女月の体が、淡く光っている。月光強化。霧に隠れていた第六席の本体が、くっきりと浮かび上がった。","f":"noa"},{"t":"d","s":"「見えたわ、会長」","f":"noa"},{"t":"d","s":"「ありがとう、早乙女さん。――結城くん」","f":"noa"},{"t":"d","s":"「了解。もう、覚えた」","f":"noa"},{"t":"n","s":"結城蒼の手の中に、無数の刃が生まれた。第二席の千刃万象を、そっくりそのまま写し取った刃だった。","f":"noa"},{"t":"d","s":"「返すよ。あんたの技だ」","f":"noa"},{"t":"n","s":"刃の雨が、霧ごと、二人の敵を呑み込んだ。","f":"noa"},{"t":"n","s":"九十九は、夜空を見上げた。満月の下に、桜の花びらが、舞っている。","f":"tsukumo"},{"t":"d","s":"「丘の向こうだ。全員、行こう」","f":"tsukumo"},{"t":"n","s":"その頃、丘の向こうで、無明が、ゆっくりと笑っていた。","f":"mumyo"},{"t":"d","s":"「面白い。夜を作るか」","f":"mumyo"},{"t":"n","s":"冷たい目が、桜色の夜を、見下ろしていた。","f":"mumyo"}]}]},{"n":45,"title":"一人じゃない","sub":"高校・2年6月","era":"high2","lead":"夜桜繚蘭をもってしても、無明は強い。苦戦する耀平のもとへ、仲間たちが駆けつける。","scenes":[{"key":"45-1","title":"届かない刃","bg":"bg_forest","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["mumyo","yohei"],"lines":[{"t":"d","s":"「はあああっ！」"},{"t":"n","s":"夜桜の花びらが、道を作る。足が地面を蹴るたびに、桜が弾けた。"},{"t":"n","s":"速い。さっきまでとは、まるで違う。一閃で、無明の障壁にひびが入る。二閃で、ひびが広がる。三閃で、障壁が砕けた。","f":"mumyo","fx":"shake"},{"t":"n","s":"けれど。","f":"mumyo"},{"t":"d","s":"「遅い」","f":"mumyo"},{"t":"n","s":"砕けた障壁の向こうで、無明は、もう、そこにいなかった。","f":"mumyo","fx":"shake"},{"t":"n","s":"背後。黒い刃が、耀平の背中を、浅く裂いた。","f":"yohei"},{"t":"d","s":"「ぐっ……！」","f":"yohei"},{"t":"d","s":"「夜を作ったのは、見事だ。だが、夜は、俺の領分でもある」","f":"yohei"},{"t":"n","s":"無明の足元から、闇が、にじみ出した。夜桜の月明かりを、黒く塗り潰すように。","f":"mumyo"},{"t":"d","s":"「天冠の頃から、俺は夜の中で生きてきた。お前の夜は、まだ、浅い」","f":"mumyo"},{"t":"n","s":"闇の刃が、四方から迫る。耀平は、花びらで受け、刀で弾き、それでも、一本、二本と、体をかすめていく。","f":"yohei"},{"t":"i","s":"（強い……）","f":"yohei"},{"t":"n","s":"去年の冬とは、まるで違った。あの時、無明は、本気ではなかったのだと、今さら分かる。","f":"mumyo"},{"t":"n","s":"膝が、地面についた。息が、上がる。","f":"mumyo"},{"t":"d","s":"「終わりだ」","f":"mumyo"},{"t":"n","s":"無明が、黒い刃を振り上げた。","f":"mumyo"}]},{"key":"45-2","title":"炎、水、雪","bg":"bg_forest","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["ryoma","noa","yohei"],"lines":[{"t":"n","s":"その刃を、炎が、横から殴りつけた。"},{"t":"d","s":"「させるかよ！」"},{"t":"n","s":"竜馬だった。燃え盛る拳で、黒い刃を弾き飛ばす。服のあちこちが、凍りついて白くなっていた。","f":"ryoma"},{"t":"d","s":"「竜馬……！」","f":"ryoma"},{"t":"d","s":"「七席は、片づけてきた。遅くなったな」","f":"ryoma"},{"t":"n","s":"次の瞬間、竜馬に迫った闇を、水の奔流が押し流した。","f":"ryoma"},{"t":"d","s":"「――碧水心希」","f":"ryoma"},{"t":"n","s":"乃亜だった。髪から、まだ、海水のしずくが垂れている。","f":"noa"},{"t":"d","s":"「八席も。……毒なんて、流しちゃえば、ただの水」","f":"noa"},{"t":"n","s":"乃亜は、膝をついた耀平の前に、立った。それから、振り返らずに言った。","f":"noa"},{"t":"d","s":"「耀平、一人じゃないよ」","f":"noa"},{"t":"n","s":"その声は、少しだけ、震えていた。","f":"noa"},{"t":"d","s":"「……乃亜」","f":"noa"},{"t":"d","s":"「蛍さんのこと、見た。……だから、一人で抱えないで」","f":"noa"},{"t":"n","s":"柚月が、そっと、耀平の背中に手を置いた。淡雪が、傷口に降りる。痛みが、すうっと、遠のいていった。","f":"yuzuki"},{"t":"d","s":"「拒絶、です。少しの間だけ、痛みを、ここから先には通しません」","f":"yuzuki"},{"t":"d","s":"「柚月……」","f":"yuzuki"},{"t":"d","s":"「隣の席の人を、一人で戦わせたりしません」","f":"yuzuki"}]},{"key":"45-3","title":"会長の意地","bg":"bg_forest","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["tsukumo","mumyo","ryoma"],"lines":[{"t":"d","s":"「やれやれ。主役の座は、譲ってもらえないみたいだね」"},{"t":"n","s":"森の奥から、新生徒会の六人が現れた。先頭の九十九の制服は、あちこちが裂けている。","f":"tsukumo"},{"t":"d","s":"「第二席と第六席は、片づけた。こっちも、少しは役に立たないとね」","f":"tsukumo"},{"t":"d","s":"「九十九……」","f":"tsukumo"},{"t":"d","s":"「僕は、会長だからね」","f":"tsukumo"},{"t":"n","s":"九十九は、眼鏡を外して、胸ポケットにしまった。穏やかな顔から、笑みが、すっと消える。","f":"tsukumo"},{"t":"d","s":"「会長の意地を、見せるよ。――九十九変化」","f":"tsukumo"},{"t":"n","s":"九十九の姿が、揺らいだ。次の瞬間、九十九は、北条の石壁を、久我の磁力を、早乙女の月光を、次々と纏いながら、無明の闇に飛び込んでいった。","f":"tsukumo"},{"t":"d","s":"「ほう。器用な小僧だ」","f":"tsukumo"},{"t":"d","s":"「器用なのが、取り柄でね」","f":"tsukumo"},{"t":"n","s":"さらに、その後ろから。","f":"tsukumo"},{"t":"d","s":"「おい、夜桜！　まだ生きてるか！」","f":"tsukumo"},{"t":"n","s":"嵐堂刃だった。妹の灯里と、白鷺女学園の雪乃、麗華も一緒だ。","f":"tsukumo"},{"t":"d","s":"「勝手に死なれちゃ、困るんだよ。次は勝つって、言っただろ」","f":"tsukumo"},{"t":"d","s":"「……刃」","f":"tsukumo"},{"t":"d","s":"「借りは、ここで返す。学園の連中だけに、いいところを持っていかれてたまるか」","f":"tsukumo"},{"t":"n","s":"刃の雷が、無明の側面を打った。灯里が、雷鳴結界で、竜馬と乃亜を闇から守る。雪乃の氷の花びらが、無明の足元を凍らせ、麗華の炎の蓮が、その上で弾けた。","f":"mumyo"},{"t":"d","s":"「まったく、学園の方々は、無茶をなさいますわね！」","f":"mumyo"},{"t":"d","s":"「麗華さん、文句を言いながら、一番前に出ていますよ」","f":"mumyo"},{"t":"d","s":"「う、うるさいですわ！」","f":"mumyo"},{"t":"n","s":"無明の闇が、四方から押し返されていく。","f":"mumyo"}]},{"key":"45-4","title":"行け","bg":"bg_forest","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["yohei","ryoma","noa"],"lines":[{"t":"d","s":"「隙ができた」"},{"t":"n","s":"竜馬が、耀平の腕を掴んで、引き起こした。","f":"ryoma"},{"t":"d","s":"「一瞬だけだ。みんなで、こじ開ける」","f":"ryoma"},{"t":"d","s":"「竜馬」","f":"ryoma"},{"t":"d","s":"「行け」","f":"ryoma"},{"t":"n","s":"竜馬は、それだけ言って、耀平の背中を、どんと押した。","f":"ryoma"},{"t":"d","s":"「お前の剣だ。お前が、決めろ」","f":"ryoma"},{"t":"n","s":"乃亜が、頷いた。柚月が、微笑んだ。九十九が、闇の中から、片手を上げた。","f":"noa","m":"happy"},{"t":"n","s":"刃が叫ぶ。","f":"noa"},{"t":"d","s":"「行け、夜桜！」","f":"noa"},{"t":"n","s":"耀平は、刀を握り直した。","f":"yohei"},{"t":"n","s":"一人では、届かなかった。けれど、今は、違う。","f":"yohei"},{"t":"n","s":"背中が、温かかった。","f":"yohei"},{"t":"d","s":"「……ありがとう、みんな」","f":"yohei"},{"t":"n","s":"夜桜の花びらが、一斉に、耀平の刀に集まった。","f":"yohei"}]}]},{"n":46,"title":"止められた剣","sub":"高校・2年6月","era":"high2","lead":"仲間がこじ開けた一瞬。耀平の刀は、確かに無明に届くはずだった。それを止めたのは、隣にいた後輩だった。","scenes":[{"key":"46-1","title":"追い詰める","bg":"bg_forest","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["mumyo","yohei"],"lines":[{"t":"n","s":"耀平は、地面を蹴った。","f":"yohei"},{"t":"n","s":"闇の壁が、仲間たちの技に削られて、薄くなっている。その一点に、花びらの道が、まっすぐに伸びた。","f":"yohei"},{"t":"d","s":"「はあああっ！」","f":"yohei"},{"t":"n","s":"一閃。無明の黒い刃が、根元から折れた。","f":"mumyo","fx":"flash"},{"t":"n","s":"二閃。無明の外套が、肩口から裂けた。","f":"mumyo"},{"t":"n","s":"無明が、初めて、後ろへ下がった。足が、わずかにもつれる。","f":"mumyo"},{"t":"d","s":"「……ぬ」","f":"mumyo"},{"t":"d","s":"「まだだ！」","f":"mumyo"},{"t":"n","s":"三閃。無明の頬に、深い傷が走った。赤い血が、月光の下で、黒く光る。","f":"mumyo"},{"t":"n","s":"押している。","f":"mumyo"},{"t":"n","s":"周りの音が、遠くなった。仲間たちの声も、技のぶつかり合う音も。目の前には、無明の顔だけがあった。","f":"mumyo"},{"t":"i","s":"（蛍さん）","f":"mumyo"},{"t":"n","s":"刀を、大きく振りかぶる。花びらが、刃に集まって、淡く光った。","f":"mumyo","fx":"flash"},{"t":"i","s":"（いける）","f":"mumyo"},{"t":"n","s":"届く。","f":"mumyo"},{"t":"n","s":"確信が、全身を貫いた。","f":"mumyo"},{"t":"d","s":"「これで――」","f":"mumyo"}]},{"key":"46-2","title":"金属の音","bg":"bg_forest","dark":true,"mood":"tense","bgm":"tense1","cast":["yohei","rika","mumyo"],"lines":[{"t":"n","s":"キン、と。"},{"t":"n","s":"澄んだ音が、夜の森に響いた。"},{"t":"n","s":"耀平の刀が、止まっていた。","f":"yohei"},{"t":"cg","v":"cg_rika_block"},{"t":"n","s":"細い刀が、真横から、耀平の刃を受け止めていた。柄に、紫の花の模様。","f":"yohei"},{"t":"d","s":"「…………は？」","f":"yohei"},{"t":"n","s":"耀平は、目の前の光景が、理解できなかった。","f":"yohei"},{"t":"n","s":"莉花だった。","f":"rika"},{"t":"n","s":"小さな体が、無明の前に、立ちはだかっている。耀平の渾身の一撃を、片手の刀だけで、受け止めて。","f":"mumyo"},{"t":"n","s":"いつもの笑顔は、なかった。","f":"mumyo"},{"t":"n","s":"甘い声も、語尾のハートも、くるくると変わる表情も、何もなかった。ただ、真っ白な無表情が、月光の下で、耀平を見上げていた。","f":"yohei"},{"t":"d","s":"「…………莉花？」","f":"yohei"},{"t":"n","s":"返事は、なかった。","f":"yohei"},{"t":"n","s":"刃と刃が、かち合ったまま、震えている。莉花の力は、微塵も、揺らがなかった。","f":"rika"}]},{"key":"46-3","title":"凍りつく夜","bg":"bg_forest","dark":true,"mood":"tense","bgm":"tense1","cast":["rika","yohei","noa"],"lines":[{"t":"n","s":"周りの戦いが、一斉に、止まった。"},{"t":"d","s":"「え……」"},{"t":"d","s":"「今、莉花さんが……」"},{"t":"n","s":"乃亜の手から、水が、ぱしゃりと地面にこぼれ落ちた。柚月は、口元を両手で覆ったまま、動けなかった。","f":"noa"},{"t":"n","s":"竜馬が、低く唸った。","f":"ryoma"},{"t":"d","s":"「おい……何の冗談だ、そりゃ」","f":"ryoma"},{"t":"n","s":"九十九が、闇から離れて、着地した。その目が、鋭く細められる。","f":"tsukumo"},{"t":"d","s":"「……なるほど。そういうことか」","f":"tsukumo"},{"t":"n","s":"刃が、雷を纏ったまま、立ち尽くした。","f":"tsukumo"},{"t":"d","s":"「おい、夜桜のペアだろ、あいつ。何で、敵を庇って……」","f":"tsukumo"},{"t":"n","s":"誰も、答えられなかった。","f":"tsukumo"},{"t":"n","s":"莉花は、ゆっくりと、刀を押し返した。耀平の体が、一歩、後ろへ下がる。","f":"rika"},{"t":"d","s":"「どうして」","f":"rika"},{"t":"n","s":"耀平の声が、震えた。","f":"yohei"},{"t":"d","s":"「どうして、莉花が」","f":"yohei"},{"t":"n","s":"莉花は、答えなかった。無表情のまま、刀を構え直す。その切っ先は、耀平の胸に、まっすぐ向けられていた。","f":"rika"},{"t":"n","s":"背後で、無明が、くつくつと笑った。","f":"mumyo","m":"happy"},{"t":"d","s":"「……やっと、出てきたか」","f":"mumyo"},{"t":"n","s":"夜桜の花びらが、二人の間を、はらはらと落ちていった。","f":"mumyo"}]}]},{"n":47,"title":"第一席","sub":"高校・2年6月","era":"high2","lead":"莉花は、みんなの前で、自分の正体を告げる。そして、もう一度、耀平を庇う。","scenes":[{"key":"47-1","title":"名乗り","bg":"bg_forest","dark":true,"mood":"tense","bgm":"tense1","cast":["rika","noa","yohei"],"lines":[{"t":"d","s":"「改めまして」"},{"t":"n","s":"莉花は、刀を下ろさないまま、小さく頭を下げた。","f":"rika"},{"t":"n","s":"まるで、自動販売機の前で初めて会った日のように。けれど、その声には、甘さが一滴もなかった。","f":"rika"},{"t":"d","s":"「新八天、第一席。莉花です」","f":"rika"},{"t":"n","s":"夜の森が、しんと静まり返った。","f":"rika"},{"t":"d","s":"「…………え」","f":"rika"},{"t":"d","s":"「第一席って……」","f":"rika"},{"t":"d","s":"「新八天の、一番上……？」","f":"rika"},{"t":"n","s":"ざわめきが、さざ波のように広がる。乃亜が、一歩、前に出かけて、止まった。","f":"noa"},{"t":"d","s":"「嘘でしょ……」","f":"noa"},{"t":"n","s":"耀平は、何も言えなかった。","f":"yohei"},{"t":"n","s":"頭の中で、いくつもの場面が、ぐるぐると回る。自販機の前の笑顔。河原の特訓。屋上の夜風。船の上のピアノ。手を握ってほしいと言った、震える指。","f":"yohei"},{"t":"n","s":"全部が、嘘だったのか。","f":"yohei"},{"t":"d","s":"「最初から、か」","f":"yohei"},{"t":"n","s":"やっと出た声は、掠れていた。","f":"yohei"},{"t":"d","s":"「最初から、そのつもりで、おれに近づいたのか」","f":"yohei"},{"t":"d","s":"「はい。学園に潜り込むために、一年生として入学しました。せんぱいのペアになったのも、計画のうちです」","f":"yohei"},{"t":"n","s":"莉花は、淡々と答えた。","f":"rika"},{"t":"d","s":"「新八天の襲撃の日取りも、知っていました。ソレイユのことも、無明さんのことも」","f":"rika"},{"t":"d","s":"「蛍さんのことも、か」","f":"rika"},{"t":"n","s":"莉花の睫毛が、ほんの一瞬だけ、震えた。","f":"rika"},{"t":"d","s":"「……蛍さんのことは、知りませんでした」","f":"rika"},{"t":"n","s":"その一言だけが、無表情の仮面に、細いひびを入れた。","f":"rika"}]},{"key":"47-2","title":"それは事実です","bg":"bg_forest","dark":true,"mood":"tense","bgm":"tense1","cast":["rika","yohei","noa"],"lines":[{"t":"d","s":"「でも」"},{"t":"n","s":"莉花が、顔を上げた。","f":"rika"},{"t":"d","s":"「せんぱいのことは、本当に好きですよ」","f":"rika"},{"t":"n","s":"月光の下で、莉花の瞳が、まっすぐに耀平を射抜いた。","f":"rika"},{"t":"d","s":"「愛しています。わたしのものにしたい。……それは、事実です」","f":"rika"},{"t":"n","s":"その言葉は、甘くなかった。重かった。ずしりと、胸の底に沈むような重さだった。","f":"rika"},{"t":"n","s":"耀平は、一歩、後ずさった。","f":"yohei"},{"t":"i","s":"（何を、信じればいい）","f":"yohei"},{"t":"n","s":"好きだと言われて、嬉しいはずがなかった。信じたいと思うほど、足元が崩れていく。","f":"yohei"},{"t":"d","s":"「せんぱい」","f":"yohei"},{"t":"n","s":"莉花が、呼んだ。いつもと同じ呼び方。それなのに、その一言に、耀平の肩が、びくりと跳ねた。","f":"rika"},{"t":"d","s":"「……やめてくれ」","f":"rika"},{"t":"d","s":"「せんぱい」","f":"rika"},{"t":"d","s":"「その呼び方、やめてくれ……」","f":"rika"},{"t":"n","s":"耀平は、刀を握る手に、力が入らなかった。膝が、また、崩れそうになる。","f":"yohei"},{"t":"n","s":"乃亜が、唇を噛んで、莉花を睨んだ。","f":"noa","m":"anger"},{"t":"d","s":"「……ふざけないで」","f":"noa"},{"t":"n","s":"柚月は、乃亜の袖を握りしめたまま、何も言えずにいた。その目に、怒りと、戸惑いと、言葉にならない何かが、混ざっていた。","f":"yuzuki"}]},{"key":"47-3","title":"もう一度","bg":"bg_forest","dark":true,"mood":"tense","bgm":"tense1","cast":["rika","mumyo","yohei"],"lines":[{"t":"d","s":"「くだらん」"},{"t":"n","s":"背後で、無明が、吐き捨てた。","f":"mumyo"},{"t":"d","s":"「第一席の役目は、果たした。もう、いい」","f":"mumyo"},{"t":"n","s":"無明の手に、黒い刃が生まれた。その切っ先が、狙ったのは、膝をつきかけた耀平だった。","f":"mumyo"},{"t":"n","s":"闇が、一直線に走る。","f":"mumyo"},{"t":"d","s":"「――せんぱいっ！」","f":"mumyo"},{"t":"n","s":"莉花の体が、跳んだ。","f":"rika"},{"t":"n","s":"耀平の前に、小さな背中が、飛び込んでくる。細い刀が、闇の刃を、真っ二つに裂いた。裂けた闇が、耀平の左右を、すり抜けていく。","f":"yohei"},{"t":"n","s":"莉花の肩が、切れていた。袖に、赤い染みが、じわりと広がる。","f":"rika"},{"t":"d","s":"「…………莉花？」","f":"rika"},{"t":"n","s":"莉花は、振り返らなかった。無明を、まっすぐに見据えていた。","f":"rika"},{"t":"n","s":"無明の目が、見開かれていた。初めて見せる、本物の驚きだった。","f":"mumyo"},{"t":"d","s":"「……貴様。何のつもりだ」","f":"mumyo"},{"t":"d","s":"「言ったでしょう、無明さん」","f":"mumyo"},{"t":"n","s":"莉花の声が、凛と響いた。","f":"rika"},{"t":"d","s":"「この人は、わたしのものです。あなたにも、渡しません」","f":"rika"},{"t":"d","s":"「血迷ったか、第一席」","f":"rika"},{"t":"d","s":"「いいえ。最初から、ずっと、正気です」","f":"rika"},{"t":"n","s":"莉花は、肩の血を拭いもせずに、ゆっくりと、全員を見回した。","f":"rika"},{"t":"n","s":"乃亜。柚月。竜馬。九十九たち。他校の生徒たち。そして、耀平。","f":"noa"},{"t":"d","s":"「みなさんに、聞いてほしい話が、あります」","f":"noa"},{"t":"n","s":"夜桜の花びらが、莉花の髪に、ひとひら、落ちた。","f":"rika"},{"t":"d","s":"「ある少女の話を、しましょう」","f":"rika"}]}]},{"n":48,"title":"ある少女の話","sub":"高校・2年6月","era":"high2","lead":"莉花が語るのは、祖父の工房と、ある冬の出来事。そして、その話を遮るように、道化が笑う。","scenes":[{"key":"48-1","title":"工房の少女","bg":"bg_forest","dark":true,"mood":"night","bgm":"night2","cast":["rika"],"lines":[{"t":"d","s":"「むかし、街の外れに、小さな刀鍛冶の工房がありました」"},{"t":"n","s":"莉花の声は、物語を読み聞かせるように、穏やかだった。","f":"rika"},{"t":"d","s":"「そこには、おじいちゃんと、孫の女の子が、二人で暮らしていました。女の子の両親は、小さい頃に亡くなっていて、おじいちゃんだけが、家族でした」","f":"rika"},{"t":"n","s":"夜の森が、静まり返っている。誰も、口を挟まなかった。","f":"rika"},{"t":"d","s":"「おじいちゃんは、無口で、腕のいい職人でした。女の子は、工房の奥の部屋から、槌の音を聞きながら育ちました。おやつの時間になると、おじいちゃんは、決まって、『休憩だぞ』って、笑ってくれました」","f":"rika"},{"t":"n","s":"莉花は、ほんの少しだけ、目を細めた。","f":"rika"},{"t":"d","s":"「ある冬の日。工房に、黒いコートの大人たちが、来ました」","f":"rika"}]},{"key":"48-2","title":"冬の日","bg":"bg_forest","dark":true,"mood":"night","bgm":"night2","cast":["rika","noa","tsukumo"],"lines":[{"t":"d","s":"「銀の紋章をつけた人たちでした」"},{"t":"n","s":"その一言に、何人かが、はっと顔を上げた。銀の紋章。黒いコート。この場にいる誰もが、見覚えのある姿だった。"},{"t":"d","s":"「その人たちは、ある事件の犯人を、追っていました。危険な武器を作って、悪い人たちに流している職人がいる、と。……おじいちゃんが、その職人だと、思われたんです」"},{"t":"d","s":"「……違ったのか」と、竜馬が、低く尋ねた。"},{"t":"d","s":"「違いました。人違いでした」"},{"t":"n","s":"莉花は、淡々と言った。","f":"rika"},{"t":"d","s":"「おじいちゃんは、何も知らないと言いました。何度も、何度も。でも、聞いてもらえませんでした。工房は荒らされて、おじいちゃんは連れていかれて……三日後に、帰ってきました」","f":"rika"},{"t":"n","s":"莉花の指が、刀の柄を、ぎゅっと握った。","f":"rika"},{"t":"d","s":"「冷たくなって」","f":"rika"},{"t":"n","s":"乃亜が、小さく息を呑んだ。","f":"noa","m":"surprise"},{"t":"d","s":"「書類には、『老衰』と書かれていました。前の日まで、元気に槌を振るっていた人が、です。……後で、本当の犯人は、別の街で捕まりました。でも、誰も、謝りには来ませんでした」","f":"noa"},{"t":"d","s":"「そんな……」","f":"noa"},{"t":"d","s":"「SHITと、学園が、隠したんです。間違えて人を殺したなんて、公になったら、組織が持たないから」","f":"noa"},{"t":"n","s":"その言葉に、全員が、息を止めた。","f":"noa"},{"t":"n","s":"刃が、呆然と呟く。","f":"noa"},{"t":"d","s":"「SHITが……？　学園も……？」","f":"noa"},{"t":"d","s":"「はい」","f":"noa"},{"t":"n","s":"莉花は、静かに頷いた。","f":"rika"},{"t":"d","s":"「女の子は、それを知ってしまいました。偶然、聞いてしまったんです。大人たちが、『あれは、なかったことにする』と話しているのを」","f":"rika"},{"t":"n","s":"九十九の顔から、表情が消えていた。柚月は、乃亜の袖を握りしめたまま、震えていた。","f":"tsukumo"},{"t":"n","s":"耀平は、黙って聞いていた。胸のどこかが、小さく、ざわついた。","f":"yohei"},{"t":"i","s":"（老衰）","f":"yohei"},{"t":"n","s":"けれど、その引っかかりが、自分のことと繋がる前に、莉花の声が、続いた。","f":"rika"}]},{"key":"48-3","title":"同じ目的","bg":"bg_forest","dark":true,"mood":"night","bgm":"night2","cast":["mumyo","rika","yohei"],"lines":[{"t":"d","s":"「女の子は、誓いました。真実を、暴いてやるって。そのために、力を手に入れました。たとえ、悪の組織に身を置くことになっても」"},{"t":"n","s":"無明が、鼻で笑った。","f":"mumyo","m":"happy"},{"t":"d","s":"「なるほどな。それで、俺についたというわけか。SHITと学園を潰すという、同じ目的のために」","f":"mumyo"},{"t":"d","s":"「そうです！」","f":"mumyo"},{"t":"n","s":"莉花は、明るく答えた。いつもの、甘い声で。","f":"rika"},{"t":"n","s":"一瞬だけ。ほんの一瞬だけ、その笑顔が、耀平の方を向いた。その目は、少しも笑っていなかった。","f":"yohei"},{"t":"i","s":"（……演技だ）","f":"yohei"},{"t":"n","s":"なぜか、耀平には、それが分かった。","f":"yohei"},{"t":"d","s":"「ならば、なぜ」","f":"yohei"},{"t":"n","s":"無明の声が、冷たくなった。","f":"mumyo"},{"t":"d","s":"「なぜ、その小僧を庇う。そいつは、学園の人間だ」","f":"mumyo"},{"t":"d","s":"「決まってるじゃないですか」","f":"mumyo"},{"t":"n","s":"莉花は、首をかしげて、にっこりと笑った。","f":"rika","m":"happy"},{"t":"d","s":"「愛してるからですよ？」","f":"rika"}]},{"key":"48-4","title":"あのときの鍛冶屋","bg":"bg_forest","dark":true,"mood":"night","bgm":"night2","cast":["rika","noa","yohei"],"lines":[{"t":"n","s":"莉花は、耀平の方へ、向き直った。","f":"rika"},{"t":"d","s":"「その女の子の工房に、一度だけ、お客さんが来たことがあります。中学一年の、冬。先生に紹介されたっていう、男の子と、女の子が」","f":"rika"},{"t":"n","s":"乃亜の肩が、びくりと跳ねた。","f":"noa"},{"t":"d","s":"「男の子は、一本ずつ、刀を握っていきました。ゆっくり、慎重に。わたし、奥の障子の隙間から、ずっと見ていたんです」","f":"noa"},{"t":"n","s":"莉花の声が、ほんの少しだけ、甘さを取り戻した。","f":"rika"},{"t":"d","s":"「黒い鞘の、地味な刀を握った時でした。窓の隙間から、桜の花びらが、ひらりと入ってきて。男の子は、それを、すごく優しい顔で、見上げたんです」","f":"rika"},{"t":"n","s":"莉花は、胸に手を当てた。","f":"rika"},{"t":"d","s":"「一目惚れでした。……おじいちゃんに、聞いたんです。『ねえ、おじいちゃん、今の子は？』って」","f":"rika"},{"t":"n","s":"乃亜が、震える声で、呟いた。","f":"noa"},{"t":"d","s":"「……あのときの、鍛冶屋……」","f":"noa"},{"t":"d","s":"「はい」","f":"noa"},{"t":"d","s":"「無銘の刀を、くれた……あの、おじいさんの」","f":"noa"},{"t":"d","s":"「はい。わたしの、おじいちゃんです」","f":"noa"},{"t":"n","s":"乃亜は、口元を押さえて、立ち尽くした。","f":"noa"},{"t":"n","s":"耀平は、腰の刀に、そっと手を触れた。","f":"yohei"},{"t":"n","s":"無銘の刀は、静かに、あたたかかった。あの日と、同じ温度だった。","f":"yohei"},{"t":"d","s":"「あの人たちが来たのは、その、一週間後でした」","f":"yohei"},{"t":"n","s":"莉花は、小さく微笑んだ。泣きそうな、笑顔だった。","f":"rika","m":"sad"},{"t":"d","s":"「だから、わたしにとって、せんぱいは、おじいちゃんが最後にくれた、思い出なんです」","f":"rika"}]},{"key":"48-5","title":"やっほー","bg":"bg_forest","dark":true,"mood":"battle","bgm":"battle2","cast":["soleil","yohei"],"lines":[{"t":"n","s":"その時だった。"},{"t":"d","s":"「やっほー⭐︎」"},{"t":"n","s":"軽やかな声が、森の上から、降ってきた。"},{"t":"n","s":"全員が、一斉に見上げる。木の枝の上に、小柄な道化が、ちょこんと座っていた。","f":"soleil"},{"t":"d","s":"「いいお話だったねえ⭐︎　感動しちゃった」","f":"soleil"},{"t":"n","s":"道化の足元、木の根元に、一人の生徒が、へたり込んでいた。蒼嵐学院の制服。逃げ遅れた、一年生だった。","f":"soleil"},{"t":"d","s":"「ひっ……」","f":"soleil"},{"t":"d","s":"「でもね、長いんだもん。退屈しちゃった⭐︎」","f":"soleil"},{"t":"n","s":"道化が、指先で、とん、と少年の背中に触れた。","f":"soleil"},{"t":"d","s":"「待――」","f":"soleil"},{"t":"n","s":"耀平が叫んだのと、同時だった。","f":"yohei"},{"t":"n","s":"少年の胸を、何かが、貫いた。","f":"yohei"},{"t":"n","s":"光のような、爆ぜるような、何か。少年は、自分の胸を見下ろした。不思議そうに。それから、ゆっくりと、地面に崩れ落ちた。","f":"yohei"},{"t":"d","s":"「いやあああっ！」","f":"yohei"},{"t":"n","s":"灯里の悲鳴が、夜の森を裂いた。","f":"yohei"},{"t":"n","s":"刃が、雷を纏って、跳ねるように駆け出す。","f":"yohei"},{"t":"d","s":"「てめえ……！　うちの、一年を……！」","f":"yohei"},{"t":"n","s":"道化は、くるりと宙返りして、別の枝に飛び移った。","f":"soleil"},{"t":"n","s":"けたけたけた、と笑い声が、夜に響いた。","f":"soleil"},{"t":"d","s":"「やっほー⭐︎　三つ巴、まだまだ、これからだよ⭐︎」","f":"soleil"}]}]},{"n":49,"title":"万花雷鳴、万花一閃","sub":"高校・2年6月","era":"high2","lead":"混乱の中で、竜馬だけが動く。SHITが駆けつけ、仲間が莉花を抑え、耀平は、初めて「技」を放つ。","scenes":[{"key":"49-1","title":"竜馬だけが","bg":"bg_forest","dark":true,"mood":"battle","bgm":"battle2","cast":["ryoma","yohei","todo"],"lines":[{"t":"n","s":"誰も、動けなかった。"},{"t":"n","s":"莉花の正体。隠された死。目の前で殺された一年生。ばらばらの感情が、全員の足を、地面に縫い止めていた。","f":"rika"},{"t":"n","s":"ただ一人、竜馬だけが、動いた。","f":"ryoma"},{"t":"d","s":"「耀平」","f":"ryoma"},{"t":"n","s":"竜馬は、耀平の胸ぐらを掴んで、引き寄せた。","f":"ryoma"},{"t":"d","s":"「動けるか」","f":"ryoma"},{"t":"d","s":"「…………」","f":"ryoma"},{"t":"d","s":"「今、気持ちがいろいろあるのは分かる。おれもだ。頭ん中、ぐちゃぐちゃだ」","f":"ryoma"},{"t":"n","s":"竜馬の目は、真っ赤だった。それでも、声は、揺れていなかった。","f":"ryoma"},{"t":"d","s":"「でも、無明を倒すのが最優先だ。あいつを放っといたら、もっと死ぬ」","f":"ryoma"},{"t":"d","s":"「……竜馬」","f":"ryoma"},{"t":"d","s":"「莉花のことは、後だ。全部、後で聞く。だから、今は」","f":"ryoma"},{"t":"n","s":"竜馬は、耀平の胸を、拳で軽く叩いた。","f":"ryoma"},{"t":"d","s":"「お前ならやれる」","f":"ryoma"},{"t":"n","s":"その時、森の向こうから、無数の足音が近づいてきた。","f":"ryoma"},{"t":"d","s":"「SHITだ！」","f":"ryoma"},{"t":"d","s":"「船から、来てくれた！」","f":"ryoma"},{"t":"n","s":"黒いコートの隊員たちが、木々の間からなだれ込んでくる。先頭に立つのは、藤堂だった。","f":"todo"},{"t":"d","s":"「ソレイユを抑えろ！　生徒には近づけるな！」","f":"todo"},{"t":"n","s":"隊員たちが、木の上の道化を取り囲んだ。けたけたと笑う声が、銃声と、閃光に呑まれていく。","f":"soleil","fx":"flash","m":"happy"},{"t":"n","s":"藤堂の目が、耀平を捉えた。","f":"todo"},{"t":"d","s":"「耀平！　やれ！」","f":"todo"}]},{"key":"49-2","title":"抑える手","bg":"bg_forest","dark":true,"mood":"battle","bgm":"battle2","cast":["rika","noa","yohei"],"lines":[{"t":"d","s":"「させません」"},{"t":"n","s":"莉花が、刀を構えて、耀平と無明の間に、再び立った。","f":"rika"},{"t":"d","s":"「せんぱいは、渡しません。無明さんにも、誰にも」","f":"rika"},{"t":"d","s":"「どけ、莉花」","f":"rika"},{"t":"d","s":"「どきません」","f":"rika"},{"t":"n","s":"その莉花を、水の鎖が、横から絡め取った。","f":"rika"},{"t":"d","s":"「――悪いけど、どいてもらう」","f":"rika"},{"t":"n","s":"乃亜だった。碧水心希の水が、莉花の両腕に巻きつく。","f":"noa"},{"t":"d","s":"「乃亜先輩……」","f":"noa"},{"t":"d","s":"「話は、後で、全部聞く。でも今は、耀平の邪魔をさせない」","f":"noa"},{"t":"n","s":"莉花が、刀で水を断ち切ろうとする。その刃を、柚月の淡雪が、ふわりと受け止めた。","f":"rika"},{"t":"d","s":"「拒絶、です。……莉花さん、ごめんなさい」","f":"rika"},{"t":"n","s":"竜馬が、莉花の背後に回り込み、両肩を押さえた。刃と灯里の雷鳴結界が、さらにその外側を囲む。雪乃の氷が、莉花の足元を、地面に縫い止めた。","f":"ryoma"},{"t":"d","s":"「くっ……」","f":"ryoma"},{"t":"n","s":"莉花は、もがいた。けれど、何重にも重なった力が、小さな体を、しっかりと押さえ込んでいた。","f":"rika"},{"t":"n","s":"莉花は、乃亜を見上げて、ぼそりと呟いた。","f":"rika"},{"t":"d","s":"「……泥棒猫」","f":"rika"},{"t":"d","s":"「どっちが」","f":"rika"},{"t":"n","s":"乃亜は、ふいと顔をそむけた。","f":"noa"},{"t":"n","s":"少し離れた場所では、九十九が、細身の道化と、刃を交えていた。影から影へと跳ぶ相手を、九十九は、次々と姿を変えながら追いかけている。","f":"tsukumo"},{"t":"d","s":"「君は、なかなか、捕まらないね」","f":"tsukumo"},{"t":"d","s":"「なんや、おもろい兄ちゃんやな」","f":"tsukumo"}]},{"key":"49-3","title":"回想","bg":"bg_forest","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["yohei"],"lines":[{"t":"n","s":"耀平は、目を閉じた。","f":"yohei"},{"t":"n","s":"船の上で、みんなに聞いて回った言葉が、浮かんでくる。","f":"yohei"},{"t":"d","s":"『誰かを傷つけるための剣じゃなくて、守るための剣。それが、一番強いと思う』","f":"yohei"},{"t":"n","s":"乃亜の声。","f":"noa"},{"t":"d","s":"『もっと、出してみろ。百枚でも、千枚でも』","f":"noa"},{"t":"d","s":"『雷みたいに、花と花を、繋げてみろ』","f":"noa"},{"t":"n","s":"竜馬の声。","f":"ryoma"},{"t":"d","s":"『夜桜は、月の光を借りて、一晩だけ、咲いているものですよね』","f":"ryoma"},{"t":"n","s":"柚月の声。","f":"yuzuki"},{"t":"d","s":"『その技が、できたら、一番最初に、見せてくださいね』","f":"yuzuki"},{"t":"n","s":"莉花の声。","f":"rika"},{"t":"n","s":"そして、地下のガラスの向こうで、老人が言った言葉。","f":"rika"},{"t":"d","s":"『状態ではなく、技を作れ。決め手を、二つ三つ持て』","f":"rika"},{"t":"i","s":"（花びらを、増やす。繋げる。守るために）","f":"rika"},{"t":"n","s":"耀平は、目を開けた。","f":"yohei"},{"t":"d","s":"「夜桜――」","f":"yohei"}]},{"key":"49-4","title":"万花雷鳴","bg":"bg_forest","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["mumyo","yohei"],"lines":[{"t":"n","s":"刀を、天に掲げる。"},{"t":"n","s":"花びらが、一斉に、空へ舞い上がった。百枚、千枚、万枚。夜空が、桜の花びらで埋め尽くされていく。"},{"t":"d","s":"「万花、雷鳴」"},{"t":"n","s":"花びらが、一斉に、無明へ降り注いだ。","f":"mumyo"},{"t":"n","s":"一枚一枚が、雷のように、紫の光を帯びている。轟音とともに、桜の雨が、無明に襲いかかる。","f":"mumyo","fx":"shake"},{"t":"n","s":"けれど。","f":"mumyo"},{"t":"d","s":"「見切った」","f":"mumyo"},{"t":"n","s":"無明は、闇を纏って、花びらの雨の隙間を、すり抜けた。一枚も、体に触れさせずに。","f":"mumyo"},{"t":"d","s":"「数を増やしても、隙間は隙間だ」","f":"mumyo"},{"t":"n","s":"無明が、耀平の目の前に、現れる。黒い刃が、振り上げられた。","f":"mumyo"},{"t":"n","s":"その瞬間。","f":"mumyo"},{"t":"n","s":"ばちっ、と。","f":"mumyo"},{"t":"n","s":"無明の周りに散らばった花びらと花びらの間に、紫の稲妻が走った。","f":"mumyo"},{"t":"n","s":"一枚から、一枚へ。また一枚へ。空に残った花びらが、まるで網の目のように、雷で繋がっていく。","f":"mumyo"},{"t":"d","s":"「なに……！」","f":"mumyo"},{"t":"n","s":"花びらの網が、無明を、四方から包み込んだ。","f":"mumyo"},{"t":"n","s":"雷が、直撃した。","f":"mumyo"},{"t":"d","s":"「がっ……ああああっ！」","f":"mumyo"},{"t":"n","s":"無明の体が、痙攣した。黒い刃が、手から零れ落ちる。膝が、がくりと崩れた。","f":"mumyo"},{"t":"n","s":"花びらは、避けるためのものではなかった。繋ぐためのものだった。","f":"mumyo"}]},{"key":"49-5","title":"万花一閃","bg":"bg_forest","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["mumyo","yohei","soleil"],"lines":[{"t":"n","s":"無明は、動けなかった。雷に焼かれた体が、細かく震えている。","f":"mumyo"},{"t":"n","s":"それでも、その目は、冷たいままだった。","f":"mumyo"},{"t":"d","s":"「……見事だ。だが、それで終わりか」","f":"mumyo"},{"t":"d","s":"「いや」","f":"mumyo"},{"t":"n","s":"耀平は、刀を、静かに構え直した。","f":"yohei"},{"t":"n","s":"呼吸を整える。心臓の音が、遠くなる。周りの音が、ひとつずつ、消えていく。","f":"yohei"},{"t":"n","s":"月が、真上にあった。空に残った花びらが、一枚、また一枚と、刀の刃に集まってくる。雷の残光が、刃先に、凝縮されていった。","f":"yohei"},{"t":"i","s":"（蛍さん）","f":"yohei"},{"t":"n","s":"小指に残った、あの温もり。","f":"yohei"},{"t":"i","s":"（名前も知らない、あの一年生）","f":"yohei"},{"t":"n","s":"不思議そうに、自分の胸を見下ろした顔。","f":"yohei"},{"t":"d","s":"「蛍さんや、殺された生徒の、仇だ」","f":"yohei"},{"t":"n","s":"耀平は、一歩だけ、前に出た。","f":"yohei"},{"t":"d","s":"「夜桜、万花――」","f":"yohei"},{"t":"n","s":"世界が、静止した。","f":"yohei"},{"t":"n","s":"音が、ない。風が、ない。落ちかけた花びらさえ、空中で止まっている。","f":"yohei"},{"t":"d","s":"「一閃」","f":"yohei","fx":"flash"},{"t":"cg","v":"cg_manka_issen"},{"t":"n","s":"銀の光が、夜を貫いた。","f":"yohei"},{"t":"n","s":"無明の胸に、細い光の線が、一本、走った。","f":"mumyo"},{"t":"n","s":"時が、動き出した。","f":"mumyo"},{"t":"n","s":"無明は、自分の胸を見下ろした。それから、ゆっくりと、耀平を見た。","f":"mumyo"},{"t":"n","s":"最期まで、その目は、冷たかった。","f":"mumyo"},{"t":"d","s":"「……くだらん、世界だ」","f":"mumyo"},{"t":"n","s":"無明の体が、ゆっくりと、傾いた。","f":"mumyo"},{"t":"n","s":"地面に倒れた音は、思ったより、ずっと小さかった。","f":"mumyo"},{"t":"n","s":"夜桜の花びらが、静かに、降り続けていた。","f":"mumyo"},{"t":"n","s":"木の上で、道化が、ぱちぱちと手を叩いた。","f":"soleil"},{"t":"d","s":"「すごい、すごーい⭐︎　夜桜くん、かっこいい！」","f":"soleil"},{"t":"n","s":"その笑い声だけが、ひどく、場違いに明るかった。","f":"soleil"}]}]},{"n":50,"title":"救い出す手","sub":"高校・2年6月","era":"high2","lead":"無明が倒れ、ソレイユは去る。捕らえられかけた莉花に、耀平は、手を伸ばす。","scenes":[{"key":"50-1","title":"興ざめ","bg":"bg_forest","dark":true,"mood":"tense","bgm":"tense2","cast":["soleil","tsukumo","todo"],"lines":[{"t":"d","s":"「あーあ」"},{"t":"n","s":"九十九と刃を交えていた細身の道化が、ふいに、動きを止めた。","f":"tsukumo"},{"t":"n","s":"影の上に、ひょいと腰を下ろす。仮面の口が、つまらなそうに、への字に曲がって見えた。","f":"tsukumo"},{"t":"d","s":"「無明さん、やられたか」","f":"tsukumo"},{"t":"d","s":"「……逃がさないよ」と、九十九が構える。","f":"tsukumo"},{"t":"d","s":"「逃げるんちゃう。帰るんや」","f":"tsukumo"},{"t":"n","s":"道化は、肩をすくめた。","f":"soleil"},{"t":"d","s":"「ほな、三つ巴は成立せんのう。二つ巴なんて、おもろないわ」","f":"soleil"},{"t":"n","s":"その声に応えるように、木の上の小柄な道化と、銃弾を浴びても平然と立っていた巨体の道化が、ひょいひょいと、細身の道化のそばへ集まった。","f":"soleil"},{"t":"d","s":"「えー、もう帰るの⭐︎」","f":"soleil"},{"t":"d","s":"「…………」","f":"soleil"},{"t":"d","s":"「楽しくなさそうやもん。またな、夜桜くん。次は、もっとおもろい舞台、用意しといてや」","f":"soleil"},{"t":"n","s":"三人の姿が、影の中に、すうっと沈んでいく。","f":"soleil"},{"t":"d","s":"「待て！」","f":"soleil"},{"t":"n","s":"隊員たちが駆け寄ろうとするのを、藤堂が、鋭く制した。","f":"todo"},{"t":"d","s":"「深追いするな！　あれは、今の戦力で追える相手じゃない」","f":"todo"},{"t":"n","s":"影が、消えた。道化の笑い声だけが、しばらく、夜の森に残っていた。","f":"soleil"}]},{"key":"50-2","title":"捕縛","bg":"bg_forest","dark":true,"mood":"tense","bgm":"tense2","cast":["rika","todo","yohei"],"lines":[{"t":"n","s":"静けさが戻ると、全員の視線が、一点に集まった。"},{"t":"n","s":"莉花だった。","f":"rika"},{"t":"n","s":"水の鎖と、雪と、雷の結界に、何重にも押さえ込まれて、地面に膝をついている。肩の傷から、血が、まだ流れていた。","f":"rika"},{"t":"d","s":"「新八天の、第一席」","f":"rika"},{"t":"n","s":"藤堂が、ゆっくりと、近づいた。","f":"todo"},{"t":"d","s":"「さっきの話は、聞こえていた。……その件は、後で、必ず調べる。だが、今は」","f":"todo"},{"t":"n","s":"藤堂の手が、上がった。隊員たちが、一斉に、莉花を取り囲む。","f":"todo"},{"t":"d","s":"「拘束する。抵抗するなら、力ずくでも」","f":"todo"},{"t":"d","s":"「……っ」","f":"todo"},{"t":"n","s":"莉花は、もがいた。刀を握る手に、力を込める。乃亜の水が、ぎしりと軋む。","f":"rika"},{"t":"n","s":"けれど、数が違った。隊員たちの拘束術が、次々と、莉花の手足に絡みついていく。藤堂自身の領域が、莉花の周りを、静かに閉ざしていく。","f":"rika"},{"t":"n","s":"莉花の膝が、がくりと崩れた。","f":"rika"},{"t":"n","s":"二度、耀平を庇った体だった。もう、ほとんど、力は残っていなかった。","f":"yohei"},{"t":"d","s":"「……せん、ぱい」","f":"yohei"},{"t":"n","s":"かすれた声が、漏れた。","f":"yohei"},{"t":"n","s":"耀平は、その場に、立ち尽くしていた。","f":"yohei"},{"t":"i","s":"（二度も、庇われた）","f":"yohei"},{"t":"n","s":"一度目は、無明の前に立ちはだかって。二度目は、自分の体を盾にして。","f":"mumyo"},{"t":"n","s":"そして、火の向こうで、莉花が言った言葉が、耳の奥で、何度も繰り返される。","f":"rika"},{"t":"d","s":"『私も、いたんですよ〜』","f":"rika"},{"t":"n","s":"祖父が、いた。工房で、槌を振るっていた祖父が。","f":"rika"},{"t":"i","s":"（老衰、って、書かれてた）","f":"rika"},{"t":"n","s":"胸のざわめきが、はっきりとした形を取り始めていた。","f":"rika"}]},{"key":"50-3","title":"分かってます","bg":"bg_forest","dark":true,"mood":"tense","bgm":"tense2","cast":["yohei","rika","todo"],"lines":[{"t":"n","s":"隊員の一人が、銀色の枷を手に、莉花の手首を取った。","f":"rika"},{"t":"n","s":"その腕を、横から、掴む手があった。","f":"rika"},{"t":"d","s":"「――待ってください」","f":"rika"},{"t":"n","s":"耀平だった。","f":"yohei"},{"t":"n","s":"いつの間に動いたのか、誰も、見ていなかった。花びらが一枚、耀平の足元に、ひらりと落ちる。","f":"yohei"},{"t":"d","s":"「耀平くん……？」","f":"yohei"},{"t":"d","s":"「莉花は、渡せません」","f":"yohei"},{"t":"n","s":"耀平は、隊員の手を、静かに外した。それから、莉花の体を抱き上げた。驚くほど、軽かった。","f":"yohei"},{"t":"n","s":"藤堂の顔が、凍りついた。","f":"todo"},{"t":"d","s":"「……耀平」","f":"todo"},{"t":"d","s":"「…………」","f":"todo"},{"t":"d","s":"「お前、何をしているか、分かっているのか」","f":"todo"},{"t":"n","s":"藤堂の声は、低く、厳しかった。","f":"todo"},{"t":"d","s":"「その子は、新八天の第一席だ。敵の幹部だ。それを連れて行けば、お前も、共犯と見なされる」","f":"todo"},{"t":"d","s":"「分かってます」","f":"todo"},{"t":"n","s":"耀平は、まっすぐに藤堂を見た。","f":"yohei"},{"t":"d","s":"「分かってます。でも、真実を知りたいんです」","f":"yohei"},{"t":"d","s":"「真実？」","f":"yohei"},{"t":"d","s":"「莉花の話は、まだ、終わってない。……ここで莉花を渡したら、もう、聞けなくなる気がするんです」","f":"yohei"},{"t":"n","s":"前八天は、拘束中に、全員殺された。その事実が、耀平の頭から、離れなかった。","f":"yohei"},{"t":"d","s":"「耀平、待って……！」","f":"yohei"},{"t":"n","s":"乃亜が、手を伸ばした。けれど、その手は、届かなかった。","f":"noa"},{"t":"n","s":"夜桜の花びらが、一斉に、耀平の周りに舞い上がった。視界が、桃色に霞む。","f":"yohei"},{"t":"d","s":"「ごめん」","f":"yohei"},{"t":"n","s":"花びらが散った時、耀平と莉花の姿は、もう、どこにもなかった。","f":"yohei"}]},{"key":"50-4","title":"薄れる意識","bg":"bg_forest","dark":false,"mood":"sad","bgm":"sad1","cast":["rika","yohei","noa"],"lines":[{"t":"n","s":"夜の森を、耀平は、走った。","f":"yohei"},{"t":"n","s":"腕の中で、莉花が、浅く息をしている。顔は、紙のように白い。","f":"rika"},{"t":"d","s":"「莉花。しっかりしろ」","f":"rika"},{"t":"d","s":"「……せん、ぱい……」","f":"rika"},{"t":"n","s":"莉花の目が、うっすらと開いた。焦点が、合っていない。","f":"rika"},{"t":"d","s":"「どうして……」","f":"rika"},{"t":"d","s":"「喋るな」","f":"rika"},{"t":"d","s":"「……来て、くれたんですね……」","f":"rika"},{"t":"n","s":"莉花は、ほんの少しだけ、笑った。それから、ゆっくりと、目を閉じた。","f":"rika","m":"happy"},{"t":"n","s":"体から、力が、抜けていく。","f":"rika"},{"t":"d","s":"「莉花！」","f":"rika"},{"t":"n","s":"息は、ある。力を、使い果たしただけだ。","f":"rika"},{"t":"n","s":"耀平は、莉花を抱き直して、また、走り出した。","f":"yohei"},{"t":"n","s":"背後の森の中で、乃亜が、膝をついていた。伸ばした手を、ぎゅっと、握りしめて。","f":"noa"},{"t":"d","s":"「……また、止められなかった」","f":"noa"},{"t":"n","s":"その呟きを聞いた者は、誰もいなかった。夜桜の夜が、少しずつ、朝の色に戻り始めていた。","f":"noa"}]}]},{"n":51,"title":"耀平の祖父の話","sub":"高校・2年6月","era":"high2","lead":"一足先に島を抜け出した耀平は、寮の自室で、莉花の話の続きを聞く。それは、耀平自身の話だった。","scenes":[{"key":"51-1","title":"小さなボート","bg":"bg_ship","dark":true,"mood":"night","bgm":"night1","cast":["yohei"],"lines":[{"t":"n","s":"島の沖に、先生たちの船が、錨を下ろしていた。"},{"t":"n","s":"夜明け前の海は、まだ暗い。甲板には、見張りが二人だけ。誰もが、島の騒ぎに気を取られていた。"},{"t":"n","s":"耀平は、莉花を背負ったまま、船の陰を、音もなく進んだ。花びらを一枚、足元に浮かべて、足音を消す。","f":"yohei"},{"t":"n","s":"船尾に、救命用の小さなボートが吊るされていた。","f":"yohei"},{"t":"i","s":"（……ごめんなさい）","f":"yohei"},{"t":"n","s":"心の中で、誰にともなく謝って、耀平は、ボートの綱を解いた。","f":"yohei"},{"t":"n","s":"エンジンの音が、波の音に紛れる。島の灯りが、少しずつ、遠ざかっていった。","f":"yohei"},{"t":"n","s":"背中で、莉花が、浅く息をしている。肩の傷には、自分のシャツを裂いて、きつく巻いておいた。","f":"rika"},{"t":"n","s":"水平線の向こうが、うっすらと、白み始めていた。","f":"rika"}]},{"key":"51-2","title":"悪い子に見えなかったから","bg":"bg_dorm","dark":false,"mood":"daily","bgm":"daily3","cast":["rika","yohei"],"lines":[{"t":"n","s":"学園の寮に着いたのは、昼前だった。"},{"t":"n","s":"合宿の最中で、寮はがらんとしていた。管理人室の前を、そっと通り過ぎる。自分の部屋の扉を開けると、出かけた日のままの、散らかった机が、目に入った。"},{"t":"n","s":"莉花を、ベッドに寝かせる。","f":"rika"},{"t":"n","s":"窓の外から、蝉の声が聞こえた。島の夜が、嘘のように、遠い。","f":"rika"},{"t":"n","s":"しばらくして、莉花の睫毛が、震えた。","f":"rika"},{"t":"d","s":"「……ん」","f":"rika"},{"t":"d","s":"「起きたか」","f":"rika"},{"t":"d","s":"「せんぱい……？　ここ、は」","f":"rika"},{"t":"d","s":"「おれの部屋。寮の」","f":"rika"},{"t":"n","s":"莉花は、ゆっくりと身を起こそうとして、顔をしかめた。肩の傷が、痛むらしい。","f":"rika"},{"t":"d","s":"「寝てろ」","f":"rika"},{"t":"d","s":"「……どうして」","f":"rika"},{"t":"n","s":"莉花は、天井を見つめたまま、ぽつりと言った。","f":"rika"},{"t":"d","s":"「どうして、助けてくれたんですか？　わたし、せんぱいを、ずっと騙してたのに」","f":"rika"},{"t":"n","s":"耀平は、窓際の椅子に座ったまま、少し考えた。","f":"yohei"},{"t":"n","s":"それから、正直に答えた。","f":"yohei"},{"t":"d","s":"「悪い子に、見えなかったから」","f":"yohei"},{"t":"d","s":"「…………」","f":"yohei"},{"t":"d","s":"「騙されてたのは、悲しかった。でも、莉花は、二回も、おれを庇った。……悪い子は、そんなことしないだろ」","f":"yohei"},{"t":"n","s":"莉花の目に、みるみる、涙が溜まった。","f":"rika","m":"sad"},{"t":"d","s":"「……ずるいです、せんぱい」","f":"rika"},{"t":"d","s":"「何が」","f":"rika"},{"t":"cg","v":"cg_rika_tears"},{"t":"d","s":"「そういうところが、ずるいんです」","f":"rika"},{"t":"n","s":"莉花は、両手で顔を覆った。肩が、小さく震えていた。","f":"rika"}]},{"key":"51-3","title":"もう一人の祖父","bg":"bg_dorm","dark":false,"mood":"sad","bgm":"sad2","cast":["yohei","rika"],"lines":[{"t":"n","s":"莉花が落ち着くまで、耀平は、黙って待った。","f":"rika"},{"t":"n","s":"やがて、莉花は、ゆっくりと顔を上げた。涙で濡れた目が、まっすぐに、耀平を見た。","f":"rika","m":"sad"},{"t":"d","s":"「せんぱい。島で話したこと、まだ、続きがあるんです」","f":"rika"},{"t":"d","s":"「……うん」","f":"rika"},{"t":"d","s":"「わたしが、聞いてしまった、大人たちの話。『あれは、なかったことにする』って」","f":"rika"},{"t":"n","s":"莉花は、膝の上で、両手を握りしめた。","f":"rika"},{"t":"d","s":"「あの時、大人たちは、もう一つ、名前を出していました。同じ捜査で、同じように間違えて……死なせてしまった人が、もう一人いる、って」","f":"rika"},{"t":"n","s":"耀平の背筋を、冷たいものが走った。","f":"yohei"},{"t":"d","s":"「その人は、昔、剣を教えていた人でした。孫と二人暮らしで、孫は、遠くの学校の寮に入っていた。だから、何も気づかれなかった、って」","f":"yohei"},{"t":"d","s":"「…………」","f":"yohei"},{"t":"d","s":"「その人の死も、『老衰』として、処理されました。孫には、祖父からの手紙が、残されていたそうです」","f":"yohei"},{"t":"n","s":"耀平の手が、震え出した。","f":"yohei"},{"t":"d","s":"「……やめろ」","f":"yohei"},{"t":"d","s":"「せんぱい」","f":"yohei"},{"t":"d","s":"「やめてくれ」","f":"yohei"},{"t":"d","s":"「その人の名前は」","f":"yohei"},{"t":"n","s":"莉花の声が、震えた。","f":"rika"},{"t":"d","s":"「せんぱいの、おじいさんです」","f":"rika"},{"t":"n","s":"部屋の空気が、止まった。","f":"rika"},{"t":"n","s":"蝉の声が、遠くなる。窓の光が、白く滲む。","f":"rika"},{"t":"d","s":"「…………嘘だろ」","f":"rika"},{"t":"n","s":"耀平の声は、ほとんど、音になっていなかった。","f":"yohei"},{"t":"d","s":"『いや。歳じゃ。ただの、歳』","f":"yohei"},{"t":"n","s":"病室で、祖父は、そう言って笑っていた。","f":"yohei"},{"t":"i","s":"（歳じゃ、なかった？）","f":"yohei"},{"t":"n","s":"箪笥の中の、手紙。『強くなれ。優しくなれ。そして、ちゃんと、笑え』。","f":"yohei"},{"t":"n","s":"何度も、何度も、読み返した。","f":"yohei"},{"t":"d","s":"「嘘だろ……」","f":"yohei"},{"t":"n","s":"手が、止まらなかった。膝の上で、指先が、かたかたと震え続けている。","f":"yohei"}]},{"key":"51-4","title":"仲間がいた","bg":"bg_dorm","dark":false,"mood":"sad","bgm":"sad2","cast":["rika","yohei","rio"],"lines":[{"t":"d","s":"「ずっと、確かめたかったんです」"},{"t":"n","s":"莉花は、ベッドから身を乗り出して、耀平の震える手に、そっと自分の手を重ねた。","f":"rika"},{"t":"d","s":"「祖父の命日に、お墓に行きました。紫の桔梗を、置いてきたのは、わたしです。……ずっと、謝りたかった。わたしの家族を奪った人たちが、せんぱいの家族も、奪っていたから」","f":"rika"},{"t":"d","s":"「……莉花」","f":"rika"},{"t":"d","s":"「わたし、ずっと、一人だと思ってました」","f":"rika"},{"t":"n","s":"莉花の涙が、重ねた手の上に、ぽたりと落ちた。","f":"rika","m":"sad"},{"t":"d","s":"「誰も、本当のことを知らない。誰も、わたしの痛みを分からない。だから、強くなるしかないって。強い者が支配すれば、もう、こんなことは起きないって」","f":"rika"},{"t":"d","s":"「…………」","f":"rika"},{"t":"d","s":"「でも、違いました」","f":"rika"},{"t":"n","s":"莉花は、泣きながら、笑った。","f":"rika","m":"sad"},{"t":"d","s":"「仲間が、いたんです。……しかも、それが、せんぱいだった」","f":"rika"},{"t":"n","s":"耀平は、何も言えなかった。","f":"yohei"},{"t":"n","s":"ただ、莉花の小さな手を、握り返した。","f":"rika"},{"t":"n","s":"二人の手は、どちらも、ひどく冷たくて、ひどく、震えていた。","f":"rika"},{"t":"d","s":"「せんぱい」","f":"rika"},{"t":"d","s":"「……うん」","f":"rika"},{"t":"d","s":"「おじいさんの手紙、まだ、持っていますか」","f":"rika"},{"t":"d","s":"「持ってる」","f":"rika"},{"t":"d","s":"「確かめましょう。……本当に、おじいさんが、書いたものなのか」","f":"rika"},{"t":"n","s":"耀平は、ゆっくりと、顔を上げた。","f":"yohei"},{"t":"n","s":"頭に浮かんだのは、ひとりの少女の顔だった。お菓子の袋を抱えて、空中に、過去の映像を映し出す、あの子。","f":"yohei"},{"t":"d","s":"「……理央」","f":"yohei"},{"t":"n","s":"その名前を、耀平は、静かに、口にした。","f":"yohei"}]}]},{"n":52,"title":"痕跡が見せたもの","sub":"高校・2年6月","era":"high2","lead":"船は、莉花を捕らえるために学園へ急ぐ。その頃、耀平は、SHITの本部で、理央に一通の手紙を差し出していた。","scenes":[{"key":"52-1","title":"帰りの船","bg":"bg_ship","dark":true,"mood":"tense","bgm":"tense1","cast":["todo","noa","ryoma"],"lines":[{"t":"n","s":"島を離れる船の甲板で、藤堂は、腕を組んで、海を睨んでいた。","f":"todo","m":"anger"},{"t":"d","s":"「全速で、学園へ。到着次第、寮を含めて、学園内を捜索する」","f":"todo"},{"t":"d","s":"「対象は、新八天第一席」と、隊員が復唱した。","f":"todo"},{"t":"d","s":"「それと」","f":"todo"},{"t":"n","s":"藤堂は、少しだけ、言い淀んだ。","f":"todo"},{"t":"d","s":"「……耀平もだ」","f":"todo"},{"t":"d","s":"「耀平くんも、ですか」","f":"todo"},{"t":"d","s":"「敵の幹部を連れて逃げた。今の時点では、共助と見なされても、おかしくない」","f":"todo"},{"t":"n","s":"隊員が、黙り込んだ。","f":"todo"},{"t":"n","s":"甲板の端では、乃亜が、手すりを握りしめて、遠ざかる島を見つめていた。柚月は、その隣で、ずっと乃亜の袖を掴んでいる。竜馬は、腕を組んで、一言も喋らなかった。","f":"noa"},{"t":"n","s":"蛍の棺が、船倉に安置されていた。その前を通るたび、生徒たちは、無言で頭を下げた。","f":"hotaru"},{"t":"d","s":"「……耀平、どこに行ったんだろう」","f":"hotaru"},{"t":"n","s":"乃亜の呟きに、答える者はいなかった。","f":"noa"}]},{"key":"52-2","title":"理央の部屋","bg":"bg_shit_base","dark":false,"mood":"daily","bgm":"daily4","cast":["rio","yohei","rika"],"lines":[{"t":"n","s":"その頃。SHITの本部の、奥まった一室。"},{"t":"d","s":"「お兄ちゃん？」"},{"t":"n","s":"扉を開けた理央が、目を丸くした。お菓子の袋を抱えたまま、固まっている。","f":"rio","m":"surprise"},{"t":"d","s":"「合宿、じゃなかったの？　それに、その子……」","f":"rio"},{"t":"n","s":"耀平の後ろに、莉花が立っていた。肩に、包帯。顔は、まだ青白い。","f":"yohei"},{"t":"d","s":"「理央。頼みがあるんだ」","f":"yohei"},{"t":"n","s":"耀平の声は、静かだった。静かすぎて、理央は、何かを察したように、お菓子の袋を机に置いた。","f":"yohei"},{"t":"d","s":"「……入って」","f":"yohei"},{"t":"n","s":"部屋の中は、几帳面に畳まれたお菓子の空き袋が、積んであった。理央は、二人を椅子に座らせると、自分は机の端に腰かけた。","f":"rio"},{"t":"d","s":"「島で、何かあったんだね」","f":"rio"},{"t":"d","s":"「後で、全部話す。……先に、これを見てほしい」","f":"rio"},{"t":"n","s":"耀平は、鞄の底から、古い封筒を取り出した。何度も開けて、何度も閉じた、角の擦り切れた封筒。","f":"yohei"},{"t":"d","s":"「じいちゃんの、手紙なんだ。中学一年の時に、箪笥の中から出てきた」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「これが、どうやって書かれたのか。映像で、出してほしい」","f":"yohei"},{"t":"n","s":"理央は、しばらく、耀平の顔を見つめていた。それから、こくりと頷いた。","f":"rio"},{"t":"d","s":"「分かった。……お兄ちゃん、覚悟は、ある？」","f":"rio"},{"t":"d","s":"「ある」","f":"rio"},{"t":"n","s":"即答だった。理央は、それ以上、何も聞かなかった。","f":"rio"}]},{"key":"52-3","title":"映像","bg":"bg_shit_base","dark":false,"mood":"sad","bgm":"sad1","cast":["rio","yohei","noa"],"lines":[{"t":"n","s":"理央の指先が、便箋の文字を、そっとなぞる。","f":"rio"},{"t":"n","s":"空中に、淡い光が、灯った。","f":"rio"},{"t":"n","s":"映ったのは、薄暗い和室だった。障子越しの、夕方の光。耀平の知っている部屋だった。祖父の家の、奥の間。","f":"yohei"},{"t":"n","s":"けれど、そこに、祖父の姿はなかった。","f":"yohei"},{"t":"n","s":"机の前に座っていたのは、見知らぬ男だった。","f":"yohei"},{"t":"n","s":"黒いコート。肩に、銀の紋章。年は、四十前後だろうか。細い指で、筆を持っている。","f":"yohei"},{"t":"n","s":"男は、筆を、便箋にかざした。","f":"yohei"},{"t":"n","s":"筆先が、紙に触れていない。それなのに、淡い光が、筆先から紙へと走り、文字が、ひとりでに浮かび上がっていく。","f":"yohei"},{"t":"d","s":"『耀平へ。』","f":"yohei"},{"t":"n","s":"丸みのある、懐かしい筆跡。祖父の、字だった。","f":"yohei"},{"t":"d","s":"『強くなれ。優しくなれ。そして、ちゃんと、笑え。乃亜ちゃんを、大事にな。』","f":"yohei"},{"t":"n","s":"最後の一文字が浮かぶと、男は、筆を置いた。便箋を折り、封筒に入れる。それから、部屋の隅の箪笥を開けて、引き出しの奥に、そっと滑り込ませた。","f":"yohei"},{"t":"n","s":"男の唇が、動いた。","f":"yohei"},{"t":"n","s":"声は、聞こえない。けれど、理央が、静かに読み上げた。","f":"rio"},{"t":"d","s":"「『これで、あの子も、納得するだろう』」","f":"rio"},{"t":"n","s":"映像は、そこで、ふっと揺らいで、消えた。","f":"rio"}]},{"key":"52-4","title":"表情が消える","bg":"bg_shit_base","dark":false,"mood":"sad","bgm":"sad1","cast":["yohei","rio","todo"],"lines":[{"t":"n","s":"沈黙が、部屋を満たした。"},{"t":"n","s":"理央は、淡々と、便箋を封筒に戻した。","f":"rio"},{"t":"d","s":"「スキルで、他人の筆跡を、そっくりに書く魔法。……この人、知ってる。昔、SHITにいた人。今は、もう辞めてる」","f":"rio"},{"t":"d","s":"「…………」","f":"rio"},{"t":"d","s":"「手紙を書いたのは、おじいちゃんじゃない。この人だよ、お兄ちゃん」","f":"rio"},{"t":"n","s":"耀平は、何も言わなかった。","f":"yohei"},{"t":"n","s":"莉花が、息を詰めて、耀平の横顔を見つめていた。","f":"rika"},{"t":"n","s":"その顔から、表情が、消えていた。","f":"rika"},{"t":"n","s":"怒りも、悲しみも、驚きも、何もなかった。ただ、空っぽの目が、さっきまで映像が浮かんでいた空中を、じっと見ていた。","f":"rika"},{"t":"d","s":"『強くなれ。優しくなれ。そして、ちゃんと、笑え』","f":"rika"},{"t":"n","s":"あの言葉に、何度、救われただろう。眠れない夜に、何度、読み返しただろう。一人ぼっちになった部屋で、あの文字だけが、味方だった。","f":"rika"},{"t":"n","s":"それが、全部。","f":"rika"},{"t":"d","s":"「……せんぱい」","f":"rika"},{"t":"n","s":"莉花が、そっと、耀平の袖を握った。耀平は、振り払わなかった。けれど、握り返しもしなかった。","f":"rika"},{"t":"n","s":"理央の机の上で、通信機が、ぴぴっと鳴った。","f":"rio"},{"t":"d","s":"『理央。聞こえるか。今、学園に向かっている』","f":"rio"},{"t":"n","s":"藤堂の声だった。","f":"todo"},{"t":"n","s":"理央は、ちらりと耀平を見てから、通信機を取った。","f":"rio"},{"t":"d","s":"「藤堂さん。……今、お兄ちゃんが、ここにいる」","f":"rio"},{"t":"d","s":"『何？』","f":"rio"},{"t":"d","s":"「それとね。藤堂さんに、見てほしい映像がある」","f":"rio"},{"t":"n","s":"理央は、さっきの映像を、通信機の向こうへ送った。","f":"rio"},{"t":"n","s":"長い沈黙が、あった。","f":"rio"},{"t":"n","s":"やがて、通信機の向こうから、藤堂の、絞り出すような声が聞こえた。","f":"todo"},{"t":"d","s":"『…………そんな、ことが』","f":"todo"},{"t":"n","s":"それは、耀平が初めて聞く、藤堂の、苦渋に満ちた声だった。","f":"yohei"},{"t":"d","s":"『当時の捜査には……わたしも、関わっていた。だが、こんな……こんなことは、知らされて……』","f":"yohei"},{"t":"n","s":"耀平は、立ち上がった。","f":"yohei"},{"t":"d","s":"「行くぞ、莉花」","f":"yohei"},{"t":"d","s":"「せんぱい、どこへ」","f":"yohei"},{"t":"d","s":"「学園」","f":"yohei"},{"t":"n","s":"その声には、もう、何の温度もなかった。","f":"yohei"},{"t":"d","s":"「知ってるやつに、聞きに行く」","f":"yohei"}]}]},{"n":53,"title":"学長室、ばいばい","sub":"高校・2年6月","era":"high2","lead":"学園に戻った乃亜たちは、耀平を探し回る。見つけたのは、学長室だった。耀平は、学園長に、刃を向けていた。","scenes":[{"key":"53-1","title":"どこにもいない","bg":"bg_dorm","dark":true,"mood":"tense","bgm":"tense1","cast":["noa","yuzuki","ryoma"],"lines":[{"t":"n","s":"船が港に着いたのは、夕方だった。"},{"t":"n","s":"乃亜は、誰よりも先に、桟橋を駆け下りた。柚月と竜馬が、すぐ後を追う。","f":"noa"},{"t":"d","s":"「耀平の部屋！」","f":"noa"},{"t":"n","s":"寮の扉は、鍵がかかっていなかった。中には、誰もいない。ベッドのシーツに、乾いた血の跡が、点々と残っていた。","f":"noa"},{"t":"d","s":"「……ここに、いたんだ」","f":"noa"},{"t":"d","s":"「莉花さんの、血でしょうか」","f":"noa"},{"t":"d","s":"「分からない」","f":"noa"},{"t":"n","s":"屋上。いない。校庭。いない。道場、図書室、食堂、E組の教室。どこにも、いない。","f":"noa"},{"t":"n","s":"隣の席の机は、きちんと椅子が入れられたまま、空っぽだった。柚月は、その机の前で、一瞬だけ立ち止まった。","f":"yuzuki"},{"t":"d","s":"「乃亜先輩、竜馬さん」","f":"yuzuki"},{"t":"d","s":"「何」","f":"yuzuki"},{"t":"d","s":"「……まだ、探していない場所が、一つだけ」","f":"yuzuki"},{"t":"n","s":"柚月の視線は、本館の最上階に向いていた。","f":"yuzuki"},{"t":"n","s":"学長室。","f":"yuzuki"},{"t":"n","s":"三人は、顔を見合わせた。最後の希望のように、階段を駆け上がった。","f":"yuzuki"}]},{"key":"53-2","title":"答えろ","bg":"bg_principal","dark":true,"mood":"battle","bgm":"battle2","cast":["yohei","principal","noa"],"lines":[{"t":"n","s":"学長室の扉は、半分、開いていた。"},{"t":"n","s":"中から、聞いたことのない声が、響いてきた。"},{"t":"d","s":"「答えろ！」"},{"t":"n","s":"乃亜は、扉を押し開けた。","f":"noa"},{"t":"n","s":"夕日が、大きな窓から、部屋いっぱいに差し込んでいた。橙色の光の中に、二つの影があった。","f":"noa"},{"t":"n","s":"一つは、机の向こうに立つ、学園長。","f":"principal"},{"t":"n","s":"もう一つは、その喉元に、無銘の刀の切っ先を、突きつけている、耀平。","f":"yohei"},{"t":"n","s":"部屋の隅に、莉花が、黙って立っていた。","f":"rika"},{"t":"d","s":"「…………耀平」","f":"rika"},{"t":"n","s":"乃亜の声が、震えた。","f":"noa"},{"t":"n","s":"耀平は、振り返らなかった。刀は、学園長の喉の、一寸手前で、ぴたりと止まっている。","f":"yohei"},{"t":"d","s":"「じいちゃんは、殺されたんだ。SHITの捜査で、人違いで。手紙は、SHITのやつが、魔法で書いた。……学園は、それを知ってたんだろ」","f":"yohei"},{"t":"d","s":"「…………耀平くん」","f":"yohei"},{"t":"d","s":"「答えろ！　誰が隠した！　あんたは、知ってたのか！」","f":"yohei"},{"t":"cg","v":"cg_principal_blade"},{"t":"n","s":"あの耀平が、叫んでいた。","f":"yohei"},{"t":"n","s":"いつも眠そうで、いつも穏やかで、怒鳴ることなど一度もなかった耀平が。","f":"yohei","m":"anger"},{"t":"n","s":"学園長は、刃を突きつけられたまま、凍りついていた。その顔は、真っ青だった。","f":"principal"},{"t":"d","s":"「……知らない」","f":"principal"},{"t":"d","s":"「嘘をつくな！」","f":"principal"},{"t":"d","s":"「本当に、知らないのだ……！　剛三が、殺された……？　SHITの、捜査で……？」","f":"principal"},{"t":"n","s":"学園長の声は、震えていた。皺の刻まれた手が、机の縁を、強く掴んでいる。","f":"principal"},{"t":"n","s":"その目に浮かんでいたのは、言い逃れの色ではなかった。本当に、たった今、それを知った者の、驚きと、恐怖だった。","f":"principal"}]},{"key":"53-3","title":"止める声","bg":"bg_principal","dark":true,"mood":"battle","bgm":"battle2","cast":["yohei","todo","noa"],"lines":[{"t":"d","s":"「やめて、耀平！」"},{"t":"n","s":"乃亜が、駆け寄った。耀平の腕に、しがみつく。","f":"noa"},{"t":"d","s":"「刀を下ろして……！　お願い……！」","f":"noa"},{"t":"n","s":"竜馬が、反対側から、耀平の肩を掴んだ。","f":"ryoma"},{"t":"d","s":"「耀平！　お前、自分が何してるか、分かってんのか！」","f":"ryoma"},{"t":"n","s":"柚月は、扉のそばで、立ち尽くしていた。両手を、胸の前で、ぎゅっと握りしめて。","f":"yuzuki"},{"t":"n","s":"廊下が、騒がしくなった。足音。怒号。警備の職員と、SHITの隊員たちが、学長室になだれ込んでくる。先頭に、藤堂がいた。","f":"todo"},{"t":"d","s":"「耀平！」","f":"todo"},{"t":"n","s":"藤堂の声が、部屋に響いた。","f":"todo"},{"t":"d","s":"「何をしているか、分かっているのか！」","f":"todo"},{"t":"n","s":"耀平は、ゆっくりと、振り返った。","f":"yohei"},{"t":"n","s":"その目を見た瞬間、藤堂の足が、止まった。","f":"todo"},{"t":"n","s":"空っぽの目だった。夜の底のような、何も映さない目。","f":"todo"},{"t":"d","s":"「近づくな」","f":"todo"},{"t":"n","s":"低い声だった。それだけで、隊員たちが、一斉に足を止めた。耀平の周りに、花びらが、はらはらと舞い始めていた。","f":"yohei"},{"t":"n","s":"藤堂は、唇を噛んだ。通信機越しに見た映像が、頭から離れないのだろう。それ以上、一歩も踏み出さなかった。","f":"todo"}]},{"key":"53-4","title":"ばいばい","bg":"bg_principal","dark":false,"mood":"climax","bgm":"climax2","cast":["yohei","noa","yuzuki"],"lines":[{"t":"n","s":"耀平は、刀を、下ろした。","f":"yohei"},{"t":"n","s":"乃亜が、はっと顔を上げる。竜馬の手から、力が抜ける。","f":"noa"},{"t":"n","s":"けれど、耀平は、刀を鞘に納めなかった。","f":"yohei"},{"t":"d","s":"「ありがとう」","f":"yohei"},{"t":"n","s":"耀平は、乃亜を見た。竜馬を見た。柚月を見た。","f":"yohei"},{"t":"n","s":"その声は、さっきまでの叫びとは違って、とても静かだった。","f":"yohei"},{"t":"d","s":"「乃亜たちが、心配してくれてるのは、分かってる」","f":"yohei"},{"t":"d","s":"「耀平……」","f":"yohei"},{"t":"d","s":"「でも、おれは、真実を知った。もう、知らなかった頃には、戻れない」","f":"yohei"},{"t":"n","s":"耀平は、学園長を、一度だけ振り返った。それから、窓の外へ、目を向けた。","f":"yohei"},{"t":"d","s":"「おれは、外から、守る。……この学園も、みんなも」","f":"yohei"},{"t":"n","s":"それが、名目だということに、気づいた者は、莉花だけだった。","f":"rika"},{"t":"n","s":"柚月が、震える声で、言った。","f":"yuzuki"},{"t":"d","s":"「……約束は？」","f":"yuzuki"},{"t":"n","s":"耀平の肩が、わずかに、揺れた。","f":"yohei"},{"t":"d","s":"「隣の席の、約束は……？」","f":"yohei"},{"t":"n","s":"柚月の目から、涙が、こぼれ落ちた。","f":"yuzuki","m":"sad"},{"t":"d","s":"「ごめん」","f":"yuzuki"},{"t":"n","s":"耀平は、目を伏せた。","f":"yohei"},{"t":"d","s":"「約束を守れなくて、ごめん」","f":"yohei"},{"t":"d","s":"「耀平、戻れ！」と、竜馬が叫んだ。","f":"yohei"},{"t":"d","s":"「やめて、耀平……行かないで……！」","f":"yohei"},{"t":"n","s":"乃亜の手が、耀平の袖を、掴もうとした。","f":"noa"},{"t":"d","s":"「ばいばい」","f":"noa"},{"t":"n","s":"夜桜の花びらが、学長室いっぱいに、舞い上がった。","f":"noa"},{"t":"n","s":"視界が、桃色に霞む。乃亜の手が、空を切った。","f":"noa"},{"t":"n","s":"花びらが散った時、耀平と莉花の姿は、もう、なかった。","f":"yohei"},{"t":"n","s":"開け放たれた窓から、夕方の風が、吹き込んでいた。床に、花びらが、一枚だけ、残っていた。","f":"yohei"},{"t":"n","s":"乃亜は、その花びらを、拾い上げた。","f":"noa"},{"t":"n","s":"声を殺して、泣いた。","f":"noa","m":"sad"},{"t":"n","s":"この日を最後に、耀平は、二度と、学園には戻らなかった。","f":"yohei"},{"t":"n","s":"胸の奥に、ひとつの決意だけを、抱えて。","f":"yohei"},{"t":"i","s":"（許さない。隠したやつらも、のうのうと生きているやつらも、全員）","f":"yohei"}]}]},{"n":54,"title":"二人で消える","sub":"高校・2年7月","era":"high2","lead":"耀平は、莉花と一緒に、学園から姿を消す。卒業を待たずに。誰にも行き先を告げずに。","scenes":[{"key":"54-1","title":"夜行列車","bg":"bg_riverside","dark":true,"mood":"night","bgm":"night3","cast":["rika","yohei"],"lines":[{"t":"n","s":"七月の初め。夜行列車の窓の外を、街の灯りが、後ろへ流れていく。"},{"t":"n","s":"二人は、向かい合わせの席に、座っていた。荷物は、鞄が二つだけ。制服は、もう着ていなかった。"},{"t":"n","s":"耀平は、窓の外を見つめていた。何も、見ていなかった。","f":"yohei"},{"t":"n","s":"学長室を出てから、ほとんど喋っていない。食事も、莉花が差し出したパンを、半分だけかじった。夜は、眠れないまま、天井を見ていた。","f":"rika"},{"t":"i","s":"（じいちゃん）","f":"rika"},{"t":"n","s":"心の中で呼んでも、返事はなかった。浮かぶのは、映像の中の、黒いコートの男の、細い指だけだった。","f":"rika"},{"t":"d","s":"「せんぱい」","f":"rika"},{"t":"n","s":"莉花が、そっと呼んだ。","f":"rika"},{"t":"d","s":"「……ん」","f":"rika"},{"t":"d","s":"「寒くないですか」","f":"rika"},{"t":"d","s":"「平気」","f":"rika"},{"t":"d","s":"「嘘です。手、冷たいです」","f":"rika"},{"t":"n","s":"莉花は、向かいの席から身を乗り出して、耀平の手を、両手で包んだ。小さな手が、じんわりと、温かかった。","f":"rika"},{"t":"d","s":"「…………」","f":"rika"},{"t":"d","s":"「せんぱい」","f":"rika"},{"t":"d","s":"「うん」","f":"rika"},{"t":"d","s":"「せんぱいの苦しみも、痛みも、全部、わたしは分かります」","f":"rika"},{"t":"n","s":"莉花の声は、静かだった。","f":"rika"},{"t":"d","s":"「家族を、奪われたこと。それを、なかったことにされたこと。信じていた言葉が、嘘だったこと。……全部、わたしも、知ってますから」","f":"rika"},{"t":"n","s":"耀平は、ゆっくりと、莉花の方を向いた。","f":"yohei"},{"t":"n","s":"莉花の目は、まっすぐだった。泣いてはいなかった。けれど、その奥に、同じ色の痛みが、確かにあった。","f":"rika","m":"sad"},{"t":"d","s":"「だから、ずっと、そばにいますね」","f":"rika"},{"t":"n","s":"列車が、トンネルに入った。窓が、真っ暗になる。轟音の中で、莉花の手の温度だけが、はっきりと分かった。","f":"rika","fx":"shake"}]},{"key":"54-2","title":"一緒に","bg":"bg_riverside","dark":true,"mood":"night","bgm":"night3","cast":["rika","yohei","noa"],"lines":[{"t":"n","s":"トンネルを抜けると、窓の外に、星空が広がっていた。"},{"t":"n","s":"耀平は、長い間、黙っていた。","f":"yohei"},{"t":"n","s":"それから、ぽつりと、口を開いた。","f":"yohei"},{"t":"d","s":"「莉花」","f":"yohei"},{"t":"d","s":"「はい」","f":"yohei"},{"t":"d","s":"「おれ、許せないんだ」","f":"yohei"},{"t":"n","s":"自分の声が、ひどく、低かった。","f":"yohei"},{"t":"d","s":"「じいちゃんを殺したやつも。手紙を書いたやつも。それを隠して、今も、のうのうと生きてるやつらも。……全員」","f":"yohei"},{"t":"d","s":"「はい」","f":"yohei"},{"t":"d","s":"「これから、おれがやろうとしてることは、たぶん、正しくない。乃亜たちが知ったら、止めると思う」","f":"yohei"},{"t":"d","s":"「はい」","f":"yohei"},{"t":"d","s":"「それでも」","f":"yohei"},{"t":"n","s":"耀平は、莉花の手を、握り返した。","f":"yohei"},{"t":"d","s":"「一緒に、やってくれるか？」","f":"yohei"},{"t":"n","s":"莉花は、一瞬、目を見開いた。","f":"rika","m":"surprise"},{"t":"n","s":"それから、ふわりと、笑った。小悪魔の笑顔でも、作った笑顔でもない。ただの、ひとりの少女の、嬉しそうな笑顔だった。","f":"rika","m":"happy"},{"t":"d","s":"「もちろん」","f":"rika"},{"t":"n","s":"莉花は、耀平の手を、自分の頬に押し当てた。","f":"rika"},{"t":"d","s":"「わたしは、あなたがいれば、幸せです」","f":"rika"}]},{"key":"54-3","title":"港町の夜","bg":"bg_grandpa_house","dark":false,"mood":"sad","bgm":"sad2","cast":["rika","yohei"],"lines":[{"t":"n","s":"翌朝、小さな港町で、列車を降りた。"},{"t":"n","s":"潮の匂いが、風に混じっている。古い商店街が、朝日に照らされている。"},{"t":"d","s":"「ここ、おじいちゃんの工房があった街です」"},{"t":"n","s":"莉花に連れられて、坂を登った。その先に、古びた建物があった。屋根は崩れかけ、戸は朽ちていた。軒先に、小さな鉄の看板が、まだ、残っていた。","f":"rika"},{"t":"d","s":"『桔梗屋』","f":"rika"},{"t":"n","s":"扉を押すと、軋んだ音を立てて、開いた。","f":"rika"},{"t":"n","s":"中は、薄暗く、埃っぽかった。作業台が、ぽつんと置いてある。三年半前、耀平が無銘の刀を握った、あの場所だった。","f":"yohei"},{"t":"n","s":"莉花は、作業台の前に立って、そっと、指で撫でた。","f":"rika"},{"t":"d","s":"「おじいちゃん、ただいま」","f":"rika"},{"t":"n","s":"答える者は、いなかった。","f":"rika"},{"t":"n","s":"耀平は、黙って、隣に立った。それから、腰の刀を、作業台の上に置いた。","f":"yohei"},{"t":"d","s":"「この刀、ずっと、使ってます」","f":"yohei"},{"t":"n","s":"誰にともなく、そう言った。","f":"yohei"},{"t":"d","s":"「おかげで、何度も、守れました。……守れなかったものも、あったけど」","f":"yohei"},{"t":"n","s":"莉花の肩が、震えた。耀平は、そっと、その肩を抱いた。","f":"rika"},{"t":"n","s":"莉花は、声を殺して、泣いた。","f":"rika","m":"sad"},{"t":"n","s":"その夜。港を見下ろす小さな旅館で、二つ並べた布団の間から、莉花の手が、耀平の方へ伸びてきた。","f":"rika"},{"t":"n","s":"耀平は、その手を、握った。","f":"yohei"},{"t":"d","s":"「おやすみなさい、せんぱい」","f":"yohei"},{"t":"d","s":"「おやすみ、莉花」","f":"yohei"},{"t":"n","s":"窓の外で、漁船の灯りが、波に揺れていた。","f":"yohei"},{"t":"n","s":"怒りは、まだ、胸の底で燃えていた。けれど、握った手の温度の分だけ、その夜は、眠ることができた。","f":"yohei"},{"t":"n","s":"学園を出てから、初めての、眠りだった。","f":"yohei"}]}]},{"n":55,"title":"ありがとう、莉花","sub":"高校・2年夏〜秋","era":"high2","lead":"旅に出た二人。莉花は、光の消えた耀平の目を、少しずつ取り戻そうとする。","scenes":[{"key":"55-1","title":"最初のデート","bg":"bg_riverside","dark":false,"mood":"soft","bgm":"soft1","cast":["rika","yohei"],"lines":[{"t":"n","s":"旅に出て、ひと月が経った。"},{"t":"n","s":"耀平は、よく、遠くを見ていた。宿の窓から。列車の窓から。海辺の堤防から。何かを見ているようで、何も見ていない目だった。","f":"yohei"},{"t":"n","s":"笑わなかった。食べる量も、減った。夜中に、ふと目を覚ますと、隣の布団で、耀平が天井を見つめていることが、何度もあった。","f":"yohei"},{"t":"n","s":"光が、消えていた。あの、優しい目から。","f":"yohei"},{"t":"i","s":"（わたしが、取り戻す）","f":"yohei"},{"t":"n","s":"莉花は、そう決めていた。","f":"rika"},{"t":"d","s":"「せんぱい、今日は、考えごとはお休みです!」","f":"rika"},{"t":"n","s":"朝の宿の前で、莉花が、両手を腰に当てて宣言した。","f":"rika"},{"t":"d","s":"「休み?」","f":"rika"},{"t":"d","s":"「はい。ずっと張りつめてたら、倒れちゃいます」","f":"rika"},{"t":"d","s":"「でも」","f":"rika"},{"t":"d","s":"「でも、じゃありません。許せない人たちは、逃げません。……たぶん」","f":"rika"},{"t":"n","s":"耀平は、少しだけ、口の端を動かした。笑った、と呼ぶには、あまりに小さな動きだった。莉花は、ぱっと耀平の腕に抱きついた。","f":"yohei","m":"happy"},{"t":"d","s":"「だから、デートです」","f":"yohei"},{"t":"d","s":"「デート」","f":"yohei"},{"t":"d","s":"「はい。ちゃんとした、デート」","f":"yohei"},{"t":"n","s":"連れて行かれたのは、河原の桜並木だった。季節は、もう夏の終わり。花は咲いていない。それでも、緑の葉が、風に揺れて、さらさらと音を立てていた。","f":"yohei"},{"t":"d","s":"「桜、咲いてないな」","f":"yohei"},{"t":"d","s":"「いいんです。わたしの目には、見えてますから」","f":"yohei"},{"t":"d","s":"「見える?」","f":"yohei"},{"t":"d","s":"「はい。せんぱいが、花びらを呼ぶ姿が」","f":"yohei"},{"t":"cg","v":"cg_date_point"},{"t":"n","s":"莉花は、腕に絡んだまま、前を指差した。","f":"rika"},{"t":"d","s":"「あ、あそこ。あそこのお店、行きましょう!」","f":"rika"},{"t":"d","s":"「引っ張るな」","f":"rika"},{"t":"d","s":"「引っ張ります!」","f":"rika"},{"t":"n","s":"土手の店で、かき氷を食べた。莉花は、眠そうな耀平の顔を見て、くすくす笑った。","f":"rika","m":"happy"},{"t":"d","s":"「せんぱい、目、閉じかけてます」","f":"rika"},{"t":"d","s":"「ごめん。歩き疲れた」","f":"rika"},{"t":"d","s":"「じゃあ、休憩ですね」","f":"rika"},{"t":"n","s":"莉花は、土手の草の上に座り、自分の膝を、ぽんぽんと叩いた。","f":"rika"},{"t":"d","s":"「どうぞ」","f":"rika"},{"t":"d","s":"「……え」","f":"rika"},{"t":"d","s":"「膝枕です」","f":"rika"},{"t":"d","s":"「いや、それは」","f":"rika"},{"t":"d","s":"「いいから」","f":"rika"},{"t":"cg","v":"cg_lap_pillow"},{"t":"n","s":"耀平は、観念して、莉花の膝に、頭を預けた。空が、高かった。","f":"yohei"},{"t":"d","s":"「重くない?」","f":"yohei"},{"t":"d","s":"「ぜんぜん。軽いです」","f":"yohei"},{"t":"n","s":"風が、吹いた。莉花の指が、耀平の髪を、そっと梳いた。","f":"rika"}]},{"key":"55-2","title":"十月桜の並木","bg":"bg_riverside","dark":false,"mood":"soft","bgm":"soft1","cast":["rika","yohei"],"lines":[{"t":"n","s":"次の日は、朝から、風が涼しかった。"},{"t":"n","s":"宿のある港町から、バスで三十分。連れて行かれたのは、山裾の小さな公園だった。"},{"t":"d","s":"「せんぱい、見てください！」"},{"t":"n","s":"莉花が、前を指差して、ぴょんと跳ねた。","f":"rika"},{"t":"n","s":"秋の澄んだ空の下、並木道に、桜が咲いていた。","f":"rika"},{"t":"n","s":"薄い桃色の、小ぶりな花。葉の緑のあいだに、ぽつぽつと、控えめに。","f":"rika"},{"t":"d","s":"「十月桜、です。秋に咲く桜なんですよ」","f":"rika"},{"t":"d","s":"「秋に？」","f":"rika"},{"t":"d","s":"「はい。春にも咲くんですけど、秋にも、少しだけ。季節外れの、帰り咲き」","f":"rika"},{"t":"n","s":"耀平は、足を止めて、枝を見上げた。","f":"yohei"},{"t":"n","s":"春の桜のような、一面の花ではない。けれど、一輪一輪が、はっきりと、そこに在った。","f":"yohei"},{"t":"d","s":"「……きれいだ」","f":"yohei"},{"t":"d","s":"「でしょう？　せんぱいに、見せたくて」","f":"yohei"},{"t":"cg","v":"cg_date_arm"},{"t":"n","s":"莉花は、耀平の腕に、ぎゅっとしがみついた。体を預けるようにして、頬を肩に押しつける。","f":"rika"},{"t":"d","s":"「歩きにくい」","f":"rika"},{"t":"d","s":"「いいんです。ゆっくり歩きましょう」","f":"rika"},{"t":"d","s":"「そんなに引っ付かなくても」","f":"rika"},{"t":"d","s":"「引っ付きたいんです」","f":"rika"},{"t":"n","s":"莉花の声は、いつもの甘さだった。けれど、その腕は、離したらどこかへ行ってしまうものを、必死に掴んでいるようだった。","f":"rika"},{"t":"n","s":"並木の下を、二人はゆっくりと歩いた。花びらが、ひとひら、莉花の髪に落ちる。耀平は、それを、指でそっと取った。","f":"rika"},{"t":"d","s":"「あ」","f":"rika"},{"t":"d","s":"「ついてた」","f":"rika"},{"t":"d","s":"「……ありがとうございます」","f":"rika"},{"t":"n","s":"莉花は、一瞬だけ、固まって、それから、耳まで赤くなった。","f":"rika"},{"t":"d","s":"「せんぱいって、たまに、そういうことを、さらっとしますよね」","f":"rika"},{"t":"d","s":"「そういうこと?」","f":"rika"},{"t":"d","s":"「無自覚なところです！　ずるいです！」","f":"rika"},{"t":"d","s":"「何が」","f":"rika"},{"t":"d","s":"「もういいです！」","f":"rika"},{"t":"n","s":"莉花は、ぷいと顔をそむけた。それなのに、腕は、さっきより強く、絡んでいた。","f":"rika"},{"t":"n","s":"ベンチに座って、買ってきたお茶を飲む。紙コップの湯気が、秋の空気に溶けていく。","f":"rika"},{"t":"d","s":"「季節外れでも、咲くんですね」","f":"rika"},{"t":"d","s":"「うん」","f":"rika"},{"t":"d","s":"「わたしは、それが、好きなんです」","f":"rika"},{"t":"d","s":"「どうして」","f":"rika"},{"t":"d","s":"「遅れても、咲いていいって、言われてる気がして」","f":"rika"},{"t":"n","s":"莉花は、紙コップを両手で包んだ。","f":"rika"},{"t":"d","s":"「おじいちゃんが、よく言ってました。『花には、花の時がある。早い花も、遅い花も、どちらも、本物だ』って」","f":"rika"},{"t":"n","s":"耀平は、頷いた。","f":"yohei"},{"t":"d","s":"「……いい言葉だな」","f":"yohei"},{"t":"d","s":"「でしょう？」","f":"yohei"},{"t":"d","s":"「おれも、遅れてるかな」","f":"yohei"},{"t":"d","s":"「何がですか」","f":"yohei"},{"t":"d","s":"「いろいろ。気づくのも、動くのも」","f":"yohei"},{"t":"n","s":"莉花は、首を横に振った。","f":"rika"},{"t":"d","s":"「せんぱいは、ちゃんと、咲いてます。わたしが、知ってます」","f":"rika"},{"t":"n","s":"秋の風が、枝を揺らした。花びらが、二人の膝に、そっと降りた。","f":"rika"}]},{"key":"55-3","title":"水族館","bg":"bg_riverside","dark":false,"mood":"soft","bgm":"soft1","cast":["rika","yohei"],"lines":[{"t":"n","s":"その次の日。莉花は、また、予定を決めていた。","f":"rika"},{"t":"d","s":"「今日は、水族館です！」","f":"rika"},{"t":"d","s":"「また、急だな」","f":"rika"},{"t":"d","s":"「港町には、小さい水族館があるって、宿のおばあちゃんに聞いたんです！」","f":"rika"},{"t":"n","s":"小さな、古い水族館だった。水槽の青い光が、薄暗い廊下を、静かに照らしている。平日の昼間で、客は、ほとんどいなかった。","f":"rika"},{"t":"d","s":"「せんぱい、見て見て、くらげ！」","f":"rika"},{"t":"n","s":"莉花が、水槽に顔を近づけて、目を輝かせた。ふわふわと漂うくらげが、青い光の中で、白く透けている。","f":"rika"},{"t":"d","s":"「きれい」","f":"rika"},{"t":"d","s":"「ですよね！　見ていると、心が、すうっとします」","f":"rika"},{"t":"d","s":"「うん」","f":"rika"},{"t":"n","s":"耀平は、水槽の前の長椅子に腰かけた。足の疲れが、どっと出た。このところ、ずっと緊張が続いていたせいだろう。水の音と、薄暗い光が、眠気を誘う。","f":"yohei"},{"t":"d","s":"「せんぱい、あっち、ペンギン──」","f":"yohei"},{"t":"d","s":"「……うん」","f":"yohei"},{"t":"d","s":"「せんぱい？」","f":"yohei"},{"t":"d","s":"「……ん」","f":"yohei"},{"t":"n","s":"まぶたが、勝手に落ちてくる。頭が、こくり、こくりと揺れた。","f":"yohei"},{"t":"d","s":"「せんぱい、寝てます？」","f":"yohei"},{"t":"d","s":"「寝てない」","f":"yohei"},{"t":"d","s":"「寝てます」","f":"yohei"},{"t":"d","s":"「寝てないって」","f":"yohei"},{"t":"d","s":"「じゃあ、あのペンギン、何匹いますか」","f":"yohei"},{"t":"d","s":"「……三匹」","f":"yohei"},{"t":"d","s":"「七匹です！」","f":"yohei"},{"t":"n","s":"莉花が、ぷっと吹き出した。耀平は、目をこすって、ようやく起き上がる。","f":"rika"},{"t":"d","s":"「ごめん。ちょっと、眠くて」","f":"rika"},{"t":"d","s":"「いいですよ。ペンギンなんて、逃げませんから」","f":"rika"},{"t":"n","s":"莉花は、隣に座って、水槽の方を指差した。","f":"rika"},{"t":"d","s":"「でも、見てください、せんぱい。あの、一番小さい子」","f":"rika"},{"t":"d","s":"「どれ」","f":"rika"},{"t":"d","s":"「あの、みんなの後ろから、よちよち歩いてる子」","f":"rika"},{"t":"n","s":"小さなペンギンが、仲間の列から少し遅れて、必死に歩いていた。","f":"rika"},{"t":"d","s":"「遅れても、ちゃんと、ついていってます」","f":"rika"},{"t":"d","s":"「そうだな」","f":"rika"},{"t":"d","s":"「わたし、ああいう子、大好きです」","f":"rika"},{"t":"n","s":"莉花は、水槽に手を当てた。ガラスの向こうの小さな影が、ぴょこんと跳ねる。","f":"rika"},{"t":"d","s":"「わたしも、遅れてきたから」","f":"rika"},{"t":"d","s":"「莉花は、遅れてないよ」","f":"rika"},{"t":"d","s":"「ううん」","f":"rika"},{"t":"n","s":"莉花は、静かに首を振った。","f":"rika"},{"t":"d","s":"「遅れてきたんです。せんぱいのところに、辿り着くのが」","f":"rika"},{"t":"n","s":"耀平は、答えなかった。ただ、莉花の隣で、水槽を眺めていた。","f":"yohei"},{"t":"n","s":"青い光が、二人の横顔を、ゆっくりと撫でていく。","f":"yohei"},{"t":"n","s":"帰り際、売店で、小さなペンギンのキーホルダーを買った。莉花が、二つ選んで、片方を耀平に押しつける。","f":"rika"},{"t":"d","s":"「おそろいです」","f":"rika"},{"t":"d","s":"「付けるの、おれ」","f":"rika"},{"t":"d","s":"「付けてください。失くしたら、怒りますよ」","f":"rika"},{"t":"d","s":"「怒るのか」","f":"rika"},{"t":"d","s":"「めちゃくちゃ怒ります」","f":"rika"},{"t":"n","s":"そう言いながら、莉花は、鞄にキーホルダーを付けて、嬉しそうに揺らした。","f":"rika"},{"t":"n","s":"耀平も、鞄の端に、小さなペンギンを付けた。","f":"yohei"},{"t":"n","s":"小さな青い重みが、鞄の隅で、ことん、と揺れた。","f":"yohei"}]},{"key":"55-4","title":"背中合わせ","bg":"bg_riverside","dark":false,"mood":"soft","bgm":"soft1","cast":["rika","yohei"],"lines":[{"t":"cg","v":"cg_back_to_back"},{"t":"n","s":"秋が深まった頃。海辺の町の、朝の浜で、二人は、背中合わせに立っていた。"},{"t":"d","s":"「せんぱい、背中、貸してください」"},{"t":"d","s":"「どうした」"},{"t":"d","s":"「鍛錬です。後輩が、先輩に、背中を預ける訓練」"},{"t":"n","s":"莉花は、くすっと笑った。耀平も、つられて、少しだけ笑った。","f":"rika","m":"happy"},{"t":"n","s":"この頃には、耀平は、よく笑うようになっていた。小さな声で。けれど、ちゃんと、目まで。","f":"yohei","m":"happy"},{"t":"n","s":"波の音。朝の風。背中に、莉花の体温が、薄く伝わってくる。","f":"rika"},{"t":"d","s":"「なあ、莉花」","f":"rika"},{"t":"d","s":"「はい」","f":"rika"},{"t":"d","s":"「おれ、ずっと、一人で戦ってるつもりだった。守るなら、全部、自分で背負わなきゃって」","f":"rika"},{"t":"d","s":"「はい」","f":"rika"},{"t":"d","s":"「でも、島で、みんなに背中を押されて、分かった。背中を預けるのも、強さなんだな」","f":"rika"},{"t":"n","s":"莉花は、小さく息を吸った。","f":"rika"},{"t":"d","s":"「わたしも、そうです。ずっと、一人で立っていました。背中を預けられる人なんて、いないと思ってました」","f":"rika"},{"t":"n","s":"莉花の肩が、わずかに、耀平の背に寄りかかる。","f":"rika"},{"t":"d","s":"「でも、今は、いるんですよね」","f":"rika"},{"t":"d","s":"「いるよ」","f":"rika"},{"t":"d","s":"「……よかった」","f":"rika"},{"t":"n","s":"二人は、同時に、刀を抜いた。朝日が、二本の刃を、金色に染めた。","f":"rika"}]},{"key":"55-5","title":"ほっぺちゅー","bg":"bg_riverside","dark":false,"mood":"climax","bgm":"climax1","cast":["rika","yohei"],"lines":[{"t":"n","s":"その日の夕暮れ。河原の土手に、二人並んで座っていた。"},{"t":"n","s":"川面が、夕日を映して、金色に揺れている。"},{"t":"d","s":"「せんぱい」"},{"t":"d","s":"「うん」"},{"t":"d","s":"「今日も、楽しかったです」"},{"t":"d","s":"「おれも」"},{"t":"d","s":"「ほんとですか」"},{"t":"d","s":"「うん。ほんと」"},{"t":"n","s":"莉花は、膝を抱えた。","f":"rika"},{"t":"d","s":"「わたし、こんなふうに、普通の女の子みたいに過ごすの、せんぱいと旅に出てからが、初めてです」","f":"rika"},{"t":"d","s":"「そうなのか」","f":"rika"},{"t":"d","s":"「はい。ずっと、真実と、復讐のためだけに、生きてきたから」","f":"rika"},{"t":"n","s":"耀平は、莉花の横顔を見た。夕日に染まった頬が、赤く光っている。","f":"yohei","m":"blush"},{"t":"n","s":"旅に出たばかりの頃の自分を、思い出した。何も見えていなかった目。何も味わわなかった食事。眠れなかった夜。","f":"yohei"},{"t":"n","s":"その全部に、莉花がいた。手を握って。腕を引いて。笑って。","f":"rika"},{"t":"d","s":"「ありがとう、莉花」","f":"rika"},{"t":"d","s":"「え」","f":"rika"},{"t":"d","s":"「いろいろ」","f":"rika"},{"t":"n","s":"耀平は、川面を見つめたまま、言った。","f":"yohei"},{"t":"d","s":"「許せない気持ちは、変わらない。たぶん、ずっと、変わらない。でも、莉花がいると、心が、軽くなるんだ」","f":"yohei"},{"t":"d","s":"「……せんぱい」","f":"yohei"},{"t":"d","s":"「だから」","f":"yohei"},{"t":"n","s":"耀平は、莉花の方を向いた。","f":"yohei"},{"t":"d","s":"「これからも、そばにいて」","f":"yohei"},{"t":"n","s":"莉花は、目を丸くした。","f":"rika","m":"surprise"},{"t":"n","s":"唇が、震えた。泣きそうになるのを、必死にこらえているのが、分かった。","f":"rika","m":"sad"},{"t":"n","s":"それから、莉花は、ふっと立ち上がり、耀平の前にしゃがみ込んだ。","f":"rika"},{"t":"d","s":"「せんぱい。目、閉じてください」","f":"rika"},{"t":"d","s":"「え」","f":"rika"},{"t":"d","s":"「いいから」","f":"rika"},{"t":"n","s":"耀平は、言われるまま、目を閉じた。","f":"yohei"},{"t":"cg","v":"cg_cheek_kiss"},{"t":"n","s":"頬に、やわらかい感触が触れた。","f":"yohei"},{"t":"n","s":"ほんの一瞬。花びらのように、軽かった。","f":"yohei"},{"t":"n","s":"目を開けると、莉花が、真っ赤な顔で、微笑んでいた。","f":"rika","m":"happy"},{"t":"d","s":"「……今は、それだけで、充分ですよ」","f":"rika"},{"t":"d","s":"「莉花」","f":"rika"},{"t":"d","s":"「せんぱいの、そばにいられるなら。今は、それだけで」","f":"rika"},{"t":"n","s":"耀平は、頬に手を当てた。熱かった。","f":"yohei"},{"t":"n","s":"照れくささと、ほんの少しの罪悪感が、胸の中で、混ざり合った。こんなに真っ直ぐな気持ちに、今の自分は、まだ、何も返せない。","f":"yohei"},{"t":"n","s":"それでも、莉花は、幸せそうに笑っていた。","f":"rika"}]},{"key":"55-6","title":"枯花計画","bg":"bg_grandpa_house","dark":true,"mood":"night","bgm":"night2","cast":["rika","yohei"],"lines":[{"t":"n","s":"その夜。宿の部屋の灯りの下で、莉花は、一冊のノートを、耀平の前に広げた。","f":"rika"},{"t":"n","s":"旅のあいだ、二人で書き溜めてきたノートだった。","f":"rika"},{"t":"n","s":"祖父たちの事件に関わった、捜査の記録。手紙を書いた、元SHITの男。記録を偽り、学園長の知らないところで隠し続けた者たち。そして、当時の捜査に名を連ねていた、SHITの隊員たちの名前。","f":"principal"},{"t":"n","s":"その中には、見覚えのある名前も、あった。","f":"principal"},{"t":"n","s":"耀平は、黙って、そのページを見つめていた。","f":"yohei"},{"t":"n","s":"窓の外に、満月が浮かんでいる。夜桜の光に、よく似た色だった。","f":"yohei"},{"t":"d","s":"「百の花が、咲き乱れる学園」","f":"yohei"},{"t":"n","s":"莉花が、静かに言った。","f":"rika"},{"t":"d","s":"「その花を、枯らした人たちがいます。わたしのおじいちゃんも、せんぱいのおじいさんも、その人たちに、枯らされました」","f":"rika"},{"t":"d","s":"「ああ」","f":"rika"},{"t":"d","s":"「だから、今度は、わたしたちの番です」","f":"rika"},{"t":"n","s":"莉花は、ノートの最初のページに、ペンを走らせた。","f":"rika"},{"t":"n","s":"一行だけ。","f":"rika"},{"t":"d","s":"『枯花計画』","f":"rika"},{"t":"n","s":"莉花は、顔を上げて、にっこりと笑った。その笑顔は、甘くて、優しくて、少しだけ、怖かった。","f":"rika","m":"happy"},{"t":"d","s":"「さて。どのように、復讐をするか」","f":"rika"},{"t":"n","s":"耀平の目に、夜の光が、静かに宿った。","f":"yohei"},{"t":"d","s":"「私たちの『枯花計画』を、始めましょうか」","f":"yohei"}]}]},{"label":"エピローグ1","n":56,"title":"残された者たち","sub":"","era":"high2","lead":"","scenes":[{"key":"56-1","title":"長期任務","bg":"bg_graduation","dark":false,"mood":"sad","bgm":"sad1","cast":["principal","noa"],"lines":[{"t":"n","s":"耀平が学園を去って、一週間が経った。","f":"yohei"},{"t":"n","s":"全校集会の講堂で、学園長が、壇上に立った。少し、痩せたように見えた。","f":"principal"},{"t":"d","s":"「二年E組の耀平くんは、先の合宿での功績を認められ、本日より、SHITの長期任務に就くこととなりました」","f":"principal"},{"t":"n","s":"講堂が、ざわめいた。","f":"principal"},{"t":"d","s":"「無明を倒した人だろ」","f":"principal"},{"t":"d","s":"「長期任務って、すごい」","f":"principal"},{"t":"d","s":"「さすが、夜桜の」","f":"principal"},{"t":"n","s":"誇らしげな声が、あちこちから上がる。その中で、三人だけが、黙って、うつむいていた。","f":"principal"},{"t":"n","s":"乃亜。竜馬。柚月。","f":"noa"},{"t":"i","s":"（長期任務、なんかじゃない）","f":"noa"},{"t":"n","s":"乃亜は、膝の上で、拳を握りしめた。","f":"noa"},{"t":"n","s":"あの夕方の学長室。刃を突きつけていた耀平の、空っぽの目。花びらが散ったあとの、開け放たれた窓。","f":"yohei"},{"t":"n","s":"本当のことを知っているのは、この講堂の中で、ほんの数人だけだった。","f":"yohei"}]},{"key":"56-2","title":"空いた席","bg":"bg_classroom_e","dark":false,"mood":"sad","bgm":"sad1","cast":["yuzuki","noa","ryoma"],"lines":[{"t":"n","s":"放課後のE組の教室。"},{"t":"n","s":"窓際の、一番後ろの席。その隣の席に、柚月は、ひとりで座っていた。","f":"yuzuki"},{"t":"n","s":"隣の机は、きれいに片づけられていた。教科書も、ノートも、もうない。椅子だけが、きちんと机の下に入れられている。","f":"yuzuki"},{"t":"n","s":"柚月は、その空白を、ずっと見つめていた。","f":"yuzuki"},{"t":"d","s":"「……毎日、ここに座るって、約束したのに」","f":"yuzuki"},{"t":"n","s":"声に出すと、喉の奥が、ぎゅっと痛んだ。","f":"yuzuki"},{"t":"n","s":"教室の扉が開いて、乃亜と竜馬が入ってきた。三人は、何も言わずに、空いた席の周りに集まった。","f":"noa"},{"t":"d","s":"「竜馬さん」","f":"noa"},{"t":"d","s":"「ああ」","f":"noa"},{"t":"d","s":"「耀平さんの、おじいさんのこと……もう一度、教えていただけますか」","f":"noa"},{"t":"n","s":"柚月は、二人とは、高校からの付き合いだった。耀平の祖父のことは、名前と、亡くなったことしか知らなかった。","f":"yuzuki"},{"t":"n","s":"竜馬が、ぽつりぽつりと、話し始めた。","f":"ryoma"},{"t":"n","s":"小さい頃、耀平が祖父と二人で暮らしていたこと。縁側で、祖父が、いつも笑っていたこと。中学一年の春、祖父が、急に亡くなったこと。「歳じゃ」と笑っていたこと。箪笥の中から、手紙が出てきたこと。","f":"yohei"},{"t":"n","s":"乃亜が、その続きを、静かに引き取った。","f":"noa"},{"t":"d","s":"「耀平、あの手紙を、ずっと、お守りみたいにしてた。何度も、何度も、読み返してた」","f":"noa"},{"t":"d","s":"「…………」","f":"noa"},{"t":"d","s":"「それが、偽物だったなんて」","f":"noa"},{"t":"n","s":"乃亜の声が、震えた。柚月は、両手で、口元を覆った。","f":"noa"}]},{"key":"56-3","title":"理央の話","bg":"bg_principal","dark":true,"mood":"tense","bgm":"tense2","cast":["rio","todo","noa"],"lines":[{"t":"n","s":"あの日、耀平が学長室から消えた、すぐ後のことだった。","f":"yohei"},{"t":"n","s":"息を切らして、学長室に駆け込んできたのは、理央だった。","f":"rio"},{"t":"d","s":"「お兄ちゃん……！　もう、行っちゃった……？」","f":"rio"},{"t":"n","s":"理央は、空っぽの部屋を見回して、唇を噛んだ。それから、そこにいた全員の前で、すべてを話した。","f":"rio"},{"t":"n","s":"耀平が、莉花を連れて、本部に来たこと。祖父の手紙を見せたこと。映像に映ったのが、元SHITの男だったこと。その男が、魔法で、祖父の筆跡を真似て、手紙を書いていたこと。","f":"yohei"},{"t":"n","s":"乃亜と竜馬は、言葉を失った。","f":"noa"},{"t":"d","s":"「……なんで」","f":"noa"},{"t":"n","s":"最初に声を出したのは、乃亜だった。","f":"noa"},{"t":"d","s":"「なんで、SHITの人が、魔法で、耀平のおじいちゃんの手紙を書いたの」","f":"noa"},{"t":"n","s":"藤堂は、答えられなかった。唇を噛み、目を伏せたまま、首を横に振るだけだった。","f":"todo"},{"t":"d","s":"「わたしにも……分からない。当時の捜査に、わたしと理央も、加わっていた。だが、そんな事件があったことも、被害者が誰だったのかも、知らされていなかった」","f":"todo"},{"t":"n","s":"その場では、誰も、答えを持っていなかった。","f":"todo"}]},{"key":"56-4","title":"学園長の述懐","bg":"bg_principal","dark":true,"mood":"tense","bgm":"tense2","cast":["principal","ryoma","noa"],"lines":[{"t":"n","s":"三日後。学長室に、乃亜たち三人と、藤堂、理央が呼ばれた。","f":"noa"},{"t":"n","s":"学園長は、三日前よりも、ずっと老けて見えた。机の上には、古い書類の束が、積み上げられていた。","f":"principal"},{"t":"d","s":"「……わしが、話そう」","f":"principal"},{"t":"n","s":"学園長は、深く椅子に腰を下ろした。その手が、小さく震えていた。","f":"principal"},{"t":"d","s":"「この三日で、記録を洗わせた。……四年前、SHITは、違法な武器を流していた職人を追っていた。その捜査が、行きすぎた。間違った相手を、何人も、締め上げた」","f":"principal"},{"t":"d","s":"「…………」","f":"principal"},{"t":"d","s":"「その中で、二人が、死んだ。刀鍛冶の老人と、元剣術師範の老人。……剛三は、わしの、古い友人だった」","f":"principal"},{"t":"n","s":"学園長の声が、掠れた。","f":"principal"},{"t":"d","s":"「それを知った当時の副学長と、捜査に関わったSHITの者たちが、すべてを隠した。死因を書き換え、遺族には、偽りの手紙を残した。学園とSHITの信用が、崩れることを恐れて。……わしの、知らないところで」","f":"principal"},{"t":"d","s":"「知らなかったで、済むんですか」","f":"principal"},{"t":"n","s":"竜馬が、低い声で言った。拳が、白くなるほど握りしめられていた。","f":"ryoma"},{"t":"d","s":"「済まん」","f":"ryoma"},{"t":"n","s":"学園長は、はっきりと答えた。","f":"principal"},{"t":"d","s":"「関与はしておらん。だが、わしが長を務める学園で、起きたことだ。責任は、わしにある」","f":"principal"},{"t":"d","s":"「でも……！」","f":"principal"},{"t":"d","s":"「副学長たちも、最初から、人を殺すつもりだったわけではない。故意ではなかった。だが、故意でなかったからといって、許されることでもない」","f":"principal"},{"t":"n","s":"誰も、納得していなかった。乃亜は、呆然とした顔のまま、静かに震えていた。それが、悲しみなのか、怒りなのか、自分でも分からなかった。","f":"noa"},{"t":"n","s":"竜馬は、窓の外を睨んでいた。","f":"ryoma","m":"anger"},{"t":"i","s":"（卒業したら、決着だって、言ったのに）","f":"ryoma"},{"t":"n","s":"あいつを、止められなかった。決着の約束も、もう、果たせないかもしれない。その怒りは、耀平にではなく、自分自身に向いていた。","f":"yohei"},{"t":"n","s":"学園長は、窓の外の、夕暮れの空を見上げた。","f":"principal"},{"t":"d","s":"「あやつらは、必ず、戻ってくる」","f":"principal"},{"t":"n","s":"その声には、責任の重さと、答えを出せない苦しさが、滲んでいた。","f":"principal"},{"t":"d","s":"「その時は……敵かもしれん」","f":"principal"},{"t":"n","s":"柚月は、隣の席の空白を、見つめていた。","f":"yuzuki"},{"t":"n","s":"窓から差し込む夕日が、誰も座っていない椅子を、静かに照らしていた。","f":"yuzuki"}]}]},{"label":"エピローグ2","n":57,"title":"一年後の夜","sub":"","era":"high2","lead":"","scenes":[{"key":"57-1","title":"生徒会室","bg":"bg_classroom_e","dark":true,"mood":"night","bgm":"night1","cast":["noa","ryoma","yuzuki"],"lines":[{"t":"n","s":"一年後。夏の夜。"},{"t":"n","s":"学園の生徒会室に、明かりが灯っていた。"},{"t":"d","s":"「議案は、以上です。……承認します」"},{"t":"n","s":"会長席に座っているのは、乃亜だった。三年生の春、九十九から、会長を引き継いだ。","f":"noa"},{"t":"n","s":"副会長席には、竜馬。苦い顔で、書類にペンを走らせている。","f":"ryoma"},{"t":"d","s":"「おい、乃亜。この予算案、細けえんだよ」","f":"ryoma"},{"t":"d","s":"「竜馬が、ちゃんと読まないからでしょ」","f":"ryoma"},{"t":"d","s":"「おれは、副会長だぞ。書類は、会長の仕事だろ」","f":"ryoma"},{"t":"d","s":"「副会長の仕事でもあるの」","f":"ryoma"},{"t":"n","s":"窓際の椅子に、柚月が座っていた。生徒会には、入らなかった。それでも、毎晩のように、ここで、本を読んでいる。","f":"yuzuki"},{"t":"d","s":"「お二人とも、そろそろ、夜も遅いですよ」","f":"yuzuki"},{"t":"d","s":"「うん。今日は、ここまでにしよう」","f":"yuzuki"},{"t":"n","s":"乃亜は、立ち上がって、窓の外を見た。","f":"noa"},{"t":"n","s":"月が、高く昇っていた。","f":"noa"},{"t":"n","s":"この一年、いろいろなことがあった。学園は、さらに大きくなった。新しい一年生が入ってきた。隼は、二年生になって、竜馬の後をついて回っている。","f":"ryoma"},{"t":"n","s":"それでも、ふとした瞬間に、窓の外を見てしまう癖だけは、抜けなかった。","f":"ryoma"},{"t":"d","s":"「……ねえ、柚月」","f":"ryoma"},{"t":"d","s":"「はい」","f":"ryoma"},{"t":"d","s":"「一年、経ったね」","f":"ryoma"},{"t":"d","s":"「ええ」","f":"ryoma"},{"t":"n","s":"柚月は、本を閉じた。その指が、表紙の上で、小さく止まった。","f":"yuzuki"},{"t":"n","s":"E組の窓際の、一番後ろの席。その隣の席は、一年間、ずっと空いたままだった。毎朝、柚月が、机を拭き続けていた。","f":"yuzuki"}]},{"key":"57-2","title":"夜が降りる","bg":"bg_classroom_e","dark":false,"mood":"climax","bgm":"climax2","cast":["noa","ryoma","yuzuki"],"lines":[{"t":"n","s":"その時だった。"},{"t":"n","s":"ふっと、明かりが、揺れた。"},{"t":"d","s":"「……え」"},{"t":"n","s":"窓の外の月が、ぐんと、大きくなったように見えた。いや、違う。空が、急速に、暗くなっていく。"},{"t":"n","s":"夜が、さらに深い夜に、塗り替えられていく。"},{"t":"n","s":"星が、一斉に、瞬いた。"},{"t":"n","s":"そして、夜空に、桜の花びらが、舞い始めた。"},{"t":"d","s":"「これ……」"},{"t":"n","s":"乃亜の声が、震えた。","f":"noa"},{"t":"n","s":"忘れるはずがなかった。一年前、島の朝を、夜に変えた光景。","f":"noa"},{"t":"d","s":"「夜桜繚蘭……」","f":"noa","fx":"yozakura"},{"t":"n","s":"竜馬が、椅子を蹴って、立ち上がった。拳に、炎が灯る。柚月の周りに、淡雪が、ふわりと降りた。","f":"ryoma"},{"t":"n","s":"三人とも、身構えていた。","f":"ryoma"},{"t":"n","s":"それなのに、誰一人、目に浮かんだものを、止められなかった。","f":"ryoma"}]},{"key":"57-3","title":"窓が割れる","bg":"bg_classroom_e","dark":false,"mood":"climax","bgm":"climax2","cast":["yohei","rika"],"lines":[{"t":"n","s":"ぱりん、と。"},{"t":"n","s":"生徒会室の窓ガラスが、外側から、砕け散った。","fx":"shake"},{"t":"n","s":"月光の中を、ガラスの破片と、桜の花びらが、きらきらと舞う。"},{"t":"cg","v":"cg_window"},{"t":"n","s":"窓枠に、二つの影が、立っていた。"},{"t":"n","s":"一人は、黒い外套の少年。少し伸びた髪。一年前より、背が高くなっている。"},{"t":"n","s":"もう一人は、その隣に、寄り添うように立つ、小柄な少女。黒いカーディガンの袖が、夜風に揺れていた。"},{"t":"n","s":"少年が、ゆっくりと、顔を上げた。"},{"t":"n","s":"穏やかな目だった。一年前、学長室で見た、空っぽの目ではない。けれど、その奥に、深い夜が、静かに沈んでいた。"},{"t":"d","s":"「……耀平」"},{"t":"n","s":"乃亜の唇から、名前が、こぼれた。","f":"noa"},{"t":"n","s":"構えた手が、震えていた。泣きそうな顔で、それでも、乃亜は、手を下ろさなかった。","f":"noa","m":"sad"},{"t":"n","s":"竜馬も、同じだった。燃える拳を前に突き出したまま、奥歯を噛みしめている。","f":"ryoma"},{"t":"d","s":"「……約束は」","f":"ryoma"},{"t":"n","s":"柚月が、かすれた声で、言った。","f":"yuzuki"},{"t":"d","s":"「隣の席の、約束は……？」","f":"yuzuki"},{"t":"n","s":"耀平は、答えなかった。","f":"yohei"},{"t":"n","s":"ただ、少しだけ、目を細めた。","f":"yohei"},{"t":"n","s":"隣で、莉花が、そっと耀平の袖を握った。","f":"rika"},{"t":"n","s":"夜桜の花びらが、生徒会室の中に、はらはらと舞い込んでくる。","f":"rika"},{"t":"n","s":"耀平は、三人を、ゆっくりと見渡した。","f":"yohei"},{"t":"n","s":"そして、静かに、笑った。","f":"yohei","m":"happy"},{"t":"d","s":"「久しぶり、みんな」","f":"yohei"},{"t":"n","s":"月が、桜の向こうで、冷たく輝いていた。","f":"yohei"},{"t":"d","s":"「さあ、やろうか」","f":"yohei"},{"t":"n","s":"(第2部　完)","f":"yohei"}]}]}];
